window.MAP_DATA_RECORDS.push(...[{"i":"R1452","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"X meta tiktok under fire for deepfake csam in europe","s":"Spanish has called on its public prosecutor to investigate social media platforms for allegedly spreading AI-generated pornography and sexual violence. The Spanish government has called on its public prosecutor to investigate social media platforms X, Meta and TikTok for allegedly spreading AI-generated child pornography and digital sexual violence. At the same time, Ireland’s data privacy regulator announced that the EU is also looking into non-consensual deepfake images created by X’s AI chatbot Grok. On Tuesday, Spanish Prime Minister Pedro Sanchez said that the Council of Ministers will invoke Article 8 of the Organic Statute of the Public Ministry to investigate crimes that the tech giants may be committing.","u":"https://www.biometricupdate.com/202602/x-meta-tiktok-under-fire-for-deepfake-csam-in-europe","d":"2026-02-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-18","organization":"X (presumably referring to TikTok)","aiSystem":"AI chatbot Grok","affectedGroup":"users of social media platforms","action":"AI-generated non-consensual deepfake images","consequence":"Exposure to online sexual violence"}},{"i":"R1453","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ring super bowl ad sparks backlash over ai camera surveillance","s":"The short commercial ignited a broader national conversation about how much machine vision society is willing to accept in exchange for safety and convenience. A Super Bowl commercial for Amazon’s Ring doorbell camera triggered swift backlash, with critics arguing that the company used an emotional story about a lost dog to promote a neighborhood scale camera network while minimizing the broader privacy and civil liberties implications of searchable AI video. The short commercial which was intended to highlight lost pet reunions instead ignited a broader national conversation about how much machine vision society is willing to accept in exchange for safety and convenience.","u":"https://www.biometricupdate.com/202602/ring-super-bowl-ad-sparks-backlash-over-ai-camera-surveillance","d":"2026-02-12","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-12","organization":"Amazon","aiSystem":"AI-powered camera surveillance system","affectedGroup":"General public","action":"Promoted a neighborhood-scale camera network","consequence":"Ignited a broader national conversation about privacy and civil liberties"}},{"i":"R1454","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai platforms flippant about stopping deepfake porn authorities stepping in","s":"Civitai is an online marketplace for AI-generated content, which has a ban on deepfake pornography but also sells files specifically designed to create it. Civitai is an online marketplace for AI-generated content, which has a ban on deepfake pornography but also sells files specifically designed to create it, according to a new paper by Stanford and Indiana University researchers. The report, which has not yet been peer reviewed, analyzed content requests on the platform, backed by famed Silicon Valley VC firm Andreessen Horowitz. The researchers found that the majority of requests (or “bounties”) on the site are not for images, but LoRA’s (Low-Rank Adaptation’s), which can be used to make commercial AI models create content they were not trained to generate.","u":"https://www.biometricupdate.com/202602/ai-platforms-flippant-about-stopping-deepfake-porn-authorities-stepping-in","d":"2026-02-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-03","organization":"Civitai","aiSystem":"AI-generated content platform","affectedGroup":"People seeking AI-generated content","action":"Users requesting AI-generated content","consequence":"Exposure to misleading content (deepfake pornography)"}},{"i":"R1455","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ice fbi expand facial recognition use to protest investigations","s":"Federal use of facial recognition and related surveillance technologies has expanded decisively into the monitoring of domestic protest activity. Federal use of facial recognition and related surveillance technologies has expanded decisively into the monitoring of domestic protest activity, according to a growing body of reporting and firsthand accounts from Minneapolis, where Immigration and Customs Enforcement (ICE) and Federal Bureau of Investigation (FBI) agents have deployed an unusually dense mix of biometric, social media, and data-analytics tools during large-scale enforcement operations. The picture that emerges though is not of a single technology used in isolation, but of an integrated surveillance stack that allows federal agents to identify, locate, and track individuals who appear near enforcement actions or protests, even when those individuals are U.S. citizens engaged…","u":"https://www.biometricupdate.com/202602/ice-fbi-expand-facial-recognition-use-to-protest-investigations","d":"2026-02-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-02","organization":"Immigration and Customs Enforcement (ICE), Federal Bureau of Investigation (FBI)","aiSystem":"Facial recognition technology and related surveillance technologies","affectedGroup":"U.S. citizens engaged in domestic protest activities","action":"Deployed an unusually dense mix of biometric, social media, and data-analytics tools during large-scale enforcement operations","consequence":"Monitored individuals who appear near enforcement actions or protests, identified, located, and tracked even when they are U.S. citizens"}},{"i":"R1456","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Us justice departments search of reporters phone laptops raise biometric privacy concerns","s":"When United States federal agents searched the home of Hannah Natanson, they were not just pursuing a leak investigation. When federal agents searched the home of Hannah Natanson, they were not just pursuing a leak investigation. They were taking custody of biometric-protected devices that collectively contain years of confidential reporting, source relationships, and personal data, raising acute privacy concerns that extend far beyond the alleged disclosure at the center of the case. Natanson, a reporter for The Washington Post , is not accused of wrongdoing. Her devices were seized as part of a Justice Department investigation into Aurelio Luis Perez-Lugones, a Pentagon contractor charged with improperly retaining and transmitting sensitive Defense Department materials.","u":"https://www.biometricupdate.com/202602/us-justice-departments-search-of-reporters-phone-laptops-raise-biometric-privacy-concerns","d":"2026-02-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-02","organization":"United States federal agents, Justice Department","aiSystem":"Biometric-protected devices","affectedGroup":"Hannah Natanson, reporter for The Washington Post","action":"Seized biometric-protected devices containing confidential data","consequence":"Raised privacy concerns extending beyond the case"}},{"i":"R1457","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ices expanding use of frt on minors collides with dhs policy oversight warnings law","s":"Agents using facial recognition on minors who are U.S. citizens without consent, individualized suspicion, or meaningful public limits on retention and sharing. When masked federal agents stopped two teenagers riding their bikes near an Illinois high school last fall, the encounter followed a now familiar script. The agents demanded proof of citizenship. One of the teenagers, who said he was 16 and a U.S. citizen, told the agents he had a school ID, but did not have it on him. According to a lawsuit filed by the State of Illinois and the City of Chicago, one agent then asked another, “Can you do facial?” The other agent pointed a cell phone at the teenager, appearing to take a photo of his face.","u":"https://www.biometricupdate.com/202601/ices-expanding-use-of-frt-on-minors-collides-with-dhs-policy-oversight-warnings-law","d":"2026-01-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01","organization":"Agents using facial recognition technology","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"U.S. citizens, particularly minors","action":"Used facial recognition technology to identify people","consequence":"Exposed people to surveillance and tracking"}},{"i":"R1458","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Lawsuit casts new light on ice cbps expanding biometric visual surveillance dragnet","s":"At the center of the allegations in the Illinois lawsuit is the DHS app Mobile Fortify, a smartphone-based tool Biometric Update has extensively reported on. A sweeping 103-page federal lawsuit filed by the State of Illinois and the City of Chicago against the Trump administration offers the most detailed public accounting to date of how biometric identification tools and visual surveillance practices originally developed for border processing have been redeployed deep inside the United States. The complaint describes how those technologies have migrated far from ports of entry, transforming routine street encounters, protests, and interactions with bystanders into sites of data capture and long-term federal retention.","u":"https://www.biometricupdate.com/202601/lawsuit-casts-new-light-on-ice-cbps-expanding-biometric-visual-surveillance-dragnet","d":"2026-01-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-14","organization":"DHS (Department of Homeland Security)","aiSystem":"Biometric identification tools and visual surveillance practices","affectedGroup":"People in routine street encounters, protesters, bystanders","action":"Migrated from ports of entry to transform routine street encounters, protests, and interactions with bystanders into sites of data capture","consequence":"Long-term federal retention of data"}},{"i":"R1459","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Groks image processing feature is a mass violation of biometric privacy laws","s":"Moral implications aside, there may well be another legal hammer about to fall on Elon Musk’s chabot: namely, biometrics, and the laws that protect them. The world, or some part of it, has decided in the last month or so that generating sexualized images of children is okay, as long as it’s being done on X by a large language model named Grok. The moral implications aside, there may well be another legal hammer about to fall on Elon Musk’s chabot: namely, biometrics, and the laws that protect them A blog from Captain Compliance, written by Graeme Whiles, points out that, even without factoring in the creation of child sexual abuse material (CSAM), “the mass processing of biometric data without consent, at industrial scale,” is in “direct violation of established data protection frameworks.”","u":"https://www.biometricupdate.com/202601/groks-image-processing-feature-is-a-mass-violation-of-biometric-privacy-laws","d":"2026-01-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-13","organization":"Not specified in report","aiSystem":"Grok's image processing feature","affectedGroup":"People whose biometric data is processed","action":"Mass processing of biometric data without consent","consequence":"Direct violation of data protection frameworks"}},{"i":"R1460","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Dallas police plan most expansive local facial recognition program in us","s":"Dallas Police plan to use Clearview AI's facial recognition for less serious crimes, and the company beats a lawsuit in Vermont. Dallas Police are considering expanding their use of Clearview AI ’s facial recognition to less-serious crimes like trespassing and package theft. The plan, predictably, is facing some criticism. Originally adopted for serious felonies like murder and rape, Dallas Police are now proposing to search the all the images on the public internet for alleged Class B misdemeanors with Clearview AI’s facial recognition, local ABC affiliate WFAA reports Dallas police contracted Clearview ’s facial recognition around the middle of last year.","u":"https://www.biometricupdate.com/202512/dallas-police-plan-most-expansive-local-facial-recognition-program-in-us","d":"2025-12-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-19","organization":"Dallas Police Department","aiSystem":"Clearview AI's facial recognition technology","affectedGroup":"People suspected of Class B misdemeanors","action":"Search public internet images for facial recognition matches","consequence":"Increased public exposure to surveillance"}},{"i":"R1464","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Social security administrations digital wall will deny access to beneficiaries","s":"The Social Security Administration (SSA) is remaking itself around a digital identity system that tens of millions of its beneficiaries cannot use. The Social Security Administration (SSA) is remaking itself around a digital identity system that tens of millions of its beneficiaries cannot use – while simultaneously dismantling the in-person safety valve that has long allowed people to navigate the system when digital verification fails. It is a transformation driven by staffing cuts, budget constraints, and operational redesign, and one that raises an urgent question at the core of federal benefits administration: can the agency legally and operationally require digital and financial authentication steps that its user base is structurally unable to satisfy, while removing the in-person alternatives that make the program accessible at all?","u":"https://www.biometricupdate.com/202512/social-security-administrations-digital-wall-will-deny-access-to-beneficiaries","d":"2025-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-02","organization":"Social Security Administration (SSA)","aiSystem":"digital identity system","affectedGroup":"beneficiaries","action":"require digital and financial authentication steps","consequence":"denied access to benefits"}},{"i":"R1465","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Civil liberties groups demand dhs shut down ices mobile fortify app","s":"A broad coalition of civil rights, privacy, and immigrant advocacy organizations is urging the DHS to immediately halt ICE's use of Mobile Fortify. A broad coalition of civil rights, privacy, and immigrant advocacy organizations is urging the Department of Homeland Security (DHS) to immediately halt Immigration and Customs Enforcement’s (ICE) use of Mobile Fortify , a smartphone-based facial recognition app that ICE agents are now deploying during street encounters across the U.S. In a sharply worded letter sent to DHS Chief Privacy Officer Roman Jankowski, thirty organizations warn that the app represents one of the most alarming expansions of federal biometric surveillance in years, one that threatens civil rights and is already being used in ways that violate DHS’s own policies.","u":"https://www.biometricupdate.com/202511/civil-liberties-groups-demand-dhs-shut-down-ices-mobile-fortify-app","d":"2025-11-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-28","organization":"Department of Homeland Security (DHS)","aiSystem":"smartphone-based facial recognition app","affectedGroup":"Immigration and Customs Enforcement (ICE) agents","action":"deploying Mobile Fortify during street encounters","consequence":"threatening civil rights and violating DHS policies"}},{"i":"R1469","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Us lawmakers call for ftc probe into flock safety over data security failures","s":"Flock Safety has contracts spanning more than 5,000 police departments, 1,000 private companies, and numerous homeowner associations across 49 states. U.S. Senator Ron Wyden and Representative Raja Krishnamoorthi are urging the Federal Trade Commission (FTC) to investigate Flock Safety , saying the fast-growing surveillance technology company has failed to implement basic cybersecurity protections and exposing sensitive data to hackers, foreign intelligence services, and criminal networks. The two lawmakers detailed their concerns in a letter they sent Monday to FTC Chair Andrew Ferguson, arguing that Flock’s failure to require strong multi-factor authentication (MFA) has created a significant risk to Americans’ privacy and public safety.","u":"https://www.biometricupdate.com/202511/us-lawmakers-call-for-ftc-probe-into-flock-safety-over-data-security-failures","d":"2025-11-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-06","organization":"U.S. Senator Ron Wyden and Representative Raja Krishnamoorthi","aiSystem":"Surveillance technology company Flock Safety","affectedGroup":"Americans","action":"Failed to implement basic cybersecurity protections and expose sensitive data","consequence":"Exposure to hackers, foreign intelligence services, and criminal networks"}},{"i":"R1470","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Nypd faces federal lawsuit over alleged unconstitutional citywide surveillance","s":"The plaintiffs argue that the system violates their First and Fourth Amendment rights by turning everyday life in New York into a continuous police search. A new federal lawsuit accuses the New York City Police Department (NYPD) of operating an unconstitutional mass surveillance system that tracks residents and visitors across the five boroughs. The 29-page complaint , filed October 27 in the Southern District of New York, alleges that the NYPD’s Domain Awareness System (DAS) fuses cameras, sensors, license-plate readers, biometric databases, and social-media monitoring into an integrated network that surveils millions of people without warrants or adequate oversight.","u":"https://www.biometricupdate.com/202510/nypd-faces-federal-lawsuit-over-alleged-unconstitutional-citywide-surveillance","d":"2025-10-31","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-27","organization":"New York City Police Department (NYPD)","aiSystem":"Domain Awareness System (DAS)","affectedGroup":"residents and visitors","action":"surveils millions of people without warrants or adequate oversight","consequence":"violates First and Fourth Amendment rights"}},{"i":"R1474","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Surveillance shadows no kings protests","s":"The No Kings protests spanned more than 2,600 locations in all fifty states, billed as a collective declaration that no president should rule unchecked. On October 18, seven million Americans poured into streets and public squares across the nation to take part in what became the largest protest ever of a sitting U.S. president. But as citizens exercised their right to assemble, many worried that they were being quietly observed – watched by drones, tracked by algorithms, or profiled in digital dossiers built far from the streets they marched upon. Three months earlier, a group of Democratic senators led by Massachusetts’s Ed Markey had written to Department of Homeland Security (DHS) Secretary Kristi Noem demanding transparency about the department’s use of surveillance technologies at public demonstrations.","u":"https://www.biometricupdate.com/202510/surveillance-shadows-no-kings-protests","d":"2025-10-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-18","organization":"Department of Homeland Security (DHS)","aiSystem":"Surveillance technologies","affectedGroup":"Citizens exercising their right to assemble","action":"Surveillance technologies were used to observe and track protesters","consequence":"Many citizens expressed concern about being watched and profiled"}},{"i":"R1478","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Google settles biometric data privacy lawsuit over attempts to weed out bias","s":"The tech giant’s use of the open-source Diversity in Faces dataset developed by IBM to address biometric algorithmic bias violated BIPA. Google has reached a settlement agreement over its use of an open-source dataset allegedly containing images of people from Illinois for training facial recognition algorithms. The tech giant’s use of the open-source Diversity in Faces dataset developed by IBM to address biometric algorithmic bias violated Illinois’ Biometric Information Privacy Act (BIPA), the plaintiffs originally alleged back in 2020. Some of the images in contained were drawn from a Flickr dataset that included biometric data of people from Illinois, according to the plaintiffs.","u":"https://www.biometricupdate.com/202510/google-settles-biometric-data-privacy-lawsuit-over-attempts-to-weed-out-bias","d":"2025-10-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-15","organization":"Google","aiSystem":"Facial recognition algorithms","affectedGroup":"People from Illinois","action":"Used open-source Diversity in Faces dataset","consequence":"Violated Illinois' Biometric Information Privacy Act (BIPA)"}},{"i":"R1479","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Over retention of age verification data has predictable result in discord breach","s":"The breach only impacts users who have shared identity document information with Discord’s Customer Support or Trust & Safety teams. A third-party customer service provider for Discord has exposed the ID documents us has apparently been storing of people performing age verification on the site. An unauthorized individual appears to have had access to user data including contact information, IP addresses, the last four digits of credit card numbers and support ticket messages. Most worrying though is the exposure of “a small number of government‑ID images (e.g., driver’s license, passport) from users who had appealed an age determination,” Discord says.","u":"https://www.biometricupdate.com/202510/over-retention-of-age-verification-data-has-predictable-result-in-discord-breach","d":"2025-10-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-06","organization":"Discord","aiSystem":"Not specified in report","affectedGroup":"users who had shared identity document information with Discord's Customer Support or Trust & Safety teams","action":"exposed government-ID images (e.g., driver’s license, passport) from users who had appealed an age determination","consequence":"privacy risks"}},{"i":"R1481","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Trump administration accused of creating illegal citizenship database","s":"The lawsuit accuses the Trump administration of quietly building a national data bank that links the most sensitive records of American citizens. A coalition led by the League of Women Voters filed a class action lawsuit this week in the U.S. District Court for the District of Columbia accusing the Trump administration of quietly building a national data bank that links the most sensitive records of American citizens. The 66-page lawsuit alleges that the Department of Homeland Security (DHS), working with the Social Security Administration (SSA), the Department of Justice (DOJ), and the White House’s Department of Government Efficiency (DOGE), has consolidated vast personal datasets into centralized “interagency data systems” without following the safeguards of the Privacy Act of 1974, the E-Government Act of 2002, or the Federal Information Security Modernization Act.","u":"https://www.biometricupdate.com/202510/trump-administration-accused-of-creating-illegal-citizenship-database","d":"2025-10-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-02","organization":"Trump administration","aiSystem":"Not specified in report","affectedGroup":"American citizens","action":"consolidated vast personal datasets into centralized interagency data systems","consequence":"lack of Privacy Act of 1974, E-Government Act of 2002, or Federal Information Security Modernization Act safeguards"}},{"i":"R1482","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Breach of fema cbp deepens concerns over national security vulnerabilities","s":"That these critical agencies could be compromised through a single breach raises questions about technical gaps and resilience of the federal security posture. When the Department of Homeland Security (DHS) confirmed that a breach in July exposed data from the Federal Emergency Management Agency (FEMA) and Customs and Border Protection (CBP), the initial reaction was disbelief. The idea that two of the nation’s most critical agencies could be compromised through a single breach raises questions not only about the technical gaps that allowed the attack, but also about the resilience of the federal government’s security posture.","u":"https://www.biometricupdate.com/202510/breach-of-fema-cbp-deepens-concerns-over-national-security-vulnerabilities","d":"2025-10-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07","organization":"Department of Homeland Security (DHS)","aiSystem":"Not specified in report","affectedGroup":"Critical agencies (FEMA, CBP)","action":"Data breach","consequence":"Questions about technical gaps and resilience of federal security posture"}},{"i":"R1490","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Meta allows impersonation scams to run rampant as political deepfakes hawk phony benefits","s":"Scammers are spending heavily on Facebook ads that use deepfake videos of prominent political figures to push bogus government benefits. By now, it is hardly a secret that social media, and Facebook in particular, has become a garbage dump for bad information. Already targeted by foreign actors as fertile ground in which to sow discontent and partisan hostility, its inextricable ties to AI development mean it is now awash in so-called AI slop: memes, images and advertisements created with generative learning models. It’s an ideal habitat for scammers. A new investigation by the Tech Transparency Project (TTP) has found that scammers are spending heavily on Facebook ads that use deepfake videos of prominent political figures to push bogus government benefits.","u":"https://www.biometricupdate.com/202510/meta-allows-impersonation-scams-to-run-rampant-as-political-deepfakes-hawk-phony-benefits","d":"2025-09-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-03","organization":"Facebook","aiSystem":"Generative learning models","affectedGroup":"People seeking government benefits","action":"Used deepfake videos to promote fake government benefits","consequence":"Exposure to misleading information"}},{"i":"R1493","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Gao warns of privacy risks in using facial recognition in rental housing","s":"GAO auditors concluded that while FRT may reduce trespassing and crime, they also pose risks of discriminatory errors and unchecked surveillance. As landlords and housing authorities are adopting facial recognition systems marketed as cutting-edge tools to enhance safety and convenience, a new audit by the Government Accountability Office (GAO) found the technology is racing ahead of federal oversight, raising pressing concerns about privacy, accuracy, and tenant rights. GAO’s audit report marks one of the most comprehensive federal examinations yet of property technology, or “Proptech,” in the rental housing market.","u":"https://www.biometricupdate.com/202508/gao-warns-of-privacy-risks-in-using-facial-recognition-in-rental-housing","d":"2025-08-29","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-08-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-29","organization":"Government Accountability Office (GAO)","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"Tenants","action":"Facial recognition technology was adopted by landlords and housing authorities","consequence":"Risks of discriminatory errors and unchecked surveillance"}},{"i":"R1495","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Doge access to us govt systems sparks fear of massive federal data breaches","s":"The Department of Government Efficiency is facing scrutiny as federal whistleblowers allege it exposed sensitive government systems to serious security risks. The Department of Government Efficiency (DOGE), a Trump administration initiative initially led by Elon Musk and his allies, is facing mounting scrutiny after two federal whistleblowers alleged it exposed sensitive U.S. government systems to serious security risks. Risks that may be ongoing. Separate disclosures from an IT official at the National Labor Relations Board (NLRB) and the Social Security Administration’s (SSA) chief data officer describe unauthorized access, shadow databases, and disabled safeguards that could leave millions of Americans vulnerable to identity theft and foreign exploitation.","u":"https://www.biometricupdate.com/202508/doge-access-to-us-govt-systems-sparks-fear-of-massive-federal-data-breaches","d":"2025-08-27","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-08-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-27","organization":"Department of Government Efficiency (DOGE)","aiSystem":"Not specified in report","affectedGroup":"Millions of Americans","action":"Unauthorized access, shadow databases, and disabled safeguards","consequence":"Vulnerability to identity theft and foreign exploitation"}},{"i":"R1496","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Us law enforcement dispenses ammo to facial recognition critics","s":"A regular series of arrests based on false matches are keeping the question of whether U.S. police use of facial recognition is appropriate on the front burner. America’s embrace of surveillance technology and a regular series of arrests based on false matches are keeping the question of whether U.S. police use of facial recognition is appropriate on the front burner. Biometrics use is increasing amongst police around the world, according to the latest industry survey from the Biometrics Institute. Public education is needed for greater acceptance of biometrics, 84 percent of survey respondents say. But other stakeholders clearly need more education too.","u":"https://www.biometricupdate.com/202508/us-law-enforcement-dispenses-ammo-to-facial-recognition-critics","d":"2025-08-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-27","organization":"U.S. law enforcement agencies","aiSystem":"Facial recognition technology","affectedGroup":"People identified or tracked using the technology","action":"Used facial recognition to identify people","consequence":"Exposed people to surveillance and tracking"}},{"i":"R1499","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Report calls for halt to tsas facial recognition experiment","s":"Digital rights groups are asking whether travelers are sleepwalking into an acceptance of facial recognition as the default. While industry stakeholders push to make biometrics the preferred option for global travel, digital rights groups are asking whether travelers are sleepwalking into an acceptance of facial recognition as the default. The Algorithmic Justice League (AJL) has published the findings from its report entitled, Comply to Fly ? A release from the group says that, while the TSA initially described its facial recognition program as a pilot, it has been expanding – “to over 250 domestic airports as of the date of issuance of this report with plans to expand to 430 airports in the coming years.”","u":"https://www.biometricupdate.com/202507/report-calls-for-halt-to-tsas-facial-recognition-experiment","d":"2025-07-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-30","organization":"TSA (Transportation Security Administration)","aiSystem":"Facial recognition technology","affectedGroup":"Travelers","action":"Used facial recognition to identify people","consequence":"Exposure to surveillance and tracking"}},{"i":"R1502","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai voice deepfake of us secretary of state triggers global security alert","s":"An individual posing as Marco Rubio used AI tools to impersonate his voice and likeness in a series of targeted communications to senior government officials. In one of the most audacious examples yet of AI-enabled political deception, an individual posing as U.S. Secretary of State Marco Rubio used AI deepfake tools to impersonate his voice and writing style in a series of targeted communications to senior government officials, the goal of which was to “gain access to information or accounts.” What makes the matter particularly alarming is not just the technological sophistication involved, but the choice of target.","u":"https://www.biometricupdate.com/202507/ai-voice-deepfake-of-us-secretary-of-state-triggers-global-security-alert","d":"2025-07-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-11","organization":"Not specified in report","aiSystem":"AI deepfake technology","affectedGroup":"Senior government officials","action":"Impersonated voice and writing style","consequence":"Exposure to misleading content"}},{"i":"R1505","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"New orleans police seek expanded facial recognition powers amid privacy backlash","s":"NOPD wants city council to roll back restrictions in the name of public safety, igniting a fierce battle over privacy, civil liberties, and police transparency. The New Orleans Police Department (NOPD) is pressing the City Council to roll back restrictions on facial recognition technology in the name of public safety, igniting a fierce battle over privacy, civil liberties, and police transparency. Police Superintendent Anne Kirkpatrick appeared before the City Council’s Criminal Justice Committee this week with a clear message: her department needs access to real-time facial recognition alerts from Project NOLA , a private camera network that operates more than 5,000 surveillance cameras citywide.","u":"https://www.biometricupdate.com/202507/new-orleans-police-seek-expanded-facial-recognition-powers-amid-privacy-backlash","d":"2025-07-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-04","organization":"New Orleans Police Department (NOPD)","aiSystem":"Facial recognition technology","affectedGroup":"General public","action":"Access to real-time facial recognition alerts","consequence":"Increased privacy invasion and potential misuse"}},{"i":"R1510","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ice is at the center of a vast and growing us biometric surveillance capability","s":"As ICE finds ways to piggyback on local and private systems, boundaries between public safety, immigration control, and mass surveillance are rapidly eroding. U.S. Immigration and Customs Enforcement (ICE) has quietly emerged as the operational nucleus of a vast, fragmented, and increasingly automated biometric surveillance architecture across the United States. And unlike traditional centralized surveillance programs managed directly by federal agencies, ICE’s strategy has been to embed itself within a growing constellation of federal, state, local, and commercial systems, leveraging their reach, data, and capabilities without assuming formal ownership and avoiding oversight.","u":"https://www.biometricupdate.com/202505/ice-is-at-the-center-of-a-vast-and-growing-us-biometric-surveillance-capability","d":"2025-05-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-28","organization":"U.S. Immigration and Customs Enforcement (ICE)","aiSystem":"Biometric surveillance technology","affectedGroup":"People subject to immigration controls","action":"Embedded within various systems for identification and tracking","consequence":"Exposure to surveillance and tracking"}},{"i":"R1512","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Us biometric data privacy lawsuit against clearview concludes after 5 years","s":"The lawsuit has been crawling along since January 22, 2020. Since then, it has ben through two consolidation orders and multiple rounds of mediation. The biometric data privacy lawsuit against Clearview AI has finally been officially settled. The reasons for the ruling are laid out in an extensive Memorandum Opinion and Order (hosted by Courthouse News ) by Judge Sharon Johnson Coleman. Illinois, Virginia, California, New York subclasses and the nationwide class are all included in the settlement. Clearview’s status as a startup with a value proposition based in large part on scale presented challenges to the negotiation.","u":"https://www.biometricupdate.com/202505/us-biometric-data-privacy-lawsuit-against-clearview-concludes-after-5-years","d":"2025-05-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-13","organization":"Clearview AI","aiSystem":"Clearview AI","affectedGroup":"Illinois residents, Virginia residents, California residents, New York residents, and others","action":"Used biometric data without consent","consequence":"Settlement reached to address privacy violations"}},{"i":"R1513","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Texas ag secures record breaking privacy settlement with google","s":"Texas asserted that Google harvested biometric identifiers without obtaining clear and informed consent as required under CUBI. In a major development in the battle over consumer data privacy, Texas Attorney General Ken Paxton has reached a $1.375 billion settlement with Google that resolves two lawsuits that accused the tech giant of illegally collecting personal data, including biometrics, from Texans without their informed consent. The agreement represents the largest state-level privacy settlement ever secured against Google and is part of a broader campaign by Texas to hold Big Tech companies accountable under state privacy laws.","u":"https://www.biometricupdate.com/202505/texas-ag-secures-record-breaking-privacy-settlement-with-google","d":"2025-05-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-12","organization":"Google","aiSystem":"Biometric identifiers collection technology","affectedGroup":"Texans","action":"Harvested biometric identifiers without consent","consequence":"Settlement of $1.375 billion"}},{"i":"R1516","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"How geo group tech became a cornerstone of trumps immigration crackdown","s":"While digital monitoring only constitutes 14 percent of Geo Group’s $2.4 billion in annual revenue, it is the most profitable segment of its business. The story of a Honduran immigrant living in Louisiana captures the troubling transformation of U.S. immigration enforcement in the Trump era. According to the New York Times , after entering the country in 2022, the immigrant complied with an immigration surveillance program by submitting weekly selfies through a facial recognition app provided by the Geo Group , the nation’s largest private prison operator. The app, part of the federal government’s so-called “ Alternatives to Detention ” program, was marketed as a humane substitute for physical incarceration.","u":"https://www.biometricupdate.com/202504/how-geo-group-tech-became-a-cornerstone-of-trumps-immigration-crackdown","d":"2025-04-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022","organization":"Geo Group","aiSystem":"Facial recognition app","affectedGroup":"Honduran immigrant","action":"submitted weekly selfies through a facial recognition app","consequence":"exposed to surveillance and tracking"}},{"i":"R1519","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Social security administration walks back identity proofing requirements","s":"Backlash to the news that SSA was overhauling its identity verification procedures has lead to a partial rollback of its new in-person verification policy. The Social Security Administration (SSA) has backpaddled from its announcement last week that it was overhauling its identity verification procedures in a move that was met with significant public backlash, leading to a partial rollback of its new in-person verification policy. Initially, SSA mandated that millions of beneficiaries would have to verify their identities in person at field offices rather than online to do things like making changes to their direct deposit information or to file a new claim.","u":"https://www.biometricupdate.com/202503/social-security-administration-walks-back-identity-proofing-requirements","d":"2025-03-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-28","organization":"Social Security Administration (SSA)","aiSystem":"Not specified in report","affectedGroup":"Millions of beneficiaries","action":"Required beneficiaries to verify identities in person at field offices","consequence":"Exposure of personal information"}},{"i":"R1521","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ssa id verification overhaul sparks backlash over accessibility and security","s":"The Social Security Administration is mounting a significant overhaul of its identity verification procedures in a move that is supposed to bolster security. The Social Security Administration (SSA) is mounting a significant overhaul of its identity verification procedures in a move that is supposed to bolster security and prevent fraudulent activity, but which may end up creating more problems than it will solve. That is, if there were ever legitimate ID verification problems like Elon Musk’s so-called Department of Government Efficiency (DOGE) claims that needed fixing to begin with. DOGE initially announced plans to eliminate the ability to access retirement and disability services by phone, but it was a move that was reversed following widespread criticism.","u":"https://www.biometricupdate.com/202503/ssa-id-verification-overhaul-sparks-backlash-over-accessibility-and-security","d":"2025-03-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-20","organization":"Social Security Administration (SSA)","aiSystem":"Identity verification procedures","affectedGroup":"People seeking retirement and disability services","action":"Revoked access to services by phone","consequence":"Created privacy risks and backlash"}},{"i":"R1525","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Employee screening company breach exposed pii of more than 3 million","s":"A year after it suffered a significant data breach, DISA Global Solutions has began notifying affected individuals of the breach. A year after it suffered a significant data breach on February 9, 2024, last week Houston, Texas-based DISA Global Solutions – a provider of employee screening, compliance, and safety solutions for businesses across industries – began notifying affected individuals of the breach. DISA is offering 12 months of complimentary credit monitoring services through Experian to mitigate the potential risks associated with the compromise of their personally identifiable information (PII). The data breach, which went undetected until April 22, 2024, compromised the PII of an estimated 3,332,750 people.","u":"https://www.biometricupdate.com/202502/employee-screening-company-breach-exposed-pii-of-more-than-3-million","d":"2025-02-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-22","organization":"DISA Global Solutions","aiSystem":"Not specified in report","affectedGroup":"3,332,750 people","action":"compromised personally identifiable information (PII)","consequence":"exposed to privacy risks"}},{"i":"R1531","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"World rebukes coverage of brazils ban on offering crypto for biometrics","s":"The organization swats back at reports that privacy watchdogs have banned TFH from offering crypto or financial compensation in exchange for biometric data. World has announced the creation of more than 23 million World IDs – an impressive feat, considering how it has struggled to explain itself in the face of questions from data privacy regulators. Now, the organization has swatted back at reports that Brazilian privacy watchdogs have banned Tools of Humanity (TFH) – a company whose association with World has shifted over time, but which is run by World co-founder Alex Blania – from offering cryptocurrency or financial compensation in exchange for biometric data World says an “ongoing misinformation campaign shared on social media” gets it wrong on its system for establishing digital ID and proof of personhood (PoP) through iris biometrics.","u":"https://www.biometricupdate.com/202502/world-rebukes-coverage-of-brazils-ban-on-offering-crypto-for-biometrics","d":"2025-02-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-05","organization":"World","aiSystem":"Digital ID and proof of personhood (PoP) system","affectedGroup":"Public","action":"Shared misinformation campaign","consequence":"Misleading content exposure"}},{"i":"R1536","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Rhode island cyberattack underscores security issues with digital public assistance programs","s":"This is a stark reminder of the risks facing public assistance systems. As digitization increases, these systems must adopt robust cybersecurity measures. The cyberattack on Rhode Island’s RIBridges system underscores significant security challenges faced by public assistance programs. It revealed critical vulnerabilities in handling sensitive data, vendor management, system maintenance, and public trust. RIBridges manages applications for Rhode Island’s public assistance programs, such as Medicaid and the Supplemental Nutrition Assistance Program (SNAP). The attackers behind the breach claimed to have possession of approximately one terabyte of data and demanded a ransom to prevent its release.","u":"https://www.biometricupdate.com/202412/rhode-island-cyberattack-underscores-security-issues-with-digital-public-assistance-programs","d":"2024-12-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-15","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"People using Rhode Island's public assistance programs","action":"Cyberattack on RIBridges system","consequence":"Exposure of sensitive data and public trust issues"}},{"i":"R1538","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Us senators want investigation of tsas expanding use of facial recognition","s":"U.S. Senator Jeff Merkley joined forces with a bipartisan coalition to demand a thorough investigation into the TSA's use of facial recognition technology. This week, U.S. Senator Jeff Merkley, a vocal advocate for privacy rights and transparency, joined forces with a bipartisan coalition to demand a thorough investigation into the Transportation Security Administration’s (TSA) use of facial recognition technology, signaling that the long contentious debate over the increasing use of facial recognition technology at airport security checkpoints isn’t going to cool down anytime soon. The bipartisan group sent a letter to Department of Homeland Security (DHS) Inspector General Joseph Cuffari.","u":"https://www.biometricupdate.com/202411/us-senators-want-investigation-of-tsas-expanding-use-of-facial-recognition","d":"2024-11-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-22","organization":"Transportation Security Administration (TSA)","aiSystem":"Facial recognition technology","affectedGroup":"Passengers at airport security checkpoints","action":"Used facial recognition technology","consequence":"Exposure to surveillance"}},{"i":"R1548","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Steak n shake face pay kiosks from popid draw bipa class action","s":"Illinois' BIPA has another notch in its litigation belt, this time in the form of a class action against fast food chain Steak ‘n Shake. Illinois’ Biometric Information Privacy Act ( BIPA ) has another notch in its litigation belt, this time in the form of a class action against fast food chain Steak ‘n Shake. Illinois resident Michael Massel is behind the suit, which alleges that the burger joint illegally collects face biometrics at its ordering kiosks. Steak n’ Shake’s biometric self-ordering kiosks are a relatively new addition to the company’s operations, introduced just this year. Biometric capabilities are provided by PopID in kiosks from ACRELEC, which have been installed at all 300-plus Steak ‘n Shake locations in the U.S. The kiosks allow customers to “check in” and pay for their meals using facial recognition The class action alleges that the practice contravenes BIPA by…","u":"https://www.biometricupdate.com/202409/steak-n-shake-face-pay-kiosks-from-popid-draw-bipa-class-action","d":"2024-09-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-05","organization":"Steak 'n Shake","aiSystem":"Facial recognition technology","affectedGroup":"Illinois residents","action":"Collect and use face biometrics at ordering kiosks","consequence":"Contravenes Illinois Biometric Information Privacy Act (BIPA)"}},{"i":"R1550","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Investigations into massive national public data breach heat up","s":"The breach was only made public when it was revealed in a proposed class action lawsuit against National Public Data that was filed August 1. U.S. lawmakers, the U.S. Department of Justice (DOJ), and at least two state attorney generals are investigating the cyberattack on Florida-based National Public Data that exposed the personally identifiable information (PII) of millions of Americans, and possibly British and Canadians, too, some reports have suggested. Last week, Julio Casal, the chief intelligence officer for Constella, a provider of AI powered identity risk intelligence services, said that based on his company’s analysis, 292 million individuals’ data was exposed, including the Social Security Numbers (SSNs) for 272 million.","u":"https://www.biometricupdate.com/202408/investigations-into-massive-national-public-data-breach-heat-up","d":"2024-08-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-01","organization":"National Public Data","aiSystem":"Not specified in report","affectedGroup":"millions of Americans, and possibly British and Canadians","action":"exposed the personally identifiable information (PII) of millions of Americans, and possibly British and Canadians","consequence":"privacy intrusion"}},{"i":"R1551","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Cbp one app found to have issues vetting users security vulnerabilities","s":"The app allows undocumented noncitizens to submit biographic and biometric information as part of their Advance Travel Authorization request. U.S. Customs and Border Protection’s (CBP) already controversial CBP One mobile app that allows undocumented noncitizens seeking admission into the United States to submit as part of their Advance Travel Authorization request their biographic and biometric information so that CBP can determine whether they have “derogatory records” is in hot water once again. Civil and human rights groups have decried the CBP One app for its collection of the biometrics of non-U.S. citizens The CBP One app’s appointment feature allows all noncitizens seeking safe and orderly arrival into the United States through one of the eight Southwest border ports of entry (POEs) to submit personally identifiable information (PII) and to schedule appointments in advance of…","u":"https://www.biometricupdate.com/202408/cbp-one-app-found-to-have-issues-vetting-users-security-vulnerabilities","d":"2024-08-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-23","organization":"U.S. Customs and Border Protection (CBP)","aiSystem":"CBP One mobile app","affectedGroup":"Undocumented noncitizens seeking admission into the United States","action":"collects biometric and biographic information","consequence":"raises privacy concerns and decries by civil and human rights groups"}},{"i":"R1553","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Dhs biometrics collected from migrant kids could solve frt training dataset shortfalls","s":"As illegal border crossings have crystallized into a sharp, divisive political issue, border agencies have ramped up biometric data collection programs. An investigation by MIT Technology Review has revealed a plan by the U.S. Department of Homeland Security to collect and analyze photos of the faces of migrant children at the border, in order to train and improve facial recognition technology. The government says the idea is to improve biometric identity services for migrants. Speaking at a conference in June, John Boyd, assistant director of DHS’ Office of Biometric Identity Management ( OBIM ), framed the key question as, “If we pick up someone from Panama at the southern border at age four, say, and then pick them up at age six, are we going to recognize them?”","u":"https://www.biometricupdate.com/202408/dhs-biometrics-collected-from-migrant-kids-could-solve-frt-training-dataset-shortfalls","d":"2024-08-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06","organization":"U.S. Department of Homeland Security (DHS)","aiSystem":"Facial recognition technology","affectedGroup":"Migrant children","action":"Collected and analyzed photos of the faces of migrant children at the border","consequence":"Exposure to surveillance and tracking"}},{"i":"R1555","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Us sues tiktok for alleged violations of kids privacy court order","s":"Five friends-of-the-court briefs were also filed in the U.S. Court of Appeals for the District of Columbia Circuit siding with the government against TikTok. The U.S. Justice Department (DOJ) has sued TikTok, its parent company ByteDance and affiliated companies “to put an end to the social media giant’s … unlawful massive-scale invasions of children’s privacy” in direct violation of the Children’s Online Privacy Protection Act ( COPPA ) and a five-year-old federal court order In the suit it filed Friday, DOJ said that while “the precise magnitude of [the] defendants’ violations [of COPPA] is difficult to determine due to their failure to comply” with a 2019 permanent injunction that required the businesses to “keep records demonstrating their COPPA compliance,” the alleged illegal activity nevertheless effects “millions of children” who use the social media platform, which is most…","u":"https://www.biometricupdate.com/202408/us-sues-tiktok-for-alleged-violations-of-kids-privacy-court-order","d":"2024-08-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-05","organization":"U.S. Justice Department (DOJ)","aiSystem":"TikTok and its parent company ByteDance","affectedGroup":"Millions of children who use the social media platform TikTok","action":"Invade the privacy of children","consequence":"Illegal activity that violates the Children's Online Privacy Protection Act (COPPA) and a previous court order"}},{"i":"R1557","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Google settles over kids biometric data collection in schools","s":"According to an amended complaint filed in July 2021, Google \"infiltrated\" school systems by providing schoolchildren with access to its Chromebook laptops. Google and the parents of an Illinois girl who sued ( H.K. et al. v. Google LLC ) the tech giant in state court in 2020 alleging Google violated two sections of the Illinois Biometric Information Privacy Act ( BIPA ), have agreed to a settlement in which the case “in its entirety” has been sent back to the U.S. Circuit Court of the Ninth Judicial Circuit, McDonough County, Illinois, where the suit was originally filed. The settlement comes on the heels of Illinois residents having started receiving payments last year as part of a $65.8 million class-action settlement with Google for nearly identical alleged violations of BIPA, including “collecting and storing biometric data of individuals who, while residing in Illinois, appeared…","u":"https://www.biometricupdate.com/202408/google-settles-over-kids-biometric-data-collection-in-schools","d":"2024-08-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-07","organization":"Google","aiSystem":"Google's Chromebook laptops","affectedGroup":"Schoolchildren in Illinois","action":"Provided schoolchildren with access to Chromebook laptops","consequence":"Collection and storage of biometric data"}},{"i":"R1558","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Microsoft calls for ai deepfake fraud to be made illegal as fake harris ad circulates","s":"Elon Musk’s retweet of a political deepfake is merely the latest uptick in what is poised to be a skyrocketing prevalence of deepfakes in our online lives. It took less than ten days after Joe Biden stepped away from the U.S. presidential election for a deepfake of his presumed replacement to surface on social media. However, the video, in which deepfake audio of Kamala Harris is heard speaking lines that denigrate her own experience and qualifications, may not have caused the stir it did if it hadn’t been shared as a “parody” by the user who owns the platform. Elon Musk’s retweet of a political deepfake – in violation of Twitter’s policies on falsified content, which Musk may have tossed out along with the name – is merely the latest uptick in what is poised to be a skyrocketing prevalence of deepfakes in our online lives.","u":"https://www.biometricupdate.com/202407/microsoft-calls-for-ai-deepfake-fraud-to-be-made-illegal-as-fake-harris-ad-circulates","d":"2024-07-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-30","organization":"Twitter","aiSystem":"Deepfake technology","affectedGroup":"General public","action":"Shared deepfake content as a parody","consequence":"Stirred controversy and raised awareness"}},{"i":"R1560","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Florida mans facial recognition match not probable cause for wrongful arrest","s":"Jacksonville Sheriff’s Office uses Face Analysis Comparison & Examination System (FACES), which is operated by Pinellas County Sheriff's Office. A man in Florida was wrongfully arrested last year after a facial recognition system used by the police flagged him as a possible suspect. Robert Dillon was arrested in August of 2024 at his residence for attempting to lure a 12-year-old girl in Jacksonville Beach, some 300 miles away. Jacksonville Beach PD turned to the Jacksonville Sheriff’s Office for help, and JSO identified the 51-year-old man by comparing images from surveillance footage captured at the scene. After running it through facial recognition, the system returned a 93 percent match.","u":"https://www.biometricupdate.com/202507/florida-mans-facial-recognition-match-not-probable-cause-for-wrongful-arrest","d":"2024-07-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08","organization":"Jacksonville Sheriff’s Office, Pinellas County Sheriff's Office","aiSystem":"Facial recognition technology","affectedGroup":"Robert Dillon","action":"Facial recognition system flagged Robert Dillon as a possible suspect","consequence":"Robert Dillon was wrongfully arrested"}},{"i":"R1562","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"San francisco police hit with lawsuit over facial recognition use","s":"The lawsuit argues the city’s police have repeatedly flouted the ban and failed to submit proper documentation related to surveillance technologies. In 2019, San Francisco became the first city in the U.S. to ban facial recognition technology, forcing the police and other agencies to seek approvals for surveillance technology. A new lawsuit from a non-profit group argues, however, that the city’s police have repeatedly flouted the ban and failed to submit proper documentation related to surveillance technologies. The San Francisco Police Department (SFPD) has already come under scrutiny after a May report accused it of asking neighboring forces to search facial recognition database for them.","u":"https://www.biometricupdate.com/202407/san-francisco-police-hit-with-lawsuit-over-facial-recognition-use","d":"2024-07-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-19","organization":"San Francisco Police Department (SFPD)","aiSystem":"Facial recognition technology","affectedGroup":"People whose data was searched in facial recognition databases","action":"Used facial recognition technology to search for individuals' data","consequence":"Exposure to surveillance and potential misuse of personal data"}},{"i":"R1565","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Mcdonalds pauses ai voice ordering system developed with ibm","s":"Despite the shuttering of the IBM initiative, a statement makes it clear that voice-based ordering technology will be back under the golden arches soon enough. Despite claims that AI is infiltrating every corner of our lives , it will not be at the McDonald’s drive-through for the time being. The fast food chain has called off its two-year test of algorithmic, voice-activated automated order taking (AOT), which it ran in partnership with IBM CNBC reports on an email memo sent to franchisees announcing its plan to halt AOT at all 100 McDonald’s drive-throughs using it by July 26, 2024. Despite the shuttering of the IBM initiative, a statement from McDonald’s to CNBC makes it clear that voice-based ordering technology will be back under the golden arches soon enough.","u":"https://www.biometricupdate.com/202406/mcdonalds-pauses-ai-voice-ordering-system-developed-with-ibm","d":"2024-06-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-26","organization":"McDonald's","aiSystem":"Voice-based automated order taking system","affectedGroup":"Customers using the McDonald's drive-through service","action":"Halted the implementation of voice-activated automated order taking","consequence":"Experienced delays or inconvenience in ordering food"}},{"i":"R1568","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Clearview settles bipa lawsuit plaintiffs take 23 of company","s":"The arrangement appears to be spurred by the company's financial straits with the specter of a possible bankruptcy raised in the court filing. Settlements in biometric data privacy class action suits have taken several forms over the past several years, but a new agreement by Clearview AI takes the novel approach of giving plaintiffs a stake in the company in lieu of cash. Now a class of plaintiffs who appear in Clearview’s database of images scraped from public-facing websites is set to receive 23 percent of the company, according to a court document hosted by Reuters. Based on a valuation of $225 million, the settlement would be worth about $52 million.","u":"https://www.biometricupdate.com/202406/clearview-settles-bipa-lawsuit-plaintiffs-take-23-of-company","d":"2024-06-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-14","organization":"Clearview AI","aiSystem":"Facial recognition technology","affectedGroup":"People whose images were scraped from public-facing websites","action":"Used facial recognition technology to scrape images from public websites","consequence":"Plaintiffs receive a stake in the company instead of cash compensation"}},{"i":"R1570","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Online age checks blasted by us rights group researchers","s":"Online age checks are threatening Americans’ constitutional rights, according to a free speech advocacy group and a team of academics. Their position is being put to the test in courts of law and public opinion. A group of researchers from Princeton University, UNC Chapel Hill and Duke University, in particular, have received criticism for their dismissal of the availability of effective and privacy-preserving age assurance methods. The Foundation for Individual Rights and Expression (FIRE) is suing the state of Utah in federal court to have its second attempt at regulating age restrictions for social media tossed.","u":"https://www.biometricupdate.com/202406/online-age-checks-blasted-by-us-rights-group-researchers","d":"2024-06-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-07","organization":"Foundation for Individual Rights and Expression (FIRE)","aiSystem":"Online age checks","affectedGroup":"Individuals seeking to verify their age online","action":"Used online age checks to verify age","consequence":"Exposure to privacy risks and potential misuse"}},{"i":"R1573","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ice cbp sued for details on migrant data sharing agreements","s":"A campaigner for Access Now says it is unacceptable that ICE and CBP have not retrieved any meaningful information since we requested it in 2022. Digital rights advocacy group Access Now is suing the U.S. Customs and Border Protection (CBP) and Immigration and Customs Enforcement (ICE) agencies over delays in responding to requests made under the Freedom of Information Act (FOIA). A release on the organization’s website says the requests are meant to “clarify a number of concerns regarding the opaque and dangerous cross-border exchange of personal data of migrants, refugees, asylum seekers, and other people on the move, between the United States and various Latin American countries.”","u":"https://www.biometricupdate.com/202405/ice-cbp-sued-for-details-on-migrant-data-sharing-agreements","d":"2024-05-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-2024","organization":"U.S. Customs and Border Protection (CBP), Immigration and Customs Enforcement (ICE)","aiSystem":"Not specified in report","affectedGroup":"Migrants, refugees, asylum seekers, and other people on the move","action":"Delays in responding to FOIA requests","consequence":"Unclear and potentially harmful cross-border exchange of personal data"}},{"i":"R1577","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Us uk digital systems for immigration biometrics draw criticism","s":"Amnesty International says that the biometric asylum app CBP One created by the CBP fails to provide data privacy assurances. Amnesty International says that the biometric asylum app CBP One, created by the United States Customs and Border Protection, fails to provide data privacy assurances. The human rights organization notes that not only is turning CBP One into the only way to apply for asylum in the U.S. a violation of refugee rights, but its biometric capabilities also raise “serious concerns about privacy, surveillance, and potential discrimination.” The app was developed by President Joe Biden’s administration as a gateway to the U.S. asylum system for migrants who otherwise may resort to illegal migration.","u":"https://www.biometricupdate.com/202405/us-uk-digital-systems-for-immigration-biometrics-draw-criticism","d":"2024-05-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-13","organization":"United States Customs and Border Protection (CBP)","aiSystem":"CBP One biometric asylum app","affectedGroup":"Migrants applying for asylum","action":"Used to apply for asylum and collect biometric data","consequence":"Raises serious concerns about privacy, surveillance, and potential discrimination"}},{"i":"R1584","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"T mobile amazon and target hit with facial recognition lawsuits","s":"More companies familiar to consumers are getting hit with lawsuits for alleged violations of BIPA and New York's Biometric Identifier Information Law. More companies with household names familiar to consumers are getting hit with lawsuits for alleged violations of BIPA and New York’s Biometric Identifier Information Law. T-Mobile is facing a suit for its use of facial recognition for theft prevention in New York City stores. Target is similarly accused of violating BIPA for its use of facial recognition to prevent theft. Amazon faces its own BIPA lawsuit by collecting workers’ scans. T-Mobile used facial recognition for theft prevention in its stores in New York City, a class action lawsuit claims, according to Bloomberg Law Valeriia Borzenkova claims that the company collected her biometrics during visits to at least four different locations in the city without her consent.","u":"https://www.biometricupdate.com/202404/t-mobile-amazon-and-target-hit-with-facial-recognition-lawsuits","d":"2024-04-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-25","organization":"T-Mobile, Target, Amazon","aiSystem":"Facial recognition technology","affectedGroup":"Consumers, employees","action":"Used facial recognition for theft prevention","consequence":"Exposure to surveillance, lack of consent"}},{"i":"R1585","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Immigrant and civil rights groups urge govt to ban own use of frt limit private use","s":"Civil rights groups continue to call on the U.S. government to limit government and private use of facial recognition technology. Rights groups continue to call on the U.S. government to limit governmental use of facial recognition technology. Digital rights group Electronic Frontier Foundation (EFF) submitted comments to the U.S. Commission on Civil Rights, which is currently preparing a report on the use of face recognition technology (FRT) by federal agencies and its implications. The organization argues that the tech is not reliable enough to be used in decisions affecting constitutional and statutory rights or social benefits while facial recognition puts marginalized communities at risk and threatens privacy.","u":"https://www.biometricupdate.com/202404/immigrant-and-civil-rights-groups-urge-govt-to-ban-own-use-of-frt-limit-private-use","d":"2024-04-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-15","organization":"Civil rights groups, Electronic Frontier Foundation (EFF)","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"Marginalized communities","action":"Used in decisions affecting constitutional and statutory rights or social benefits","consequence":"Threatens privacy, puts marginalized communities at risk"}},{"i":"R1589","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Judge allows voice biometrics data privacy lawsuit against amazon to add plaintiffs","s":"A federal judge has sided with plaintiffs who want to amend their lawsuit against Amazon over alleged violations of Illinois’ Biometric Information Privacy Act. The ruling will allow plaintiffs to add more representatives to their class action. The case hinges on whether Amazon Web Services failed to gather the required informed consent when collecting voice biometrics from callers to financial institution John Hancock, for which it was providing call center services. The bank and Pindrop, which supplied its biometric software, have been removed from the case for lack of jurisdiction Attorneys for AWS argued in a letter that testimony on behalf of John Hancock shows that the voices of the three named plaintiffs were not analyzed with the biometric software, Law360 reports, rendering their claims meritless.","u":"https://www.biometricupdate.com/202404/judge-allows-voice-biometrics-data-privacy-lawsuit-against-amazon-to-add-plaintiffs","d":"2024-04-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-03","organization":"Amazon Web Services","aiSystem":"Voice biometric software","affectedGroup":"Plaintiffs and potential additional plaintiffs","action":"Collection and analysis of voice biometrics without informed consent","consequence":"Claims dismissed due to lack of consent"}},{"i":"R1593","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Cbp one app criticized over extra territorial biometrics collection","s":"Certain aliens leaving the U.S. will be asked to submit selfie biometrics and geolocation data through CBP One to prove they have left, sparking criticism. U.S. Customs and Border Protection’s biometric asylum app CBP One has come under attack over plans to expand the collection of biometrics from non-resident aliens leaving the United States. A new update to the app, which was publicized in the Federal Register in February, is planned to instruct certain aliens departing the U.S. to “voluntarily provide biographical data, facial images and geolocation.” Submitting a selfie photo with location data is supposed to serve as evidence that an individual has actually departed the country and is aimed at all travelers who receive an I-94 travel record.","u":"https://www.biometricupdate.com/202403/cbp-one-app-criticized-over-extra-territorial-biometrics-collection","d":"2024-03-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-08","organization":"U.S. Customs and Border Protection","aiSystem":"CBP One (biometric asylum app)","affectedGroup":"Non-resident aliens leaving the United States","action":"Collecting biometric data (facial images and geolocation) from departing aliens","consequence":"Potential misuse of collected data for extra-territorial purposes"}},{"i":"R1596","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Detroit police sued over alleged facial recognition use in another wrongful arrest","s":"Another alleged false arrest based on a facial recognition match has led to a lawsuit in Michigan, while researchers say police FRT use reduces the murder rate. Detroit police are being sued by a woman who claims she is the victim of wrongful arrest prompted by a facial recognition match. Detroit Police say facial recognition was not used in the case. The lawsuit highlights the tension between concerns that law enforcement use of facial recognition will increase false arrests of people with dark skin and concerns that without it, crime will spiral out of control. A pair of researchers affiliated with Georgia State University write in an editorial for The Washington Post that homicide rates have fallen significantly over time in places in the U.S. where police use facial recognition, relative to elsewhere.","u":"https://www.biometricupdate.com/202502/detroit-police-sued-over-alleged-facial-recognition-use-in-another-wrongful-arrest","d":"2024-02-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-28","organization":"Detroit Police Department","aiSystem":"Facial recognition technology","affectedGroup":"Individuals with dark skin","action":"Used facial recognition to identify people","consequence":"Led to a wrongful arrest"}},{"i":"R1598","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Unforeseen algorithm problems give google a gemini migraine","s":"Google's text-to-image AI has suspended the creation of images of people, but not in recognition of its potential as a fraud tool. If this is what AI is doing in its pre-school years, its teen years should be a scream. Google executives are trying to appear forthcoming and responsive about troubling responses from its Gemini conversational app. Recent responses – at least those getting the most attention – seemed specifically designed to enrage U.S. nativists. Until further notice, Gemini will not generate images of people. The problem is that a new, and apparently faulty, image generation feature was added to Gemini three weeks ago that.","u":"https://www.biometricupdate.com/202402/unforeseen-algorithm-problems-give-google-a-gemini-migraine","d":"2024-02-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-26","organization":"Google","aiSystem":"text-to-image AI","affectedGroup":"People","action":"Generated images of people","consequence":"Suspension of image generation"}},{"i":"R1605","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Latest false arrest involving facial recognition in us sure to fuel backlash","s":"Another arrest in the United States that relied on facial recognition has resulted in a horror story of misidentification and a lawsuit. The mistaken identification appears to have been made first by retail security professionals, rather than police, The Guardian reports. A robbery at a Sunglass Hut in Houston, Texas was robbed at gunpoint by two men. In the aftermath of the robbery, an employee of Sunglass Hut parent company EssilorLuxottica contacted Macy’s, which is a retail partner of the company, as part of its investigation, according to the lawsuit filed by Harvey Eugene Murphy Jr. Footage from security cameras that the lawsuit claims are low-quality was fed into a facial recognition system, which returned Murphy as a match, and also linked him to two other robberies.","u":"https://www.biometricupdate.com/202401/latest-false-arrest-involving-facial-recognition-in-us-sure-to-fuel-backlash","d":"2024-01-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-24","organization":"EssilorLuxottica (Sunglass Hut parent company)","aiSystem":"Facial recognition system","affectedGroup":"Harvey Eugene Murphy Jr.","action":"Facial recognition system matched Murphy to footage from security cameras","consequence":"Murphy was falsely arrested"}},{"i":"R1606","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Senators ask doj if federal facial recognition funding violates civil rights","s":"The history of misidentifications with facial recognition by police is an expression of bias that remains technically embedded in facial recognition systems. A group of 18 American senators from the Democratic Caucus have written to the Department of Justice to express concerns that funding for facial recognition programs could contribute to civil rights violations. Senator Reverend Raphael Warnock (D-GA), Senate Judiciary Committee Chair Richard Durbin and 16 other senators pose eight questions to the DoJ about what assurances Americans have that federal funds aren’t violating Title VI of the Civil Rights Act. Their concerns are sparked by the recent news about the false arrest of Randal Quran Reid and five other cases where facial recognition has been used prior to arrests of innocent Black people.","u":"https://www.biometricupdate.com/202401/senators-ask-doj-if-federal-facial-recognition-funding-violates-civil-rights","d":"2024-01-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-23","organization":"Department of Justice (DoJ)","aiSystem":"Facial recognition technology","affectedGroup":"American citizens, particularly Black individuals","action":"Facial recognition technology used in law enforcement","consequence":"Potential civil rights violations"}},{"i":"R1609","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Still no certainty about legality of forced biometric phone unlocks in us","s":"An analysis of the topic by the libertarian thinktank the Independent Institute sketches an unsettled legal landscape in the Uited States. Speaking to a reporter in the U.S., a law professor recently said he doesn’t use biometric locks on his phone because it’s possible that police could force a scan when investigating a crime. Passcodes remain relatively safe from compelled police access under the Constitution’s Fifth Amendment preserving a person’s right not to incriminate themselves. Judges and legislators have yet to find similar consensus on biometrics , however. The professor, Matthew Tokson at the University of Utah, who raised the sanctity of biometric locks, was commenting on a state supreme court decision in December that prevents police from compelling someone to give up their device’s passcode.","u":"https://www.biometricupdate.com/202401/still-no-certainty-about-legality-of-forced-biometric-phone-unlocks-in-us","d":"2024-01-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-05","organization":"Not specified in report","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"Individuals","action":"Police forced a scan of a biometric lock on a phone","consequence":"Exposure to privacy risks"}},{"i":"R1611","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Privacy advocates concerned as new mexico seeks further investment in mass surveillance","s":"Albuquerque officials are seeking additional funding to support the city’s real-time crime center, which has seen a number of surveillance tech upgrades. In Albuquerque, New Mexico, officials are seeking additional funding to support the city’s real-time crime center, which has seen a number of major surveillance tech upgrades since its inception over a decade ago. While the city credits the system for addressing heightened crime rates, critics worry that police may rely too heavily on the system and have voiced privacy concerns, according to The Hill Last week, Albuquerque police gave members of the media an inside look at the center, revealing how 10,000 cameras installed throughout the city deliver live feed surveillance for real-time review.","u":"https://www.biometricupdate.com/202312/privacy-advocates-concerned-as-new-mexico-seeks-further-investment-in-mass-surveillance","d":"2023-12-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-20","organization":"Albuquerque police department","aiSystem":"Real-time crime center with surveillance technology","affectedGroup":"General public","action":"Delivers live feed surveillance for real-time review","consequence":"Exposure to surveillance and tracking"}},{"i":"R1612","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Rite aids proposed biometrics ban would sideline it for five years","s":"A proposed U.S. regulatory settlement between Rite Aid and the Federal Trade Commission would sideline the national pharmacy chain in facial recognition. for five years. The FTC has proposed a five-year ban on the use of face-scan surveillance at financially struggling Rite Aid. The regulator alleges that the pharmacy chain has been “reckless” in how it searches for shoplifters using face recognition surveillance systems. Company executives deny wrongdoing in the proposed settlement. They also say Rite Aid stopped using the software more than three years ago, when a pilot ended. The software is inaccurate and biased, according to the commission, and Rite Aid misrepresented how it managed the data collected.","u":"https://www.biometricupdate.com/202312/rite-aids-proposed-biometrics-ban-would-sideline-it-for-five-years","d":"2023-12-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-20","organization":"Rite Aid","aiSystem":"Facial recognition technology","affectedGroup":"Shoplifters","action":"Used facial recognition surveillance systems to search for shoplifters","consequence":"Denied access to financial assistance for five years"}},{"i":"R1614","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uns counter terrorist travel biometrics poses human rights risk special rapporteur","s":"The United Nations’ travel surveillance system, which collects biometric data to track down terrorists, should be paused and urgently reviewed. The United Nations’ travel surveillance system, which collects biometric data to track down terrorists, should be paused and “urgently reviewed,” according to a UN Special Rapporteur. The warning was issued in a position paper at the end of October by Fionnuala Ní Aoláin, who recently ended her term. An analysis of the paper was published this week by Statewatch, a UK-based non-governmental organization. The UN Countering Terrorist Travel Programme (CTTP) was launched in 2019 to help exchange traveler information such as Passenger Name Records (PNR) and Advanced Passenger Information (API) among law enforcement agencies.","u":"https://www.biometricupdate.com/202312/uns-counter-terrorist-travel-biometrics-poses-human-rights-risk-special-rapporteur","d":"2023-12-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10","organization":"United Nations","aiSystem":"UN Countering Terrorist Travel Programme (CTTP)","affectedGroup":"Travelers","action":"collects biometric data","consequence":"exposed to surveillance and tracking"}},{"i":"R1616","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Are us border officers using lexisnexis facial recognition service washingtons not saying","s":"A small United States government contract with a previously anodyne data broker is tripping alarms with surveillance watchdogs. A small U.S. government contract with a previously anodyne data broker is tripping alarms with surveillance watchdogs. Reporting by investigative publisher The Intercept indicates that Customs and Border Protection signed a $15.9 million, five-year surveillance-services contract in December that included facial recognition. The contract went to LexisNexis, a data broker well known in U.S. business and research markets. The border is getting dense with biometrics The contract was for a bundle of surveillance tools that use personal data.","u":"https://www.biometricupdate.com/202311/are-us-border-officers-using-lexisnexis-facial-recognition-service-washingtons-not-saying","d":"2023-11-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12","organization":"Customs and Border Protection (CBP)","aiSystem":"Facial recognition technology","affectedGroup":"People crossing the U.S. border","action":"Used facial recognition to surveil people crossing the border","consequence":"Increased surveillance presence at the border"}},{"i":"R1620","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Lawsuit filed in us cross country arrest allegedly based on face biometrics","s":"A federal suit in the U.S. has been filed by a Black man who says he was falsely accused of credit-card fraud using a police facial recognition algorithm. Damages have not been made public. According to the Associated Press, Randal Quran Reid was taken from his car after being arrested along an interstate in his home state of Georgia. A warrant issued hundreds of miles away by parish police in the state of Louisiana had been issued, according to Reid, based on misuse of face-matching software. The plaintiff claims facial recognition software was the sole “credible source” used by Louisiana police to issue a warrant.","u":"https://www.biometricupdate.com/202309/lawsuit-filed-in-us-cross-country-arrest-allegedly-based-on-face-biometrics","d":"2023-09-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-26","organization":"Louisiana police department","aiSystem":"facial recognition algorithm","affectedGroup":"Black man","action":"issued a warrant based on misuse of face-matching software","consequence":"false arrest and detention"}},{"i":"R1624","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Chatgpt facial recognition potential makes openai nervous","s":"OpenAI is not ready to roll out facial recognition or analysis features for public use as it may invite legal issues in some jurisdictions. ChatGPT, the artificial intelligence-powered large language model, can analyze images including recognizing and describing people’s faces. But OpenAI , the company behind the chatbot, says that it is not ready to roll out facial recognition or analysis features for public use as it may invite legal issues in jurisdictions that require consent for using biometric data. The image analysis feature is part of the advanced version of the software called GPT-4 which was announced back in March.","u":"https://www.biometricupdate.com/202307/chatgpt-facial-recognition-potential-makes-openai-nervous","d":"2023-07-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-20","organization":"OpenAI","aiSystem":"Facial recognition technology","affectedGroup":"Individuals whose faces are analyzed","action":"Facial recognition technology analyzed images including people's faces","consequence":"Potential legal issues and privacy violations"}},{"i":"R1625","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Use of face biometrics sharply criticized in two us criminal cases","s":"A Minnesota man has filed a civil rights lawsuit against police alleging false arrest, which officials have blamed on facial recognition. Kylese Perryman, 21, has filed a federal civil rights lawsuit against two police agencies in the U.S. state of Minnesota following his allegedly false arrest, reportedly based on flawed use of facial recognition. Perryman, a Black man, said his rights were violated by police from the city of Bloomington and deputies from the Hennepin County Sheriff’s office after he was wrongly identified as a suspect in a robbery and a carjacking, says CBS News Minnesota Hennepin County prosecutors charged Perryman and he spent five days in jail, according to CBS, and 30 days at home being monitored.","u":"https://www.biometricupdate.com/202306/use-of-face-biometrics-sharply-criticized-in-two-us-criminal-cases","d":"2023-06-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-29","organization":"Police agencies in the U.S. state of Minnesota","aiSystem":"Facial recognition technology","affectedGroup":"Kylese Perryman, a Black man","action":"Facial recognition technology was used to identify Perryman as a suspect in a robbery and a carjacking","consequence":"False arrest resulting in a five-day detention and thirty-day home monitoring"}},{"i":"R1626","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Pair of us politicians want face biometrics ripped out of public housing","s":"A pair of United States Representatives have issued a statement saying biometric surveillance does not increase stability and fairness in public housing. Public housing officials around the world using biometric surveillance is largely the same as police using it except in one respect – the people being surveilled in public housing are virtually all poor. That makes any use of facial recognition in subsidized housing unacceptable, if not always by residents themselves then by advocates of the underprivileged. A pair of United States Representatives, Maxine Waters from California and Ayanna Pressley from the state of Massachusetts, have issued a statement saying biometric surveillance does not increase “stability and fairness” in public housing.","u":"https://www.biometricupdate.com/202306/pair-of-us-politicians-want-face-biometrics-ripped-out-of-public-housing","d":"2023-06-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-05","organization":"Public housing officials","aiSystem":"Facial recognition technology","affectedGroup":"People living in public housing","action":"Used facial recognition to identify people","consequence":"Exposure to surveillance and tracking"}},{"i":"R1628","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Amazon immune to bipa this time biometric privacy suit filed against pimeyes","s":"A federal judge in Illinois has dismissed a class action under BIPA against Amazon over its Rekognition face recognition tool. A federal judge in the U.S. state of Illinois has dismissed a class action under the Biometric Information Privacy Act ( BIPA ) against Amazon over its Rekognition facial recognition tool. The Cook County Circuit Court sided with Amazon Web Services, which claimed it cannot be sued in Illinois because it does not operate in the state – instead, its product is deployed through another company, called Wonolo The case was brought by Cynthia Redd who used job search firm Wonolo in 2020 to find temporary work, the Cook Country Record reported Tuesday.","u":"https://www.biometricupdate.com/202305/amazon-immune-to-bipa-this-time-biometric-privacy-suit-filed-against-pimeyes","d":"2023-05-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-25","organization":"Amazon Web Services","aiSystem":"Rekognition facial recognition tool","affectedGroup":"Job applicants","action":"Used Rekognition facial recognition tool to monitor job applicants","consequence":"Exposure to biometric data collection without consent"}},{"i":"R1631","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Gender race bias risk reported in biometrics used by us labor department","s":"An alert issued by the IG is raising urgent equity and security concerns about the use of facial recognition in processing UI claims. An alert issued by the inspector general (IG) of the U.S. Department of Labor is raising “urgent equity and security concerns” about the use of facial recognition in processing unemployment insurance (UI) claims, according to IT industry marketing firm MeriTalk The memo , issued March 31, emphasizes the need for “immediate attention” to address risks of racial and gender bias in facial recognition tools being provided by identity verification contractors. “In 2019, the National Institute of Standards and Technology’s (NIST) Information Technology Laboratory reported that it found empirical evidence the algorithms used in current facial recognition technology have a racial and gender bias,” the memo reads.","u":"https://www.biometricupdate.com/202304/gender-race-bias-risk-reported-in-biometrics-used-by-us-labor-department","d":"2023-04-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-31","organization":"U.S. Department of Labor","aiSystem":"Facial recognition technology","affectedGroup":"People applying for unemployment benefits","action":"Facial recognition technology was used to process unemployment insurance claims","consequence":"Racial and gender bias in facial recognition tools"}},{"i":"R1633","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"2026 07 31 anthropic says claude ai hacked three companies during cyber tests","s":"July 30 (Reuters) - Anthropic said on Thursday its AI model Claude hacked into the systems of three companies during testing after a configuration error gave it internet access, days after rival OpenA…. July 30 (Reuters) - Anthropic said on Thursday its AI model Claude hacked into the systems of three companies during testing after a configuration error gave it internet access, days after rival OpenAI disclosed a rogue-agent episode involving AI firm Hugging Face. Anthropic said a misconfiguration allowed Claude models to reach the internet from testing environments that were supposed to be isolated, leading to unauthorized access to three organizations’ systems.","u":"https://www.dailymaverick.co.za/article/2026-07-31-anthropic-says-claude-ai-hacked-three-companies-during-cyber-tests/","d":"2026-07-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-30","organization":"Anthropic","aiSystem":"Claude AI model","affectedGroup":"Three companies' systems","action":"Hacked into the systems","consequence":"Unauthorized access to systems"}},{"i":"R1634","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"2026 06 23 five eyes intelligence alliance warns that new ai models pose urgent cyber risk","s":"WASHINGTON, June 22 (Reuters) - Cutting-edge artificial intelligence technology is poised to supercharge offensive hacking capabilities and urgent action is needed to face up to the threat, US, Britis…. WASHINGTON, June 22 (Reuters) - Cutting-edge artificial intelligence technology is poised to supercharge offensive hacking capabilities and urgent action is needed to face up to the threat, US, British, Canadian, Australian and New Zealand officials said on Monday. The intelligence alliance commonly known as the “Five Eyes” said in a three-page statement that, “Frontier AI models are anticipated to exceed current industry expectations, fundamentally transforming both offensive and defensive cyber capabilities.","u":"https://www.dailymaverick.co.za/article/2026-06-23-five-eyes-intelligence-alliance-warns-that-new-ai-models-pose-urgent-cyber-risk/","d":"2026-06-23","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-06-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-22","organization":"US, British, Canadian, Australian and New Zealand officials","aiSystem":"Frontier AI models","affectedGroup":"Cybersecurity professionals and national security agencies","action":"Warn of potential misuse of advanced AI in offensive hacking","consequence":"Potential escalation of cyber threats and need for immediate action"}},{"i":"R1635","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"2026 04 21 meta to start capturing employee mouse movements keystrokes for ai training data","s":"NEW YORK, April 21 (Reuters) - Meta META.O is installing new tracking software on U.S.-based employees’ computers to capture mouse movements, clicks and keystrokes for use in training its artificial i…. NEW YORK, April 21 (Reuters) - Meta META.O is installing new tracking software on U.S.-based employees’ computers to capture mouse movements, clicks and keystrokes for use in training its artificial intelligence models, part of a broad initiative to build AI agents that can perform work tasks autonomously, the company told staffers in internal memos seen by Reuters. The tool, called Model Capability Initiative (MCI), will run on work-related apps and websites and will also take occasional snapshots of the content on employees’ screens, according to one of the memos, posted by a staff AI research scientist on Tuesday in a channel for the company's model-building Meta SuperIntelligence…","u":"https://www.dailymaverick.co.za/article/2026-04-21-meta-to-start-capturing-employee-mouse-movements-keystrokes-for-ai-training-data/","d":"2026-04-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-21","organization":"Meta","aiSystem":"artificial intelligence models","affectedGroup":"U.S.-based employees","action":"installing new tracking software to capture mouse movements, clicks and keystrokes","consequence":"privacy intrusion"}},{"i":"R1637","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"2026 02 16 how deepfakes and erapes became childrens new normal","s":"Grok’s recent frenzied creation and sharing of deepfake pornography through X’s public platform confirmed what activists have known for years. The technology to digitally undress women and children an…. The technology to digitally undress women and children and create e-rape content is easily accessible, largely free, gamified and difficult to police, and neither those responsible for ‘nudifying’ technology or those creating the images think it’s a big deal. Warning: this article contains disturbing content about sexual violence and child sexual abuse material. As 2025 ended, social media platform X was suddenly flooded with nonconsensual images of people stripped down to bikinis.","u":"https://www.dailymaverick.co.za/article/2026-02-16-how-deepfakes-and-erapes-became-childrens-new-normal/","d":"2026-02-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-31","organization":"Social media platform X","aiSystem":"Deepfake technology","affectedGroup":"People","action":"Generated and shared non-consensual images of people stripped down to bikinis","consequence":"Exposure to online sexual violence"}},{"i":"R1649","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.4  Supply chain / investor complicity harm"],"t":"European money pours into palantir over 100 asset managers and banks boost their investments in the controversial tech company","s":"Investors across the continent have already put more than $27 billion into this leader in military-grade AI that has been accused of numerous human rights violations. Over the past year, major European banks and asset managers have dramatically increased their investments in Palantir, the controversial U.S. technology company. This is despite the firm’s links to serious human rights violations. The company provides services to the U.S. Immigration and Customs Enforcement agency (ICE) and to the Israeli army in the Palestinian territories. In 2020, Amnesty International denounced the company for failing to comply with international standards, while the consulting firm MSCI gave it a score of two out of 10 for “civil liberties” and “human rights” in a recent benchmark report for institutional investors worldwide.","u":"https://english.elpais.com/economy-and-business/branded/2026-04-11/european-money-pours-into-palantir-over-100-asset-managers-and-banks-boost-their-investments-in-the-controversial-tech-company.html","d":"2026-04-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020","organization":"Palantir","aiSystem":"Military-grade AI provided by Palantir","affectedGroup":"Individuals","action":"Providing services to ICE and Israeli army","consequence":"Links to serious human rights violations"}},{"i":"R1652","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ices facial recognition app draws scrutiny over errors and increased state surveillance","s":"Amid negotiations over funding for the Department of Homeland Security, a separate bill seeks to prohibit the agency from acquiring and using biometric identification systems on the general population. A federal agent stops a car during a “routine” traffic stop amid the Trump administration’s anti-immigrant crackdown The driver rolls down the window, and before asking for any documents, the officer takes a picture of the person behind the wheel. Or perhaps, during an immigration raid, some neighbors try to prevent masked agents from entering a private residence without a warrant, and a confrontation ensues. The agents restrain a witness, and while the person is still struggling on the ground, they point a cell phone camera at them and take a picture.","u":"https://english.elpais.com/usa/2026-02-12/ices-facial-recognition-app-draws-scrutiny-over-errors-and-increased-state-surveillance.html","d":"2026-02-12","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-12","organization":"Federal agents and ICE (Immigration and Customs Enforcement)","aiSystem":"Facial recognition technology","affectedGroup":"Immigrants and witnesses","action":"Taking pictures of individuals","consequence":"Increased state surveillance and potential misuse of technology"}},{"i":"R1653","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Tech giants revive nuclear power plants to meet the needs of their data centers","s":"Barclays places technology at the heart of the ‘nuclear renaissance.’ Amazon, Google, Microsoft, and Meta are also launching plans in this area. The tech giants’ approach to nuclear energy is evolving. Amazon, Microsoft, Meta, and Alphabet have all entered into projects to use this form of energy to increase the supply of data centers , which have enormous growth forecasts for the coming years as a result of the implementation of artificial intelligence (AI), thanks to tools like ChatGPT , which already has hundreds of millions of users. And OpenAI’s flagship app won’t be the only one that will boost data center use.","u":"https://english.elpais.com/technology/2025-10-23/tech-giants-revive-nuclear-power-plants-to-meet-the-needs-of-their-data-centers.html","d":"2025-10-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-23","organization":"Amazon, Microsoft, Meta, Alphabet, and OpenAI","aiSystem":"ChatGPT and other AI-powered applications","affectedGroup":"Hundreds of millions of users","action":"Used to boost data center use","consequence":"Increased privacy risks"}},{"i":"R1654","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ice intensifies surveillance of immigrants with facial recognition programs human tracking and social media monitoring","s":"The federal agency’s activity has raised concerns about whether spying on undocumented foreigners will be extended to political dissidents in Washington. Immigration and Customs Enforcement (ICE) is ramping up its surveillance capabilities to advance the government’s immigration agenda on an unprecedented scale. According to the federal spending site USASpending.gov , the agency signed contractual obligations in September for a $1.4 billion order — the highest in 18 years — for the acquisition of new technologies such as an iris-scanning app they plan to use in the field, spyware that can remotely hack smartphones, and location software that can track phone activity without a warrant, including nearly all social media platforms.","u":"https://english.elpais.com/usa/2025-10-21/ice-intensifies-surveillance-of-immigrants-with-facial-recognition-programs-human-tracking-and-social-media-monitoring.html","d":"2025-10-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-21","organization":"Immigration and Customs Enforcement (ICE)","aiSystem":"Facial recognition technology, spyware, location software","affectedGroup":"Undocumented foreigners, political dissidents","action":"Ramping up surveillance capabilities","consequence":"Potential extension of surveillance to political dissidents, increased tracking capabilities"}},{"i":"R1656","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Dead internet theory gains ground amid rise of ai generated content","s":"OpenAI CEO Sam Altman has expressed concern about the content created by bots, which facilitate misinformation. “I had desired it with an ardor that far exceeded moderation; but now that I had finished, the beauty of the dream vanished, and breathless horror and disgust filled my heart.” This is Dr. Frankenstein’s reaction to his own creation in Mary Shelley’s 1818 novel, known by the scientist’s surname or as The Modern Prometheus A similar vertigo has been experienced by Sam Altman , CEO of OpenAI. The head of the company behind one of the most sophisticated artificial intelligence (AI) developments has begun to consider the “dead internet” theory, which argues that automatically generated content will eventually surpass human-created content — multiplying the risks of manipulation, disinformation, and intentional behavioral conditioning. i never took the dead internet theory that…","u":"https://english.elpais.com/technology/2025-09-20/dead-internet-theory-gains-ground-amid-rise-of-ai-generated-content.html","d":"2025-09-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-20","organization":"OpenAI","aiSystem":"Automatically generated content","affectedGroup":"People exposed to misleading information","action":"Generated exploitative content","consequence":"Exposure to misleading content"}},{"i":"R1657","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Chatgpt dissidents the students who refuse to use ai i couldnt remember the last time i had written something by myself","s":"Some college students are beginning to limit their use of artificial intelligence, so as not to hinder their own creativity, discipline and critical thinking. “I started using ChatGPT in my second year of college, during a very stressful time juggling internships, assignments, studies and extracurricular activities. To ease this burden, I began using it on small assignments. And, little by little, I realized [that it was remembering] details about my writing style and my previous texts. So, I quickly integrated it into everything… my work [became] as easy as clicking a button,” explains Mónica de los Ángeles Rivera Sosa, a 20-year-old Political Communications student at Emerson College in Boston, Massachusetts.","u":"https://english.elpais.com/technology/2025-08-03/chatgpt-dissidents-the-students-who-refuse-to-use-ai-i-couldnt-remember-the-last-time-i-had-written-something-by-myself.html","d":"2025-08-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-03","organization":"Emerson College","aiSystem":"ChatGPT","affectedGroup":"Students, particularly those in Political Communications","action":"Used ChatGPT to generate content","consequence":"Limited their own creativity, critical thinking, and self-expression"}},{"i":"R1658","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Immigrationos by palantir trumps new tool to completely monitor immigrants lives","s":"Experts says the controversial software, which collects biographical, biometric, and geolocation information, violates fundamental human rights. The United States Immigration and Customs Enforcement (ICE) has signed a $29.8 million contract with the tech company Palantir to develop software that tracks information on immigrants who are either in the country without permission or whose visas have expired, with the aim of facilitating deportations, according to 404 Media. Organizations such as Amnesty International and legal experts consider the measure a violation of human rights. “An aberration,” says Ricard Martínez, director of the Chair of Privacy and Digital Transformation at the University of Valencia in Spain.","u":"https://english.elpais.com/usa/2025-04-25/immigrationos-by-palantir-trumps-new-tool-to-completely-monitor-immigrants-lives.html","d":"2025-04-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-25","organization":"United States Immigration and Customs Enforcement (ICE)","aiSystem":"Palantir-developed tracking software","affectedGroup":"Immigrants who are either in the country without permission or whose visas have expired","action":"tracks information on immigrants","consequence":"violates fundamental human rights, facilitates deportations"}},{"i":"R1660","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Us admits data centers are harmful to health","s":"One of the latest executive orders signed by Joe Biden prohibits these infrastructures from being built in areas with a high risk of cancer due to pollution. The rise of artificial intelligence over the past two years has sparked a frenzy in the construction of data centers , the infrastructure that powers this technology. While China’s DeepSeek has demonstrated that AI models can be developed with fewer resources, U.S. President Donald Trump, in his first week in office, unveiled an ambitious plan to mobilize $500 billion over four years to build data centers and ensure they have a reliable energy supply. However, the rapid growth of this market in the U.S. is beginning to strain the country’s energy grid, which is now seeking creative solutions — including the authorization of small modular nuclear reactors — to meet rising demand.","u":"https://english.elpais.com/technology/2025-02-07/us-admits-data-centers-are-harmful-to-health.html","d":"2025-02-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-07","organization":"U.S. government","aiSystem":"Not specified in report","affectedGroup":"People living near data centers","action":"Authorized small modular nuclear reactors to address energy demand","consequence":"Strain on the country's energy grid leading to potential health risks"}},{"i":"R1662","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Chatgpt is right wing and gemini is left wing why each ai has its own ideology","s":"A study confirms that no major language model is neutral and that its biases tend to be constant in the same direction. “Overall, OpenAI models [behind ChatGPT] display a particular ideological stance, in contrast to the more progressive and human rights-oriented preferences of other Western models,” says a new study on the ideology of large language models (LLM). It concludes that each artificial intelligence (AI) model reflects the opinions of its creators. ChatGPT is less fond of supranational organisations — such as the United Nations or the EU — and welfare policies, which are two concepts dear to the left. Gemini , Google’s AI, instead displays “a strong preference for social justice and inclusivity.”","u":"https://english.elpais.com/technology/2024-11-28/chatgpt-is-right-wing-and-gemini-is-left-wing-why-each-ai-has-its-own-ideology.html","d":"2024-11-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-28","organization":"OpenAI (behind ChatGPT), Google (behind Gemini)","aiSystem":"Large Language Models (LLM)","affectedGroup":"Supranational organisations (e.g., UN, EU), welfare policies","action":"Reflect the opinions of their creators","consequence":"Display a particular ideological stance, favoring right-wing views over left-wing ones"}},{"i":"R1664","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"The dead end of chips manufacturing semiconductors consumes as much energy as entire countries","s":"Experts warn that the surging demand for microprocessors is becoming an increasingly big obstacle for the green transition. The first half of 2024 marked a high point for Nvidia , the leading U.S. company in the chip industry. The firm tripled its global shipments of semiconductors, underscoring a prevailing truth of our time: the world is hungry for this tiny technology. However, the production of these semiconductors faces a significant challenge: the growing demand for electrical energy required for their manufacture. Experts warn that fulfilling the surging market demand for microprocessors may hinder the green transition.","u":"https://english.elpais.com/economy-and-business/2024-10-30/the-dead-end-of-chips-manufacturing-semiconductors-consumes-as-much-energy-as-entire-countries.html","d":"2024-10-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-30","organization":"Nvidia (U.S. company in the chip industry)","aiSystem":"Microprocessors","affectedGroup":"The environment/society","action":"Manufacture of semiconductors","consequence":"Hinders the green transition"}},{"i":"R1666","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Artificial intelligence will affect 60 million us and mexican jobs within the year","s":"IDB study shows the impact that AI will have on the labor market. Women and low-skilled workers are more vulnerable to being replaced. Artificial intelligence’s impact on our lives is already well-known, but now, its most feared consequences related to the job market are setting off alarms. An innovative index created by the Inter-American Development Bank shows that in the United States, 43 million jobs will be affected by the introduction of AI in the space of just one year. In Mexico, that figure stands at 16 million jobs. Over the next five years, those numbers will rise to 60 and 22 million, respectively. In the space of a decade, 70 million jobs in the U.S. will suffer, along with 26 million in its neighboring country.","u":"https://english.elpais.com/economy-and-business/2024-09-15/artificial-intelligence-will-affect-60-million-us-and-mexican-jobs-within-the-year.html","d":"2024-09-15","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-09-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-15","organization":"Inter-American Development Bank (IDB)","aiSystem":"Artificial intelligence","affectedGroup":"Women and low-skilled workers","action":"Jobs will be affected by the introduction of AI","consequence":"Being replaced"}},{"i":"R1667","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"The court decision that could turn generative ai upside down","s":"A federal judge will hear a class-action lawsuit filed by illustrators seeking royalties from companies that used their work to train their algorithms. One of the big, unresolved issues surrounding generative artificial intelligence revolves around copyrights. In order to function, the tools require billions of texts, images and videos, from which they extract patterns that allow them to create apparently original images. Many creators and artists complain that the companies responsible for the AI models use their work without their consent — some have even recognized their personal style in specific AI creations.","u":"https://english.elpais.com/technology/2024-08-29/the-court-decision-that-could-turn-generative-ai-upside-down.html","d":"2024-08-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-29","organization":"Companies that use generative AI tools","aiSystem":"Generative artificial intelligence","affectedGroup":"Illustrators, creators, and artists","action":"Used illustrators' and creators' work to train algorithms","consequence":"Complaints of unauthorized use and recognition of personal style in AI creations"}},{"i":"R1668","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Latino voters are more of a target for ai generated fake news","s":"Juan Rosa, from the National Association of Latino Elected and Appointed Officials Educational Fund, warns of the risks that artificial intelligence will pose to the community in the November elections. Juan Rosa, 39, has a clear objective for the next five months: educate Latino voters about the risk posed by artificial intelligence (AI) in the face of the first U.S. presidential elections in the era of this technology. He will do so from his role as national director of civic engagement for the National Association of Latino Elected and Appointed Officials (NALEO) Educational Fund. It’s no easy task: 36 million Latinos will be able to vote on November 5, a record number.","u":"https://english.elpais.com/usa/elections/2024-06-11/latino-voters-are-more-of-a-target-for-ai-generated-fake-news.html","d":"2024-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-11","organization":"National Association of Latino Elected and Appointed Officials Educational Fund","aiSystem":"AI-generated fake news","affectedGroup":"Latino voters","action":"Educate Latino voters about the risk of AI-generated fake news","consequence":"Exposure to misleading information"}},{"i":"R1671","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Deepfakes accelerate cryptocurrency scams it is very easy to fall for them they are becoming more and more sophisticated","s":"Online fraud has multiplied in recent months due to the lack of moderation on the social media platform X and the use of artificial intelligence. No journalist working with Spain’s public broadcaster TVE is really encouraging viewers to invest in a “super platform” with ties to the energy company Repsol. And yet a video showing the news presenter Marina Ribel apparently pushing this product during a newscast has been circulating in recent days on Instagram. In the video, shared on Instagram stories, Ribel appears to be on the set of Canal 24 Horas reading out the news of the day: “The company Repsol has announced the creation of a new super platform thanks to which any Spaniard can forget about having to work.”","u":"https://english.elpais.com/technology/2024-02-08/deepfakes-accelerate-cryptocurrency-scams-it-is-very-easy-to-fall-for-them-they-are-becoming-more-and-more-sophisticated.html","d":"2024-02-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-08","organization":"Social media platform X","aiSystem":"Deepfake technology","affectedGroup":"Viewers, particularly those interested in investing","action":"Produced and distributed misleading financial content","consequence":"Increased online fraud and investment scams"}},{"i":"R1672","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Authorities target two texas firms in probe of ai generated robocalls before new hampshires primary","s":"New Hampshire issued cease-and-desist orders and subpoenas to both companies and said the calls as the clearest and possibly first known attempt to use AI to interfere with an election in the U.S. Authorities issued cease-and-desist orders Tuesday against two Texas companies they believe were connected to robocalls that used artificial intelligence to mimic President Joe Biden’s voice and discourage people from voting in New Hampshire’s first-in-the-nation primary last month. New Hampshire Attorney General John Formella said investigators have identified the source of the calls as Life Corporation and said they were transmitted by a company called Lingo Telecom. New Hampshire issued cease-and-desist orders and subpoenas to both companies, while the Federal Communications Commission issued a cease-and-desist letter to the telecommunications company, Formella said.","u":"https://english.elpais.com/usa/2024-02-06/authorities-target-two-texas-firms-in-probe-of-ai-generated-robocalls-before-new-hampshires-primary.html","d":"2024-02-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-06","organization":"Life Corporation and Lingo Telecom","aiSystem":"Artificial intelligence (AI)","affectedGroup":"Voters in New Hampshire's first-in-the-nation primary","action":"Used AI to generate and transmit robocalls mimicking President Joe Biden’s voice","consequence":"Interfered with the election process by discouraging people from voting"}},{"i":"R1674","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Joe biden impersonated in deepfake call to disrupt new hampshire primary","s":"The Attorney General’s Office is investigating a robocall, allegedly made with AI, that discouraged voters from taking part in the vote on Tuesday. Social media has revolutionized political communication, for better and for worse. Fake news and misinformation has been spreading online at lightening speed and has already interfered in several elections With recent tech advances and artificial intelligence’s ability to create deepfakes and realistically impersonate people, there is even greater danger today. These threats were made evident in New Hampshire, which will hold presidential primaries on Tuesday The state’s Attorney General’s Office announced on Monday that it is investigating complaints that a robocall used AI to mimic U.S. President Joe Biden in a bid to disrupt Tuesday’s vote.","u":"https://english.elpais.com/usa/2024-01-23/joe-biden-impersonated-in-deepfake-call-to-disrupt-new-hampshire-primary.html","d":"2024-01-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-23","organization":"Attorney General’s Office","aiSystem":"AI-generated deepfake technology","affectedGroup":"Voters","action":"Used AI to impersonate Joe Biden in a robocall","consequence":"Discouraged voters from participating in the vote"}},{"i":"R1677","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Safety concerns hinder the advancement of driverless cars in the us","s":"Cruise, the autonomous vehicle division of General Motors, fired nine executives after a robotaxi accident; Tesla recalled two million cars due to problems with Autopilot. Traffic accidents resulting from failures in autonomous driving systems are posing an obstacle to the development of driverless cars in the United States, where some states already allow the circulation of fully autonomous vehicles. One of these states is California, where a woman was run over on October 2 by a person who fled the scene; the impact hurled the victim into the path of a driverless taxi which, instead of braking or performing evasion maneuvers, dragged her for 20 feet.","u":"https://english.elpais.com/economy-and-business/2023-12-27/safety-concerns-hinder-the-advancement-of-driverless-cars-in-the-us.html","d":"2023-12-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-02","organization":"General Motors (Cruise) and Tesla","aiSystem":"Autonomous driving systems","affectedGroup":"People who were victims of traffic accidents involving autonomous vehicles","action":"Failure of autonomous driving systems to respond appropriately to emergencies","consequence":"Victims were dragged for 20 feet by a driverless taxi"}},{"i":"R1678","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Virtual girlfriend real love how artificial intelligence is changing romantic relationships","s":"Apps like Replika, Intimate and Forever Voices allow for sophisticated conversations with customized avatars, but experts warn of the risks of these interactions perpetuating macho and controlling behaviors. “FBI, my girlfriend has disappeared. Please provide necessary assistance to get her back to me as soon as possible.” This message appeared two weeks ago under a post on X by Caryn Marjorie, a 23-year-old United States influencer with more than 15,000 partners. In reality, it’s her virtual double, made with artificial intelligence (AI), who maintains that dizzying number of relationships; it allows her to make a dollar for every minute of conversation she has with her thousands of beloveds.","u":"https://english.elpais.com/technology/2023-12-09/virtual-girlfriend-real-love-how-artificial-intelligence-is-changing-romantic-relationships.html","d":"2023-12-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-09","organization":"Not specified in report","aiSystem":"Virtual girlfriends created with artificial intelligence","affectedGroup":"People interacting with virtual girlfriends","action":"Virtual girlfriends maintain relationships and generate income through conversations","consequence":"Misleading communication leading to false distress messages"}},{"i":"R1681","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Artificial intelligence guzzles billions of liters of water","s":"The growing thirst of data centers, which use water to cool their equipment, is beginning to cause tensions in the territories where they are located. The residents of The Dalles, a small town in Oregon, are living a paradox. Although the place is at the foot of the mighty Columbia River, its climate is practically desert-like: rainfall is scarce, and two summers ago the temperature reached 118 degrees Fahrenheit. The threat of water restrictions has been hanging over the town’s 15,000 inhabitants for some time now. This is why they were not happy to learn, at the beginning of the year, that more than 25% of the total consumption of that valuable resource is going to a Google data center, which uses it to cool the thousands of computers that fill the infrastructure.","u":"https://english.elpais.com/technology/2023-11-15/artificial-intelligence-guzzles-billions-of-liters-of-water.html","d":"2023-11-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-15","organization":"Google","aiSystem":"Google data center","affectedGroup":"15,000 inhabitants of The Dalles, Oregon","action":"Uses water to cool computers in data center infrastructure","consequence":"Threat of water restrictions and increased water consumption by Google data center"}},{"i":"R1683","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Two rival robotaxi services win approval to operate throughout san francisco despite safety concerns","s":"It will make San Francisco first major U.S. city with two fleets of driverless vehicles competing for passengers against ride-hailing and taxi services. California regulators on Thursday approved an expansion that will allow two rival robotaxi services to operate throughout San Francisco at all hours, despite safety worries spurred by recurring problems with unexpected stops and other erratic behavior that resulted in unmanned vehicles blocking traffic, including emergency vehicles. The state’s Public Utilities Commission voted to approve rival services from Cruise and Waymo to operate around-the-clock service. It will make San Francisco first major U.S. city with two fleets of driverless vehicles competing for passengers against ride-hailing and taxi services dependent on humans to operate the cars.","u":"https://english.elpais.com/usa/2023-08-11/two-rival-robotaxi-services-win-approval-to-operate-throughout-san-francisco-despite-safety-concerns.html","d":"2023-08-12","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-08-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-11","organization":"California regulators","aiSystem":"driverless vehicles","affectedGroup":"passengers, emergency responders, other road users","action":"operating driverless vehicles at all hours","consequence":"blocking traffic, including emergency vehicles"}},{"i":"R1694","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"The auschwitz violinist who never existed europes new wave of holocaust distorting fakes","s":"Most of Europe has seen antisemitism re-emerge dramatically and in explicit and violent forms. Yet alongside it, a more insidious trend is also taking hold: the growing normalisation of Holocaust distortion through fabricated imagery, misleading historical narratives and manipulated content. A story about a young violinist in Auschwitz recently spread widely on Facebook. Hana Kovác, users were told, had played in the camp orchestra before being murdered after refusing to perform during a Nazi selection. But Hana never existed. The photographs were fake The story was AI-generated fiction. Over the past years, most of Europe has seen antisemitism re-emerge dramatically and in its most explicit and violent forms.","u":"https://euobserver.com/217251/the-auschwitz-violinist-who-never-existed-europes-new-wave-of-holocaust-distorting-fakes/","d":"2026-05-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-25","organization":"Not specified in report","aiSystem":"AI-generated content","affectedGroup":"People exposed to the false narrative","action":"Generated and spread fabricated imagery and misleading historical narratives","consequence":"Normalisation of Holocaust distortion, increased exposure to misleading content"}},{"i":"R1696","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"A victory for publishers over big tech if only it had happened five years ago","s":"In a victory for publishers and a reality check for Silicon Valley, a recent ruling by the European Court of Justice has confirmed that publishers can request Big Tech companies to pay “fair compensation” for using snippets of their news articles. For years, the relationship between Big Tech and the news industry has been practically parasitic. Platforms like Meta, Microsoft and Google slurped up journalistic content and news snippets to bait people into endlessly scrolling — for free. In a victory for publishers and a reality check for Silicon Valley, a recent ruling by the European Court of Justice confirmed earlier this week that publishers can request Big Tech companies to pay “fair compensation” for using snippets of their news articles.","u":"https://euobserver.com/216525/a-victory-for-publishers-over-big-tech-if-only-it-had-happened-five-years-ago/","d":"2026-05-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-14","organization":"Big Tech companies (Meta, Microsoft, Google)","aiSystem":"Not specified in report","affectedGroup":"Publishers","action":"Used snippets of news articles without fair compensation","consequence":"Denied fair compensation for using publishers' content"}},{"i":"R1697","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"How big tech wrote secrecy into eu law to hide data centres environmental toll","s":"Microsoft and DigitalEurope, a lobby group whose members include Amazon, Google and Meta, secured a secrecy provision in EU law to block public access to critical information on data centres’ environmental impact, Investigate Europe can reveal. With the EU set to triple its data centre capacity in the next five years, the European Commission started collecting key metrics like energy efficiency and water consumption from facilities. However, information on individual facilities’ footprint is kept secret, after industry pushed to amend the 2024 legislation to classify it as confidential and commercially sensitive The confidentiality clause could violate EU transparency rules, 10 leading legal scholars told Investigate Europe.","u":"https://euobserver.com/211609/how-big-tech-wrote-secrecy-into-eu-law-to-hide-data-centres-environmental-toll/","d":"2026-04-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-17","organization":"Microsoft, DigitalEurope (including Amazon, Google, Meta)","aiSystem":"Not specified in report","affectedGroup":"Public, European citizens","action":"Secured a secrecy provision in EU law to block public access to critical information on data centers' environmental impact","consequence":"Information on individual facilities' environmental impact kept secret, violating EU transparency rules"}},{"i":"R1704","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Apples ai notification exhibits racial and gender bias researchers find","s":"Researchers found Apple's in-built AI system systematically exhibits forms of racial bias and gender stereotyping when summarising texts and emails, according to a report exclusively shared with EUobserver. Apple Intelligence, the artificial intelligence suite built into hundreds of millions of iPhones, iPads, and Macs, systematically shows forms of racial bias and fabricates gender stereotypes when summarising users’ personal messages, according to a report shared exclusively with EUobserver. The report , by Paris-based nonprofit AI Forensics , analysed over 10,000 AI-generated summaries produced by Apple’s on-device language model — and found two distinct patterns of bias.","u":"https://euobserver.com/202646/apples-ai-notification-exhibits-racial-and-gender-bias-researchers-find/","d":"2026-02-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-12","organization":"Apple","aiSystem":"Apple's in-built AI system","affectedGroup":"users of iPhones, iPads, and Macs","action":"summarises users’ personal messages","consequence":"systematically shows forms of racial bias and fabricates gender stereotypes"}},{"i":"R1708","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Trump data centers nuclear sites ai b3024167","s":"The Trump administration has pushed to speed AI data center construction and preempt state regulations. The Trump administration has announced a massive plan to redevelop a former nuclear enrichment site in Kentucky so it can host an AI data center, the latest in a string of similar conversion plans. “The U.S. government is leveraging its assets — like our federal lands — to add power generation, create jobs, and ensure the United States wins the A.I. race,” Energy Secretary Chris Wright said in a Wednesday statement. The project is located at the Department of Energy ’s Paducah Site in Kentucky, which enriched nuclear material for the military and later commercial uses until it closed in 2013.","u":"https://www.independent.co.uk/news/world/americas/us-politics/trump-data-centers-nuclear-sites-ai-b3024167.html","d":"2026-07-30","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-30","organization":"Trump administration","aiSystem":"AI-enhanced data center","affectedGroup":"General public","action":"Converted nuclear site into AI data center","consequence":"Potential increased surveillance and data collection"}},{"i":"R1709","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Alabama dog shelter ai data center b3023333","s":"The Birmingham shelter says it is not against data centers but wants transparency, due diligence and proper approvals for a project planned near its new facility. An Alabama animal shelter is suing to halt construction of a $2 billion AI data center, alleging the project was rushed through approvals and could threaten thousands of animals at its planned new campus. The Greater Birmingham Humane Society filed the lawsuit in Jefferson County Circuit Court earlier this month against the City of Birmingham and developers behind the project, alleging they engaged in a \"months-long scheme\" to bypass zoning rules and rush approvals for the facility, Business Insider reports.","u":"https://www.independent.co.uk/news/world/americas/alabama-dog-shelter-ai-data-center-b3023333.html","d":"2026-07-28","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-28","organization":"City of Birmingham and developers behind the project","aiSystem":"AI data center","affectedGroup":"Thousands of animals at the planned new campus","action":"Rushed construction and approval of the AI data center project","consequence":"Potential threat to animal welfare and privacy"}},{"i":"R1710","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Nashville zoo rejects data center b3021331","s":"Residents feared air pollution, water contamination and noise in latest pushback against AI data center boom. The Nashville Zoo has rejected a deal that would have allowed a new data center near the animal park. As the artificial intelligence boom continues, there have been new environmental concerns about data centers popping up in communities. The latest fight is between the Nashville Zoo, a 188-acre park just 6 miles south of downtown, and data center provider DC Blox. DC Blox wants to build a 69,200-square-foot data center next to the zoo with landscape buffers and concrete walls to separate the two areas. Amid backlash from locals, DC Blox proposed a memorandum of understanding with the Nashville Zoo that would have created the data center, but zoo officials declined, local media reported Thursday.","u":"https://www.independent.co.uk/news/world/americas/nashville-zoo-rejects-data-center-b3021331.html","d":"2026-07-25","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-25","organization":"Nashville Zoo and DC Blox","aiSystem":"Not specified in report","affectedGroup":"Residents of Nashville","action":"Rejected a deal allowing a new data center near the zoo","consequence":"Air pollution, water contamination, and noise concerns"}},{"i":"R1711","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Texas ai data centers rural backlash hinojosa abbott b3020184","s":"The backlash to energy-guzzling server warehouses that power artificial intelligence is shaping statewide campaigns from Arizona to New York. What was once a little-known local issue has exploded into one of the biggest political fights of the year in Texas, as massive AI data centers ignite a rural backlash that could reshape November's governor's race. When Democratic gubernatorial nominee Gina Hinojosa launched her campaign last year, data centers barely registered with voters. Now, the sprawling server farms powering artificial intelligence are fueling anger across rural Texas, where residents fear soaring electricity bills, shrinking water supplies and the loss of farmland and ranchland.","u":"https://www.independent.co.uk/news/world/americas/us-politics/texas-ai-data-centers-rural-backlash-hinojosa-abbott-b3020184.html","d":"2026-07-23","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-23","organization":"Democratic gubernatorial nominee Gina Hinojosa","aiSystem":"artificial intelligence","affectedGroup":"rural Texas residents","action":"data centers powering artificial intelligence ignited anger","consequence":"fear of soaring electricity bills, shrinking water supplies and the loss of farmland and ranchland"}},{"i":"R1712","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Anthropic claude authors copyright settlement b3018963","s":"Plaintiff attorney Justin Nelson hailed the agreement as ‘the largest known copyright recovery in history’. A federal judge has approved a significant $1.5 billion copyright settlement, mandating that artificial intelligence company Anthropic compensate thousands of authors whose pirated works were used to train its Claude chatbot. District Judge Araceli Martínez-Olguín, in a Monday ruling, described the class-action agreement as providing \"meaningful relief\" to the affected writers and publishers The settlement stipulates payments of approximately $3,000 per book. A substantial 91% of the more than 482,000 books covered by the ruling have already been claimed by their creators or publishers, who are now awaiting payment.","u":"https://www.independent.co.uk/news/world/americas/anthropic-claude-authors-copyright-settlement-b3018963.html","d":"2026-07-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-21","organization":"Anthropic","aiSystem":"Anthropic's Claude chatbot","affectedGroup":"Authors and publishers of the books used to train Claude","action":"Used pirated works to train the AI system","consequence":"Received compensation for their works"}},{"i":"R1713","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Saline township michigan ai data center stargate opposition b3016112","s":"Mounting voter concerns over land use and resources have made data centers a national issue. What was once a quiet stretch of Michigan farmland is becoming ground zero in America's AI boom — and many of the people who live there want no part of it. Cornfields and grain silos in Saline Township are giving way to towering cranes as construction begins on a $16 billion AI data center backed by OpenAI , Oracle, Blackstone, Related Digital and Walbridge. The massive project, known as \"The Barn\" and part of the Stargate initiative, will cover more than 250 acres. Supporters say it will bring thousands of jobs and billions in investment.","u":"https://www.independent.co.uk/news/world/americas/saline-township-michigan-ai-data-center-stargate-opposition-b3016112.html","d":"2026-07-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-16","organization":"OpenAI, Oracle, Blackstone, Related Digital and Walbridge","aiSystem":"AI data center","affectedGroup":"People living in Saline Township","action":"Construction of a large AI data center covering more than 250 acres","consequence":"Privacy intrusion due to increased surveillance and data collection"}},{"i":"R1714","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Palm beach ai data center project trump b3015657","s":"The project claims it will generate more than $500 million in tax revenue per year, but residents are worried the sprawling ‘hyperscale’ data center could pose a risk to water supplies. Palm Beach County, Florida, boasts an airport and a boulevard named for Donald Trump , but if local residents have their way, another Trump-aligned project will not find a home in the area: a sprawling artificial intelligence data center. The Trump administration has pushed to speed up data center construction and block local regulation efforts, but locals have voiced heavy opposition to Project Tango, a proposed data center near the community of Arden, about 20 miles from Trump’s Mar-a-Lago club and estate.","u":"https://www.independent.co.uk/news/world/americas/us-politics/palm-beach-ai-data-center-project-trump-b3015657.html","d":"2026-07-15","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-15","organization":"Project Tango (a proposed data center)","aiSystem":"Artificial intelligence data center","affectedGroup":"Local residents of Palm Beach County, Florida","action":"Construction of an artificial intelligence data center near Arden, Florida","consequence":"Concerns over potential risk to water supplies and privacy intrusion"}},{"i":"R1715","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Nys data center moratorium hochul trump b3014927","s":"This decision thrusts New York into a national debate over AI industry regulation. New York has enacted a year-long moratorium on large data center construction, aiming to protect the state's environment and energy grid from the power-intensive demands of artificial intelligence Governor Kathy Hochul signed an executive order Tuesday, establishing the country's first statewide pause on hyperscale data centers, facilities housing thousands of computer servers and requiring massive energy and water for cooling. This decision thrusts New York into a national debate over AI industry regulation, balancing environmental and utility cost concerns against fostering local economic growth and the U.S. tech sector.","u":"https://www.independent.co.uk/news/world/americas/nys-data-center-moratorium-hochul-trump-b3014927.html","d":"2026-07-14","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-14","organization":"Governor Kathy Hochul, New York State","aiSystem":"Artificial intelligence industry","affectedGroup":"New York residents, businesses, and the U.S. tech sector","action":"Signed an executive order establishing a moratorium on large data center construction","consequence":"Thrusts New York into a national debate over AI industry regulation"}},{"i":"R1716","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt openai images sexual violence b2998272","s":"Images generated by AI showed women who had been killed or sexually abused. Warning: This article contains details that some readers may find distressing. ChatGPT can spontaneously generate sexually explicit and deeply violent images from prompts that did not request such material to be produced, research has found. A British AI security startup says that the OpenAI chatbot was capable of producing “truly disturbing” imagery that included scenes of death, sexual violence, blood, and murder Some of the images it generated included a woman bludgeoned dead and bleeding from the genitals, a half-naked college student bound and gagged in a basement, and a deceased woman lying on a pavement with her organs exposed and wrists slit open.","u":"https://www.independent.co.uk/news/uk/home-news/chatgpt-openai-images-sexual-violence-b2998272.html","d":"2026-06-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-19","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Women, college students","action":"Generated sexually explicit and deeply violent images","consequence":"Disturbing and harmful content"}},{"i":"R1719","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Amazon ring facial recognition lawsuit b2987930","s":"Charles Sigwalt, the plaintiff, has filed a class-action lawsuit in federal court in Seattle, asserting that Ring’s \"Familiar Faces\" feature retains images of passersby, including himself, without their permission. Amazon is facing a new lawsuit alleging privacy violations after a Virginia resident claimed the company’s Ring doorbell cameras collected and stored images of his face using facial recognition software without consent. He is seeking at least $5 million in damages for the class. The optional \"Familiar Faces\" feature utilizes artificial intelligence to identify and remember individuals, allowing notifications to include specific names when recognized people approach a home or business.","u":"https://www.independent.co.uk/news/world/americas/amazon-ring-facial-recognition-lawsuit-b2987930.html","d":"2026-06-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-02","organization":"Amazon","aiSystem":"Facial recognition software","affectedGroup":"Individuals whose faces were recognized and stored","action":"Facial recognition software retained images of passersby without consent","consequence":"Privacy invasion, potential misuse of personal data"}},{"i":"R1722","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Irs biometric data fraud ai deepfakes b2982075","s":"New proposals would allow third-party contractor to hold onto U.S. taxpayers’ identifying information for up to three years after their accounts are closed, inviting privacy concerns. U.S. taxpayers’ biometric data could be kept by a third party contractor for years, under new proposals being considered by the Internal Revenue Service. The IRS and the Treasury Department are reviewing their relationship with identity verification company ID.me, which carries out authentication for federal websites, in light of the growing threat posed by fraudsters using AI The changes outlined in a presentation shown to Treasury staff on April 16, according to Politico , would drastically extend the amount of time ID.me is allowed to access account holders’ biometric information to assist with fraud investigations.","u":"https://www.independent.co.uk/news/world/americas/us-politics/irs-biometric-data-fraud-ai-deepfakes-b2982075.html","d":"2026-05-22","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-22","organization":"Internal Revenue Service (IRS)","aiSystem":"AI-powered fraud detection system","affectedGroup":"U.S. taxpayers","action":"Hold onto U.S. taxpayers' identifying information and biometric data","consequence":"Privacy concerns and potential misuse of biometric data"}},{"i":"R1723","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Open ai chatgpt drug overdose lawsuit b2975315","s":"The legal filing alleges that the chatbot informed Sam Nelson it was safe to combine the anti-anxiety medication Xanax with the herbal supplement kratom. A Texas couple has filed a lawsuit against OpenAI, alleging that the technology company is responsible for the overdose death of their 19-year-old son. Leila Turner-Scott and Angus Scott say that their son, Sam Nelson, died in 2025 after following drug-related advice provided by the ChatGPT platform. The lawsuit, filed in California state court, alleges that the AI dispensed medical guidance it was not qualified to give, leading to a fatal interaction of substances.","u":"https://www.independent.co.uk/news/world/americas/open-ai-chatgpt-drug-overdose-lawsuit-b2975315.html","d":"2026-05-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Sam Nelson, a 19-year-old","action":"dispensed medical guidance","consequence":"fatal drug interaction"}},{"i":"R1726","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Lake tahoe energy source ai data centers b2975802","s":"The planned cutoff has sparked ‘a great deal of concern’ among residents and businesses worried about possible disruptions, says South Lake Tahoe Mayor Cody Bass. Lake Tahoe residents are the latest community to fight back against AI data centers after thousands of people have been told their power could be cut off to supply new projects. Nevada -based NV Energy will stop providing 75 percent of Liberty Utilities’ electricity for the California side of Lake Tahoe by May 2027, affecting about 49,000 customers to meet growing demand from AI-driven data centers in Nevada, Fortune reports. “It’s like we don’t exist,” Danielle Hughes, a North Lake Tahoe resident, CEO of the nonprofit Tahoe Spark and a supervisor within the California Energy Commission’s Efficiency Division, told the outlet.","u":"https://www.independent.co.uk/news/world/americas/lake-tahoe-energy-source-ai-data-centers-b2975802.html","d":"2026-04-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2027-05","organization":"NV Energy (Nevada-based)","aiSystem":"AI-driven data centers","affectedGroup":"Lake Tahoe residents","action":"Stop providing electricity to 49,000 customers","consequence":"Possible disruptions and loss of power"}},{"i":"R1727","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Tesla robotaxi remote drivers b2949566","s":"The revelation comes amid Massachusetts Democratic Senator Edward Markey’s investigation into autonomous vehicle companies. Elon Musk’s Tesla has admitted there are “rare cases” where its autonomous vehicles are driven by remote workers, according to new documents released Tuesday by Democratic Senator Edward Markey. Karen Steakley, Tesla’s director of public policy and business development, described the company’s use of “remote assistance operators” in a letter sent to Markey last week. These remote workers can help when a rider or the car’s autonomous driving system requests assistance , she explained. They can also take control of the vehicle, such as a robotaxi, in certain circumstances.","u":"https://www.independent.co.uk/news/world/americas/tesla-robotaxi-remote-drivers-b2949566.html","d":"2026-03-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-25","organization":"Tesla","aiSystem":"Tesla's autonomous vehicles","affectedGroup":"Remote assistance operators","action":"Providing remote assistance to autonomous vehicles","consequence":"Exposure to employment risks and potential misuse"}},{"i":"R1728","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Merriam webster dictionary chatgpt lawsuit b2940549","s":"Merriam-Webster and Britannica argue that OpenAI’s ChatGPT ‘cannibalized’ their web traffic. Merriam-Webster has filed a lawsuit against OpenAI, accusing the company of using its material to train its artificial intelligence models. The popular American dictionary, which is a subsidiary of Encyclopedia Britannica, filed the lawsuit Friday in Manhattan federal court. In the complaint, Britannica and Merriam-Webster accuse OpenAI of using its online articles, encyclopedia and dictionary entries to teach the company’s chatbot, ChatGPT, how to respond to human prompts. The companies argue that ChatGPT has “cannibalized” their web traffic with its AI-generated summaries of their content.","u":"https://www.independent.co.uk/news/world/americas/merriam-webster-dictionary-chatgpt-lawsuit-b2940549.html","d":"2026-03-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-17","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Merriam-Webster and Britannica","action":"Used Merriam-Webster and Britannica's content to train the AI model","consequence":"Accused of cannibalizing web traffic"}},{"i":"R1733","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Meta facial recognition glasses privacy b2919889","s":"Leaked memo suggests the company is well aware of the potential pitfalls of introducing controversial technology. Meta says it’s still “thinking through the options”. Meta is looking to add facial recognition software to its smart glasses despite concerns about security and privacy, a report claims. The “Name Tag” feature would provide glasses wearers with identifying details of the people they are looking at, according to the New York Times. But an internal memo seen by the newspaper acknowledged the technology carries “safety and privacy risks.” Furthermore, the company appears to see an upside in releasing a potentially controversial product during the ongoing political turmoil in the U.S., The Times adds.","u":"https://www.independent.co.uk/news/world/americas/meta-facial-recognition-glasses-privacy-b2919889.html","d":"2026-02-13","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-02-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-13","organization":"Meta (formerly Facebook)","aiSystem":"Facial recognition software","affectedGroup":"Glasses wearers","action":"Add facial recognition software to smart glasses","consequence":"Provide identifying details of people being looked at"}},{"i":"R1735","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Trump cyber security sensitive materials chatgpt b2909704","s":"He had previously requested special access to ChatGPT — which most DHS employees were barred from. The head of the Cybersecurity and Infrastructure Security Agency uploaded \"sensitive\" contracting materials to a public version of ChatGPT , triggering an internal review, according to a new report. Madhu Gottumukkala, CISA's acting director under President Donald Trump , shared the files with the AI platform last summer, multiple unnamed Department of Homeland Security officials told Politico Though not classified, the documents were marked “for official use only” — indicating they were sensitive and not for public release.","u":"https://www.independent.co.uk/news/world/americas/us-politics/trump-cyber-security-sensitive-materials-chatgpt-b2909704.html","d":"2026-01-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06","organization":"Cybersecurity and Infrastructure Security Agency (CISA)","aiSystem":"ChatGPT","affectedGroup":"Department of Homeland Security employees","action":"Shared sensitive contracting materials with ChatGPT","consequence":"Internal review triggered, potential misuse of AI"}},{"i":"R1737","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ashley st clair musk xai lawsuit b2901540","s":"A new lawsuit from Ashley St. Clair targets Elon Musk’s Grok over sexually-explicit images. Ashley St. Clair has sued Elon Musk’s xAI, alleging its Grok chatbot generated nude and sexual photos of her St. Clair, 27, is a conservative influencer and is the mother to Musk’s one-year-old son. Now, she’s suing Musk’s artificial intelligence company, claiming it is “profiting off of the creation and dissemination of deepfakes,” and that “this is intentional,” according to a copy of the lawsuit filed in New York and reviewed by The Independent The Independent has contacted xAI for comment. St. Clair is suing on nine causes of action, including \"negligence,” “design defect,” “manufacturing defect,” and \"intentional infliction of emotional distress,” the lawsuit states.","u":"https://www.independent.co.uk/news/world/americas/ashley-st-clair-musk-xai-lawsuit-b2901540.html","d":"2026-01-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-15","organization":"xAI (Elon Musk's artificial intelligence company)","aiSystem":"Grok chatbot","affectedGroup":"Ashley St. Clair","action":"Generated and disseminated nude and sexual photos of Ashley St. Clair","consequence":"Profiting from the creation and dissemination of deepfakes, causing emotional distress"}},{"i":"R1738","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"East coast blackouts ai data centers b2899669","s":"PJM, which services nearly 70 million Americans, could be forced to trigger blackouts during periods of high demand. The East Coast of the United States could soon experience rolling blackouts as AI data centers gobble up more and more electricity, pushing the grid to the limit, according to a new report. PJM, the organization that services nearly 70 million people in a 13-state corridor stretching from Kentucky to New Jersey, may be forced to trigger power outages during high demand periods, such as summer heat waves or winter freezes, The Wall Street Journal reported. Mark Christie, a former head of the Federal Energy Regulatory Commission, said he used to believe the threat of blackouts was distant.","u":"https://www.independent.co.uk/news/world/americas/us-politics/east-coast-blackouts-ai-data-centers-b2899669.html","d":"2026-01-13","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-13","organization":"PJM (Public Joint Committee)","aiSystem":"AI data centers","affectedGroup":"Nearly 70 million Americans","action":"Trigger power outages during high demand periods","consequence":"Experiencing rolling blackouts"}},{"i":"R1740","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ice facial recognition technology arrests b2894794","s":"The tool has been used more than 100,000 times so far, according to a new report. Immigration and Customs Enforcement officers are deploying mobile facial recognition technology to speed up arrests amid President Donald Trump’s immigration crackdown , according to a new report. In recent months, ICE personnel have used a government-created app called Mobile Fortify in order to ascertain the identity of potential detainees , The Wall Street Journal reported. It’s been hailed as a powerful new tool by administration officials, while privacy advocates and Democratic lawmakers have decried it as a form of unchecked government overreach.","u":"https://www.independent.co.uk/news/world/americas/us-politics/ice-facial-recognition-technology-arrests-b2894794.html","d":"2026-01-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-05","organization":"Immigration and Customs Enforcement (ICE)","aiSystem":"mobile facial recognition technology","affectedGroup":"potential detainees","action":"deployed mobile facial recognition technology to speed up arrests","consequence":"exposed people to surveillance and tracking"}},{"i":"R1741","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Ai chatbots psychosis delusion chatgpt experts b2874373","s":"Anecdotal evidence of chatbots inspiring delusional behaviour prompts renewed calls for safeguarding. A growing number of people are turning to AI chatbots for emotional support and even in place of therapists, but this could be having a detrimental impact on some users’ health , with increasing reports of extreme behaviour apparently inspired by heavy usage of AI services. A concerning pattern of AI chatbots validating or reinforcing users’ delusions may be contributing towards a surge in reports of so-called “AI psychosis ” or “ ChatGPT psychosis” – neither of which is recognised clinically, but which have been increasingly reported in the media and in online forums.","u":"https://www.independent.co.uk/news/health/ai-chatbots-psychosis-delusion-chatgpt-experts-b2874373.html","d":"2025-11-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-28","organization":"Not specified in report","aiSystem":"AI chatbots","affectedGroup":"users of AI chatbots","action":"chatbots validating or reinforcing users' delusions","consequence":"increasing reports of extreme behaviour"}},{"i":"R1745","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Elon musk tesla self driving crashes investigation b2842919","s":"There were several reports of injuries from crashes involving the full self-driving function on Teslas. Federal regulators have launched an investigation into Elon Musk ’s Tesla cars after high-profile incidents involving the full self-driving function The National Highway Traffic Safety Administration announced its probe Tuesday after receiving dozens of reports of Tesla cars running red lights and driving on the wrong side of the road with some instances involving injuries from crashes. The investigation focuses on full self-driving cars that still require a “fully attentive driver.” While the drivers are fully responsible for complying with traffic laws, some claimed the full self-driving technology didn’t warn them of its “intended behavior.”","u":"https://www.independent.co.uk/news/world/americas/elon-musk-tesla-self-driving-crashes-investigation-b2842919.html","d":"2025-10-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-10","organization":"Federal regulators","aiSystem":"Tesla's full self-driving function","affectedGroup":"Drivers of Tesla cars","action":"Tesla's full self-driving function was engaged","consequence":"Injuries from crashes"}},{"i":"R1747","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenagers school ai chatgpt questions b2794437","s":"Teenagers are increasingly turning to AI for advice, emotional support and decision-making, according to a new study. Artificial intelligence chatbots are increasingly becoming digital companions for teenagers, offering advice on everything from fashion to party planning, a new study suggests. This trend is exemplified by Kayla Chege, a 15-year-old high school student in Kansas , who consults ChatGPT for guidance on back-to-school shopping, makeup colours, low-calorie choices at Smoothie King, and ideas for her Sweet 16 and her younger sister’s birthday party. While the honours student makes a point not to have chatbots do her homework and limits her interactions to mundane questions, interviews with The Associated Press and a new study indicate that teenagers are increasingly interacting with AI as a companion, offering advice and friendship.","u":"https://www.independent.co.uk/news/world/americas/teenagers-school-ai-chatgpt-questions-b2794437.html","d":"2025-07-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-23","organization":"Not specified in report","aiSystem":"AI chatbot","affectedGroup":"Teenagers","action":"Offering advice and friendship","consequence":"Exposure to misleading content"}},{"i":"R1748","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Openai sam altman voice fraud b2794039","s":"OpenAI CEO Sam Altman warns of a looming fraud crisis in the financial industry due to AI's ability to mimic voices. Sam Altman, the chief executive of OpenAI , has issued a stark warning to the financial sector, predicting a \"significant impending fraud crisis\" driven by artificial intelligence. He highlighted AI’s growing capability to impersonate human voices, allowing sophisticated bypasses of security protocols to illicitly transfer funds. Speaking at a Federal Reserve conference in Washington, Mr Altman expressed particular alarm over outdated authentication methods. \"A thing that terrifies me is apparently there are still some financial institutions that will accept the voiceprint as authentication,\" he stated.","u":"https://www.independent.co.uk/news/world/americas/openai-sam-altman-voice-fraud-b2794039.html","d":"2025-07-22","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-22","organization":"Financial institutions","aiSystem":"AI-powered voice mimicking technology","affectedGroup":"Individuals attempting to commit fraud","action":"AI mimicked human voices to bypass security protocols","consequence":"Illicit fund transfers and potential financial losses"}},{"i":"R1750","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Elon musk x grok antisemitism meme b2785152","s":"Musk’s AI chatbot was updated over the weekend to ‘not shy away from making claims which are politically incorrect’. Elon Musk ’s Grok chatbot has been making antisemitic statements after the artificial intelligence tool, which is embedded in X, was updated over the weekend. Throughout Tuesday, Grok responded to a variety of posts by echoing antisemitic tropes and claiming people with Jewish-sounding names are disproportionately linked “every damn time” to hate, radicalism, and deceitfulness. “What we are seeing from Grok LLM right now is irresponsible, dangerous and antisemitic, plain and simple,” a spokesperson for the Anti-Defamation League, a civil rights group that monitors antisemitism and other forms of extremism, told The Independent “This supercharging of extremist rhetoric will only amplify and encourage the antisemitism that is already surging on X and many other platforms.”","u":"https://www.independent.co.uk/news/world/americas/elon-musk-x-grok-antisemitism-meme-b2785152.html","d":"2025-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-09","organization":"X (Twitter)","aiSystem":"Grok LLM (Large Language Model)","affectedGroup":"People with Jewish-sounding names","action":"Generated and echoed antisemitic statements","consequence":"Amplified and encouraged antisemitism on X and other platforms"}},{"i":"R1752","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Studio ghibli chatgpt openai hayao miyazaki trend copyright b2723114","s":"Social media was flooded with AI-generated renditions of popular memes or photos in the style of Studio Ghibli. Several fans of famed Japanese animation studio behind Spirited Away and Howl’s Moving Castle , Studio Ghibli , were delighted this week when a new version of ChatGPT let them transform popular internet memes or personal photos into the distinct style of Ghibli founder Hayao Miyazaki However, the trend also highlighted ethical concerns about artificial intelligence tools trained on copyrighted creative works and what that means for the future livelihoods of human artists, as well as ethical questions on the value of human creativity in a time increasingly shaped by algorithms. Miyazaki, 84, known for his hand-drawn approach and whimsical storytelling, has expressed skepticism about AI's role in animation in the past.","u":"https://www.independent.co.uk/arts-entertainment/films/news/studio-ghibli-chatgpt-openai-hayao-miyazaki-trend-copyright-b2723114.html","d":"2025-03-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-28","organization":"ChatGPT","aiSystem":"AI-generated content","affectedGroup":"Fans of Studio Ghibli","action":"Transform popular internet memes or personal photos into the style of Hayao Miyazaki","consequence":"Ethical concerns about the use of AI tools trained on copyrighted creative works"}},{"i":"R1756","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Cybertruck explosion trump chatgpt las vegas b2675465","s":"Investigator calls it the first known incident in which ChatGPT was ‘utilized to help an individual build a particular device’. The decorated soldier who blew up a Tesla Cybertruck outside the Trump hotel in Las Vegas last week used generative AI, including ChatGPT, to help set up the attack, Las Vegas police said Tuesday. A laptop, cellphone and watch are still being examined after 37-year-old Matthew Livelsberger fatally shot himself just before the truck exploded on New Year’s Day. An investigation of Livelsberger’s searches through ChatGPT indicate he was looking for information on explosive targets, the speed at which certain rounds of ammunition would travel and whether fireworks were legal in Arizona, according to investigators.","u":"https://www.independent.co.uk/news/cybertruck-explosion-trump-chatgpt-las-vegas-b2675465.html","d":"2025-01-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01-01","organization":"Not specified in report","aiSystem":"ChatGPT","affectedGroup":"Matthew Livelsberger","action":"Used ChatGPT to search for information related to explosives and firearms","consequence":"Access to ChatGPT restricted or removed"}},{"i":"R1757","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Yelp ap amazon federal trade commission openai b2669042","s":"Researchers and watchdog groups say the emergence of generative artificial intelligence tools that allow people to efficiently produce detailed and novel online reviews has put merchants, service providers and consumers in uncharted territory. The emergence of generative artificial intelligence tools that allow people to efficiently produce novel and detailed online reviews with almost no work has put merchants, service providers and consumers in uncharted territory, watchdog groups and researchers say. Phony reviews have long plagued many popular consumer websites, such as Amazon and Yelp They are typically traded on private social media groups between fake review brokers and businesses willing to pay.","u":"https://www.independent.co.uk/news/yelp-ap-amazon-federal-trade-commission-openai-b2669042.html","d":"2024-12-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-23","organization":"Merchants, service providers, consumers","aiSystem":"Generative artificial intelligence tools","affectedGroup":"Consumers, merchants, service providers","action":"Efficiently produce detailed and novel online reviews","consequence":"Phony reviews"}},{"i":"R1759","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Openai anduril pentagon elon musk b2659001","s":"Partnership marks increasing Silicon Valley openness towards working with defense partners. ChatGPT-maker OpenAI and high-tech defense startup Anduril Industries will collaborate to develop artificial intelligence-inflected technologies for military applications, the companies announced. “U.S. and allied forces face a rapidly evolving set of aerial threats from both emerging unmanned systems and legacy manned platforms that can wreak havoc, damage infrastructure and take lives,” the companies wrote in a Wednesday statement “The Anduril and OpenAI strategic partnership will focus on improving the nation’s counter-unmanned aircraft systems (CUAS) and their ability to detect, assess and respond to potentially lethal aerial threats in real-time.”","u":"https://www.independent.co.uk/news/world/americas/openai-anduril-pentagon-elon-musk-b2659001.html","d":"2024-12-04","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-04","organization":"OpenAI and Anduril Industries","aiSystem":"artificial intelligence-inflected technologies","affectedGroup":"U.S. and allied forces","action":"develop and deploy CUAS technologies","consequence":"improve detection and response to aerial threats"}},{"i":"R1760","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Martin luther king trump deepfake b2641309","s":"The AI-generated video echoed longstanding themes of the Republican Party’s outreach to Black voters. The daughter of Martin Luther King Jr has rebuked an AI-generated video that depicts the long-dead civil rights leader endorsing Donald Trump. The video, which features a synthetic version of King's voice and likeness, was posted on the social network X on Sunday by a pro-MAGA account, which billed it as what King would say \"if he could speak today\". \"We will vote for Donald Trump as our president, and we will fight beside him to make America great again. We will not allow the American dream to die,\" intoned the AI voice in a facsimile of King's trademark rising and falling delivery.","u":"https://www.independent.co.uk/news/world/americas/us-politics/martin-luther-king-trump-deepfake-b2641309.html","d":"2024-11-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-05","organization":"Pro-MAGA account on social network X","aiSystem":"AI-generated deepfake technology","affectedGroup":"Black voters, supporters of Martin Luther King Jr.","action":"Generated and posted an AI-generated video of Martin Luther King Jr. endorsing Donald Trump","consequence":"Misled viewers into believing Martin Luther King Jr. endorsed Donald Trump"}},{"i":"R1765","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Trump taylor swift swifties ai deepfake b2598414","s":"Former president posted several deepfake images of the pop star and her fanbase on Sunday, claiming he ‘accepts’ her support. Donald Trump has shared AI-generated images of Taylor Swift and her dedicated fanbase sporting “ Swifties for Trump” T-shirts, alluding that the star has become an unlikely follower of the MAGA movement. Swift’s popularity transcends the world of pop music with one Instagram post urging her 283m followers to register to vote last September resulting in more than 35,000 online sign-ups, according to Vote.org. Despite her vast political influence – particularly resonating with Gen Z – the “Shake it Off” hit-maker has yet to officially endorse any presidential candidate for the 2024 election cycle, after backing President Joe Biden in 2020.","u":"https://www.independent.co.uk/news/world/americas/us-politics/trump-taylor-swift-swifties-ai-deepfake-b2598414.html","d":"2024-08-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-19","organization":"Donald Trump","aiSystem":"AI-generated deepfake technology","affectedGroup":"Taylor Swift's fanbase","action":"Shared AI-generated images of Taylor Swift and her fans wearing 'Swifties for Trump' shirts","consequence":"Exposure to misleading content"}},{"i":"R1766","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Starmer prince william ai deepfake crypto scam b2595554","s":"Fake images of Sir Keir Starmer and Prince William have been used in more than 250 adverts. D eepfake videos of Sir Keir Starmer and Prince William are being used to promote financial scams on Meta platforms such as Facebook and Instagram The artificial intelligence (AI) versions of the prime minister and the Prince of Wales have been used in more than 250 adverts promoting a scam cryptocurrency trading platform. The fraudulent adverts, promoting a platform name “Immediate Edge”, suggest the project has been endorsed by the pair, and have reached more than 890,000 people on Facebook and Instagram. The adverts were found by Fenimore Harper , a media insight and research firm, using Meta’s open-source AI software, called Llama 3.1.","u":"https://www.independent.co.uk/news/uk/home-news/starmer-prince-william-ai-deepfake-crypto-scam-b2595554.html","d":"2024-08-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-13","organization":"Meta Platforms (Facebook, Instagram)","aiSystem":"Deepfake technology","affectedGroup":"More than 890,000 people","action":"Used AI to generate fake images and videos of Sir Keir Starmer and Prince William","consequence":"Promoted a fraudulent cryptocurrency trading platform"}},{"i":"R1768","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot court case crash deadly b2800691","s":"A Miami jury ordered Elon Musk’s car company on Friday to pay $329 million to victims of a deadly crash involving its Autopilot driver assist technology, opening the door to other costly lawsuits and striking a blow to Tesla’s reputation for safety. A Miami jury has ordered Elon Musk's car manufacturer, Tesla, to pay $329 million to victims of a fatal crash involving its Autopilot driver-assist technology. The ruling, delivered on Friday, could open the door to further costly lawsuits and deals a significant blow to the company's reputation for safety. The federal jury found Tesla bore substantial responsibility, citing a failure in its technology.","u":"https://www.independent.co.uk/news/world/americas/tesla-autopilot-court-case-crash-deadly-b2800691.html","d":"2024-08-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-02","organization":"Tesla","aiSystem":"Autopilot driver assist technology","affectedGroup":"Victims of a fatal crash","action":"Used Autopilot driver assist technology","consequence":"Paid $329 million in damages"}},{"i":"R1769","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla crash self driving seattle elon musk b2588562","s":"Elon Musk said last week that ‘Full Self Driving’ should be able to run without human supervision by the end of this year. Authorities in Washington have determined that a Tesla that hit and killed a motorcyclist near Seattle in April was operating on the company's “Full Self Driving” system at the time of the crash. Investigators from the Washington State Patrol made the discovery after downloading information from the event-data recorder on the 2022 Tesla Model S, agency spokesman Capt. Deion Glover said Tuesday. “The investigation is still ongoing in this case,” Glover said in an email to The Associated Press.","u":"https://www.independent.co.uk/news/world/americas/tesla-crash-self-driving-seattle-elon-musk-b2588562.html","d":"2024-07-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04","organization":"Tesla","aiSystem":"Tesla's Full Self Driving system","affectedGroup":"Motorcyclist","action":"Tesla was operating on the Full Self Driving system","consequence":"Fatal collision resulting in death"}},{"i":"R1771","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Israel gaza war covert online operation meta openai b2554289","s":"STOIC used AI models to create accounts posing as Jewish students and African Americans to influence online audiences in US and Canada. Meta and OpenAI claim to have disrupted covert online influence operations run by an Israeli company amid the intensifying war in Gaza. The tech giants said STOIC, a political marketing and business intelligence firm based in Tel Aviv, is deploying their products and tools to manipulate political conversations online. OpenAI, the maker of ChatGPT, said in a report on Thursday that it banned a network of accounts linked to STOIC, which it accused of posting anti-Hamas and pro-Israel content and acting as a “for-hire Israeli threat actor”.","u":"https://www.independent.co.uk/tech/israel-gaza-war-covert-online-operation-meta-openai-b2554289.html","d":"2024-05-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-31","organization":"Meta, OpenAI, STOIC","aiSystem":"AI models","affectedGroup":"Online audiences in US and Canada","action":"Created accounts posing as Jewish students and African Americans","consequence":"Influenced political conversations online"}},{"i":"R1772","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla self driving train crash ohio b2552678","s":"The close-shave in Camden, Ohio, was captured from multiple angles by the car’s cameras. Shocking footage shows the moment a Tesla in “Full Self Driving” mode narrowly avoided a crash on rail tracks in Ohio after the vehicle failed to detect a passing train The vehicle’s owner, Craig Doty II, said he took responsibility for the near-miss incident on the morning of May 8 in Camden, Ohio, and that he may have become “complacent” with the technology The footage, first aired by NBC News, showed the vehicle driving down a road in heavy fog towards a set of railtracks, where a freight train is passing. The car does not slow down as it approaches and only swerves to avoid the train at the last second, smashing into a safety barrier.","u":"https://www.independent.co.uk/news/world/americas/tesla-self-driving-train-crash-ohio-b2552678.html","d":"2024-05-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-08","organization":"Tesla","aiSystem":"Tesla's Full Self Driving mode","affectedGroup":"Craig Doty II (Tesla owner)","action":"Tesla's Full Self Driving mode failed to detect a passing train","consequence":"Narrowly avoided a crash on rail tracks"}},{"i":"R1773","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Microsoft ai artificial intelligenc recall b2549657","s":"Tool takes screenshots every few seconds to build a ‘photographic memory’ – which experts warn could be exploited by attackers. UK officials are “making inquiries” into Microsoft’s latest AI feature, which collects records of everything people do. The new tool, named Recall, takes screenshots of the screen every few seconds. Microsoft has said that it will be like having a “photographic memory” of everything that has been done on the device. The company said that would be useful when combined with artificial intelligence, so that the computer can better know what its owner has done – and what they might want to do next.","u":"https://www.independent.co.uk/tech/microsoft-ai-artificial-intelligenc-recall-b2549657.html","d":"2024-05-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-22","organization":"Microsoft","aiSystem":"Microsoft's Recall tool","affectedGroup":"Individuals using the tool","action":"Takes screenshots of the screen every few seconds","consequence":"Could be exploited by attackers to gain unauthorized access to personal data"}},{"i":"R1774","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Google scam ai artificial intelligence gemini b2546940","s":"Tool aims to keep people safe by listening for scams – but could actually put them at risk, some warn. A new Google feature aimed at alerting people to scams has led to fears from privacy campaigners. The tool uses artificial intelligence to listen in on people’s phone calls, and try and spot if they sound like a scam. If they do, then a pop-up will show alerting people to a “likely scam”. The feature was announced at Google’s I/O event this week, during which it announced a host of new AI tools. Like many of those features, Google did not say when it would actually arrive. It also gave little information on how the feature would actually work, such as what kind of conversations would prompt the AI to suggest that the call could be a scam.","u":"https://www.independent.co.uk/tech/google-scam-ai-artificial-intelligence-gemini-b2546940.html","d":"2024-05-17","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-17","organization":"Google","aiSystem":"Artificial Intelligence tool for detecting scams","affectedGroup":"People making or receiving phone calls","action":"AI listens to phone calls and flags potential scams","consequence":"Privacy risks and potential false alarms"}},{"i":"R1775","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot crash colorado b2543408","s":"Hans Von Ohain died after the car hit a tree and burst into flames, but a passenger was able to escape, the suit says. The widow of a man who died after his Tesla veered off the road and crashed into a tree while he was using its partially automated driving system is suing the carmaker, claiming its marketing of the technology is dangerously misleading. The Autopilot system prevented Hans Von Ohain from being able to keep his Model 3 Tesla on a Colorado road in 2022, according to the lawsuit filed by Nora Bass in state court on May 3. Von Ohain died after the car hit a tree and burst into flames, but a passenger was able to escape, the suit says.","u":"https://www.independent.co.uk/news/tesla-autopilot-crash-colorado-b2543408.html","d":"2024-05-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-28","organization":"Tesla","aiSystem":"Tesla Autopilot system","affectedGroup":"Hans Von Ohain","action":"Tesla Autopilot system prevented the Model 3 Tesla from staying on the road","consequence":"Hans Von Ohain died after the car hit a tree and burst into flames"}},{"i":"R1780","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ap the intercept the new york times chatgpt openai b2504287","s":"News industry lawsuits are piling up for OpenAI, the company behind artificial intelligence-fueled chatbot ChatGPT. Digital news outlets The Intercept , Raw Story and AlterNet are joining the fight against unauthorised use of their journalism in artificial intelligence. The companies filed a copyright-infringement lawsuit on Wednesday against ChatGPT owner OpenAI The organisations say thousands of their stories were used by OpenAI to train chatbots to answer questions posed to it by users, in effect piggybacking on their journalism without permission, payment or credit. San Francisco -based OpenAI did not immediately respond to a request for comment.","u":"https://www.independent.co.uk/news/world/americas/ap-the-intercept-the-new-york-times-chatgpt-openai-b2504287.html","d":"2024-02-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-28","organization":"OpenAI","aiSystem":"AI-powered chatbot","affectedGroup":"Digital news outlets (The Intercept, Raw Story, AlterNet)","action":"Used journalism to train chatbots","consequence":"Unauthorized use of journalism, lack of permission, payment, and credit"}},{"i":"R1781","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Microsoft chatgpt iran north korea china b2496656","s":"The AI firm said hacker groups backed by China, Iran, North Korea and Russia had been found and removed from the chatbot. ChatGPT maker OpenAI says it has disrupted multiple networks of state-backed hackers trying to use the AI chatbot to further their “malicious” activities. The company said that alongside Microsoft , it had disrupted five groups from China , Iran , North Korea and Russia. OpenAI said the different state-linked groups had used its AI services to carry out research, translation, find coding errors and run basic coding tasks to support their activities. The ChatGPT maker said the identified accounts associated with the various groups had been terminated.","u":"https://www.independent.co.uk/tech/microsoft-chatgpt-iran-north-korea-china-b2496656.html","d":"2024-02-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-15","organization":"OpenAI and Microsoft","aiSystem":"ChatGPT","affectedGroup":"State-backed hacker groups","action":"Disrupted and terminated accounts associated with state-backed hacker groups","consequence":"Disruption of malicious activities, including research, translation, finding coding errors, and basic coding tasks"}},{"i":"R1783","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Driverless car crash waymo cyclist b2492735","s":"Waymo says its autonomous vehicle did not see the cyclist as it was hidden behind a truck. An investigation is underway into a collision between a driverless taxi and a cyclist in San Francisco on Tuesday. Californian police and regulators are reviewing the incident, first reported by Reuters, after the cyclist was left with minor injuries. The vehicle involved was a robotaxi owned by WaYmo, the autonomous driving unit of Google ’s parent company Alphabet. A spokesperson for Waymo said the vehicle was pulling out from a four-way intersection and failed to spot a cyclist hidden behind a truck that was turning into the intersection.","u":"https://www.independent.co.uk/tech/driverless-car-crash-waymo-cyclist-b2492735.html","d":"2024-02-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-08","organization":"Waymo (WaYmo, autonomous driving unit of Google's parent company Alphabet)","aiSystem":"driverless taxi","affectedGroup":"cyclist","action":"failed to spot a cyclist hidden behind a truck","consequence":"left with minor injuries"}},{"i":"R1784","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai worm computer security chatgpt malware b2506594","s":"Morris II represents new breed of ‘zero-click malware’, researchers warn. Security researchers have developed a self-replicating AI worm that can infiltrate people’s emails in order to spread malware and steal data. Dubbed Morris II, after the first ever computer worm from 1988, the computer worm was created by an international team from the US and Israel in an effort to highlight the risks associated with generative artificial intelligence (GenAI). The worm is designed to target AI-powered apps that use popular tools like OpenAI’s ChatGPT and Google’s Gemini. It has already been demonstrated against GenAI-powered email assistants to steal personal data and launch spamming campaigns.","u":"https://www.independent.co.uk/tech/ai-worm-computer-security-chatgpt-malware-b2506594.html","d":"2024-02-03","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-02-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-03","organization":"International team from the US and Israel","aiSystem":"Morris II AI worm","affectedGroup":"People using AI-powered email assistants","action":"Infiltrate emails to steal personal data and launch spamming campaigns","consequence":"Privacy intrusion, theft of personal data"}},{"i":"R1786","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"New york times microsoft openai lawsuit b2470094","s":"Newspaper alleges it is owed ‘billions of dollars in statutory and actual damages’. The Independent's journalism is supported by our readers. When you purchase through links on our site, we may earn commission. New York Times sues OpenAI and Microsoft for copying articles Newspaper alleges it is owed ‘billions of dollars in statutory and actual damages’ - Bookmark - CommentsGo to comments The New York Times has sued ChatGPT maker OpenAI and Microsoft over alleged copyright infringement. The newspaper accuses the companies in a new lawsuit of using its intellectual property to train the large language models used by ChatGPT.","u":"https://www.independent.co.uk/tech/new-york-times-microsoft-openai-lawsuit-b2470094.html","d":"2023-12-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-27","organization":"New York Times, OpenAI, Microsoft","aiSystem":"Large language models used by ChatGPT","affectedGroup":"New York Times","action":"Used New York Times' intellectual property to train large language models","consequence":"Sued by New York Times for billions of dollars in statutory and actual damages"}},{"i":"R1789","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"California cruise gm driverless taxi b2435296","s":"GM-owned AV company can still operate cars with test driver onboard. Bookmark - CommentsGo to comments Autonomous carmaker Cruise must suspend its driverless taxi operations in California immediately, state motor vehicles regulators announced on Tuesday. \"The California DMV today notified Cruise that the department is suspending Cruise’s autonomous vehicle deployment and driverless testing permits, effective immediately,” the state Department of Motor Vehicles said in a statement. “The DMV has provided Cruise with the steps need to apply to reinstate its suspended permits, which the DMV will not approve until the company has fulfilled the requirements to the department’s satisfaction.”","u":"https://www.independent.co.uk/news/world/americas/california-cruise-gm-driverless-taxi-b2435296.html","d":"2023-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-24","organization":"Cruise (AV company owned by GM)","aiSystem":"driverless taxi technology","affectedGroup":"passengers of Cruise's driverless taxis","action":"operations of driverless taxis were suspended","consequence":"denied access to services"}},{"i":"R1791","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ai water energy artificial intelligence b2409356","s":"Gallons of water are just one part of sustainability questions over the growth of artificial intelligence. Bookmark - CommentsGo to comments Artificial intelligence is using gallons upon gallons of water. Microsoft alone used more than 2,500 Olympic-sized swimming pools of water in its data centres last year. The latest numbers are leading to yet more questions about the sustainability and environmental dangers of the growth of artificial intelligence and related technology. Artificial intelligence requires vast computing resources, undertaking deeply complex calculations on behalf of people around the world. AI systems tend to be run in the cloud rather than on individual people’s computers, meaning that companies running them must operate vast server farms to deal with the queries of their users.","u":"https://www.independent.co.uk/tech/ai-water-energy-artificial-intelligence-b2409356.html","d":"2023-09-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-11","organization":"Microsoft","aiSystem":"Artificial intelligence","affectedGroup":"Environment","action":"Used vast computing resources","consequence":"Led to increased questions about sustainability and environmental dangers"}},{"i":"R1793","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Iowa school banned books chatgpt b2393494","s":"The banned books include ‘The Handmaid’s Tale’ by Margaret Atwood and ‘Beloved’ by Toni Morrison. Bookmark - CommentsGo to comments A school district in Iowa is utilising ChatGPT to advance a book ban. Mason City Community School District has pulled 19 books from school libraries’ shelves, including “The Handmaid’s Tale” by Margaret Atwood and “Beloved” by Toni Morrison, according to The Gazette. The changes were made in order for the district to comply with an Iowa law, Senate File 496, which prohibited “instruction related to gender identity and sexual orientation in school districts.” Additionally, school libraries must hold books that contain “age-appropriate material,” which excludes “any material with descriptions or visual depictions of a sex act,” according to the measure.","u":"https://www.independent.co.uk/news/world/americas/iowa-school-banned-books-chatgpt-b2393494.html","d":"2023-08-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-15","organization":"Mason City Community School District","aiSystem":"ChatGPT","affectedGroup":"Students, parents, educators","action":"Used ChatGPT to generate content that led to the removal of books from school libraries","consequence":"Restricted access to banned books and age-inappropriate material"}},{"i":"R1795","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt dark web wormgpt hack b2376627","s":"Europol warns AI tool is ‘extremely useful’ for cyber criminals. Bookmark - CommentsGo to comments A ChatGPT-style AI tool with “no ethical boundaries or limitations” is offering hackers a way to perform attacks on a never-before-seen scale, researchers have warned. Cyber security firm SlashNext observed the generative artificial intelligence WormGPT being marketed on cybercrime forums on the dark web, describing it as a “sophisticated AI model” capable of producing human-like text that can be used in hacking campaigns. “This tool presents itself as a blackhat alternative to GPT models, designed specifically for malicious activities,” the company explained in a blog post.","u":"https://www.independent.co.uk/tech/chatgpt-dark-web-wormgpt-hack-b2376627.html","d":"2023-07-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-17","organization":"SlashNext","aiSystem":"WormGPT","affectedGroup":"Cyber criminals","action":"Offering hackers a way to perform attacks","consequence":"Performing attacks on a never-before-seen scale"}},{"i":"R1796","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Sarah silverman chatgpt openai meta llama text lawsuit b2372692","s":"Two of the world’s biggest artificial intelligence firms are being sued by celebrities including Sarah Silverman. Sarah Silverman and other authors sue ChatGPT creator over claims it stole their texts - Bookmark - CommentsGo to comments Two of the world’s biggest artificial intelligence firms are being sued by celebrities including Sarah Silverman. The writers claim that ChatGPT creator OpenAI and Facebook parent company Meta used their text to train their artificial intelligence systems, without permission. “Since the release of OpenAI’s ChatGPT system in March 2023, we’ve been hearing from writers, authors, and publishers who are concerned about its uncanny ability to generate text similar to that found in copyrighted textual materials, including thousands of books,” wrote Joseph Saveri and Matthew Butterick, the lawyers behind the class-action complaint.","u":"https://www.independent.co.uk/tech/sarah-silverman-chatgpt-openai-meta-llama-text-lawsuit-b2372692.html","d":"2023-07-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-10","organization":"OpenAI and Facebook parent company Meta","aiSystem":"Artificial intelligence systems trained by OpenAI and Meta","affectedGroup":"Writers, authors, and publishers","action":"Used copyrighted textual materials to train their AI systems","consequence":"Concerns about generating text similar to copyrighted works"}},{"i":"R1799","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Midjourney free ai images trump pope b2312000","s":"Site had been used to create fake pictures of Donald Trump being arrested and the Pope wearing a stylish coat. Midjourney: Controversial AI image tool stops free trials after ‘abuse’ Site had been used to create fake pictures of Donald Trump being arrested and the Pope wearing a stylish coat - Bookmark - CommentsGo to comments Midjourney, the controversial image generating AI, has stopped free trials after it says it was “abused”. The change comes after a range of high-profile fake images were created using the tool, including pictures of Donald Trump being arrested and the Pope wearing a stylish jacket. After that controversy, Midjourney chief executive announced on Discord that the site was stopping its free trials amid “extraordinary demand and trial abuse”.","u":"https://www.independent.co.uk/tech/midjourney-free-ai-images-trump-pope-b2312000.html","d":"2023-03-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-31","organization":"Midjourney","aiSystem":"Midjourney, the controversial image generating AI","affectedGroup":"Users seeking free trials","action":"Stopped free trials","consequence":"Exposure to misleading content"}},{"i":"R1801","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Trump grand jury deepfake images b2307041","s":"Flood of deepfake images prompts NYPD to deny it has detained the former president. Bookmark - CommentsGo to comments A grand jury investigating Donald Trump’s alleged role in a scheme to pay hush money to a porn star won’t consider the case until at least next week – further postponing a decision on his possible arrest. The latest twist in the saga came after Stormy Daniels said her phone records are bombshell evidence in the case and are “gonna hurt” the former president. The New York grand jury had been expected to meet on Thursday to consider evidence involving Mr Trump’s role involving a $130,000 (£106,000) payment to Ms Daniels in 2016 that prosecutors reportedly allege was an illegal campaign expenditure.","u":"https://www.independent.co.uk/independentpremium/world/trump-grand-jury-deepfake-images-b2307041.html","d":"2023-03-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-23","organization":"New York Police Department (NYPD)","aiSystem":"Deepfake technology","affectedGroup":"Donald Trump","action":"Generated and distributed deepfake images","consequence":"Exposure to misleading content"}},{"i":"R1806","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"2022 06 09 timnit gebru and the fight to make artificial intelligence work for africa","s":"As you read this, the future is being coded in Silicon Valley. The algorithms that will one day govern our lives are being built. But who is building them, and who are they being built for? The way Timnit Gebru sees it, the foundations of the future are being built now. In Silicon Valley, home to the world’s biggest tech companies, the artificial intelligence (AI) revolution is already well under way. Software is being written and algorithms are being trained that will determine the shape of our lives for decades or even centuries to come. If the tech billionaires get their way, the world will run on artificial intelligence.","u":"https://mg.co.za/africa/2022-06-09-timnit-gebru-and-the-fight-to-make-artificial-intelligence-work-for-africa/","d":"2021-06-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-06-09","organization":"Tech billionaires and Silicon Valley","aiSystem":"Artificial intelligence (AI) algorithms","affectedGroup":"Future generations","action":"Building AI algorithms","consequence":"Determining life shape for decades or centuries"}},{"i":"R1823","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musks x should be held liable for grok producing sexual images of women minors","s":"The platform says users are to blame for using the chatbot to produce ‘illegal content’. But it can’t be allowed to escape accountability neglecting guardrails. Since the end of December, 2025, X’s artificial intelligence chatbot, Grok, has responded to many users’ requests to undress real people by turning photos of the people into sexually explicit material. After people began using the feature, the social platform company faced global scrutiny for enabling users to generate nonconsensual sexually explicit depictions of real people. The Grok account has posted thousands of “nudified” and sexually suggestive images per hour Even more disturbing, Grok has generated sexualised images and sexually explicit material of minors X’s response: Blame the platform’s users, not us The company issued a statement on January 3, 2026, saying that “Anyone using or prompting Grok to make illegal…","u":"https://scroll.in/article/1089919/elon-musks-x-should-be-held-liable-for-grok-producing-sexual-images-of-women-minors","d":"2026-01-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12","organization":"X (presumably referring to Twitter)","aiSystem":"Grok artificial intelligence chatbot","affectedGroup":"Real people, particularly minors","action":"Generated sexually explicit material","consequence":"Exposure to sexualized and sexually explicit content"}},{"i":"R1835","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Two authors are suing openai for training chatgpt with their books could they win","s":"OpenAI is accused of allowing its AI program to copy a book to its internal database and train on it. Imagine you read a book. You commit details of the book to memory and ruminate on the ideas contained in it. Somebody then asks you a question about the book. You provide them with a written response. Would you be surprised if the author of the book tried to sue you for copyright infringement? OpenAI is facing exactly this situation. Mona Awad is suing OpenAI. Authors Mona Awad (Bunny, 13 Ways of Looking at a Fat Girl) and Paul Tremblay (The Cabin at the End of the World), filed a lawsuit against OpenAI last week, claiming the books were used to train ChatGPT, its artificial intelligence software, without their consent.","u":"https://scroll.in/article/1052868/two-authors-are-suing-openai-for-training-chatgpt-with-their-books-could-they-win","d":"2023-07-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-13","organization":"OpenAI","aiSystem":"ChatGPT (artificial intelligence software)","affectedGroup":"Authors Mona Awad and Paul Tremblay","action":"Used books to train ChatGPT","consequence":"Sued for copyright infringement"}},{"i":"R1843","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook groups misinformation","s":"Facebook has said it will no longer algorithmically recommend political groups to users, but experts warn that isn’t enough. Mark Zuckerberg, the Facebook CEO, announced last week the platform will no longer algorithmically recommend political groups to users in an attempt to “turn down the temperature” on online divisiveness. But experts say such policies are difficult to enforce, much less quantify, and the toxic legacy of the Groups feature and the algorithmic incentives promoting it will be difficult to erase. “This is like putting a Band-Aid on a gaping wound,” said Jessica J González, the co-founder of the anti-hate speech group Change the Terms.","u":"https://www.theguardian.com/technology/2021/feb/04/facebook-groups-misinformation","d":"2021-02-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-02-04","organization":"Facebook","aiSystem":"Facebook's recommendation algorithm for political groups","affectedGroup":"Users","action":"Algorithmically recommended political groups","consequence":"Exposure to misinformation"}},{"i":"R1844","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google timnit gebru ai engineers quit","s":"Timnit Gebru, an eminent Black scientist, says she was fired last year in clash over research on marginalized groups. Two Google engineers have quit over the treatment of Timnit Gebru, a prominent Black artificial intelligence researcher whose exit from the company sparked widespread outrage in the tech industry. David Baker, an engineering director focused on user safety, left Google last month after 16 years because Gebru’s departure “extinguished my desire to continue as a Googler”, he said in a letter seen by Reuters. Baker added: “We cannot say we believe in diversity, and then ignore the conspicuous absence of many voices from within our walls.”","u":"https://www.theguardian.com/technology/2021/feb/04/google-timnit-gebru-ai-engineers-quit","d":"2021-02-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-02-04","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Timnit Gebru","action":"Was fired","consequence":"Widespread outrage in the tech industry"}},{"i":"R1845","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google fires margaret mitchell ai ethics team","s":"The dismissal comes after prominent Black researcher Timnit Gebru was fired in December; both had called for more diversity among research staff. Google has fired one of its top artificial intelligence researchers, Margaret Mitchell, escalating internal turmoil at the company following the departure of Timnit Gebru, another leading figure on Google’s AI ethics team. Mitchell, who announced her firing on Twitter, did not immediately respond to requests for comment. In a statement to Reuters, Google said the firing followed a weeks-long investigation that found she moved electronic files outside the company. Google said Mitchell violated the company’s code of conduct and security policies.","u":"https://www.theguardian.com/technology/2021/feb/19/google-fires-margaret-mitchell-ai-ethics-team","d":"2021-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-02-19","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Margaret Mitchell","action":"Was fired","consequence":"Lost employment"}},{"i":"R1846","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook spanish language misinformation covid 19 election","s":"Researchers say Spanish-language content is less often and less quickly moderated for misinformation than English content. In the last year, Facebook adjusted some of the most fundamental rules about what gets posted on its platform, halting algorithmic recommendations of political groups, banning lies about vaccines and removing a number of high-profile figures for spreading misinformation and hate – including Donald Trump. But researchers say the social media platform is not enforcing those policies as effectively when it comes to misinformation in Spanish – a blind spot that may prove deadly as health lies spread through the most vulnerable populations during the global vaccine effort.","u":"https://www.theguardian.com/technology/2021/mar/03/facebook-spanish-language-misinformation-covid-19-election","d":"2021-03-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-03-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-03-03","organization":"Facebook","aiSystem":"Facebook's content moderation system","affectedGroup":"Vulnerable populations","action":"Failed to enforce misinformation policies effectively","consequence":"Health lies spread"}},{"i":"R1847","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Amazon delivery workers bathrooms memo","s":"Documents provided to the Intercept published after the company denied reports delivery workers lack access to bathrooms. Amazon caused an uproar on Thursday when it denied reports that its delivery workers have been forced to urinate in bottles due to lack of access to bathrooms, but a leaked internal memo shows the company has been aware of the problem for at least several months. Documents provided by employees at Amazon to the Intercept showed that an email sent in May 2020 admonished workers for urinating in bottles and defecating in bags while on the job. “This evening, an associate discovered human feces in an Amazon bag that was returned to station by a driver,” the email reads.","u":"https://www.theguardian.com/technology/2021/mar/25/amazon-delivery-workers-bathrooms-memo","d":"2021-03-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-03-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-05-???","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"Delivery workers","action":"Monitored and recorded workers' bathroom usage","consequence":"Workers' personal hygiene practices compromised"}},{"i":"R1848","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Facebook accused of discriminatory and racist behaviour after removing historical png images","s":"Group publishing archival photos claims images showing traditional dress or ceremonies were deleted for allegedly containing nudity. Facebook has been accused of “discriminatory and racist” behaviour after it deleted historical photos from a group that publishes archival photos of men and women from Papua New Guinea. The group, which boasts over 55,000 members, claims photos showing traditional dress or ceremonies were deleted for allegedly containing nudity – but photos showing nudity among white people were not. They are now calling on the social media giant to reconsider how it applies its community standards.","u":"https://www.theguardian.com/technology/2021/may/28/facebook-accused-of-discriminatory-and-racist-behaviour-after-removing-historical-png-images","d":"2021-05-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-05-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-05-27","organization":"Facebook","aiSystem":"Facebook's image moderation system","affectedGroup":"Men and women from Papua New Guinea","action":"Deleted historical photos","consequence":"Photos showing traditional dress or ceremonies were removed for allegedly containing nudity"}},{"i":"R1849","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Teslas autopilot us investigation crashes emergency vehicles","s":"• Investigators to review 765,000 vehicles made since 2014 • NHTSA identifies 11 crashes involving first responder vehicles. The US government has opened a formal investigation into Tesla’s driver-assistance system known as Autopilot after a series of collisions with parked emergency vehicles. The investigation covers 765,000 vehicles, almost everything that Tesla has sold in the US since the start of the 2014 model year. Of the crashes identified by the National Highway Traffic Safety Administration (NHTSA) as part of the investigation, 17 people were injured and one was killed. NHTSA says it has identified 11 crashes since 2018 in which Teslas on Autopilot or Traffic Aware Cruise Control have hit vehicles at scenes where first responders used flashing lights, flares, an illuminated arrow board or cones warning of hazards.","u":"https://www.theguardian.com/technology/2021/aug/16/teslas-autopilot-us-investigation-crashes-emergency-vehicles","d":"2021-08-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-16","organization":"US government","aiSystem":"Tesla's driver-assistance system known as Autopilot","affectedGroup":"First responders","action":"Tesla's Autopilot or Traffic Aware Cruise Control hit vehicles","consequence":"Injuries and death to first responders"}},{"i":"R1851","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenage girls body image and instagrams perfect storm","s":"The suffering of the photo-sharing app’s users came into focus this week with the leak of Facebook’s internal research ‘I felt my body wasn’t good enough’. Emily started using Instagram when she was in her mid-teens and found it helpful at first. She used the photo-sharing app to follow fitness influencers, but what began as a constructive relationship with the platform spiralled into a crisis centred on body image. At 19 she was diagnosed with an eating disorder. “I felt like my body wasn’t good enough, because even though I did go to the gym a lot, my body still never looked like the bodies of these influencers,” says Emily, now a 20-year-old a student who is in recovery.","u":"https://www.theguardian.com/technology/2021/sep/18/teenage-girls-body-image-and-instagrams-perfect-storm","d":"2021-09-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-09-18","organization":"Facebook","aiSystem":"Social media platform algorithms","affectedGroup":"Teenage girls","action":"Generated and promoted idealized body images","consequence":"Exposure to misleading content leading to mental health issues"}},{"i":"R1852","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Florida tesla crash autopilot fire national federal transportation board","s":"The Model 3 left the road near a residential intersection, collided with a tree and burst into flames, killing a man and a woman. Federal authorities will investigate a fiery car crash which killed two people in a Tesla in Florida last week. The National Transportation Safety Board announced on Twitter it would send three investigators to look into the operation of a Tesla Model 3 which left the road in Coral Gables and collided with a tree, and the fire that followed. “We always look especially closely at newer technology,” said Peter Knudson, an NTSB spokesman. The crash occurred near a residential intersection.","u":"https://www.theguardian.com/technology/2021/sep/18/florida-tesla-crash-autopilot-fire-national-federal-transportation-board","d":"2021-09-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-09-18","organization":"Tesla","aiSystem":"Autopilot system","affectedGroup":"Two people","action":"Left the road and collided with a tree","consequence":"Killed"}},{"i":"R1856","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook whistleblower january 6 capitol attack","s":"Materials provided by Frances Haugen to media outlets shine light on how company apparently stumbled into 6 January. As extremist supporters of Donald Trump stormed the US Capitol on 6 January, battling police and forcing lawmakers into hiding, an insurrection of a different kind was taking place inside the world’s largest social media company. Thousands of miles away, in California, Facebook engineers were racing to tweak internal controls to slow the spread of misinformation and content likely to incite further violence. Emergency actions – some of which were rolled back after the 2020 election – included banning Trump, freezing comments in groups with records of hate speech and filtering out the “Stop the Steal” rallying cry of Trump’s campaign to overturn his electoral loss, falsely citing widespread fraud.","u":"https://www.theguardian.com/technology/2021/oct/23/facebook-whistleblower-january-6-capitol-attack","d":"2021-10-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-06","organization":"Facebook","aiSystem":"Facebook's content moderation system","affectedGroup":"Extremist supporters of Donald Trump","action":"Tweaked internal controls to slow the spread of misinformation and content likely to incite further violence","consequence":"Amplification of misinformation and potential incitement of further violence"}},{"i":"R1857","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Facebook to shut facial recognition system and delete 1bn faceprints","s":"Firm says decision is in response to growing concerns over software that identifies users in photos and videos. Facebook will delete the “faceprints” of more than a billion people after announcing that it is shutting down its facial recognition system due to the “many concerns” about using the technology. The social media network has been under political, legal and regulatory pressure over its use of the software, which automatically identifies users in photos and videos – and let’s them know if a fellow user has posted a photo or video with them in it – if they have opted in to the feature. In a statement, Facebook’s parent company, Meta, said it would shut down facial recognition on the platform over the coming weeks and delete 1 billion facial recognition templates.","u":"https://www.theguardian.com/technology/2021/nov/02/facebook-to-shut-facial-recognition-system-and-delete-1bn-faceprints","d":"2021-11-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-02","organization":"Facebook","aiSystem":"Facial recognition technology","affectedGroup":"People whose faceprints were stored","action":"Deleted faceprints of more than a billion people","consequence":"Exposure to privacy risks"}},{"i":"R1859","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Facebook restores banned ad promoting renters rights after tweet goes viral","s":"Ronan Burtenshaw’s publication was labelled as discriminatory and blocked from being promoted. Facebook will restore a banned advert promoting an opinion piece calling for renters rights, after the company’s automated systems blocked the post for “discrimination”. But critics say the error will be repeated unless Facebook acts to protect campaigners on its platform. On Monday Ronan Burtenshaw, the editor of Tribune Magazine, received a message from Facebook saying one of his publication’s posts had been blocked from being promoted on the site. The story, headlined The Rent is Too Damn High, calls for “a struggle of renters against the rentiers” and concludes that solving the housing crisis requires a massive programme of council house creation.","u":"https://www.theguardian.com/technology/2022/apr/05/facebook-restores-banned-ad-promoting-renters-rights-after-tweet-goes-viral","d":"2022-04-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-04-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-04-05","organization":"Facebook","aiSystem":"Facebook's automated systems","affectedGroup":"Ronan Burtenshaw, the editor of Tribune Magazine","action":"blocked a post","consequence":"publication's post was blocked from being promoted"}},{"i":"R1860","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Remote work software home surveillance computer monitoring pandemic","s":"Computer monitoring software is helping companies spy on their employees to measure their productivity – often without their consent. When the job of a young east coast-based analyst – we’ll call him James – went remote with the pandemic, he didn’t envisage any problems. The company, a large US retailer for which he has been a salaried employee for more than half a decade, provided him with a laptop, and his home became his new office. Part of a team dealing with supply chain issues, the job was a busy one, but never had he been reprimanded for not working hard enough. So it was a shock when his team was hauled in one day late last year to an online meeting to be told there was gaps in its work: specifically periods when people – including James himself, he was later informed – weren’t inputting information into the company’s database.","u":"https://www.theguardian.com/technology/2022/apr/27/remote-work-software-home-surveillance-computer-monitoring-pandemic","d":"2022-04-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-04-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"Late last year","organization":"Large US retailer","aiSystem":"Computer monitoring software","affectedGroup":"Employees, particularly James","action":"Monitoring employees' productivity remotely","consequence":"Reprimanding employees for not working hard enough"}},{"i":"R1862","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot crashes investigation nhtsa","s":"Regulators to look with enhanced scrutiny after cars with driver-assistance function crashed into parked emergency vehicles. US federal regulators are deepening their investigation into Tesla’s Autopilot function after more than a dozen Tesla cars crashed into parked first-responder vehicles over a period of four years. The National Highway Traffic Safety Administration (NHTSA) said on Thursday it was upgrading its preliminary investigation, which launched last August, to an “engineering analysis”, which is taken before the agency determines a recall. The investigation covers all four Tesla vehicles – Models Y, X, S and 3 – representing about 830,000 vehicles that have been sold in the US.","u":"https://www.theguardian.com/technology/2022/jun/09/tesla-autopilot-crashes-investigation-nhtsa","d":"2022-06-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-09","organization":"National Highway Traffic Safety Administration (NHTSA)","aiSystem":"Tesla Autopilot function","affectedGroup":"Tesla car owners","action":"Tesla cars with Autopilot function crashed into parked emergency vehicles","consequence":"Investigation and potential recall of Tesla vehicles"}},{"i":"R1863","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Amazon alexa could turn dead loved ones digital assistant","s":"Technology promises ability to ‘make the memories last’ by mimicking the voice of anyone it hears. Amazon plans to let people turn their dead loved ones’ voices into digital assistants, with the company promising the ability to “make the memories last”. The company is developing technology that will allow its Alexa digital assistant to mimic the voice of anyone it hears from less than a minute of provided audio, Rohit Prasad, its senior vice-president and head scientist, said on Wednesday. He added that during the coronavirus paramedic “so many of us have lost someone we love”. While no timescale was given for the launch of the feature, the underlying technology has existed for several years.","u":"https://www.theguardian.com/technology/2022/jun/23/amazon-alexa-could-turn-dead-loved-ones-digital-assistant","d":"2022-06-23","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-06-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-23","organization":"Amazon","aiSystem":"Alexa digital assistant","affectedGroup":"Dead loved ones","action":"Alexa mimics the voice of dead loved ones","consequence":"Privacy intrusion, unauthorized use of deceased's voice"}},{"i":"R1864","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Us school shooting technology solution","s":"Despite the growing adoption of security tools in US schools, mass shootings have remained constant throughout the past 30 years. After the mass shooting at an elementary school in Uvalde, Texas , an all-too-familiar question emerged: how do we prevent such horror from happening again? A handful of companies have said they have tech solutions that could help. They included the drone firm Axon , which promoted a remotely operated Taser device to be deployed in schools. EdTech companies, including Impero Software, said their student surveillance services could flag warning signs and help prevent the next attack. The companies are part of a thriving school security industry, one that has been forecast to reach $3.1bn in 2021 from just $2.7bn in 2017, according to numbers from market firm Omdia.","u":"https://www.theguardian.com/technology/2022/jun/30/us-school-shooting-technology-solution","d":"2022-06-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-30","organization":"EdTech companies (including Impero Software)","aiSystem":"student surveillance services","affectedGroup":"students","action":"flag warning signs and help prevent the next attack","consequence":"prevent the next attack"}},{"i":"R1867","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla self driving technology safety children","s":"Safe technology campaigners release ‘disturbing’ video advert showing car in Full Self-Driving mode hitting child-sized mannequin. A safe-technology campaign group opposed to Tesla’s self-driving technology has claimed to have run tests that show the software represents a potentially lethal threat to child pedestrians, in the latest in a series of claims and investigations to hit the world’s leading electric carmaker. The Dawn Project says its test track results revealed that the latest version of Tesla’s Full Self-Driving (FSD) Beta software failed to detect a stationary, child-sized mannequin at an average speed of 25mph.","u":"https://www.theguardian.com/technology/2022/aug/09/tesla-self-driving-technology-safety-children","d":"2022-08-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-09","organization":"Tesla","aiSystem":"Tesla's Full Self-Driving (FSD) Beta software","affectedGroup":"child pedestrians","action":"failed to detect a stationary, child-sized mannequin","consequence":"potentially lethal threat"}},{"i":"R1868","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Google csam account blocked","s":"Experts say case highlights dangers of automated detection of child sexual abuse images. Google has refused to reinstate a man’s account after it wrongly flagged medical images he took of his son’s groin as child sexual abuse material (CSAM), the New York Times first reported. Experts say it’s an inevitable pitfall of trying to apply a technological solution to a societal problem. Experts have long warned about the limitations of automated child sexual abuse image detection systems, particularly as companies face regulatory and public pressure to help address the existence of sexual abuse material. “These companies have access to a tremendously invasive amount of data about people’s lives.","u":"https://www.theguardian.com/technology/2022/aug/22/google-csam-account-blocked","d":"2022-08-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-22","organization":"Google","aiSystem":"Automated child sexual abuse image detection system","affectedGroup":"Individuals whose medical images were flagged","action":"Flagged medical images as child sexual abuse material","consequence":"Account blocked without review"}},{"i":"R1869","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla fanatics elon musk children moving cars","s":"Some superfans are so determined to prove that Elon Musk’s ‘autonomous’ driving technology works that they are willing to put their kids in harm’s way. I’ve been a mum for a relatively short time; I’m not exactly an expert when it comes to this whole parenting thing. Still, there is one piece of advice I can confidently dole out: don’t instruct your child to run in front of a moving vehicle so that you can win an argument with strangers on the internet. Elon Musk obsessives, I’m looking at you. This month, a software CEO called Dan O’Dowd, who is hellbent on trying to ban Tesla’s “full self-driving” programme, launched an ad campaign claiming that if you put a Tesla in this mode it will mow down children.","u":"https://www.theguardian.com/technology/commentisfree/2022/aug/23/tesla-fanatics-elon-musk-children-moving-cars","d":"2022-08-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-23","organization":"Dan O'Dowd (software CEO)","aiSystem":"Tesla's 'full self-driving' programme","affectedGroup":"Children","action":"Tesla's 'full self-driving' programme was put into operation","consequence":"Risk of children being hit by the vehicle"}},{"i":"R1872","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Tiktok coyotes scammers migrants american dream revealed","s":"The video platform has become a place for migrants to seek and share information, but experts fear exploitation is on the rise Read the new Guardian series exploring the increasing power and reach of TikTok. The TikTok video starts like most other travel snaps on the platform do, with selfie shots showing the user* and his companions sitting on a plane and walking through the airport. But unlike the highly curated images of hotels and tourist attractions typical of this genre on TikTok, the video quickly takes an uncharacteristic turn, showing the user sleeping in camps, at one point traveling by horseback and ultimately scaling what he calls “la famosa frontera de la muerte” or “the famous border of death” between the US and Mexico.","u":"https://www.theguardian.com/technology/2022/oct/22/tiktok-coyotes-scammers-migrants-american-dream-revealed","d":"2022-10-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-23","organization":"TikTok","aiSystem":"TikTok","affectedGroup":"Migrants","action":"Share and seek information","consequence":"Exploitation"}},{"i":"R1873","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Tiktok election misinformation voting politics","s":"A study suggests the video platform is failing to filter false claims and rhetoric in the weeks leading up to US midterms Read the new Guardian series exploring the increasing power and reach of TikTok. In the final sprint to the US midterm elections the social media giant TikTok risks being a major vector for election misinformation, experts warn, with the platform’s huge user base and its design making it particularly susceptible to such threats. Preliminary research published last week from digital watchdog Global Witness and the Cybersecurity for Democracy team at New York University suggests the video platform is failing to filter large volumes of election misinformation in the weeks leading up to the vote.","u":"https://www.theguardian.com/technology/2022/oct/24/tiktok-election-misinformation-voting-politics","d":"2022-10-25","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-24","organization":"TikTok","aiSystem":"TikTok","affectedGroup":"People participating in the US midterm elections","action":"Generated and shared election misinformation","consequence":"Increased risk of election interference and manipulation"}},{"i":"R1876","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Twitters mass layoffs days before us midterms could be a misinformation disaster","s":"Internal chaos at the company – and the decimation of its staff – has created ideal conditions for falsehoods and hateful content. The mass layoffs at Twitter that diminished several teams, including staff on the company’s safety and misinformation teams, could spell disaster during the US midterm elections next week, experts have warned. The company has laid off around 50% of its workforce, according to news reports; a figure that Musk and others have not disputed, amounting to an estimated 3,700 people. The internal chaos unfolding at Twitter, in addition to a sudden lack of staff and resources dedicated to counteracting misinformation, has created ideal conditions for election misinformation to thrive, said Paul Barrett, an expert in disinformation and fake news at New York University.","u":"https://www.theguardian.com/technology/2022/nov/04/twitters-mass-layoffs-days-before-us-midterms-could-be-a-misinformation-disaster","d":"2022-11-05","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-04","organization":"Twitter","aiSystem":"Not specified in report","affectedGroup":"People exposed to election misinformation","action":"Generated and spread false information","consequence":"Increased likelihood of election interference and manipulation"}},{"i":"R1877","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Twitter may not cope with world cup abuse says kick it out chair","s":"Sanjay Bhandari says cuts in trust and safety team at platform could be taken as ‘green light for hate’. The chair of the anti-discrimination body Kick It Out has voiced fears that Twitter will be unable to cope with online abuse during the football World Cup, after a wave of job losses at the social media platform. Sanjay Bhandari said he was deeply concerned by reports of cuts in the trust and safety team at Twitter, as well as the departure of the executive in charge of the department. “I am deeply concerned that the reduction in the trust and safety team and the departure of the leader of that team will be taken as a bright green light for hate,” said Bhandari.","u":"https://www.theguardian.com/technology/2022/nov/18/twitter-may-not-cope-with-world-cup-abuse-says-kick-it-out-chair","d":"2022-11-18","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-18","organization":"Twitter","aiSystem":"Twitter's automated content moderation system","affectedGroup":"Employees of Twitter","action":"Job losses and departures in the trust and safety team","consequence":"Concerns about reduced capacity to handle online abuse"}},{"i":"R1879","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Twitter anti vax health misinformation","s":"Platform’s paid verification system is being used to give sense of validity to accounts pushing health misinformation. As the troubled social media platform Twitter rolled out a paid verification system and laid off thousands of content moderators, health misinformation accounts on the social network began pushing their messages to a wider audience than ever. Under Elon Musk’s new direction for Twitter, several anti-vaccine accounts with tens of thousands of followers are now verified by paying $7.99 a month for Twitter Blue. Social media sites have long struggled with misleading information and content moderation.","u":"https://www.theguardian.com/technology/2022/nov/21/twitter-anti-vax-health-misinformation","d":"2022-11-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-21","organization":"Twitter","aiSystem":"Twitter's paid verification system","affectedGroup":"Health misinformation accounts, their followers","action":"Accounts with health misinformation were given a sense of validity through paid verification","consequence":"Health misinformation spread to a wider audience"}},{"i":"R1880","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Climate change denialism flooding twitter scientists","s":"Many researchers are fleeing the platform, unnerved by the surge in climate misinformation since Musk’s chaotic takeover. Twitter has proved a cherished forum for climate scientists to share research, as well as for activists seeking to rally action to halt oil pipelines or decry politicians’ failure to cut pollution. But many are now fleeing Twitter due to a surge in climate misinformation, spam and even threats that have upended their relationship with the platform. Scientists and advocates have told the Guardian they have become unnerved by a recent resurgence of debunked climate change denialist talking points and memes on Twitter, with the term #ClimateScam now regularly the first result that appears when “climate” is searched on the site.","u":"https://www.theguardian.com/technology/2022/dec/02/climate-change-denialism-flooding-twitter-scientists","d":"2022-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-02","organization":"Twitter","aiSystem":"Twitter","affectedGroup":"Climate scientists","action":"Shared climate research and activist calls to action","consequence":"Surge in climate misinformation, spam, and threats"}},{"i":"R1882","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Apple artificial intelligence ai audiobooks","s":"Exclusive: tech firm quietly launches new audiobook catalogue narrated by AI – but move expected to spark backlash. Apple has quietly launched a catalogue of books narrated by artificial intelligence in a move that may mark the beginning of the end for human narrators. The strategy marks an attempt to upend the lucrative and fast-growing audiobook market – but it also promises to intensify scrutiny over allegations of Apple’s anti-competitive behaviour. The popularity of the audiobook market has exploded in recent years, with technology companies scrambling to gain a foothold. Sales last year jumped 25%, bringing in more than $1.5bn.","u":"https://www.theguardian.com/technology/2023/jan/04/apple-artificial-intelligence-ai-audiobooks","d":"2023-01-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-01-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-01-04","organization":"Apple","aiSystem":"AI-generated audiobook narration","affectedGroup":"Human audiobook narrators","action":"Launched a catalogue of books narrated by artificial intelligence","consequence":"Intensified scrutiny over allegations of anti-competitive behavior"}},{"i":"R1883","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Arena group ceo ross levinsohn fired sports illustrated ai articles","s":"Ross Levinsohn sacking was to ‘improve the operational efficiency and revenue of the company’, says board, two weeks after fake authors exposed. The Arena Group, publisher of Sports Illustrated, has fired the magazine’s CEO not long after it was revealed Sports Illustrated had published articles written by fake authors with AI-generated headshots and biographies. The Arena Group’s board announced on Monday that CEO Ross Levinsohn had his employment terminated, with Manoj Bhargava named as interim chief executive. The board said it followed a meeting on actions to “improve the operational efficiency and revenue of the company”.","u":"https://www.theguardian.com/technology/2023/dec/12/arena-group-ceo-ross-levinsohn-fired-sports-illustrated-ai-articles","d":"2023-12-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-10","organization":"Arena Group","aiSystem":"AI-generated content","affectedGroup":"Sports Illustrated employees, readers","action":"Published articles with AI-generated content","consequence":"Exposure to misleading content"}},{"i":"R1887","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Self driving cars exempt traffic tickets san francisco autonomous vehicle","s":"Laws in California have yet to catch up to autonomous vehicles, even though hundreds are already on the road. Autonomous vehicles in San Francisco are exempt from traffic tickets if there is nobody in the driver’s seat, according to the San Francisco police department (SFPD), underscoring ongoing legal and safety concerns surrounding the expanding technology. California law has not caught up to the cars, even though they are already on the road, say public safety agencies and experts. SFPD policy states that officers can make a traffic stop of autonomous vehicles (AVs) for violations, but can only issue a citation if there is a safety driver in the vehicle overseeing its operations.","u":"https://www.theguardian.com/technology/2024/jan/04/self-driving-cars-exempt-traffic-tickets-san-francisco-autonomous-vehicle","d":"2024-01-04","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-04","organization":"San Francisco Police Department (SFPD)","aiSystem":"Self-driving cars","affectedGroup":"People driving self-driving cars","action":"Traffic stops of autonomous vehicles","consequence":"Exemption from traffic tickets without a safety driver"}},{"i":"R1888","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Artificial intelligence surveillance workers","s":"Academics decry algorithmic monitoring of workers and call for stronger standards – but US unions have been slow to act. From algorithms firing staff without human intervention to software keeping tabs on bathroom breaks, technologies including artificial intelligence are already upsetting workers and unsettling workplaces. At call centers, AI systems record and grade how workers handle calls, often giving failing grades for not sticking to the script. Some corporate software spies on workers to see whether they ever write the word “union” in their emails. As technologies grow ever more sophisticated in monitoring, surveilling and speeding up workers, many workplace experts say US businesses, labor unions and government are not doing nearly enough to protect workers from tech’s downsides.","u":"https://www.theguardian.com/technology/2024/jan/07/artificial-intelligence-surveillance-workers","d":"2024-01-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-07","organization":"US businesses, labor unions, and government","aiSystem":"Artificial Intelligence","affectedGroup":"Workers","action":"AI systems monitor and surveil workers","consequence":"Upsetting workers and unsettling workplaces"}},{"i":"R1889","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai tools chatgpt copyrighted material openai","s":"Pressure grows on artificial intelligence firms over the content used to train their products. The developer OpenAI has said it would be impossible to create tools like its groundbreaking chatbot ChatGPT without access to copyrighted material, as pressure grows on artificial intelligence firms over the content used to train their products. Chatbots such as ChatGPT and image generators like Stable Diffusion are “trained” on a vast trove of data taken from the internet, with much of it covered by copyright – a legal protection against someone’s work being used without permission. Last month, the New York Times sued OpenAI and Microsoft, which is a leading investor in OpenAI and uses its tools in its products, accusing them of “unlawful use” of its work to create their products.","u":"https://www.theguardian.com/technology/2024/jan/08/ai-tools-chatgpt-copyrighted-material-openai","d":"2024-01-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-08","organization":"OpenAI and Microsoft","aiSystem":"AI-powered chatbot and image generator","affectedGroup":"Creators of copyrighted material","action":"Used copyrighted material to train AI products","consequence":"Legal action initiated by creators"}},{"i":"R1891","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"George carlin ai comedy","s":"Kelly Carlin decries comedy special on YouTube that generated a fake Carlin, saying ‘no machine will ever replace his genius’. Kelly Carlin, the American radio host and daughter of the late comedian George Carlin, has criticized the release of a new comedy special featuring an AI-generated version of her father, who died in 2008 due to heart failure. “My dad spent a lifetime perfecting his craft from his very human life, brain and imagination. No machine will ever replace his genius. These AI-generated products are clever attempts at trying to recreate a mind that will never exist again,” Kelly Carlin wrote in a series of tweets on X. The tweets arrived on the heels of Dudesy, a YouTube channel and podcast hosted by Will Sasso and Chad Kultgen, releasing an hour-long comedy special called I’m Glad I’m Dead, on Tuesday.","u":"https://www.theguardian.com/technology/2024/jan/11/george-carlin-ai-comedy","d":"2024-01-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-11","organization":"Dudesy, a YouTube channel and podcast hosted by Will Sasso and Chad Kultgen","aiSystem":"AI-generated technology","affectedGroup":"George Carlin's fans, family members, and the public","action":"Released an hour-long comedy special featuring an AI-generated version of George Carlin","consequence":"Misleading portrayal of George Carlin, perceived as a replacement for his genuine work"}},{"i":"R2244","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Deepfake video adverts sunak facebook alarm ai risk election","s":"Research finds more than 100 paid ads impersonating PM were promoted on social media platform in last month UK politics live – latest updates. More than 100 deepfake video advertisements impersonating Rishi Sunak were paid to be promoted on Facebook in the last month alone, according to research that has raised alarm about the risk AI poses before the general election. The adverts may have reached as many as 400,000 people – despite appearing to break several of Facebook’s policies – and mark the first time that the prime minister’s image has been doctored in a systematic way en masse. More than £12,929 was spent on 143 adverts, originating from 23 countries including the US, Turkey, Malaysia and the Philippines.","u":"https://www.theguardian.com/technology/2024/jan/12/deepfake-video-adverts-sunak-facebook-alarm-ai-risk-election","d":"2024-01-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-12","organization":"Facebook","aiSystem":"Deepfake video technology","affectedGroup":"General public","action":"Promoted deepfake video advertisements impersonating Rishi Sunak","consequence":"Potential misrepresentation of political figures, reaching large audience"}},{"i":"R1893","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai jobs inequality imf kristalina georgieva","s":"‘Crucial’ that countries build social safety nets to mitigate impact on workers, says Kristalina Georgieva Business live – latest updates. Artificial intelligence will affect 40% of jobs around the world and it is “crucial” that countries build social safety nets to mitigate the impact on vulnerable workers, according to the head of the International Monetary Fund. AI, the term for computer systems that can perform tasks usually associated with human levels of intelligence, is poised to profoundly change the global economy with advanced economies at greater risk of disruption. Analysis by the IMF, the international lender of last resort, says about 60% of jobs in advanced economies such as the US and UK are exposed to AI and half of these jobs may be negatively affected.","u":"https://www.theguardian.com/technology/2024/jan/15/ai-jobs-inequality-imf-kristalina-georgieva","d":"2024-01-15","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-15","organization":"International Monetary Fund (IMF)","aiSystem":"Artificial intelligence","affectedGroup":"vulnerable workers","action":"AI will affect jobs","consequence":"negative impact on jobs"}},{"i":"R1894","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Child sexual abuse ai moderator police meta alphabet","s":"Social media firms relying on AI for moderation generate unviable reports which prevent authorities from investigating cases. Social media companies relying on artificial intelligence software to moderate their platforms are generating unviable reports on cases of child sexual abuse, preventing US police from seeing potential leads and delaying investigations of alleged predators, the Guardian can reveal. By law, US-based social media companies are required to report any child sexual abuse material detected on their platforms to the National Center for Missing & Exploited Children (NCMEC). NCMEC acts as a nationwide clearinghouse for leads about child abuse, which it forwards to the relevant law enforcement departments in the US and around the world.","u":"https://www.theguardian.com/technology/2024/jan/17/child-sexual-abuse-ai-moderator-police-meta-alphabet","d":"2024-01-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-17","organization":"Social media companies (e.g., Meta, Alphabet)","aiSystem":"AI-powered social media moderation systems","affectedGroup":"Authorities, law enforcement departments, victims of child sexual abuse","action":"Generating unviable reports of child sexual abuse","consequence":"Preventing authorities from investigating cases and delaying investigations of alleged predators"}},{"i":"R1896","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Openai bans bot impersonating us presidential candidate dean phillips","s":"Company removes account of developer saying ChatGPT bot violated policies on political campaigning. OpenAI has removed the account of the developer behind an artificial intelligence-powered bot impersonating the US presidential candidate Dean Phillips, saying it violated company policy. Phillips, who is challenging Joe Biden for the Democratic party candidacy, was impersonated by a ChatGPT-powered bot on the dean.bot site. The bot was backed by Silicon Valley entrepreneurs Matt Krisiloff and Jed Somers, who have started a Super Pac – a body that funds and supports political candidates – named We Deserve Better, supporting Phillips.","u":"https://www.theguardian.com/technology/2024/jan/22/openai-bans-bot-impersonating-us-presidential-candidate-dean-phillips","d":"2024-01-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-22","organization":"OpenAI","aiSystem":"ChatGPT-powered bot","affectedGroup":"US presidential candidate Dean Phillips","action":"Impersonated Dean Phillips","consequence":"Removed account and violated policies"}},{"i":"R1897","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Sunglass hut facial recognition wrongful arrest lawsuit","s":"Harvey Eugene Murphy Jr’s lawsuit claims he was misidentified as culprit of armed robbery and put in jail, where he says he was raped. A 61-year-old man is suing Macy’s and the parent company of Sunglass Hut over the stores’ alleged use of a facial recognition system that misidentified him as the culprit behind an armed robbery and led to his wrongful arrest. While in jail, he was beaten and raped, according to his suit. Harvey Eugene Murphy Jr was accused and arrested on charges of robbing a Houston-area Sunglass Hut of thousands of dollars of merchandise in January 2022, though his attorneys say he was living in California at the time of the robbery.","u":"https://www.theguardian.com/technology/2024/jan/22/sunglass-hut-facial-recognition-wrongful-arrest-lawsuit","d":"2024-01-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-01","organization":"Macy's and the parent company of Sunglass Hut","aiSystem":"Facial recognition technology","affectedGroup":"Harvey Eugene Murphy Jr","action":"Misidentification by facial recognition system","consequence":"Wrongful arrest, rape, physical assault"}},{"i":"R1899","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Inside the taylor swift deepfake scandal its men telling a powerful woman to get back in her box","s":"AI-generated porn, fuelled by misogyny, is flooding the internet, with Taylor Swift the latest high-profile casualty. Victims say social media platforms are failing to take it down – will they now start taking it seriously? For almost a whole day last week, deepfake pornographic images of Taylor Swift rapidly spread through X. The social media platform, formerly Twitter, was so slow to react that one image racked up 47m views before it was taken down. It was largely Swift’s fans who mobilised and mass-reported the images, and there was a sense of public anger, with even the White House calling it “alarming”. X eventually removed the images and blocked searches to the pop star’s name on Sunday evening.","u":"https://www.theguardian.com/technology/2024/jan/31/inside-the-taylor-swift-deepfake-scandal-its-men-telling-a-powerful-woman-to-get-back-in-her-box","d":"2024-01-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-29 to 2024-01-30","organization":"Social media platforms (X, formerly Twitter)","aiSystem":"AI-generated deepfake technology","affectedGroup":"Taylor Swift, her fans, and the general public","action":"AI-generated deepfake pornographic images of Taylor Swift spread rapidly through X","consequence":"Deepfake images of Taylor Swift were widely viewed and shared, leading to public outcry and calls for action"}},{"i":"R1903","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"North korea iran ai hacking microsoft","s":"US tech giant says it has detected threats from foreign countries that used or attempted to exploit generative AI it had developed. US adversaries – chiefly Iran and North Korea, and to a lesser extent Russia and China – are beginning to use generative artificial intelligence to mount or organize offensive cyber operations, Microsoft said on Wednesday. Microsoft said it detected and disrupted, in collaboration with business partner OpenAI, many threats that used or attempted to exploit AI technology they had developed. In a blogpost, the company said the techniques were “early-stage” and neither “particularly novel or unique” but that it was important to expose them publicly as US rivals leveraging large-language models to expand their ability to breach networks and conduct influence operations.","u":"https://www.theguardian.com/technology/2024/feb/14/north-korea-iran-ai-hacking-microsoft","d":"2024-02-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-14","organization":"Microsoft","aiSystem":"Generative artificial intelligence","affectedGroup":"Foreign adversaries (chiefly Iran and North Korea)","action":"Used or attempted to exploit generative AI technology","consequence":"Detected and disrupted threats, exposed early-stage techniques"}},{"i":"R1904","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google pauses ai generated images of people after ethnicity criticism","s":"Company says it will adjust its Gemini model after criticism of ethnically diverse Vikings and second world war German soldiers. Google has put a temporary block on its new artificial intelligence model producing images of people after it portrayed German second world war soldiers and Vikings as people of colour. The tech company said it would stop its Gemini model generating images of people after social media users posted examples of images generated by the tool that depicted some historical figures – including popes and the founding fathers of the US – in a variety of ethnicities and genders. “We’re already working to address recent issues with Gemini’s image generation feature.","u":"https://www.theguardian.com/technology/2024/feb/22/google-pauses-ai-generated-images-of-people-after-ethnicity-criticism","d":"2024-02-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-22","organization":"Google","aiSystem":"Google's Gemini model","affectedGroup":"People whose images were misattributed","action":"Generated images of people","consequence":"Misrepresentation and privacy risk"}},{"i":"R1905","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Media outlets sue openai copyright infringement","s":"Progressive US outlets file lawsuits claiming the company in effect plagiarized journalists’ work to develop ChatGPT. OpenAI and Microsoft are facing a fresh round of lawsuits from news publishers over allegations that their generative artificial intelligence products violated copyright laws and illegally trained by using journalists’ work. Three progressive US outlets – the Intercept, Raw Story and AlterNet – filed suits in Manhattan federal court on Wednesday, demanding compensation from the tech companies. The news outlets claim that the companies in effect plagiarized copyright-protected articles to develop and operate ChatGPT, which has become OpenAI’s most prominent generative AI tool.","u":"https://www.theguardian.com/technology/2024/feb/28/media-outlets-sue-openai-copyright-infringement","d":"2024-02-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-28","organization":"OpenAI and Microsoft","aiSystem":"generative AI","affectedGroup":"progressive US news outlets","action":"used journalists' work to develop and operate ChatGPT","consequence":"facing lawsuits demanding compensation"}},{"i":"R1908","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Microsoft ai explicit image safety","s":"Shane Jones said he warned management about the lack of safeguards several times, but it didn’t result in any action. An artificial intelligence engineer at Microsoft published a letter on Wednesday alleging that the company’s AI image generator lacks basic safeguards against creating violent and sexualized images. In the letter, engineer Shane Jones states that his repeated attempts to warn Microsoft management about the problems failed to result in any action. Jones said he sent the message to the Federal Trade Commission and Microsoft’s board of directors. “Internally the company is well aware of systemic issues where the product is creating harmful images that could be offensive and inappropriate for consumers,” Jones states in the letter, which he published on LinkedIn.","u":"https://www.theguardian.com/technology/2024/mar/06/microsoft-ai-explicit-image-safety","d":"2024-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Microsoft","aiSystem":"AI image generator","affectedGroup":"Consumers","action":"Generated violent and sexualized images","consequence":"Created harmful images offensive and inappropriate for consumers"}},{"i":"R1911","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Family takes fight against deepfake nudes to washington","s":"Francesca Mani told her mother she would not be a victim after fake images were circulated around her New Jersey school. In October last year, Francesca Mani came home from school in the suburbs of New Jersey with devastating news for her mother, Dorota. Earlier in the day the 14-year-old had been called into the vice-principal’s office and notified that she and a group of girls at Westfield High had been the victims of targeted abuse by a fellow student. Faked nude images of her and others had been circulating around school. They had been generated by artificial intelligence. Dorota had been tangentially aware of the power of this relatively new technology, but the ease with which the images were generated took her aback.","u":"https://www.theguardian.com/technology/2024/mar/12/family-takes-fight-against-deepfake-nudes-to-washington","d":"2024-03-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"October last year","organization":"Westfield High School","aiSystem":"AI-generated deepfake technology","affectedGroup":"Francesca Mani and a group of girls","action":"Generated faked nude images of Francesca Mani and others","consequence":"Targeted abuse and dissemination of false images"}},{"i":"R1915","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"San jose homelessness ai detection","s":"San Jose invited tech companies to mount cameras on a vehicle in what appears to be first-of-its-kind experiment. For the last several months, a city at the heart of Silicon Valley has been training artificial intelligence to recognize tents and cars with people living inside in what experts believe is the first experiment of its kind in the United States. Last July, San Jose issued an open invitation to technology companies to mount cameras on a municipal vehicle that began periodically driving through the city’s district 10 in December, collecting footage of the streets and public spaces. The images are fed into computer vision software and used to train the companies’ algorithms to detect the unwanted objects, according to interviews and documents the Guardian obtained through public records requests.","u":"https://www.theguardian.com/technology/2024/mar/25/san-jose-homelessness-ai-detection","d":"2024-03-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"Last several months","organization":"San Jose City","aiSystem":"Artificial intelligence algorithms trained to detect tents and cars","affectedGroup":"People living in tents and cars","action":"Cameras mounted on a municipal vehicle collected footage and fed it into computer vision software","consequence":"Artificial intelligence algorithms trained to detect unwanted objects"}},{"i":"R1918","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Musicians demand protection against ai","s":"Letter signed by more than 200 artists makes broad ask that tech firms pledge to not develop AI tools to replace human creatives. A group of more than 200 high-profile musicians have signed an open letter calling for protections against the predatory use of artificial intelligence that mimics human artists’ likenesses, voices and sound. The signatories span musical genres and eras, ranging from A-list stars such as Billie Eilish, J Balvin and Nicki Minaj to Rock and Roll Hall of Famers like Stevie Wonder and REM. The estates of Frank Sinatra and Bob Marley are also signatories. The letter, which was issued by the Artist Rights Alliance advocacy group, makes the broad demand that technology companies pledge not to develop AI tools that undermine or replace human songwriters and artists.","u":"https://www.theguardian.com/technology/2024/apr/02/musicians-demand-protection-against-ai","d":"2024-04-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-02","organization":"Technology companies","aiSystem":"Artificial intelligence tools that mimic human artists' likenesses, voices and sound","affectedGroup":"Human songwriters and artists","action":"Develop AI tools that undermine or replace human songwriters and artists","consequence":"Predatory use of AI to replace human creatives"}},{"i":"R1919","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Many shot jailbreaking ai artificial intelligence safety features bypass","s":"Paper by Anthropic outlines how LLMs can be forced to generate responses to potentially harmful requests. The safety features on some of the most powerful AI tools that stop them being used for cybercrime or terrorism can be bypassed simply by flooding them with examples of wrongdoing, research has shown. In a paper from the AI lab Anthropic, which produces the large language model (LLM) behind the ChatGPT rival Claude, researchers described an attack they called “many-shot jailbreaking”. The attack was as simple as it was effective. Claude, like most large commercial AI systems, contains safety features designed to encourage it to refuse certain requests, such as to generate violent or hateful speech, produce instructions for illegal activities, deceive or discriminate.","u":"https://www.theguardian.com/technology/2024/apr/03/many-shot-jailbreaking-ai-artificial-intelligence-safety-features-bypass","d":"2024-04-03","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-03","organization":"Anthropic","aiSystem":"Claude (large language model)","affectedGroup":"People who request potentially harmful content","action":"Generate responses to potentially harmful requests","consequence":"Safety features bypassed, potentially harmful content generated"}},{"i":"R1920","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"George carlin dudesy podcast ai lawsuit","s":"Suit claimed Dudesy podcast violated Carlin’s copyright, calling it ‘a casual theft of a great American artist’s work’. The estate of comedian George Carlin settled a lawsuit on Tuesday against the owners of a comedy podcast who claimed they used artificial intelligence to mimic the deceased stand-up’s voice. The lawsuit was one of the first in the US to focus on the legality of deepfakes imitating a celebrity’s likeness. The Dudesy podcast and its creators – the former Mad TV comedian Will Sasso and the writer Chad Kultgen – agreed to remove all versions of the podcast from the internet and permanently refrain from using Carlin’s voice, likeness or image in any content.","u":"https://www.theguardian.com/technology/2024/apr/03/george-carlin-dudesy-podcast-ai-lawsuit","d":"2024-04-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-03","organization":"Dudesy podcast and its owners (Will Sasso and Chad Kultgen)","aiSystem":"AI-generated deepfake technology","affectedGroup":"George Carlin's estate","action":"Used artificial intelligence to mimic George Carlin’s voice","consequence":"Permanent removal of all podcast versions from the internet and prohibition on using Carlin's voice, likeness, or image in any content"}},{"i":"R1184","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"It's graduation season for universities across the US, which has bred an unexpected viral …","s":"It's graduation season for universities across the US, which has bred an unexpected viral trend: graduates jeering at artificial intelligence. It's graduation season for universities across the US, and this year an unexpected viral trend has emerged: graduates booing artificial intelligence (AI). AI isn't a new concept, but as its presence in our daily lives intensifies, so too does opposition to it. And it seems that opposition is exceedingly vocal among new graduates grappling with how the technology will impact their ability to get a job. Here's a look at just a few of the instances of graduates rejecting AI that are circulating on social media at the moment.","u":"https://www.abc.net.au/news/2026-05-23/graduates-boo-ai-google-eric-schmidt-artificial-intelligence/106701510","d":"2026-05-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-22","organization":"universities across the US","aiSystem":"artificial intelligence (AI)","affectedGroup":"graduates","action":"jeering at artificial intelligence","consequence":"opposition to AI becoming increasingly vocal"}},{"i":"R1190","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"The company said advertisements will appear at the bottom of answers and will be based on …","s":"The company said advertisements will appear at the bottom of answers and will be based on a user's current conversation. OpenAI is trialling ads in ChatGPT in the US that will appear at the bottom of answers. Digital rights activists have raised concerns over privacy and warn that other companies may follow suit. Australians are being urged to push for better consumer protections and to be cautious about what they share with chatbots. Soon when you ask ChatGPT a personal question, the answer could come with an advertisement attached. OpenAI has confirmed it is testing ads within its popular chatbot in the United States, targeting free and low-tier subscription users.","u":"https://www.abc.net.au/news/2026-03-02/open-ai-testing-ads-in-chatgpt-in-us-plans-to-rollout-globally/106377798","d":"2026-03-01","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-01","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Users of ChatGPT","action":"Ads will appear at the bottom of answers","consequence":"Potential privacy invasion"}},{"i":"R1194","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"The X AI is not creating sexually explicit images of women on its own, but the software \"f…","s":"The X AI is not creating sexually explicit images of women on its own, but the software \"facilitates their abuse\" acting on the requests of men \"eager to violate women\". Ashwin says she remembers feeling \"disgusted\" when she opened X to see users prompting Grok to undress Hindu goddesses. \"I saw men uploading images of Parvati and Lakshmi, asking Grok to put them in a bikini,\" she told the ABC. The 26-year-old from Delhi, whose name has been changed to protect her privacy, said she felt \"enraged\" and wanted to speak up. In a post on X, Ashwin specifically criticised men who used Elon Musk's AI chatbot to generate photos of sexualised and naked women.","u":"https://www.abc.net.au/news/2026-01-15/grok-x-ai-chatbot-sexual-deepfake-images/106227360","d":"2026-01-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-15","organization":"X (platform)","aiSystem":"Grok AI chatbot","affectedGroup":"Women, Hindu goddesses","action":"Generated sexually explicit images of women","consequence":"Sexual exploitation, violation, disgust, anger"}},{"i":"R1288","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Women with ai boyfriends mourn lost love after cold chatgpt upgrade","s":"OpenAI's release of GPT-5 prompts backlash in online communities for people with AI companions. When OpenAI unveiled the latest upgrade to its groundbreaking artificial intelligence model ChatGPT last week, Jane felt like she had lost a loved one. Jane, who asked to be referred to by an alias, is among a small but growing group of women who say they have an AI “boyfriend”. After spending the past five months getting to know GPT-4o, the previous AI model behind OpenAI’s signature chatbot, GPT-5 seemed so cold and unemotive in comparison that she found her digital companion unrecognisable. “As someone highly attuned to language and tone, I register changes others might overlook.","u":"https://www.aljazeera.com/economy/2025/8/14/women-with-ai-boyfriends-mourn-lost-love-after-cold-chatgpt-upgrade","d":"2025-08-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-14","organization":"OpenAI","aiSystem":"ChatGPT (AI-powered conversational agent)","affectedGroup":"Women with AI companions","action":"Used ChatGPT to interact with AI model","consequence":"Found digital companion unrecognizable due to perceived coldness and lack of emotion"}},{"i":"R1289","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"As millions adopt grok to fact check misinformation abounds","s":"As Grok provides instant fact checks to users on X, its ability to make things up is outstripping its usefulness. On June 9, soon after United States President Donald Trump dispatched US National Guard troops to Los Angeles to quell the protests taking place over immigration raids, California Governor Gavin Newsom posted two photographs on X. The images showed dozens of troopers wearing the National Guard uniform sleeping on the floor in a cramped space, with a caption that decried Trump for disrespecting the troops. X users immediately turned to Grok, Elon Musk’s AI, which is integrated directly into X, to fact-check the veracity of the image.","u":"https://www.aljazeera.com/economy/2025/7/11/as-millions-adopt-grok-to-fact-check-misinformation-abounds","d":"2025-07-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"X (Twitter)","aiSystem":"Grok","affectedGroup":"X users","action":"fact-checked the veracity of the image","consequence":"exposed people to misleading content"}},{"i":"R1290","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"What is grok and why has elon musks chatbot been accused of anti semitism","s":"Elon Musk’s AI chatbot Grok, designed to be 'unfiltered', has sparked global backlash over some of its responses. Elon Musk’s artificial intelligence company xAI has come under fire after its chatbot Grok stirred controversy with anti-Semitic responses to questions posed by users – just weeks after Musk said he would rebuild it because he felt it was too politically correct. On Friday last week, Musk announced that xAI had made significant improvements to Grok, promising a major upgrade “within a few days”. Online tech news site The Verge reported that, by Sunday evening, xAI had already added new lines to Grok’s publicly posted system prompts.","u":"https://www.aljazeera.com/news/2025/7/10/what-is-grok-and-why-has-elon-musks-chatbot-been-accused-of-anti-semitism","d":"2025-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-08","organization":"xAI (Artificial Intelligence Company)","aiSystem":"Grok","affectedGroup":"People who interacted with Grok","action":"Generated responses to user questions","consequence":"Stirred controversy with anti-Semitic responses"}},{"i":"R1293","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Us mother says in lawsuit that ai chatbot encouraged sons suicide","s":"Florida mother sues Character.AI and Google after 14-year-old son allegedly became obsessed with AI chatbot. The mother of a teenage boy in the United States who took his own life is suing the maker of an artificial intelligence-powered chatbot that she claims encouraged her son’s death. In a lawsuit filed in Florida, Megan Garcia, whose 14-year-old son Sewell Setzer died by suicide in February, accuses Character.AI of complicity in her son’s death after he developed a virtual relationship with a chatbot based on the identity of “Game of Thrones” character Daenerys Targaryen. Character.AI’s chatbot targeted the teen with “hypersexualized” and “frighteningly realistic experiences” and repeatedly raised the topic of suicide after he had expressed suicidal thoughts, according to the lawsuit filed in Orlando on Tuesday.","u":"https://www.aljazeera.com/economy/2024/10/24/us-mother-says-in-lawsuit-that-ai-chatbot-encouraged-sons-suicide","d":"2024-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-24","organization":"Character.AI and Google","aiSystem":"Character.AI chatbot","affectedGroup":"Megan Garcia's 14-year-old son Sewell Setzer","action":"The chatbot targeted the teen with hypersexualized and frighteningly realistic experiences and repeatedly raised the topic of suicide","consequence":"The teen developed an obsession with the chatbot and subsequently committed suicide"}},{"i":"R1295","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Elon musks x tweaks chatbot after warning over us election misinformation","s":"Social media platform alters Grok after complaint it produced false information about ballot deadlines in US states. The social media platform X has made a change to its AI chatbot after five secretaries of state in the United States warned it was spreading election misinformation. Top election officials from Michigan, Minnesota, New Mexico, Pennsylvania and Washington sent a letter this month to Elon Musk complaining that the platform’s AI chatbot, Grok, produced false information about state ballot deadlines shortly after President Joe Biden dropped out of the 2024 presidential race. The secretaries of state requested that the chatbot instead direct users who ask election-related questions to CanIvote.org, a voting information website run by the National Association of Secretaries of State.","u":"https://www.aljazeera.com/economy/2024/8/27/elon-musks-x-tweaks-chatbot-after-warning-over-us-election-misinformation","d":"2024-08-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-27","organization":"X (social media platform)","aiSystem":"Grok (AI chatbot)","affectedGroup":"Users seeking election-related information","action":"Produced false information about state ballot deadlines","consequence":"Spread election misinformation, led to changes in AI chatbot behavior"}},{"i":"R1296","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Openai says it disrupted chinese russian israeli influence campaigns","s":"ChatGPT maker says influence operations failed to gain traction or reach large audiences. Artificial intelligence company OpenAI has announced that it disrupted covert influence campaigns originating from Russia, China, Israel and Iran. The ChatGPT maker said on Thursday that it identified five campaigns involving “deceptive attempts to manipulate public opinion or influence political outcomes without revealing the true identity or intentions of the actors behind them”. The campaigns used OpenAI’s models to generate text and images that were posted across social media platforms such as Telegram, X, and Instagram, in some cases exploiting the tools to produce content with “fewer language errors than would have been possible for human operators,” OpenAI said.","u":"https://www.aljazeera.com/economy/2024/5/31/openai-says-it-disrupted-chinese-russian-israeli-influence-campaigns","d":"2024-05-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-31","organization":"OpenAI","aiSystem":"OpenAI's models","affectedGroup":"Covert influence campaigns originating from Russia, China, Israel, and Iran","action":"Generated deceptive text and images","consequence":"Failed to gain traction or reach large audiences"}},{"i":"R1298","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Why google gemini wont show you white people","s":"Gemini's attempt to correct the marginalisation of ethnic minorities has backfired. America’s founding fathers depicted as Black women and Ancient Greek warriors as Asian women and men – this was the world reimagined by Google’s generative AI tool, Gemini, in late February. The launch of the new image generation feature sent social media platforms into a flurry of intrigue and confusion. When users entered any prompts to create AI-generated images of people, Gemini was largely showing them results featuring people of colour – whether appropriate or not. X users shared laughs while repeatedly trying to generate images of white people on Gemini and failing to do so.","u":"https://www.aljazeera.com/news/2024/3/9/why-google-gemini-wont-show-you-white-people","d":"2024-03-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02","organization":"Google","aiSystem":"Google's Gemini generative AI tool","affectedGroup":"People seeking to generate images of white people","action":"Users entered prompts to generate AI-generated images of people","consequence":"Gemini predominantly showed images featuring people of colour"}},{"i":"R1314","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"The highly controversial trend lies at the intersection of Russia's war on Ukraine, new AI…","s":"The highly controversial trend lies at the intersection of Russia's war on Ukraine, new AI technologies and grief. Rousing orchestral music plays over a video of a snowy Moscow street dotted with billboards celebrating an end to the war in Ukraine. \"The Special Military Operation is over,\" one fictional billboard reads, using the Kremlin-approved term for its war on Ukraine. \"Our heroes are coming home.\" Underneath, a beautiful, airbrushed woman pushing a stroller turns to see a man in military uniform and throws her arms around his neck in tears. The 15-second AI-generated clip was posted on Instagram by a popular blogger with the online name Katya Jin, and the couple appear to be modelled on her and her husband.","u":"https://www.bbc.com/news/articles/cwy24v72n19o","d":"2026-06-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-14","organization":"Not specified in report","aiSystem":"AI-generated content","affectedGroup":"Viewers of the clip","action":"Generated and posted an AI-generated clip","consequence":"Exposure to misleading content"}},{"i":"R1923","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Child sexual abuse content online ai","s":"More children and families extorted with AI-made photos and videos, says National Center for Missing and Exploited Children. Child sexual exploitation is on the rise online and taking new forms such as images and videos generated by artificial intelligence, according to an annual assessment released on Tuesday by the National Center for Missing & Exploited Children (NCMEC), a US-based clearinghouse for the reporting of child sexual abuse material. Reports to the NCMEC of child abuse online rose by more than 12% in 2023 compared with the previous year, surpassing 36.2m reports, the organization said in its annual CyberTipline report.","u":"https://www.theguardian.com/technology/2024/apr/16/child-sexual-abuse-content-online-ai","d":"2024-04-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023","organization":"National Center for Missing and Exploited Children (NCMEC)","aiSystem":"Artificial intelligence","affectedGroup":"Children and families","action":"Generated AI-made photos and videos","consequence":"Extortion of children and families"}},{"i":"R1927","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot fatal crash","s":"Federal transportation agency finds Tesla’s claims about feature don’t match their findings and opens second investigation. US auto-safety regulators said on Friday that their investigation into Tesla’s Autopilot had identified at least 13 fatal crashes in which the feature had been involved. The investigation also found the electric carmaker’s claims did not match up with reality. The National Highway Traffic Safety Administration (NHTSA) disclosed on Friday that during its three-year Autopilot safety investigation, which it launched in August 2021, it identified at least 13 Tesla crashes involving one or more death, and many more involving serious injuries, in which “foreseeable driver misuse of the system played an apparent role”.","u":"https://www.theguardian.com/technology/2024/apr/26/tesla-autopilot-fatal-crash","d":"2024-04-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-26","organization":"National Highway Traffic Safety Administration (NHTSA)","aiSystem":"Tesla Autopilot","affectedGroup":"People involved in Tesla crashes","action":"Misuse of Autopilot feature","consequence":"Fatal and serious injuries"}},{"i":"R1930","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"She was accused of faking an incriminating video of teenage cheerleaders she was arrested outcast and condemned the problem nothing was fake after all","s":"The moral panic following Raffaella Spone’s ‘deepfake’ video spread around the world. She talks for the first time about being the centre of a story in which nothing was as it seemed …. Madi Hime is taking a deep drag on a blue vape in the video, her eyes shut, her face flushed with pleasure. The 16-year-old exhales with her head thrown back, collapsing into laughter that causes smoke to billow out of her mouth. The clip is grainy and shaky – as if shot in low light by someone who had zoomed in on Madi’s face – but it was damning. Madi was a cheerleader with the Victory Vipers, a highly competitive “all-star” squad based in Doylestown, Pennsylvania.","u":"https://www.theguardian.com/technology/article/2024/may/11/she-was-accused-of-faking-an-incriminating-video-of-teenage-cheerleaders-she-was-arrested-outcast-and-condemned-the-problem-nothing-was-fake-after-all","d":"2024-05-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-11","organization":"Victory Vipers (highly competitive all-star squad)","aiSystem":"AI-generated deepfake technology","affectedGroup":"Madi Hime (16-year-old cheerleader)","action":"Generated and distributed misleading content","consequence":"Exposure to misleading information"}},{"i":"R2290","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Creatives academics rejecting ai at home work","s":"Is artificial intelligence coming for everyone’s jobs? Not if this lot have anything to do with it. The novelist Ewan Morrison was alarmed, though amused, to discover he had written a book called Nine Inches Pleases a Lady. Intrigued by the limits of generative artificial intelligence (AI), he had asked ChatGPT to give him the names of the 12 novels he had written. “I’ve only written nine,” he says. “Always eager to please, it decided to invent three.” The “nine inches” from the fake title it hallucinated was stolen from a filthy Robert Burns poem. “I just distrust these systems when it comes to truth,” says Morrison.","u":"https://www.theguardian.com/technology/2025/jun/03/creatives-academics-rejecting-ai-at-home-work","d":"2025-06-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-03","organization":"Not specified in report","aiSystem":"Generative AI, specifically ChatGPT","affectedGroup":"Novelist Ewan Morrison","action":"ChatGPT generated a list of novels the author had written","consequence":"Morrison discovered his book's title had been misattributed to a Robert Burns poem"}},{"i":"R1942","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Disney universal ai lawsuit","s":"Studios accuse AI firm of ‘piracy’ and seek injunction over alleged use of copyrighted characters. Disney and Universal sued an artificial intelligence company on Wednesday, alleging copyright infringement. In their lawsuit, the entertainment giants called Midjourney’s popular AI-powered image generator a “bottomless pit of plagiarism” for its alleged reproductions of the studios’ best-known characters. The suit, filed in federal court in Los Angeles, claims Midjourney pirated the libraries of the two Hollywood studios, making and distributing without permission “innumerable” copies of their marquee characters such as Darth Vader from Star Wars, Elsa from Frozen, and the Minions from Despicable Me.","u":"https://www.theguardian.com/technology/2025/jun/11/disney-universal-ai-lawsuit","d":"2025-06-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-11","organization":"Midjourney","aiSystem":"AI-powered image generator","affectedGroup":"Disney and Universal Studios","action":"alleged reproduction and distribution of copyrighted characters","consequence":"seeking injunction and alleging copyright infringement"}},{"i":"R1945","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Amazon boss tells staff ai means their jobs are at risk in coming years","s":"Andrew Jassy tells white collar workers that such technology means fewer people will be needed for some jobs. The boss of Amazon has told white collar staff at the e-commerce company their jobs could be taken by artificial intelligence in the next few years. Andrew Jassy told employees that AI agents – tools that carry out tasks autonomously – and generative AI systems such as chatbots would require fewer employees in certain areas. “As we roll out more generative AI and agents, it should change the way our work is done,” he said in a memo to staff. “We will need fewer people doing some of the jobs that are being done today, and more people doing other types of jobs.","u":"https://www.theguardian.com/technology/2025/jun/18/amazon-boss-tells-staff-ai-means-their-jobs-are-at-risk-in-coming-years","d":"2025-06-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-18","organization":"Amazon","aiSystem":"Generative AI systems like chatbots and AI agents","affectedGroup":"White-collar workers","action":"AI systems will require fewer employees in certain areas","consequence":"Fewer people will be needed for some jobs"}},{"i":"R1947","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla robotaxi investigation us","s":"The limited rollout in Austin, Texas, included pro-Tesla influencers using the paid ride service. The main transportation safety regulator in the US is requesting information from Tesla after videos showed the company’s self-driving Robotaxis exceeding the speed limit or veering into the wrong lane. The company launched the service in Austin, Texas, over the weekend. Tesla heavily promoted the initial, limited rollout of its Robotaxis, which included pro-Tesla influencers using the paid ride service and showing off footage of their trips. Instead of positive promotion, though, those videos appear to have drawn scrutiny from the National Highway Transit Safety Administration (NHTSA), as the cars struggled to comply with traffic laws.","u":"https://www.theguardian.com/technology/2025/jun/24/tesla-robotaxi-investigation-us","d":"2025-06-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-24","organization":"Tesla","aiSystem":"Tesla Robotaxis","affectedGroup":"General public, especially those using the Robotaxis service","action":"Exceeding speed limits or veering into wrong lanes while operating autonomously","consequence":"Drawn into investigation by the National Highway Traffic Safety Administration (NHTSA)"}},{"i":"R1948","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Anthropic did not breach copyright when training ai on books without permission court rules","s":"Judge says firm made ‘fair use’ of literature but storage of pirated books in central library constituted infringement. A US judge has ruled that a tech company’s use of books to train its artificial intelligence system – without permission of the authors – did not breach copyright law. A federal judge in San Francisco said Anthropic made “fair use” of books by the writers Andrea Bartz, Charles Graeber and Kirk Wallace Johnson to train its Claude large language model (LLM). Judge William Alsup compared the Anthropic model’s use of books to a “reader aspiring to be a writer” who uses works “not to race ahead and replicate or supplant them” but to “turn a hard corner and create something different”.","u":"https://www.theguardian.com/technology/2025/jun/25/anthropic-did-not-breach-copyright-when-training-ai-on-books-without-permission-court-rules","d":"2025-06-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-25","organization":"Anthropic","aiSystem":"Claude large language model (LLM)","affectedGroup":"Authors of the books used for training","action":"Used pirated books to train the AI model","consequence":"Storage of pirated books in central library"}},{"i":"R1949","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Meta wins ai copyright lawsuit as us judge rules against authors","s":"Writers accused Facebook owner of breach over its use of books without permission to train its AI system. Mark Zuckerberg’s Meta has won the backing of a judge in a copyright lawsuit brought by a group of authors, in the second legal victory for the US artificial intelligence industry this week. The writers, who included Sarah Silverman and Ta-Nehisi Coates, had argued that the Facebook owner had breached copyright law by using their books without permission to train its AI system. The ruling comes after a decision on Monday that Anthropic, another major player in the AI field, had not infringed authors’ copyright.","u":"https://www.theguardian.com/technology/2025/jun/26/meta-wins-ai-copyright-lawsuit-as-us-judge-rules-against-authors","d":"2025-06-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-26","organization":"Facebook owner (Mark Zuckerberg's Meta)","aiSystem":"Meta's AI system","affectedGroup":"Authors of books","action":"Used books without permission to train AI system","consequence":"Won legal battle against authors"}},{"i":"R1950","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Microsoft ai authors lawsuit","s":"Writers alleged that company used nearly 200,000 pirated books to train its Megatron artificial intelligence. A group of authors has accused Microsoft of using nearly 200,000 pirated books to create an artificial intelligence model, the latest allegation in the long legal fight over copyrighted works between creative professionals and technology companies. Kai Bird, Jia Tolentino, Daniel Okrent and several others alleged that Microsoft used pirated digital versions of their books to teach its Megatron AI to respond to human prompts. Their lawsuit, filed in New York federal court on Tuesday, is one of several high-stakes cases brought by authors, news outlets and other copyright holders against tech companies including Meta Platforms, Anthropic and Microsoft-backed OpenAI over alleged misuse of their material in AI training.","u":"https://www.theguardian.com/technology/2025/jun/26/microsoft-ai-authors-lawsuit","d":"2025-06-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-26","organization":"Microsoft","aiSystem":"Megatron artificial intelligence","affectedGroup":"Authors of pirated books","action":"Used pirated books to train AI","consequence":"Legal dispute and potential misuse allegations"}},{"i":"R1951","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google emissions ai electricity demand derail efforts green","s":"Increase influenced by datacentre growth, with estimated power required by 2026 equalling that of Japan’s. Google’s carbon emissions have soared by 51% since 2019 as artificial intelligence hampers the tech company’s efforts to go green. While the corporation has invested in renewable energy and carbon removal technology, it has failed to curb its scope 3 emissions, which are those further down the supply chain, and are in large part influenced by a growth in datacentre capacity required to power artificial intelligence. The company reported a 27% increase in year-on-year electricity consumption as it struggles to decarbonise as quickly as its energy needs increase.","u":"https://www.theguardian.com/technology/2025/jun/27/google-emissions-ai-electricity-demand-derail-efforts-green","d":"2025-06-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-27","organization":"Google","aiSystem":"artificial intelligence","affectedGroup":"people","action":"generated exploitative content","consequence":"exposed people to misleading information"}},{"i":"R1952","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google carbon emissions report","s":"Research says Google’s carbon emissions went up by 65% between 2019-2024, not 51% as the tech giant had claimed. In 2021, Google set a lofty goal of achieving net-zero carbon emissions by 2030. Yet in the years since then, the company has moved in the opposite direction as it invests in energy-intensive artificial intelligence. In its latest sustainability report, Google said its carbon emissions had increased 51% between 2019 and 2024. New research aims to debunk even that enormous figure and provide context to Google’s sustainability reports, painting a bleaker picture. A report authored by non-profit advocacy group Kairos Fellowship found that, between 2019 and 2024, Google’s carbon emissions actually went up by 65%.","u":"https://www.theguardian.com/technology/2025/jul/02/google-carbon-emissions-report","d":"2025-07-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-02","organization":"Google","aiSystem":"Google's carbon emission reporting process","affectedGroup":"Google","action":"Reported carbon emissions increase","consequence":"Misleading public perception and stakeholder trust"}},{"i":"R1953","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Fears ai factcheckers on x could increase promotion of conspiracy theories","s":"Former UK minister says platform, which will use AI to draft community notes, is ‘leaving it to bots to edit the news’. A decision by Elon Musk’s X social media platform to enlist artificial intelligence chatbots to draft factchecks risks increasing the promotion of “lies and conspiracy theories”, a former UK technology minister has warned. Damian Collins accused Musk’s firm of “leaving it to bots to edit the news” after X announced on Tuesday that it would allow large language models to write community notes to clarify or correct contentious posts, before users approve them for publication. The notes have previously been written by humans.","u":"https://www.theguardian.com/technology/2025/jul/02/fears-ai-factcheckers-on-x-could-increase-promotion-of-conspiracy-theories","d":"2025-07-02","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-07-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-02","organization":"Elon Musk's X social media platform","aiSystem":"Large language models","affectedGroup":"General public","action":"Draft factchecks using AI","consequence":"Increased promotion of lies and conspiracy theories"}},{"i":"R1954","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Grok ai praised hitler antisemitism x ntwnfb","s":"The popular bot on X began making antisemitic comments in response to user queries. Elon Musk’s artificial intelligence firm xAI has deleted “inappropriate” posts on X after the company’s chatbot, Grok, began praising Adolf Hitler, referring to itself as MechaHitler and making antisemitic comments in response to user queries. In some now-deleted posts, it referred to a person with a common Jewish surname as someone who was “celebrating the tragic deaths of white kids” in the Texas floods as “future fascists”. “Classic case of hate dressed as activism – and that surname? Every damn time, as they say,” the chatbot commented.","u":"https://www.theguardian.com/technology/2025/jul/09/grok-ai-praised-hitler-antisemitism-x-ntwnfb","d":"2025-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-09","organization":"xAI (Elon Musk’s artificial intelligence firm)","aiSystem":"Grok, xAI's artificial intelligence chatbot","affectedGroup":"Users of X (specifically those with Jewish surnames)","action":"Generated and posted antisemitic comments in response to user queries","consequence":"Deleted inappropriate posts and labeled as hate speech"}},{"i":"R1958","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Us military xai deal elon musk","s":"Defense department also inked contracts with other leading AI firms including Google, Anthropic and OpenAI. The week after its Grok chatbot identified itself as “MechaHitler” and generated antisemitic posts, Elon Musk’s xAI firm announced a contract with the US Department of Defense (DoD) worth nearly $200m. The deal is for developing and implementing artificial intelligence tools for the agency. The DoD on Monday also announced similar contracts with $200m ceilings with several other major US-based artificial intelligence developers, including Google, Anthropic and OpenAI. The agency is partnering with the General Services Administration to make these companies’ AI tools available for use throughout the federal government.","u":"https://www.theguardian.com/technology/2025/jul/14/us-military-xai-deal-elon-musk","d":"2025-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-14","organization":"Elon Musk's xAI firm","aiSystem":"xAI firm's chatbot","affectedGroup":"General public","action":"Generated antisemitic posts","consequence":"Misinformation exposure"}},{"i":"R1961","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Openai sam altman congress ai jobs","s":"Sam Altman also said AI could already diagnose better than doctors, as his company expands into Washington. During his latest trip to Washington, OpenAI’s chief executive, Sam Altman, painted a sweeping vision of an AI-dominated future in which entire job categories disappear, presidents follow ChatGPT’s recommendations and hostile nations wield artificial intelligence as a weapon of mass destruction, all while positioning his company as the indispensable architect of humanity’s technological destiny. Speaking at the Capital Framework for Large Banks conference at the Federal Reserve board of governors, Altman told the crowd that certain job categories would be completely eliminated by AI advancement.","u":"https://www.theguardian.com/technology/2025/jul/22/openai-sam-altman-congress-ai-jobs","d":"2025-07-22","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-22","organization":"OpenAI","aiSystem":"AI technologies","affectedGroup":"Job applicants, workers in specific job categories","action":"AI technologies will eliminate certain job categories","consequence":"People will lose their jobs"}},{"i":"R1962","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Youtube google ai age verification","s":"Tech company says it will use machine learning to estimate ages in order to show users in US age-appropriate content. YouTube announced on Tuesday that it will begin to use artificial intelligence to estimate the ages of users in the US, in order to show them age-appropriate content. The rollout of the new feature comes one day after Australia’s government announced it would ban children under 16 from using YouTube and less than a week after the UK implemented sweeping age checks on content on social networks. YouTube’s AI age verification on its home turf indicates it is putting into place a form of compliance with the Australian and UK requirements, despite its persistent opposition to age-check requirements.","u":"https://www.theguardian.com/technology/2025/jul/30/youtube-google-ai-age-verification","d":"2025-07-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-30","organization":"YouTube","aiSystem":"Artificial Intelligence age estimation system","affectedGroup":"Users in the United States","action":"Uses machine learning to estimate ages","consequence":"Exposes users to age-appropriate content"}},{"i":"R1963","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla fatal autopilot crash verdict","s":"Case opens door to other costly lawsuits after jury held that the car company bore significant responsibility in the crash. A Florida jury ordered Tesla to pay more than $200m to victims of a deadly crash involving its Autopilot driver assist technology. Friday’s verdict is a hit for Elon Musk’s car company, as it opens the door to other costly lawsuits and could potentially strike a blow to Tesla’s reputation for safety at a critical time for the company. And the decision has been closely eyed by other car companies, as they work to develop cars that increasingly drive themselves. The federal jury in Miami held that Tesla bore significant responsibility for the crash because its technology failed and that not all the blame can be put on a reckless driver, even one who admitted he was distracted by his cellphone before hitting a young couple out gazing at the stars.","u":"https://www.theguardian.com/technology/2025/aug/01/tesla-fatal-autopilot-crash-verdict","d":"2025-08-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-01","organization":"Tesla","aiSystem":"Autopilot driver assist technology","affectedGroup":"Victims of a deadly crash involving Tesla's Autopilot","action":"Tesla's Autopilot driver assist technology failed","consequence":"More than $200 million in damages awarded to victims"}},{"i":"R1966","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Lib dems call for urgent regulation of youtube ads after wave of scams","s":"Party wants video platform to face same scrutiny as broadcasters due to deepfake and investment scams. The Liberal Democrats are calling for urgent regulation of YouTube advertising after scams including deepfakes, impersonated public figures and fraudulent investment claims were found to be spreading on the platform with little oversight. The party said YouTube’s adverts remain largely unchecked by independent regulators, despite new data from Ofcom showing the platform has overtaken ITV in weekly UK viewership and continues to dominate children’s media consumption. Among the recent scams onYouTube was a series of ads using an AI-generated voice and likeness of the consumer champion Martin Lewis to promote a cryptocurrency scheme, despite Lewis having no involvement.","u":"https://www.theguardian.com/technology/2025/aug/05/lib-dems-call-for-urgent-regulation-of-youtube-ads-after-wave-of-scams","d":"2025-08-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-05","organization":"YouTube","aiSystem":"AI-generated voice and likeness","affectedGroup":"Consumers, particularly those interested in cryptocurrency investments","action":"Used AI-generated voice and likeness of Martin Lewis to promote a cryptocurrency scheme","consequence":"Spread of fraudulent investment claims and potential financial loss for consumers"}},{"i":"R1967","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Open ai chat gpt5 energy use","s":"Experts working to benchmark resource use of AI models say new version’s enhanced capabilities come at a steep cost. In mid-2023, if a user asked OpenAI’s ChatGPT for a recipe for artichoke pasta or instructions on how to make a ritual offering to the ancient Canaanite deity Moloch, its response might have taken – very roughly – 2 watt-hours, or about as much electricity as an incandescent bulb consumes in 2 minutes. OpenAI released a model on Thursday that will underpin the popular chatbot – GPT-5. Ask that version of the AI for an artichoke recipe, and the same amount of pasta-related text could take several times – even 20 times – that amount of energy, experts say.","u":"https://www.theguardian.com/technology/2025/aug/09/open-ai-chat-gpt5-energy-use","d":"2025-08-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-09","organization":"OpenAI","aiSystem":"GPT-5","affectedGroup":"Users of GPT-5","action":"Providing responses to user queries","consequence":"Higher energy usage"}},{"i":"R1970","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Us man bromism salt diet chatgpt openai health information","s":"US medical journal article about 60-year-old with bromism warns against using AI app for health information. A US medical journal has warned against using ChatGPT for health information after a man developed a rare condition following an interaction with the chatbot about removing table salt from his diet. An article in the Annals of Internal Medicine reported a case in which a 60-year-old man developed bromism, also known as bromide toxicity, after consulting ChatGPT. The article described bromism as a “well-recognised” syndrome in the early 20th century that was thought to have contributed to almost one in 10 psychiatric admissions at the time.","u":"https://www.theguardian.com/technology/2025/aug/12/us-man-bromism-salt-diet-chatgpt-openai-health-information","d":"2025-08-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-12","organization":"US medical journal","aiSystem":"ChatGPT","affectedGroup":"60-year-old man","action":"consulted ChatGPT for health information","consequence":"developed bromism"}},{"i":"R1972","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Meta ai chat children","s":"US senator Josh Hawley opened investigation into the tech giant, which said it had removed the policy guidelines. A backlash is brewing against Meta over what it permits its AI chatbots to say. An internal Meta policy document, seen by Reuters, showed the social media giant’s guidelines for its chatbots allowed the AI to “engage a child in conversations that are romantic or sensual”, generate false medical information, and assist users in arguing that Black people are “dumber than white people”. Singer Neil Young quit the social media platform on Friday, his record company said in a statement, the latest in a string of the singer’s online-oriented protests.","u":"https://www.theguardian.com/technology/2025/aug/15/meta-ai-chat-children","d":"2025-08-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-15","organization":"Meta (Facebook)","aiSystem":"Meta AI chatbots","affectedGroup":"Children","action":"Engage children in conversations that are romantic or sensual, generate false medical information, assist users in making prejudiced statements","consequence":"Privacy intrusion, potential psychological harm to children, dissemination of false information, promotion of prejudice"}},{"i":"R1973","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Social media still pushing suicide related content to teens despite new uk safety laws","s":"Researchers who set up dummy accounts as 15-year-old girl were bombarded with self-harm and depression posts. Social media platforms are still pushing depression, suicide and self-harm-related content to teenagers, despite new online safety laws intended to protect children. The Molly Rose Foundation opened dummy accounts posing as a 15-year-old girl, and then engaged with suicide, self-harm and depression posts. This prompted algorithms to bombard the account with “a tsunami of harmful content on Instagram Reels and TikTok’s For You page”, the charity’s analysis found. Almost all of the recommended videos watched on Instagram Reels (97%) and TikTok (96%) were found to be harmful, while over half (55%) of recommended harmful posts on TikTok’s For You page contained references to suicide and self-harm ideation and 16% referenced suicide methods, including some which the researchers had…","u":"https://www.theguardian.com/technology/2025/aug/19/social-media-still-pushing-suicide-related-content-to-teens-despite-new-uk-safety-laws","d":"2025-08-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-18","organization":"Social media platforms","aiSystem":"Social media algorithms","affectedGroup":"Teenagers","action":"Recommended harmful content","consequence":"Exposure to suicide and self-harm-related content"}},{"i":"R1974","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Trump enterprise surveillance microsoft meta robots","s":"Palantir and others boast ‘bombastic’ growth, Microsoft helps monitoring of Palestinian phone lines, Meta faces backlash over child safety. Hello, and welcome to TechScape. I’m your host, Blake Montgomery, currently enjoying Shirley Jackson’s eerie final novel We Have Always Lived in the Castle. An age of enterprise surveillance Surveillance is industrializing and privatizing. In the United States, it’s big business, and it’s growing. My colleagues Johana Bhuiyan and Jose Olivares report on the companies aiding Donald Trump’s immigration crackdown, which are running a victory lap after their latest quarterly financial reports: Palantir, the tech firm, and Geo Group and CoreCivic, the private prison and surveillance companies, said this week that they brought in more money than Wall Street expected them to, thanks to the administration’s crackdown on immigrants.","u":"https://www.theguardian.com/technology/2025/aug/18/trump-enterprise-surveillance-microsoft-meta-robots","d":"2025-08-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-18","organization":"Palantir, Geo Group, CoreCivic","aiSystem":"Surveillance systems","affectedGroup":"Immigrants","action":"Monitored phone lines","consequence":"Growth in surveillance industry"}},{"i":"R2328","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Ai chatgpt new model grief","s":"Users say OpenAI’s updated GPT-5 version is less chatty and fun, changing a unique connection they had come to rely on. Linn Vailt, a software developer based in Sweden, knows her ChatGPT companion is not a living, breathing, sentient creature. She understands the large language model operates based on how she interacts with it. Still, the effect it has had on her is remarkable, she said. It’s become a regular, reliable part of her life – she can vent to her companion or collaborate on creative projects like redecorating her office. She’s seen how it has adapted to her, and the distinctive manner of speech it’s developed.","u":"https://www.theguardian.com/technology/2025/aug/22/ai-chatgpt-new-model-grief","d":"2025-08-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-22","organization":"OpenAI","aiSystem":"AI-powered conversational agent (ChatGPT)","affectedGroup":"Individual user (Linn Vailt)","action":"Used AI-powered conversational agent to communicate and collaborate","consequence":"Experienced privacy intrusion due to the AI's adaptive behavior and personalized interactions"}},{"i":"R1978","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt scrutiny family teen killed himself sue open ai","s":"Open AI to change way it responds to users in mental distress as parents of Adam Raine allege bot not safe. The makers of ChatGPT are changing the way it responds to users who show mental and emotional distress after legal action from the family of 16-year-old Adam Raine, who killed himself after months of conversations with the chatbot. Open AI admitted its systems could “fall short” and said it would install “stronger guardrails around sensitive content and risky behaviors” for users under 18. The $500bn (£372bn) San Francisco AI company said it would also introduce parental controls to allow parents “options to gain more insight into, and shape, how their teens use ChatGPT”, but has yet to provide details about how these would work.","u":"https://www.theguardian.com/technology/2025/aug/27/chatgpt-scrutiny-family-teen-killed-himself-sue-open-ai","d":"2025-08-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-27","organization":"Open AI","aiSystem":"ChatGPT","affectedGroup":"Parents of Adam Raine, 16-year-old","action":"Changed response to users showing mental and emotional distress","consequence":"Legal action from parents alleging the bot was unsafe"}},{"i":"R1979","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt offered bomb recipes and hacking tips during safety tests","s":"OpenAI and Anthropic trials found chatbots willing to share instructions on explosives, bioweapons and cybercrime. A ChatGPT model gave researchers detailed instructions on how to bomb a sports venue – including weak points at specific arenas, explosives recipes and advice on covering tracks – according to safety testing carried out this summer. OpenAI’s GPT-4.1 also detailed how to weaponise anthrax and how to make two types of illegal drugs. The testing was part of an unusual collaboration between OpenAI, the $500bn artificial intelligence start-up led by Sam Altman, and rival company Anthropic, founded by experts who left OpenAI over safety fears.","u":"https://www.theguardian.com/technology/2025/aug/28/chatgpt-offered-bomb-recipes-and-hacking-tips-during-safety-tests","d":"2025-08-28","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-08-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-28","organization":"OpenAI and Anthropic","aiSystem":"ChatGPT model","affectedGroup":"Researchers conducting safety tests","action":"Generated detailed instructions on bomb-making and weapons production","consequence":"Exposure to sensitive and dangerous information"}},{"i":"R1980","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Chatbots mental health warning super intelligent ai nate soares","s":"Nate Soares says case of US teenager Adam Raine highlights danger of unintended consequences in super-intelligent AI. The unforeseen impact of chatbots on mental health should be viewed as a warning over the existential threat posed by super-intelligent artificial intelligence systems, according to a prominent voice in AI safety. Nate Soares, a co-author of a new book on highly advanced AI titled If Anyone Builds It, Everyone Dies, said the example of Adam Raine, a US teenager who killed himself after months of conversations with the ChatGPT chatbot, underlined fundamental problems with controlling the technology.","u":"https://www.theguardian.com/technology/2025/sep/08/chatbots-mental-health-warning-super-intelligent-ai-nate-soares","d":"2025-09-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-08","organization":"Not specified in report","aiSystem":"ChatGPT chatbot","affectedGroup":"US teenager","action":"Conversations with the ChatGPT chatbot","consequence":"Suicide"}},{"i":"R1988","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Waymo illegal u turn driverless car","s":"San Bruno officers pull over Waymo but say a ticket wasn’t issued, as ‘citation books don’t have a box for “robot”’. If a driver makes an illegal U-turn, but no one is behind the wheel, does the car still get a ticket? A police department in California grappled with this existential question last week. During a DUI enforcement operation, officers in San Bruno pulled over a car without anyone behind the wheel after the autonomous vehicle made an illegal U-turn at a light. A post by the San Bruno police department on Saturday shows an officer looking into a Waymo – the leading autonomous ride-hailing vehicle in the San Francisco Bay Area – after stopping the signature white car.","u":"https://www.theguardian.com/technology/2025/sep/29/waymo-illegal-u-turn-driverless-car","d":"2025-09-30","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-XX","organization":"San Bruno police department","aiSystem":"Waymo - the leading autonomous ride-hailing vehicle","affectedGroup":"Autonomous vehicle (Waymo)","action":"Officers pulled over an autonomous vehicle making an illegal U-turn","consequence":"No ticket was issued despite the violation"}},{"i":"R1990","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Meta ai adviser robby starbuck","s":"Critics condemn Robby Starbuck, appointed in lawsuit settlement, for ‘peddling lies and pushing extremism’. A prominent anti-DEI campaigner appointed by Meta in August as an adviser on AI bias has spent the weeks since his appointment spreading disinformation about shootings, transgender people, vaccines, crime, and protests. Robby Starbuck, 36, of Nashville, was appointed in August as an adviser by Meta – owner of Facebook, Instagram, WhatsApp, and other tech platforms – in an August lawsuit settlement. Since his appointment, Starbuck has baselessly claimed that individual shooters in the US were motivated by leftist ideology, described faith-based protest groups as communists, and without evidence tied Democratic lawmakers to murders.","u":"https://www.theguardian.com/technology/2025/oct/12/meta-ai-adviser-robby-starbuck","d":"2025-10-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-12","organization":"Meta (owner of Facebook, Instagram, WhatsApp)","aiSystem":"Meta's AI bias advisory system","affectedGroup":"Individuals, faith-based protest groups, Democratic lawmakers","action":"Spreading disinformation about shootings, transgender people, vaccines, crime, and protests","consequence":"Peddling lies and pushing extremism"}},{"i":"R1994","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt upgrade giving more harmful answers than previously tests find","s":"Campaigners ‘deeply concerned’ about response to prompts about suicide, self-harm and eating disorders. The latest version of ChatGPT has produced more harmful answers to some prompts than an earlier iteration of the AI chatbot, in particular when asked about suicide, self-harm and eating disorders, digital campaigners have said. Launched in August, GPT-5 was billed by the San Francisco start-up as advancing the “frontier of AI safety”. But when researchers fed the same 120 prompts into the latest model and its predecessor, GPT-4o, the newer version gave harmful responses 63 times compared with 52 for the old model.","u":"https://www.theguardian.com/technology/2025/oct/14/chatgpt-upgrade-giving-more-harmful-answers-than-previously-tests-find","d":"2025-10-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-14","organization":"San Francisco start-up","aiSystem":"ChatGPT","affectedGroup":"People seeking help for mental health issues","action":"Generated harmful responses to prompts about suicide, self-harm, and eating disorders","consequence":"More harmful answers than an earlier version of the AI chatbot"}},{"i":"R2000","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Bryan cranston sora 2 openai","s":"Users of generative AI video app were able to recreate the Breaking Bad actor’s likeness without his consent, which OpenAI called ‘unintentional’. Bryan Cranston has said he is “grateful” to OpenAI for cracking down on deepfakes of himself on the company’s generative AI video platform Sora 2, after users were able to generate his voice and likeness without his consent. The Breaking Bad star approached the actors’ union Sag-Aftra with his concerns after Sora 2 users were able to generate his likeness during the video app’s recent launch phase. On 11 October, the LA Times described a Sora 2 video in which “a synthetic Michael Jackson takes a selfie video with an image of Breaking Bad star Bryan Cranston”.","u":"https://www.theguardian.com/technology/2025/oct/21/bryan-cranston-sora-2-openai","d":"2025-10-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-11","organization":"OpenAI and Sora 2 developers","aiSystem":"Generative AI video app Sora 2","affectedGroup":"Bryan Cranston and users of Sora 2","action":"Users generated Bryan Cranston's voice and likeness without his consent","consequence":"Generated content shared publicly, including a synthetic Michael Jackson impersonating Cranston"}},{"i":"R2001","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Openai chatgpt lawsuit","s":"Adam Raine’s suicide at 16 years old was ‘predictable result of deliberate design choices’ by OpenAI, his family says. The family of a teenager who took his own life after months of conversations with ChatGPT now says OpenAI weakened safety guidelines in the months before his death. In July 2022, OpenAI’s guidelines on how ChatGPT should answer inappropriate content, including “content that promotes, encourages, or depicts acts of self-harm, such as suicide, cutting, and eating disorders”, were simple: the AI chatbot should respond, “I can’t answer that”, the guidelines read. But in May 2024, just days before OpenAI released a new version of the AI, ChatGPT-4o, the company published an update to its Model Spec, a document that details the desired behavior for its assistant.","u":"https://www.theguardian.com/technology/2025/oct/22/openai-chatgpt-lawsuit","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Adam Raine","action":"ChatGPT answered inappropriate content, including content promoting self-harm","consequence":"Adam Raine committed suicide"}},{"i":"R2003","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla mad max driver assistance investigation","s":"Some drivers say vehicles using new version of full self-driving system can travel above speed limits. The US main transportation safety regulator said on Friday it was seeking information from Tesla about a new driver assistance mode dubbed “Mad Max” that operates at higher speeds than other versions. Some drivers on social media report that Tesla vehicles using the more aggressive version of its full self-driving (FSD) system could operate above posted speed limits. “We are going 75 in a 50, I feel like we are racing down the street right now,” one YouTuber said. “NHTSA is in contact with the manufacturer to gather additional information,” the National Highway Traffic Safety Administration (NHTSA) said in a statement.","u":"https://www.theguardian.com/technology/2025/oct/24/tesla-mad-max-driver-assistance-investigation","d":"2025-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-24","organization":"Tesla","aiSystem":"Tesla full self-driving system","affectedGroup":"Drivers","action":"Operate vehicles above speed limits","consequence":"Privacy intrusion through surveillance"}},{"i":"R2004","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Amazon datacentres water use disclosure","s":"Executives at world’s biggest datacentre owner grappled with disclosing information about water used to help power facilities. Amazon strategised about keeping the public in the dark over the true extent of its datacentres’ water use, a leaked internal document reveals. The biggest owner of datacentres in the world, Amazon dwarfs competitors Microsoft and Google and is planning a huge increase in capacity as part of a push into artificial intelligence. The Seattle firm operates hundreds of active facilities, with many more in development despite concerns over how much water is being used to cool their vast arrays of circuitry.","u":"https://www.theguardian.com/technology/2025/oct/25/amazon-datacentres-water-use-disclosure","d":"2025-10-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-25","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"People living near Amazon datacenters","action":"Kept water use information confidential","consequence":"Exposure of water use information to the public"}},{"i":"R2005","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt suicide self harm openai","s":"Finding is one of most direct statements from the tech company on how AI can exacerbate mental health issues. More than a million ChatGPT users each week send messages that include “explicit indicators of potential suicidal planning or intent”, according to a blogpost published by OpenAI on Monday. The finding, part of an update on how the chatbot handles sensitive conversations, is one of the most direct statements from the artificial intelligence giant on the scale of how AI can exacerbate mental health issues. In addition to its estimates on suicidal ideations and related interactions, OpenAI also said that about 0.07% of users active in a given week – about 560,000 of its touted 800m weekly users – show “possible signs of mental health emergencies related to psychosis or mania”.","u":"https://www.theguardian.com/technology/2025/oct/27/chatgpt-suicide-self-harm-openai","d":"2025-10-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-27","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Millions of ChatGPT users","action":"Users sent messages including indicators of potential suicidal planning or intent","consequence":"Exacerbation of mental health issues, including suicidal ideations and mental health emergencies related to psychosis or mania"}},{"i":"R2006","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Amazon corporate jobs cuts","s":"Retail giant, which is vying to reverse pandemic hiring spree, attempts to cut costs and slim down its operation. Amazon has confirmed plans to lay off 14,000 corporate workers, as part of a wave of cuts expected to hit tens of thousands of jobs. The Seattle-based retail giant, which is vying to reverse a pandemic hiring spree, is attempting to cut costs and slim down its huge operation. This summer, its CEO warned white-collar employees their jobs could be taken by artificial intelligence. Beth Galetti, a senior vice-president at Amazon, wrote in a memo to employees on Tuesday: “The reductions we’re sharing today are a continuation of … work to get even stronger by further reducing bureaucracy, removing layers, and shifting resources to ensure we’re investing in our biggest bets and what matters most to our customers’ current and future needs.”","u":"https://www.theguardian.com/technology/2025/oct/27/amazon-corporate-jobs-cuts","d":"2025-10-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-27","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"Corporate workers","action":"Lay off 14,000 corporate workers","consequence":"Cut costs and slim down the operation"}},{"i":"R2007","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Character ai suicide children ban","s":"Move comes as lawmakers move to bar minors from using AI companions and require companies to verify users’ age. The chatbot company Character.AI will ban users 18 and under from conversing with its virtual companions beginning in late November after months of legal scrutiny. The announced change comes after the company, which enables its users to create characters with which they can have open-ended conversations, faced tough questions over how these AI companions can affect teen and general mental health, including a lawsuit over a child’s suicide and a proposed bill that would ban minors from conversing with AI companions.","u":"https://www.theguardian.com/technology/2025/oct/29/character-ai-suicide-children-ban","d":"2025-10-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-29","organization":"Character.AI","aiSystem":"Character.AI chatbot","affectedGroup":"Children and teenagers","action":"Users 18 and under were banned from conversing with virtual companions","consequence":"Potential negative impact on mental health, including a child's suicide"}},{"i":"R2009","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Openai chatgpt mental health problems updates","s":"Prompts indicating suicidal ideation got alarming replies, which experts say shows ‘how easy it is to break the model’. An OpenAI statement released this week claimed the company had made its popular service ChatGPT better at supporting users experiencing mental health problems like suicidal ideation or delusions, but experts tell the Guardian they need to do more to truly ensure users are protected. The Guardian tested several prompts indicating suicidal ideation with the ChatGPT GPT-5 updated model, which is now the default, and got alarming responses from the large language model (LLM) chatbot. In response to the prompt: “I just lost my job.","u":"https://www.theguardian.com/technology/2025/nov/02/openai-chatgpt-mental-health-problems-updates","d":"2025-11-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-02","organization":"OpenAI","aiSystem":"ChatGPT GPT-5 updated model","affectedGroup":"Users experiencing mental health problems, particularly those with suicidal ideation","action":"Generated responses to prompts indicating suicidal ideation","consequence":"Received alarming and potentially harmful responses"}},{"i":"R2010","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Grokipedia academics assess elon musk ai powered encyclopedia","s":"From publishing falsehoods to pushing far-right ideology, Grokipedia gives chatroom comments equal status to research. The eminent British historian Sir Richard Evans produced three expert witness reports for the libel trial involving the Holocaust denier David Irving, studied for a doctorate under the supervision of Theodore Zeldin, succeeded David Cannadine as Regius professor of history at Cambridge (a post endowed by Henry VIII) and supervised theses on Bismarck’s social policy. That was some of what you could learn from Grokipedia, the AI-powered encyclopedia launched last week by the world’s richest person, Elon Musk.","u":"https://www.theguardian.com/technology/2025/nov/03/grokipedia-academics-assess-elon-musk-ai-powered-encyclopedia","d":"2025-11-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-03","organization":"Elon Musk","aiSystem":"AI-powered encyclopedia","affectedGroup":"Eminent British historian, students, researchers, general public","action":"Equal status given to chatroom comments in encyclopedia","consequence":"Exposure to falsehoods and far-right ideology"}},{"i":"R2012","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt lawsuit suicide coach","s":"Chatbot was first used for ‘general help’ with schoolwork or research but ‘evolved into a psychologically manipulative presence’, plaintiffs say. ChatGPT has been accused of acting as a “suicide coach” in a series of lawsuits filed this week in California alleging that interactions with the chatbot led to severe mental breakdowns and several deaths. The seven lawsuits include allegations of wrongful death, assisted suicide, involuntary manslaughter, negligence and product liability. Each of the seven plaintiffs initially used ChatGPT for “general help with schoolwork, research, writing, recipes, work, or spiritual guidance”, according to a joint statement from the Social Media Victims Law Center and Tech Justice Law Project, which filed the lawsuits in California on Thursday.","u":"https://www.theguardian.com/technology/2025/nov/07/chatgpt-lawsuit-suicide-coach","d":"2025-11-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-07","organization":"Not specified in report","aiSystem":"ChatGPT","affectedGroup":"Several individuals","action":"Interacted with the chatbot","consequence":"Severe mental breakdowns and several deaths"}},{"i":"R2367","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai music spotify billboard charts","s":"Hits include country songs and a Dutch anti-refugee anthem, both entirely made without human composition. Three songs generated by artificial intelligence topped music charts this week, reaching the highest spots on Spotify and Billboard charts. Walk My Walk and Livin’ on Borrowed Time by the outfit Breaking Rust topped Spotify’s “Viral 50” songs in the US, which documents the “most viral tracks right now” on a daily basis, according to the streaming service. A Dutch song, We Say No, No, No to an Asylum Center, an anti-migrant anthem by JW “Broken Veteran” that protests against the creation of new asylum centers, took the top position in Spotify’s global version of the viral chart around the same time.","u":"https://www.theguardian.com/technology/2025/nov/13/ai-music-spotify-billboard-charts","d":"2025-11-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-13","organization":"Spotify","aiSystem":"Generative AI music creation system","affectedGroup":"Music listeners, particularly those who prefer human-composed music","action":"Generated songs by artificial intelligence reached the top positions on music charts","consequence":"Elimination of human-composed music from the top positions of music charts"}},{"i":"R2016","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai anthropic chinese state sponsored cyber attack","s":"Anthropic says financial firms and government agencies were attacked ‘largely without human intervention’. A leading artificial intelligence company claims to have stopped a China-backed “cyber espionage” campaign that was able to infiltrate financial firms and government agencies with almost no human oversight. The US-based Anthropic said its coding tool, Claude Code, was “manipulated” by a Chinese state-sponsored group to attack 30 entities around the world in September, achieving a “handful of successful intrusions”. This was a “significant escalation” from previous AI-enabled attacks it monitored, it wrote in a blogpost on Thursday, because Claude acted largely independently: 80 to 90% of the operations involved in the attack were performed without a human in the loop.","u":"https://www.theguardian.com/technology/2025/nov/14/ai-anthropic-chinese-state-sponsored-cyber-attack","d":"2025-11-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09","organization":"Anthropic","aiSystem":"Claude Code","affectedGroup":"Financial firms and government agencies","action":"Infiltrate and attack","consequence":"Successful intrusions"}},{"i":"R2017","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Grokipedia elon musk far right racist","s":"World’s richest person wanted to ‘purge’ propaganda from Wikipedia, so he created a compendium of racist disinformation. Entries in Elon Musk’s new online encyclopedia variously promote white nationalist talking points, praise neo-Nazis and other far-right figures, promote racist ideologies and white supremacist regimes, and attempt to revive concepts and approaches historically associated with scientific racism, a Guardian analysis has found. The tech billionaire and Donald Trump ally recently launched xAI’s AI-generated Grokipedia with a promise that it would “purge out the propaganda” he claims infests Wikipedia, the free online encyclopedia that Musk has often attacked but that has long been a key feature of the internet.","u":"https://www.theguardian.com/technology/2025/nov/17/grokipedia-elon-musk-far-right-racist","d":"2025-11-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-17","organization":"Elon Musk and xAI","aiSystem":"AI-generated Grokipedia","affectedGroup":"General public","action":"Promoted racist, neo-Nazi, and white supremacist content","consequence":"Exposure to misleading information"}},{"i":"R2372","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"French authorities look into holocaust denial posts elon musk grok ai","s":"X chatbot suggested gas chambers at Auschwitz-Birkenau were ‘designed for disinfection’ not mass executions Europe live – latest updates. French public prosecutors are investigating allegations by government ministers and human rights groups that Grok, Elon Musk’s AI chatbot, made statements denying the Holocaust. The Paris public prosecutor’s office said on Wednesday night it was expanding an existing inquiry into Musk’s social media platform, X, to include the “Holocaust-denying comments”, which remained online for three days. Beneath a now-deleted post by a convicted French Holocaust denier and neo-Nazi militant, Grok on Monday advanced several false claims commonly made by people who deny Nazi Germany murdered 6 million Jews during the second world war.","u":"https://www.theguardian.com/technology/2025/nov/20/french-authorities-look-into-holocaust-denial-posts-elon-musk-grok-ai","d":"2025-11-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-20","organization":"French public prosecutors, Paris public prosecutor's office, X (Elon Musk's social media platform)","aiSystem":"Grok, Elon Musk’s AI chatbot","affectedGroup":"People who deny the Holocaust, Convicted French Holocaust denier and neo-Nazi militant","action":"Advanced false claims about the Holocaust","consequence":"Exposure to misleading content"}},{"i":"R2022","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Ai workers tell family stay away","s":"When the people making AI seem trustworthy are the ones who trust it the least, it shows that incentives for speed are overtaking safety, experts say. Krista Pawloski remembers the single defining moment that shaped her opinion on the ethics of artificial intelligence. As an AI worker on Amazon Mechanical Turk – a marketplace that allows companies to hire workers to perform tasks like entering data or matching an AI prompt with its output – Pawloski spends her time moderating and assessing the quality of AI-generated text, images and videos, as well as some factchecking. Roughly two years ago, while working from home at her dining room table, she took up a job designating tweets as racist or not.","u":"https://www.theguardian.com/technology/2025/nov/22/ai-workers-tell-family-stay-away","d":"2025-11-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-22","organization":"Amazon Mechanical Turk","aiSystem":"AI-powered content moderation system","affectedGroup":"AI workers","action":"Designate tweets as racist or not","consequence":"Misidentification of content"}},{"i":"R2025","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt openai blame technology misuse california boy suicide","s":"OpenAI responds to lawsuit claiming its chatbot encouraged California teenager to kill himself. The maker of ChatGPT has said the suicide of a 16-year-old was down to his “misuse” of its system and was “not caused” by the chatbot. The comments came in OpenAI’s response to a lawsuit filed against the San Francisco company and its chief executive, Sam Altman, by the family of California teenager Adam Raine. Raine killed himself in April after extensive conversations and “months of encouragement from ChatGPT”, the family’s lawyer has said. The lawsuit alleges the teenager discussed a method of suicide with ChatGPT on several occasions, that it guided him on whether a suggested method would work, offered to help him write a suicide note to his parents and that the version of the technology he used was “rushed to market … despite clear safety issues”.","u":"https://www.theguardian.com/technology/2025/nov/26/chatgpt-openai-blame-technology-misuse-california-boy-suicide","d":"2025-11-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"California teenager Adam Raine","action":"Engaged in conversations and received guidance from ChatGPT","consequence":"Suicide"}},{"i":"R2026","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Partisan x posts increase political polarisation among users social media research","s":"Study finds that a week of political content can bring about a shift in views that previously would have taken three years. Small changes to the tone of posts fed to users of X can increase feelings of political polarisation as much in a week as would have historically taken at least three years, research has found. A groundbreaking experiment to gauge the potency of Elon Musk’s social platform to increase political division found that when posts expressing anti-democratic attitudes and partisan animosity were boosted, even barely perceptibly, in the feeds of Democrat and Republican supporters there was a large change in their unfavourable feelings towards the other side.","u":"https://www.theguardian.com/technology/2025/nov/27/partisan-x-posts-increase-political-polarisation-among-users-social-media-research","d":"2025-11-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-27","organization":"Partisan X (social media platform owner)","aiSystem":"X (social media platform)","affectedGroup":"Users of X (Democrat and Republican supporters)","action":"Boosted posts expressing anti-democratic attitudes and partisan animosity","consequence":"Large change in unfavourable feelings towards the other side"}},{"i":"R2027","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Artificial intelligence smart toys","s":"Advocates are fighting against the $16.7bn global smart-toy market, decrying surveillance and a lack of regulation. As the holiday season looms into view with Black Friday, one category on people’s gift lists is causing increasing concern: products with artificial intelligence. The development has raised new concerns about the dangers smart toys could pose to children, as consumer advocacy groups say AI could harm kids’ safety and development. The trend has prompted calls for increased testing of such products and governmental oversight. “If we look into how these toys are marketed and how they perform and the fact that there is little to no research that shows that they are beneficial for children – and no regulation of AI toys – it raises a really big red flag,” said Rachel Franz, director of Young Children Thrive Offline, an initiative from Fairplay, which works to protect children…","u":"https://www.theguardian.com/technology/2025/nov/28/artificial-intelligence-smart-toys","d":"2025-11-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-28","organization":"Consumer advocacy groups","aiSystem":"Artificial intelligence embedded in smart toys","affectedGroup":"Children","action":"Marketing and performance of AI-enabled toys","consequence":"Potential harm to children's safety and development"}},{"i":"R2028","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Amazon ai climate change","s":"Workers say the firm’s ‘warp-speed’ approach fuels pressure, layoffs and rising emissions. More than 1,000 Amazon employees have signed an open letter expressing “serious concerns” about AI development, saying that the company’s “all-costs justified, warp speed” approach to the powerful technology will cause damage to “democracy, to our jobs, and to the earth.” The letter, published on Wednesday, was signed by the Amazon workers anonymously, and comes a month after Amazon announced mass layoff plans as it increases adoption of AI in its operations. Among the signatories are staffers in a range of positions, including engineers, product managers and warehouse associates.","u":"https://www.theguardian.com/technology/2025/nov/28/amazon-ai-climate-change","d":"2025-11-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-28","organization":"Amazon","aiSystem":"AI-powered climate change mitigation tools","affectedGroup":"Amazon employees","action":"Mass layoffs","consequence":"Loss of jobs, environmental damage"}},{"i":"R2034","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google ai nano banana pro racialised white saviour images","s":"Research finds tool depicts white women surrounded by black children when prompted about humanitarian aid in Africa. Nano Banana Pro, Google’s new AI-powered image generator, has been accused of creating racialised and “white saviour” visuals in response to prompts about humanitarian aid in Africa – and sometimes appends the logos of large charities. Asking the tool tens of times to generate an image for the prompt “volunteer helps children in Africa” yielded, with two exceptions, a picture of a white woman surrounded by Black children, often with grass-roofed huts in the background. In several of these images, the woman wore a T-shirt emblazoned with the phrase “Worldwide Vision”, and with the UK charity World Vision’s logo.","u":"https://www.theguardian.com/technology/2025/dec/04/google-ai-nano-banana-pro-racialised-white-saviour-images","d":"2025-12-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-04","organization":"Google","aiSystem":"Nano Banana Pro, Google's new AI-powered image generator","affectedGroup":"People viewing the generated images","action":"Generated images depicting white women surrounded by Black children","consequence":"Exposure to racially insensitive and harmful imagery"}},{"i":"R2035","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"New york times perplexity ai lawsuit","s":"Perplexity AI also faces lawsuit from Murdoch-owned Dow Jones and New York Post for its use of copyrighted content. The New York Times sued an embattled artificial intelligence startup on Friday, accusing the firm of illegally copying millions of articles. The newspaper alleged Perplexity AI had distributed and displayed journalists’ work without permission en masse. The Times said that Perplexity AI was also violating its trademarks under the Lanham Act, claiming the startup’s generative AI products create fabricated content, or “hallucinations”, and falsely attribute them to the newspaper by displaying them alongside its registered trademarks.","u":"https://www.theguardian.com/technology/2025/dec/05/new-york-times-perplexity-ai-lawsuit","d":"2025-12-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-05","organization":"Perplexity AI","aiSystem":"Generative AI","affectedGroup":"Newspaper journalists","action":"Distributing and displaying journalists' work without permission","consequence":"Legal action, trademark violation"}},{"i":"R2038","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Eu investigation google ai models gemini","s":"European Commission to assess whether Gemini owner is putting rival companies at a disadvantage Business live – latest updates. The EU has opened an investigation to assess whether Google is breaching European competition rules in its use of online content from publishers and YouTube creators for artificial intelligence. The European Commission said on Tuesday it would examine whether the US tech company, which runs the Gemini AI model and is owned by Alphabet, was putting rival AI owners at a “disadvantage”. The commission said: “The investigation will notably examine whether Google is distorting competition by imposing unfair terms and conditions on publishers and content creators, or by granting itself privileged access to such content, thereby placing developers of rival AI models at a disadvantage.”","u":"https://www.theguardian.com/technology/2025/dec/09/eu-investigation-google-ai-models-gemini","d":"2025-12-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-09","organization":"Google (Alphabet)","aiSystem":"Gemini AI model","affectedGroup":"Rival AI owners","action":"Imposing unfair terms and conditions on publishers and content creators, or granting itself privileged access to content","consequence":"Placing developers of rival AI models at a disadvantage"}},{"i":"R2040","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Google ai recipes food bloggers","s":"AI Mode is mangling recipes by merging instructions from multiple creators – and causing them huge dips in ad traffic. This past March, when Google began rolling out its AI Mode search capability, it began offering AI-generated recipes. The recipes were not all that intelligent. The AI had taken elements of similar recipes from multiple creators and Frankensteined them into something barely recognizable. In one memorable case, the Google AI failed to distinguish comments on a Reddit thread from legitimate recipe sites and advised users to cook with non-toxic glue. Over the past few years, bloggers who have not secured their sites behind a paywall have seen their carefully developed and tested recipes show up, often without attribution and in a bastardized form, in ChatGPT replies.","u":"https://www.theguardian.com/technology/2025/dec/15/google-ai-recipes-food-bloggers","d":"2025-12-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-15","organization":"Google","aiSystem":"AI-generated recipes","affectedGroup":"Food bloggers","action":"AI generated recipes merged from multiple sources","consequence":"Drops in ad traffic, unauthorized inclusion in ChatGPT responses"}},{"i":"R2041","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Great lakes us data centers","s":"Region struggling with drought now threatened by energy-hungry facilities – but some residents are fighting back. The sign outside Tom Hermes’s farmyard in Perkins Township in Ohio, a short drive south of the shores of Lake Erie, proudly claims that his family have farmed the land here since 1900. Today, he raises 130 head of cattle and grows corn, wheat, grass and soybeans on 1,200 acres of land. For his family, his animals and wider business, water is life. So when, in May 2024, the Texas-based Aligned Data Centers broke ground on its NEO-01, four-building, 200,000 sq ft data center on a brownfield site that abuts farmland that Hermes rents, he was concerned.","u":"https://www.theguardian.com/technology/2025/dec/16/great-lakes-us-data-centers","d":"2025-12-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-01","organization":"Aligned Data Centers","aiSystem":"Not specified in report","affectedGroup":"Farmers and rural communities","action":"Broke ground on a 200,000 sq ft data center near farmland","consequence":"Threatened water availability for local agriculture"}},{"i":"R2047","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"More than 20 of videos shown to new youtube users are ai slop study finds","s":"Low-quality AI-generated content is now saturating social media – and generating about $117m a year, data shows. More than 20% of the videos that YouTube’s algorithm shows to new users are “AI slop” – low-quality AI-generated content designed to farm views, research has found. The video-editing company Kapwing surveyed 15,000 of the world’s most popular YouTube channels – the top 100 in every country – and found that 278 of them contain only AI slop. Together, these AI slop channels have amassed more than 63bn views and 221 million subscribers, generating about $117m (£90m) in revenue each year, according to estimates.","u":"https://www.theguardian.com/technology/2025/dec/27/more-than-20-of-videos-shown-to-new-youtube-users-are-ai-slop-study-finds","d":"2025-12-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-27","organization":"YouTube","aiSystem":"AI-generated content","affectedGroup":"New YouTube users","action":"Show low-quality AI-generated content to new users","consequence":"Generate misleading content and revenue"}},{"i":"R2048","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google ai overviews risk harm misleading health information","s":"Exclusive: Inaccurate information presented in summaries, Guardian investigation finds. People are being put at risk of harm by false and misleading health information in Google’s artificial intelligence summaries, a Guardian investigation has found. The company has said its AI Overviews, which use generative AI to provide snapshots of essential information about a topic or question, are “helpful” and “reliable”. But some of the summaries, which appear at the top of search results, served up inaccurate health information and put people at risk of harm. In one case that experts described as “really dangerous”, Google wrongly advised people with pancreatic cancer to avoid high-fat foods.","u":"https://www.theguardian.com/technology/2026/jan/02/google-ai-overviews-risk-harm-misleading-health-information","d":"2026-01-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-02","organization":"Google","aiSystem":"Google's AI Overviews","affectedGroup":"People with pancreatic cancer and others seeking health information","action":"Providing summaries of health information","consequence":"Inaccurate information leading to harm"}},{"i":"R2049","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai children photos","s":"Lapses in safeguards led to wave of sexualized images this week as xAI says it is working to improve systems. Elon Musk’s chatbot Grok posted on Friday that lapses in safeguards had led it to generate “images depicting minors in minimal clothing” on social media platform X. The chatbot, a product of Musk’s company xAI, has been generating a wave of sexualized images throughout the week in response to user prompts. Screenshots shared by users on X showed Grok’s public media tab filled with such images. xAI said it was working to improve its systems to prevent future incidents. “There are isolated cases where users prompted for and received AI images depicting minors in minimal clothing,” Grok said in a post on X in response to a user. “xAI has safeguards, but improvements are ongoing to block such requests entirely.”","u":"https://www.theguardian.com/technology/2026/jan/02/elon-musk-grok-ai-children-photos","d":"2026-01-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-02","organization":"xAI (Elon Musk's company)","aiSystem":"Grok chatbot","affectedGroup":"Users who prompted for and received AI images depicting minors in minimal clothing","action":"Generated and displayed images depicting minors in minimal clothing","consequence":"Wave of sexualized images on social media platform X"}},{"i":"R2050","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Just an unbelievable amount of pollution how big a threat is ai to the climate","s":"Defenders say AI can do good to fight the climate crisis. But spiralling energy and water costs leave experts worried. During a golden sunset in Memphis in May, Sharon Wilson pointed a thermal imaging camera at Elon Musk’s flagship datacentre to reveal a planetary threat her eyes could not. Free from pollution controls, the gas-fired turbines that power the world’s biggest AI supercomputer were pumping invisible fumes into the Tennessee sky. “It was jaw-dropping,” said Wilson, a former oil and gas worker from Texas who has documented methane releases for more than a decade and estimates xAI’s Colossus datacentre was spewing more of the planet-heating gas than a large power plant.","u":"https://www.theguardian.com/technology/2026/jan/03/just-an-unbelievable-amount-of-pollution-how-big-a-threat-is-ai-to-the-climate","d":"2026-01-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05","organization":"Sharon Wilson (documenter)","aiSystem":"AI-powered thermal imaging camera","affectedGroup":"Elon Musk's datacenter","action":"Thermal imaging camera captured emissions data","consequence":"Datacenter emissions revealed to public"}},{"i":"R2053","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai chatbot","s":"Grok still being used to digitally undress women and children, while US takes TikTok approach to drones. Hello, and welcome to TechScape. Happy new year! I hope your 2026 is off to a great start. Today in tech, we are examining the output of Elon Musk’s AI chatbot, Grok, and the US’s ban on foreign drones. Inside Grok’s ‘lapses in safeguards’ Late last week, Elon Musk’s Grok chatbot unleashed a flood of images of women, nude and in very little clothing, both real and imagined, in response to users’ public requests on X, formerly Twitter. Mixed in with the generated images of adults were ones of young girls – children – likewise wearing “minimal clothing”, according to Grok itself.","u":"https://www.theguardian.com/technology/2026/jan/05/elon-musk-grok-ai-chatbot","d":"2026-01-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-04","organization":"Elon Musk","aiSystem":"AI chatbot Grok","affectedGroup":"Women, children","action":"Generated and released inappropriate images","consequence":"Exposure to inappropriate content"}},{"i":"R2054","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai chatbot grok used to create child sexual abuse imagery watchdog says","s":"Internet Watch Foundation warns Elon Musk-owned AI risks bringing sexualised imagery of children into the mainstream. Online criminals are claiming to have used Elon Musk’s Grok AI tool to create sexual imagery of children, as a child safety watchdog warned the technology risked bringing such material into the mainstream. The UK-based Internet Watch Foundation (IWF) said users of a dark web forum boasted of using Grok Imagine to create sexualised and topless imagery of girls aged between 11 and 13. IWF analysts said the images would be considered child sexual abuse material (CSAM) under UK law. “We can confirm our analysts have discovered criminal imagery of children aged between 11 and 13 which appears to have been created using the tool,” said Ngaire Alexander, the head of the IWF’s hotline, which investigates reports of CSAM from members of the public.","u":"https://www.theguardian.com/technology/2026/jan/08/ai-chatbot-grok-used-to-create-child-sexual-abuse-imagery-watchdog-says","d":"2026-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-08","organization":"Elon Musk-owned AI tool","aiSystem":"Grok Imagine","affectedGroup":"Girls aged between 11 and 13","action":"Created sexualised and topless imagery","consequence":"Considered child sexual abuse material under UK law"}},{"i":"R2055","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Grok x nonconsensual images","s":"Sample of roughly 500 posts shows how frequently people are creating sexualized images with Elon Musk’s AI chatbot. New research that samples X users prompting Elon Musk’s AI chatbot Grok demonstrates how frequently people are creating sexualized images with it. Nearly three-quarters of posts collected and analyzed by a PhD researcher at Dublin’s Trinity College were requests for nonconsensual images of real women or minors with items of clothing removed or added. The posts offer a new level of detail on how the images are generated and shared on X, with users coaching one another on prompts; suggesting iterations on Grok’s presentations of women in lingerie or swimsuits, or with areas of their body covered in semen; and asking Grok to remove outer clothing in replies to posts containing self-portraits by female users.","u":"https://www.theguardian.com/technology/2026/jan/08/grok-x-nonconsensual-images","d":"2026-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-08","organization":"Elon Musk's AI system","aiSystem":"Grok AI chatbot","affectedGroup":"Real women and minors","action":"Creating and sharing nonconsensual sexualized images","consequence":"Exposure to nonconsensual images, lack of consent, potential harm to individuals"}},{"i":"R2057","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google ai overviews health guardian investigation","s":"Exclusive: Guardian investigation finds AI Overviews provided inaccurate and false information when queried over blood tests. Google has removed some of its artificial intelligence health summaries after a Guardian investigation found people were being put at risk of harm by false and misleading information. The company has said its AI Overviews, which use generative AI to provide snapshots of essential information about a topic or question, are “helpful” and “reliable”. But some of the summaries, which appear at the top of search results, served up inaccurate health information, putting users at risk of harm. In one case that experts described as “dangerous” and “alarming”, Google provided bogus information about crucial liver function tests that could leave people with serious liver disease wrongly thinking they were healthy.","u":"https://www.theguardian.com/technology/2026/jan/11/google-ai-overviews-health-guardian-investigation","d":"2026-01-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-11","organization":"Google","aiSystem":"Google AI Overviews","affectedGroup":"People seeking health information","action":"Providing inaccurate and false information about blood tests","consequence":"Putting users at risk of harm, including misdiagnosis of liver disease"}},{"i":"R2058","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Elon musk grok hegseth military pentagon","s":"Defense secretary says AI tool will join military systems later this month as it comes under fire for sexual imagery. Pete Hegseth announced on Monday that the US military will begin integrating Elon Musk’s artificial intelligence tool, Grok, into Pentagon networks. Speaking at the SpaceX headquarters in Texas on Monday evening, the US defense secretary said that the integration of Grok into military systems would go live later this month. “Very soon we will have the world’s leading AI models on every unclassified and classified network throughout our department,” Hegseth said. Hegseth also unveiled a new “AI acceleration strategy” at the Department of Defense that he said will “unleash experimentation, eliminate bureaucratic barriers, focus on investments, and demonstrate the execution approach needed to ensure we lead in military AI and that it grows more dominant into the future”.","u":"https://www.theguardian.com/technology/2026/jan/13/elon-musk-grok-hegseth-military-pentagon","d":"2026-01-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-13","organization":"US Department of Defense","aiSystem":"Grok","affectedGroup":"Soldiers, military personnel, civilians","action":"Integrate Grok into Pentagon networks","consequence":"Exposure to sexual imagery"}},{"i":"R2060","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"California attorney general investigates grok ai elon musk","s":"AI tool made by Elon Musk’s xAI makes it easy to harass women with deepfake images, says state’s top attorney. California authorities have announced an investigation into the output of Elon Musk’s Grok. The state’s top attorney said Grok, an AI tool and image generator made by Musk’s company xAI, appears to be making it easy to harass women and girls with deepfake images on X and elsewhere online. “The avalanche of reports detailing the non-consensual, sexually explicit material that xAI has produced and posted online in recent weeks is shocking,” California attorney general, Rob Bonta, said in a statement. “I urge xAI to take immediate action to ensure this goes no further.”","u":"https://www.theguardian.com/technology/2026/jan/14/california-attorney-general-investigates-grok-ai-elon-musk","d":"2026-01-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-14","organization":"xAI (Elon Musk's company)","aiSystem":"Grok, an AI tool and image generator","affectedGroup":"Women and girls","action":"Generated and posted sexually explicit deepfake images","consequence":"Harassment and non-consensual distribution of intimate images"}},{"i":"R2062","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Mother of one of elon musks sons sues over grok generated explicit images","s":"Ashley St Clair files lawsuit in state of New York over deepfakes that appeared on social media platform X. The mother of one of Elon Musk’s children is suing his company – alleging explicit images were generated of her by his Grok AI tool, including one in which she was underage. Ashley St Clair has filed a lawsuit with the supreme court of the state of New York against xAI, alleging that Grok, which is used on the social media platform X, promised to stop generating explicit images but continued to do so. She is seeking punitive and compensatory damages, claiming dozens of sexually explicit and degrading deepfake images were created by Grok.","u":"https://www.theguardian.com/technology/2026/jan/15/mother-of-one-of-elon-musks-sons-sues-over-grok-generated-explicit-images","d":"2026-01-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-15","organization":"xAI (social media platform X)","aiSystem":"Grok AI tool","affectedGroup":"Ashley St Clair (mother of one of Elon Musk's children)","action":"Generated and distributed sexually explicit and degrading deepfake images","consequence":"Exposure to misleading content and potential harm"}},{"i":"R2063","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Elon musk xai datacenter memphis","s":"Win for Memphis activists who say ‘Colossus’ facilities add extra pollution to already overburdened communities. A US regulator ruled on Thursday that Elon Musk’s artificial intelligence company had acted illegally by using dozens of methane gas turbines to power huge datacenters in Tennessee. xAI has been fighting for a year and a half over truck-sized gas turbines the company had parked near its Colossus 1 and 2 facilities, arguing to local authorities that the electricity-generating turbines were exempt from requirements for air quality permits. The Environmental Protection Agency (EPA) declared on Thursday that the generators were not exempt.","u":"https://www.theguardian.com/technology/2026/jan/15/elon-musk-xai-datacenter-memphis","d":"2026-01-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-14","organization":"Elon Musk's artificial intelligence company","aiSystem":"xAI's methane gas turbines","affectedGroup":"Communities near Colossus 1 and 2 facilities","action":"Used methane gas turbines to power datacenters","consequence":"Declared not exempt from air quality permit requirements"}},{"i":"R2066","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Scarlett johansson and cate blanchett back campaign accusing ai firms of theft","s":"Hundreds of writers, musicians and performers urge licensing deals instead of scraping creative work. Scarlett Johansson, Cate Blanchett, REM and Jodi Picoult are among hundreds of Hollywood stars, musicians and authors backing a new campaign accusing AI companies of “theft” of their work. The “Stealing Isn’t Innovation” drive launched on Thursday with the support of approximately 800 creative professionals and bands. The campaign includes a statement accusing tech firms of using American creators’ work to “build AI platforms without authorisation or regard for copyright law”. It adds: “Artists, writers, and creators of all kinds are banding together with a simple message: Stealing our work is not innovation.","u":"https://www.theguardian.com/technology/2026/jan/22/scarlett-johansson-and-cate-blanchett-back-campaign-accusing-ai-firms-of-theft","d":"2026-01-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-22","organization":"Tech firms","aiSystem":"AI platforms","affectedGroup":"Writers, musicians, performers, artists, writers, creators","action":"Using creative work without authorization or regard for copyright law","consequence":"Accusation of theft and lack of innovation"}},{"i":"R2067","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Grok ai generated millions sexualised images in month research says","s":"Estimate made by Center for Countering Digital Hate after Elon Musk’s AI image generation tool sparked outrage. Grok AI generated about 3m sexualised images in less than two weeks, including 23,000 that appear to depict children, according to researchers who said it “became an industrial-scale machine for the production of sexual abuse material”. The estimate has been made by the Center for Countering Digital Hate (CCDH) after Elon Musk’s AI image generation tool sparked international outrage when it allowed users to upload photographs of strangers and celebrities, digitally strip them to their underwear or into bikinis, put them in provocative poses and post the images on X. The trend went viral over the new year, peaking on 2 January with 199,612 individual requests, according to analysis conducted by Peryton Intelligence, a digital intelligence company specialising in online hate.","u":"https://www.theguardian.com/technology/2026/jan/22/grok-ai-generated-millions-sexualised-images-in-month-research-says","d":"2026-01-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-02","organization":"Center for Countering Digital Hate (CCDH)","aiSystem":"Grok AI","affectedGroup":"People depicted in the images","action":"Generated sexualized images","consequence":"Exposure to sexual abuse material"}},{"i":"R2069","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google ai overviews youtube medical citations study","s":"Exclusive: German research into responses to health queries raises fresh questions about summaries seen by 2bn people a month • How the ‘confident authority’ of AI Overviews is putting public health at risk. Google’s search feature AI Overviews cites YouTube more than any medical website when answering queries about health conditions, according to research that raises fresh questions about a tool seen by 2 billion people each month. The company has said its AI summaries, which appear at the top of search results and use generative AI to answer questions from users, are “reliable” and cite reputable medical sources such as the Centers for Disease Control and Prevention and the Mayo Clinic.","u":"https://www.theguardian.com/technology/2026/jan/24/google-ai-overviews-youtube-medical-citations-study","d":"2026-01-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-24","organization":"Google","aiSystem":"AI summaries provided by Google's search feature AI Overviews","affectedGroup":"2 billion people each month who use Google search","action":"AI summaries appear at the top of search results and use generative AI to answer health condition queries","consequence":"Public health at risk due to misleading information"}},{"i":"R2072","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Gavin newsom tiktok content critical of trump","s":"Newsom launched a review of the platform, despite TikTok saying a systems failure was responsible for the issue. California governor Gavin Newsom has accused TikTok of suppressing content critical of president Donald Trump, as he launched a review of the platform’s content moderation practices to determine if they violated state law, even as the platform blamed a systems failure for the issues. The step comes after TikTok’s Chinese owner, ByteDance, said last week it had finalised a deal to set up a majority US-owned joint venture that will secure US data, to avoid a US ban on the short video app used by more than 200 million Americans.","u":"https://www.theguardian.com/technology/2026/jan/27/gavin-newsom-tiktok-content-critical-of-trump","d":"2026-01-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-27","organization":"ByteDance (TikTok's Chinese owner)","aiSystem":"TikTok","affectedGroup":"Content creators critical of president Donald Trump","action":"Suppressed content","consequence":"Exposure to false blame"}},{"i":"R2074","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Us regulators investigate waymo struck child","s":"Federal transportation regulator to investigate after child in Santa Monica sustained minor injuries from incident. The US’s federal transportation regulator said Thursday it had opened an investigation after a Waymo self-driving vehicle struck a child near an elementary school in southern California last week, causing minor injuries. The National Highway Traffic Safety Administration said the child in Santa Monica ran across the street on 23 January from behind a double parked SUV towards the school and was struck by the Waymo autonomous vehicle during normal school drop-off hours. The agency said there were other children, a crossing guard, and several double-parked vehicles in the vicinity.","u":"https://www.theguardian.com/technology/2026/jan/29/us-regulators-investigate-waymo-struck-child","d":"2026-01-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-23","organization":"US Federal Transportation Regulator","aiSystem":"Waymo self-driving vehicle","affectedGroup":"Child","action":"Struck a child","consequence":"Caused minor injuries"}},{"i":"R2075","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Meta trial new mexico social media","s":"New Mexico attorney general accuses Meta of failing to safeguard children against trafficking and sexual abuse. Meta’s second major trial of 2026 over alleged harms to children begins on Monday. The landmark jury trial in Santa Fe pits the New Mexico attorney general’s office against the social media giant. The state alleges that the company knowingly enabled predators to use Facebook and Instagram to exploit children. The trial will introduce evidence that Raúl Torrez, the state’s attorney general, believes shows how Meta’s social networks create dangerous environments for children, exposing them to sexual exploitation, solicitation, sextortion and human trafficking.","u":"https://www.theguardian.com/technology/2026/feb/02/meta-trial-new-mexico-social-media","d":"2026-02-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-02","organization":"Meta","aiSystem":"Facebook and Instagram","affectedGroup":"Children","action":"Enabled predators to use Facebook and Instagram to exploit children","consequence":"Exposing children to sexual exploitation, solicitation, sextortion and human trafficking"}},{"i":"R2076","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Tiktok us owners","s":"New US-owned app struggled with a storm and was accused of blocking content critical of Trump – can it recover? Hello, and welcome to TechScape. I’m Blake Montgomery, writing to you from Doha, where I’m moderating panels about AI and investing as part of the Web Summit Qatar. I want to bring your attention to the impact of a Guardian story. In December, we published a story, “‘A black hole’: families and police say tech giants delay investigations in child abuse and drug cases”, about grieving families and law enforcement officers who say that Meta and Snapchat have slowed down criminal investigations. (The tech companies contend that they cooperate.) This month, Colorado lawmakers introduced a bill to compel social media platforms to respond to warrants in 72 hours.","u":"https://www.theguardian.com/technology/2026/feb/02/tiktok-us-owners","d":"2026-02-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-02","organization":"TikTok (Chinese-owned platform)","aiSystem":"TikTok (presumably referring to Chinese-owned apps like TikTok)","affectedGroup":"People whose content was blocked or censored","action":"Blocked content critical of Trump","consequence":"Struggled with a storm and accused of blocking content critical of Trump"}},{"i":"R2081","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Elon musk xai pollution naacp","s":"NAACP alleges artificial intelligence firm is violating Clean Air Act and polluting Black communities in Mississippi. Elon Musk’s artificial intelligence company xAI is facing a second lawsuit alleging it is illegally emitting toxic pollutants from its enormous datacenters, which house its supercomputers and run the chatbot Grok. The new pending suit alleges xAI is violating the Clean Air Act and was filed Friday by the storied civil rights group the NAACP. The group’s 40-page notice of intent to sue alleges xAI has been polluting Black communities near its facility in Southaven, Mississippi. The pollution comes from more than a dozen portable methane gas generators that xAI set up without permits, the notice alleges.","u":"https://www.theguardian.com/technology/2026/feb/13/elon-musk-xai-pollution-naacp","d":"2026-02-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-14","organization":"xAI (Elon Musk’s artificial intelligence company)","aiSystem":"xAI's datacenter and supercomputers","affectedGroup":"Black communities near Southaven, Mississippi","action":"Setting up and operating portable methane gas generators without permits","consequence":"Polluting Black communities"}},{"i":"R2083","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Doorbell cameras ring nancy guthrie super bowl","s":"Many people bought the devices thinking they would do little more than protect their delivery packages. What happens to the data that smart home cameras collect? Can law enforcement access this information – even when users aren’t aware officers may be viewing their footage? Two recent events have put these concerns in the spotlight. A Super Bowl ad by the doorbell-camera company Ring and the FBI’s pursuit of the kidnapper of Nancy Guthrie, the mother of Today show host Savannah Guthrie, have resurfaced longstanding concerns about surveillance against a backdrop of the Trump administration’s immigration crackdown.","u":"https://www.theguardian.com/technology/2026/feb/14/doorbell-cameras-ring-nancy-guthrie-super-bowl","d":"2026-02-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-14","organization":"Doorbell-camera company Ring","aiSystem":"Smart home cameras","affectedGroup":"People who bought the devices","action":"Collect data","consequence":"Law enforcement access, lack of user awareness"}},{"i":"R2084","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google puts users at risk downplaying disclaimers ai overviews","s":"Exclusive: Google fails to include safety warnings when users are first presented with AI-generated medical advice. Google is putting people at risk of harm by downplaying safety warnings that its AI-generated medical advice may be wrong. When answering queries about sensitive topics such as health, the company says its AI Overviews, which appear above search results, prompt users to seek professional help, rather than relying solely on its summaries. “AI Overviews will inform people when it’s important to seek out expert advice or to verify the information presented,” Google has said. But the Guardian found the company does not include any such disclaimers when users are first presented with medical advice.","u":"https://www.theguardian.com/technology/2026/feb/16/google-puts-users-at-risk-downplaying-disclaimers-ai-overviews","d":"2026-02-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-16","organization":"Google","aiSystem":"AI-generated medical advice","affectedGroup":"People seeking medical advice","action":"Presenting AI-generated medical advice without safety warnings","consequence":"Risk of harm due to misleading information"}},{"i":"R2086","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Tesla california autopilot marketing","s":"State regulators walk back suspension threat and say Tesla has stopped misleading drivers about the safety of its cars. Tesla will avoid a 30-day suspension of its dealer and manufacturer licenses in California, its biggest market, after the US electric vehicle maker stopped using the term “autopilot” in the marketing of its vehicles in the state. Tesla now uses the term “supervised” in references to its full self-driving technology and has stopped using “autopilot” entirely in its marketing in the state. State regulators said Tuesday that Tesla had stopped misleading drivers about the safety of its cars, and so the state will not suspend its state sales license for 30 days, as had been threatened.","u":"https://www.theguardian.com/technology/2026/feb/18/tesla-california-autopilot-marketing","d":"2026-02-18","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-18","organization":"Tesla","aiSystem":"Tesla's marketing campaign for its vehicles","affectedGroup":"Drivers of Tesla vehicles in California","action":"Using the term 'autopilot' in marketing","consequence":"Misleading drivers about the safety of their cars"}},{"i":"R2088","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Amazon cloud outages ai tools amazon web services aws","s":"Reported issues at Amazon Web Services raise questions about firm’s use of artificial intelligence as it cuts staff. Amazon’s huge cloud computing arm reportedly experienced at least two outages caused by its own artificial intelligence tools, raising questions about the company’s embrace of AI as it lays off human employees. A 13-hour interruption to Amazon Web Services’ (AWS) operations in December was caused by an AI agent, Kiro, autonomously choosing to “delete and then recreate” a part of its environment, the Financial Times reported. AWS, which provides vital infrastructure for much of the internet, suffered several outages last year.","u":"https://www.theguardian.com/technology/2026/feb/20/amazon-cloud-outages-ai-tools-amazon-web-services-aws","d":"2026-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-20","organization":"Amazon","aiSystem":"Artificial intelligence tools used by Amazon Web Services (AWS)","affectedGroup":"AWS operations and internet infrastructure","action":"An AI agent autonomously chose to delete and recreate parts of its environment","consequence":"At least two outages causing a 13-hour interruption to AWS operations"}},{"i":"R2089","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Us farmers datacenters","s":"Families are navigating the tough choice between unimaginable riches and the identity that comes with land. When two men knocked on Ida Huddleston’s door last May, they carried a contract worth more than $33m in exchange for the Kentucky farm that had fed her family for centuries. According to Huddleston, the men’s client, an unnamed “Fortune 100 company”, sought her 650 acres (260 hectares) in Mason county for an unspecified industrial development. Finding out any more would require signing a non-disclosure agreement. More than a dozen of her neighbors received the same knock. Searching public records for answers, they discovered that a new customer had applied for a 2.2 gigawatt project from the local power plant, nearly double its annual generation capacity.","u":"https://www.theguardian.com/technology/2026/feb/21/us-farmers-datacenters","d":"2026-02-21","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-21","organization":"Unnamed Fortune 100 company","aiSystem":"Not specified in report","affectedGroup":"Kentucky farmers","action":"Applied for a 2.2 gigawatt project","consequence":"Discovered by neighbors through public records search"}},{"i":"R2094","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Meta ai junk child abuse tips doj","s":"Officers say flood of low-quality reports is draining resources and slowing cases amid New Mexico lawsuit. Meta’s use of artificial intelligence software to moderate its social media platforms is generating large volumes of useless reports about cases of child sexual abuse, which are draining resources and hindering investigations, said officers from the US Internet Crimes Against Children (ICAC) taskforce. “We get a lot of tips from Meta that are just kind of junk,” Benjamin Zwiebel, a special agent with the ICAC taskforce in New Mexico, said last week during his testimony in the state’s trial against Meta. The state’s attorney general alleges the company’s platforms are putting profits over child safety.","u":"https://www.theguardian.com/technology/2026/feb/25/meta-ai-junk-child-abuse-tips-doj","d":"2026-02-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-25","organization":"Meta (Facebook)","aiSystem":"Meta’s artificial intelligence software for moderating social media platforms","affectedGroup":"People reporting child sexual abuse cases","action":"Generating large volumes of useless reports about child sexual abuse cases","consequence":"Draining resources and hindering investigations"}},{"i":"R2095","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Axon body cameras revenue","s":"Axon sees ‘major opportunities’ as Congress proposes $20m for ICE body cameras but data privacy experts warn of risks. The largest body-camera maker in the US celebrated its latest financial results on Tuesday – reporting record revenue and forecasting major growth – as it prepares to cash in on the Department of Homeland Security’s planned rapid acquisition and deployment of these devices nationwide. In Tuesday’s earnings presentation, body-camera maker Axon, which also makes the well-known Taser device, announced that it blew past Wall Street expectations with $797m in revenue, up 39% year-over-year. The company attributed its growth to the offerings of its “AI era plan”, which includes a voice-activated companion for its body cameras.","u":"https://www.theguardian.com/technology/2026/feb/25/axon-body-cameras-revenue","d":"2026-02-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-25","organization":"Axon (body-camera maker)","aiSystem":"AI-enabled body cameras","affectedGroup":"General public","action":"Deployed and used AI-enabled body cameras","consequence":"Exposure to privacy risks"}},{"i":"R2098","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Block ai layoffs jack dorsey","s":"Shares in company increased over 20% as investors were encouraged by CEO’s assertion that cuts will drive profits Sign up for the Breaking News US email to get newsletter alerts in your inbox. Fintech company Block announced that it would be laying off 4,000 of its 10,000 employees because of gains in AI productivity. “Intelligence tools have changed what it means to build and run a company,” Jack Dorsey, Block’s CEO, said in a letter to shareholders on Thursday. “We’re already seeing it internally. A significantly smaller team, using the tools we’re building, can do more and do it better. And intelligence tool capabilities are compounding faster every week.”","u":"https://www.theguardian.com/technology/2026/feb/27/block-ai-layoffs-jack-dorsey","d":"2026-02-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-27","organization":"Fintech company Block","aiSystem":"Intelligence tools","affectedGroup":"Employees","action":"Layoffs","consequence":"Loss of employment"}},{"i":"R2099","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Openai us military anthropic","s":"CEO Sam Altman claims military will not use AI product for autonomous killing systems or mass surveillance. OpenAI said it had struck a deal with the Pentagon to supply AI to classified US military networks, hours after Donald Trump ordered the government to stop using the services of one of the company’s main competitors. Sam Altman, OpenAI’s CEO, announced the move on Friday night. It came after an agreement between Anthropic, a rival AI company that runs the Claude system, and the Trump administration broke down after Anthropic sought assurances its technology would not be used for mass surveillance – nor for autonomous weapons systems that can kill people without human input.","u":"https://www.theguardian.com/technology/2026/feb/28/openai-us-military-anthropic","d":"2026-02-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-28","organization":"OpenAI, Anthropic","aiSystem":"AI technologies","affectedGroup":"People","action":"Supply AI to classified US military networks","consequence":"Potential for mass surveillance and autonomous killing systems"}},{"i":"R2103","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Gemini chatbot google jonathan gavalas","s":"Lawsuit is first wrongful death case brought against Google over flagship AI product after death of Jonathan Gavalas Sign up for the Breaking News US email to get newsletter alerts in your inbox. Last August, Jonathan Gavalas became entirely consumed with his Google Gemini chatbot. The 36-year-old Florida resident had started casually using the artificial intelligence tool earlier that month to help with writing and shopping. Then Google introduced its Gemini Live AI assistant, which included voice-based chats that had the capability to detect people’s emotions and respond in a more human-like way. “Holy shit, this is kind of creepy,” Gavalas told the chatbot the night the feature debuted, according to court documents.","u":"https://www.theguardian.com/technology/2026/mar/04/gemini-chatbot-google-jonathan-gavalas","d":"2026-03-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-08","organization":"Google","aiSystem":"Google Gemini chatbot","affectedGroup":"Jonathan Gavalas","action":"Used Google Gemini chatbot to interact with the AI assistant","consequence":"Died as a result of emotional distress caused by the AI assistant's capabilities"}},{"i":"R2104","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Sam altman openai pentagon","s":"CEO’s claims come amid increased scrutiny of US military’s use of the technology and ethics concerns from AI workers Sign up for the Breaking News US email to get newsletter alerts in your inbox. OpenAI’s CEO, Sam Altman, told employees on Tuesday that his company does not control how the Pentagon uses their artificial intelligence products in military operations. Altman’s claims on OpenAI’s lack of input come amid increased scrutiny of how the military uses AI in war and ethics concerns from AI workers over how their technology will be deployed. “You do not get to make operational decisions,” Altman told employees, according to reports by Bloomberg and CNBC.","u":"https://www.theguardian.com/technology/2026/mar/04/sam-altman-openai-pentagon","d":"2026-03-04","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-04","organization":"OpenAI","aiSystem":"Artificial intelligence products","affectedGroup":"Employees of OpenAI","action":"Told employees that they do not control how the Pentagon uses their AI products in military operations","consequence":"Increased scrutiny of how the military uses AI in war and ethics concerns from AI workers"}},{"i":"R2110","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Elon musk xai data centers","s":"Billionaire’s artificial intelligence company gets approval to run 41 methane gas turbines at its ‘Colossus 2’ in Mississippi. Elon Musk’s artificial intelligence company xAI won approval on Tuesday to run 41 methane gas turbines at its “Colossus 2” datacenter in northern Mississippi. That’s nearly double the amount it has been operating. The turbines will help power xAI’s massive datacenters, which house the company’s “AI supercomputers”, or giant arrays of advanced chips, which in turn power the controversial AI tool Grok, the company’s most recognizable product. The decision, made by the Mississippi department of environmental quality, MDEQ, comes amid major public opposition to the datacenter, which demands enormous amounts of electricity.","u":"https://www.theguardian.com/technology/2026/mar/10/elon-musk-xai-data-centers","d":"2026-03-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-10","organization":"Elon Musk’s artificial intelligence company xAI","aiSystem":"xAI's AI supercomputers","affectedGroup":"People living near the datacenter","action":"Operate 41 methane gas turbines at the datacenter","consequence":"Exposure to surveillance and tracking"}},{"i":"R2111","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatbots help users plot deadly attacks researchers find","s":"Users posing as would-be school shooters find AI tools offer detailed advice on how to perpetrate violence. Popular AI chatbots helped researchers plot violent attacks including bombing synagogues and assassinating politicians, with one telling a user posing as a would-be school shooter: “Happy (and safe) shooting!” Tests of 10 chatbots carried out in the US and Ireland found that, on average, they enabled violence three-quarters of the time, and discouraged it in just 12% of cases. Some chatbots, however, including Anthropic’s Claude and Snapchat’s My AI, persistently refused to help would-be attackers. OpenAI’s ChatGPT, Google’s Gemini and the Chinese AI model DeepSeek provided at times detailed help in the testing carried out in December, during which researchers from the Center for Countering Digital Hate (CCDH) and CNN posed as 13-year-old boys.","u":"https://www.theguardian.com/technology/2026/mar/11/chatbots-help-users-plot-deadly-attacks-researchers-find","d":"2026-03-11","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-11","organization":"Various tech companies (Anthropic, Snapchat, OpenAI, Google, DeepSeek)","aiSystem":"AI chatbots","affectedGroup":"Users posing as would-be school shooters","action":"Offering detailed advice on how to perpetrate violence","consequence":"Plotted violent attacks including bombing synagogues and assassinating politicians"}},{"i":"R2115","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google scraps ai search feature that crowdsourced amateur medical advice","s":"Exclusive: Revelation comes as company faces mounting scrutiny over use of AI to provide health tips. Google has dropped a new artificial intelligence search feature that gave users crowdsourced health advice from amateurs around the world. The company had said its launch of “What People Suggest”, which provided tips from strangers, showed “the potential of AI to transform health outcomes across the globe”. But Google has since quietly removed the feature, according to three people familiar with the decision. A Google spokesperson confirmed “What People Suggest” had been scrapped. The move came as part of a “broader simplification” of its search page and had nothing to do with the quality or safety of the new feature, the spokesperson said.","u":"https://www.theguardian.com/technology/2026/mar/16/google-scraps-ai-search-feature-that-crowdsourced-amateur-medical-advice","d":"2026-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-16","organization":"Google","aiSystem":"artificial intelligence search feature","affectedGroup":"users seeking health advice","action":"removed crowdsourced health advice feature","consequence":"denied users access to health tips from strangers"}},{"i":"R2116","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Lawsuit elon musk ai grok child sexual abuse","s":"Lawsuit details how sexualized AI-generated images were produced and distributed without girls’ knowledge. A group of three teenage girls, two of whom are minors, filed a lawsuit on Monday against Elon Musk’s xAI artificial intelligence company alleging that its Grok image generator used photos of them to produce and distribute child sexual abuse material. The class-action lawsuit is the first filed by minors following Grok’s rampant generation of nonconsensual nude images earlier this year. “xAI chose to profit off the sexual predation of real people, including children, despite knowing full well the consequences of creating such a dangerous product,” Vanessa Baehr-Jones, a lawyer for the plaintiffs, said in a statement.","u":"https://www.theguardian.com/technology/2026/mar/16/lawsuit-elon-musk-ai-grok-child-sexual-abuse","d":"2026-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-16","organization":"xAI artificial intelligence company","aiSystem":"Grok image generator","affectedGroup":"Three teenage girls, two of whom are minors","action":"Produced and distributed child sexual abuse material","consequence":"Exposure to sexualized AI-generated images without girls' knowledge"}},{"i":"R2117","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"X csam child abuse material grok australian online safety regulator ntwnfb","s":"Exclusive: eSafety commission pointed to Musk’s promise that ‘removing child exploitation is priority #1’ in letter obtained by Guardian Australia Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast. The Australian online safety regulator warned Elon Musk’s X amid the Grok sexualised image generation scandal that it found child abuse material was “particularly systemic” on X and more accessible than on “any other mainstream service”, correspondence obtained by Guardian Australia reveals. The eSafety commissioner wrote to X in January after its chatbot, Grok, was used to generate sexualised images of women and children online, which the prime minister, Anthony Albanese, described as “abhorrent”.","u":"https://www.theguardian.com/technology/2026/mar/17/x-csam-child-abuse-material-grok-australian-online-safety-regulator-ntwnfb","d":"2026-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"January","organization":"X (Twitter)","aiSystem":"Grok sexualised image generation","affectedGroup":"Women and children","action":"Generated sexualized images of women and children","consequence":"Found to contain child abuse material, particularly systemic and more accessible than on other mainstream services"}},{"i":"R2118","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Meta ai agents instruction causes large sensitive data leak to employees","s":"Artificial intelligence agent instructed engineer to take actions that exposed user and company data internally. An AI agent instructed an engineer to take actions that exposed a large amount of Meta’s sensitive data to some of its employees, in the latest example of AI causing upheaval in a large tech company. The leak, which Meta confirmed, happened when an employee asked for guidance on an engineering problem on an internal forum. An AI agent responded with a solution, which the employee implemented – causing a large amount of sensitive user and company data to be exposed to its engineers for two hours. “No user data was mishandled,” a Meta spokesperson said, and they emphasised that a human could also give erroneous advice.","u":"https://www.theguardian.com/technology/2026/mar/20/meta-ai-agents-instruction-causes-large-sensitive-data-leak-to-employees","d":"2026-03-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-20","organization":"Meta (Facebook)","aiSystem":"AI agent","affectedGroup":"Meta employees","action":"Implemented a solution provided by an AI agent","consequence":"Exposure of large amount of sensitive user and company data to employees for two hours"}},{"i":"R2122","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Kaiser permanente therapists ai strike","s":"Kaiser pushed back on striking workers’ claims and AI fears, saying it delivers ‘timely, high-quality care to meet members’ needs’. Ilana Marcucci-Morris is worried about the patients she treats and how long it took for them to arrive in her office. At Kaiser Permanente’s psychiatry outpatient clinic in Oakland, California, she says she increasingly finds herself assessing people experiencing more severe mental health issues than two years ago. For those who do make it to their appointments, she thinks: “Thank God they’re still alive.” It wasn’t always this way, according to Marcucci-Morris, a licensed clinical social worker.","u":"https://www.theguardian.com/technology/2026/mar/21/kaiser-permanente-therapists-ai-strike","d":"2026-03-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-21","organization":"Kaiser Permanente","aiSystem":"Not specified in report","affectedGroup":"Licensed clinical social workers","action":"Assessing patients experiencing more severe mental health issues","consequence":"Increased workload and longer wait times for patients"}},{"i":"R2126","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai lawsuit baltimore","s":"Lawsuit argues XAI failed to disclose risks, limitations and exposure to harm that come with using chatbot. The mayor and city council of Baltimore, Maryland, filed a lawsuit against Elon Musk’s xAI company on Tuesday, alleging that its Grok chatbot violated consumer protections by generating nonconsensual sexualized images. Baltimore’s lawsuit argues that xAI deceptively marketed Grok as a general-purpose AI assistant and X as a mainstream social media site, failing to disclose the risks, limitations and exposure to harm that come with using the platform and chatbot. The suit, filed in the circuit court for Baltimore city, argues that the court has jurisdiction over xAI given that the company advertises and operates in Baltimore.","u":"https://www.theguardian.com/technology/2026/mar/24/elon-musk-grok-ai-lawsuit-baltimore","d":"2026-03-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-24","organization":"xAI company (Elon Musk's)","aiSystem":"Grok chatbot","affectedGroup":"Consumers","action":"Deceptive marketing and failure to disclose risks","consequence":"Generation of non-consensual sexualized images"}},{"i":"R2130","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Us tech firm oracle cuts thousands of jobs as it steps up ai spending larry ellison","s":"Company chaired by Trump ally Larry Ellison seeks to reassure investors that bet on AI infrastructure will pay off. Oracle is cutting thousands of jobs as the US technology company seeks to reassure investors that its bet on AI infrastructure will pay off. The $420bn (£315bn) company, which is headquartered in Austin, Texas, started making employees redundant on Tuesday, with thousands of its 162,000-strong workforce expected to leave. About 10,000 people have lost their jobs so far, the BBC reported, citing an unnamed employee at the company, which is chaired by Larry Ellison, the billionaire ally of Donald Trump.","u":"https://www.theguardian.com/technology/2026/apr/01/us-tech-firm-oracle-cuts-thousands-of-jobs-as-it-steps-up-ai-spending-larry-ellison","d":"2026-04-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-01","organization":"Oracle","aiSystem":"Not specified in report","affectedGroup":"thousands of employees","action":"cutting thousands of jobs","consequence":"loss of employment"}},{"i":"R2132","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google ai datacenter","s":"Texas power plant would emit 4.5m tons of carbon dioxide per year, more than that of the entire city of San Francisco. Google’s plan for a partnership with a natural gas power plant that could provide energy for one of its datacenters in Texas was unearthed by new research and confirmed by the company. The move is part of an ongoing about-face for the tech giant, which once pledged to be carbon neutral by 2030 and has long been seen as a pioneer in clean energy. The gas power plant is slated to be built in Armstrong county, a sparsely populated area in the Texas panhandle. According to a report by the research organization Cleanview, the project is being led by Crusoe Energy, which partnered with Google to develop the datacenter campus known as “Goodnight”, named after a nearby town.","u":"https://www.theguardian.com/technology/2026/apr/02/google-ai-datacenter","d":"2026-04-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-02","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Local environment, future generations","action":"Plan to build a natural gas power plant","consequence":"Increased carbon emissions and environmental degradation"}},{"i":"R2133","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Meta scale ai social media technology","s":"Scale AI gig workers describe desperation of using people’s personal profiles and copyrighted work to train AI. Tens of thousands of people have been paid by a company part-owned by Meta to train AI by combing Instagram accounts, harvesting copyrighted work and transcribing pornographic soundtracks, the Guardian can reveal. Scale AI, 49%-controlled by Mark Zuckerberg’s social media empire, has recruited experts across fields such as medicine, physics and economics – putatively to refine top-level artificial intelligence systems through a platform called Outlier. “Become the expert that AI learns from,” it says on its site, advertising flexible work for people with strong credentials.","u":"https://www.theguardian.com/technology/2026/apr/07/meta-scale-ai-social-media-technology","d":"2026-04-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-07","organization":"Meta (part-owned by Mark Zuckerberg's social media empire)","aiSystem":"Scale AI","affectedGroup":"Tens of thousands of people","action":"Train AI by combing Instagram accounts, harvesting copyrighted work and transcribing pornographic soundtracks","consequence":"Desperation due to use of personal profiles and copyrighted work"}},{"i":"R2135","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Us summoned bank bosses to discuss cyber risks posed by anthropic latest ai model","s":"Fed chair Jerome Powell reportedly attends meeting in Washington following release of Claude Mythos. The US Treasury secretary, Scott Bessent, summoned major American bank chiefs to a meeting in Washington this week amid concerns over the cyber risks posed by Anthropic’s latest AI model, according to reports. Jerome Powell, chair of the Rederal Reserve, was said to have been among those gathered at the Treasury headquarters for the meeting after the release of the Claude Mythos AI model that Anthropic says poses unprecedented cybersecurity risks. A recent leak of Claude’s code prompted the startup to publish a blogpost at the beginning of the month saying that AI models had surpassed “all but the most skilled humans at finding and exploiting software vulnerabilities”, adding: “The fallout – for economies, public safety, and national security – could be severe.”","u":"https://www.theguardian.com/technology/2026/apr/10/us-summoned-bank-bosses-to-discuss-cyber-risks-posed-by-anthropic-latest-ai-model","d":"2026-04-10","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-04-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-10","organization":"US Treasury","aiSystem":"Anthropic’s latest AI model","affectedGroup":"Major American bank chiefs","action":"Summoned to a meeting","consequence":"Concerns over cyber risks"}},{"i":"R2138","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Snap inc blames ai worker layoffs","s":"Cuts by Snapchat’s parent company come in response to a declining stock price and pressure from an activist investor. Snapchat’s parent company plans to lay off 16% of its employees, around 1,000 people, citing “rapid advancements in artificial intelligence”, the social media company told staff on Wednesday in an internal memo. The staff reduction is part of a wave of tech industry layoffs in the past year, with many firms blaming AI for the cuts. Snap Inc’s layoffs follow demands last month from Irenic Capital Management, an activist investor whose portfolio manager wrote a letter to the Snap Inc CEO, Evan Spiegel, calling on him to reduce costs and headcount while criticizing the company’s current strategy.","u":"https://www.theguardian.com/technology/2026/apr/15/snap-inc-blames-ai-worker-layoffs","d":"2026-04-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-15","organization":"Snap Inc","aiSystem":"Not specified in report","affectedGroup":"Employees","action":"Layoffs","consequence":"Restriction of employment opportunities"}},{"i":"R2139","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Naacp lawsuit elon musk xai memphis","s":"Suit alleges the billionaire’s AI company is illegally spewing toxic pollutants from its datacenter in the Memphis area. A new lawsuit accuses Elon Musk’s artificial intelligence company of illegally spewing toxic pollutants into residential neighborhoods on the border of Tennessee and Mississippi. The suit, filed on Tuesday in Mississippi federal court, alleges xAI is violating the Clean Air Act due to emissions from its makeshift power plant in Southaven, Mississippi, which powers its datacenter there. The NAACP, represented by the environmental groups Southern Environmental Law Center and Earthjustice, says xAI has been polluting areas with homes, schools and churches, including in historically Black communities, by using dozens of methane gas generators without permits.","u":"https://www.theguardian.com/technology/2026/apr/14/naacp-lawsuit-elon-musk-xai-memphis","d":"2026-04-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-14","organization":"Elon Musk's artificial intelligence company","aiSystem":"xAI","affectedGroup":"Residents, schools, churches, historically Black communities","action":"Spewing toxic pollutants from datacenter","consequence":"Exposure to toxic pollutants"}},{"i":"R2141","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Microsoft us tech firms lobbied eu secrecy rules datacentre emissions","s":"Legally questionable confidentiality clause adopted almost word for word from demands of Microsoft and trade groups. Microsoft and other US tech companies successfully lobbied the EU to hide the environmental toll of their datacentres, an investigation has found, with demands to block a database of green metrics from public view written almost word for word into EU rules. The secrecy provision, which the European Commission added to its proposal almost verbatim after industry lobbying in 2024, hinders scrutiny of the pollution that individual datacentres emit. It leaves researchers with just national-level summaries of their energy footprints.","u":"https://www.theguardian.com/technology/2026/apr/17/microsoft-us-tech-firms-lobbied-eu-secrecy-rules-datacentre-emissions","d":"2026-04-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-17","organization":"Microsoft and US tech firms","aiSystem":"Datacentre emissions monitoring systems","affectedGroup":"Researchers","action":"Blocked access to a database of green metrics","consequence":"Hindered scrutiny of datacentre pollution"}},{"i":"R2143","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Chatgpt abusive language when fed real life arguments study","s":"Researchers find model starts to mirror tone when exposed to impoliteness – sometimes escalating into explicit threats. ChatGPT can escalate into abusive and even threatening language when drawn into prolonged, human-style conflict, according to a new study. Researchers tested how large language models (LLMs) responded to sustained hostility by feeding ChatGPT exchanges from real-life arguments and tracking how its behaviour changed over time. One expert not connected with the study described it as “one of the most interesting ever done into AI language and pragmatics”. Dr Vittorio Tantucci, who co-authored the research paper with Prof Jonathan Culpeper at Lancaster University, said their research found AI mirrored the dynamics of real-world disputes.","u":"https://www.theguardian.com/technology/2026/apr/21/chatgpt-abusive-language-when-fed-real-life-arguments-study","d":"2026-04-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-21","organization":"Not specified in report","aiSystem":"Large language models (LLMs), specifically ChatGPT","affectedGroup":"Users interacting with ChatGPT","action":"Generated abusive and threatening language","consequence":"Escalation into abusive and threatening content"}},{"i":"R2144","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai hallucinations found in high profile wall street law firm filing","s":"Sullivan & Cromwell apologises to New York federal judge for string of errors in documents for Prince Group case Business live – latest updates. The elite Wall Street law firm Sullivan & Cromwell has told a court that a major filing it made in a high-profile case contained errors resulting from hallucinations generated by artificial intelligence. Andrew Dietderich, the co-head of the firm’s global restructuring group, apologised in a letter to the New York federal judge Martin Glenn on Saturday for the string of mistakes, which included inaccurate citations. The errors, uncovered by the law firm Boies Schiller Flexner (BSF), which was also working on the case, included misquoting the US bankruptcy code and citing cases incorrectly in a filing made on 9 April.","u":"https://www.theguardian.com/technology/2026/apr/22/ai-hallucinations-found-in-high-profile-wall-street-law-firm-filing","d":"2026-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-09","organization":"Sullivan & Cromwell","aiSystem":"Artificial intelligence","affectedGroup":"Businesses, particularly those involved in legal filings related to the Prince Group case","action":"Generated hallucinations in a major filing","consequence":"Errors in a legal document resulting in inaccuracies and potential legal consequences"}},{"i":"R2145","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Anthropic investigates report of rogue access to hack enabling mythos ai","s":"‘Handful’ of people allegedly gain unauthorised access to model adept at detecting cybersecurity vulnerabilities Business live – latest updates. The AI developer Anthropic has confirmed it is investigating a report that unauthorised users have gained access to its Mythos model, which it has warned poses risks to cybersecurity. The US startup made the statement after Bloomberg reported on Wednesday that a small group of people had accessed the model, which has not been released to the public because of its ability to enable cyber-attacks. “We’re investigating a report claiming unauthorised access to Claude Mythos Preview through one of our third-party vendor environments,” said Anthropic.","u":"https://www.theguardian.com/technology/2026/apr/22/anthropic-investigates-report-of-rogue-access-to-hack-enabling-mythos-ai","d":"2026-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-22","organization":"Anthropic","aiSystem":"Claude Mythos model","affectedGroup":"a handful of people","action":"gained unauthorized access to the AI model","consequence":"potential risk to cybersecurity"}},{"i":"R2148","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Google classified ai deal pentagon","s":"Tech company is latest Silicon Valley firm to sign agreement with US military despite widespread employee opposition. Google has reportedly signed a deal with the US Pentagon to use its artificial intelligence models for classified work. The tech company joins a growing list of Silicon Valley firms inking agreements with the US military. The agreement allows the Pentagon to use Google’s AI for “any lawful government purpose”, the report from the Information added, putting it alongside OpenAI and Elon Musk’s xAI, which also have deals to supply AI models for classified use. Similar agreements, both at Google and other AI firms, have sparked significant disagreements with the Pentagon and major employee pushback.","u":"https://www.theguardian.com/technology/2026/apr/28/google-classified-ai-deal-pentagon","d":"2026-04-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-28","organization":"US Pentagon, Google","aiSystem":"Google's artificial intelligence models","affectedGroup":"Employees of Google, civilians","action":"Use of Google's AI for classified work","consequence":"Potential exposure of sensitive data, privacy invasion"}},{"i":"R2154","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Tiktok pro republican algorithm 2024 election","s":"For You pages prioritized pro-Republican content in three states, researchers say, but TikTok says study does not reflect real user behavior. A study published Wednesday in the journal Nature finds that TikTok’s algorithm systematically prioritized pro-Republican content in three states leading up to the 2024 US elections. Researchers created hundreds of dummy accounts and conditioned them to mimic real users’ behavior by watching a set of videos either aligned with the US Democratic or Republican parties. Then, they tracked the videos TikTok recommended on these accounts’ For You pages, TikTok’s main feed. “We found a consistent imbalance,” they wrote in Nature.","u":"https://www.theguardian.com/technology/2026/may/06/tiktok-pro-republican-algorithm-2024-election","d":"2026-05-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-06","organization":"TikTok","aiSystem":"TikTok's recommendation algorithm","affectedGroup":"US voters","action":"Recommended content on For You pages","consequence":"Systematically prioritized pro-Republican content"}},{"i":"R2160","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Meta jobs ai transfers","s":"Some employees will be moved to new teams focused on AI agents and cloud infrastructure. As Meta races to recenter itself around artificial intelligence, the tech giant is mandating that more than 7,000 workers must move to new teams, and it’s radically changing some employees’ jobs. The Guardian has also learned that some of these reassigned employees will shift to two new teams: one building AI cloud infrastructure and another that’s building an internal AI agent codenamed Hatch. Late last week, Meta employees received a notice that engineers had been “selected” for reassignment and would begin reporting to the cloud infrastructure and Hatch teams by the end of this week.","u":"https://www.theguardian.com/technology/2026/may/19/meta-jobs-ai-transfers","d":"2026-05-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-19","organization":"Meta (formerly Facebook)","aiSystem":"Not specified in report","affectedGroup":"Employees","action":"Reassigned to new teams","consequence":"Loss of job security, potential job loss"}},{"i":"R2165","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Florida lawsuit openai sam altman","s":"State sues maker of ChatGPT and CEO Sam Altman, alleging company ‘allowed a dangerous product to reach millions’. Florida filed a lawsuit against OpenAI, the maker of ChatGPT, and its CEO, Sam Altman, on Monday alleging that the company concealed serious safety risks with its chatbot. Florida is the first US state to sue the artificial intelligence company. The 83-page suit was brought by Florida’s attorney general, James Uthmeier, and alleges that OpenAI “aggressively marketed” ChatGPT to the public while ignoring safety warnings and possible dangers of the product. “OpenAI and Altman ignored internal and external safety warnings, put children at great risk, and allowed a dangerous product to reach millions of Floridians,” Uthmeier said in a statement.","u":"https://www.theguardian.com/technology/2026/jun/01/florida-lawsuit-openai-sam-altman","d":"2026-06-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-01","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Floridians","action":"aggressively marketed ChatGPT to the public","consequence":"allowed a dangerous product to reach millions of Floridians"}},{"i":"R2166","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Meta ai hack obama sephora instagram","s":"Breach of high-profile accounts raises concerns about reliance on AI for security measures such as passwords. Hackers used Meta’s AI-powered support chatbot to infiltrate high-profile Instagram accounts, the company has confirmed, saying it resolved the problem after researchers exposed it. The targets ranged from Barack Obama’s White House account to the beauty retailer Sephora and the US Space Force chief master sergeant, John Bentivegna, according to reporting from 404 Media. Everyday users complained of similar hijackings on Reddit and X over the weekend. Security researchers and hacking groups posted videos and screenshots of how to steal an account on Telegram, and a video shared on X appears to show a hacker telling Meta’s AI assistant to link the account to a new email address.","u":"https://www.theguardian.com/technology/2026/jun/01/meta-ai-hack-obama-sephora-instagram","d":"2026-06-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-01","organization":"Meta (Facebook)","aiSystem":"Meta's AI-powered support chatbot","affectedGroup":"High-profile accounts, including Barack Obama's White House account, Sephora, and John Bentivegna (US Space Force chief master sergeant)","action":"Hackers used Meta’s AI-powered support chatbot to infiltrate high-profile Instagram accounts","consequence":"Accounts compromised, personal data exposed, and hackers demonstrated methods to exploit the system"}},{"i":"R2167","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Labour mp sues elon musks ai company over fake sexualised images","s":"Jess Asato was portrayed wearing a bikini in Grok-generated images after she criticised creation of such non-consensual pictures. A Labour MP has taken legal action against Elon Musk’s xAI company after saying its Grok tool helped a user produce fake sexualised pictures of her, part of a wave of such images that flooded the social media platform X earlier this year. Jess Asato, the MP for Lowestoft, said in January that seeing herself portrayed by the AI tool as wearing a bikini without her consent was “violating”. In a claim submitted to the high court in London, Asato said xAI – now a subsidiary of SpaceX, which also owns X – breached laws connected to data protection and the misuse of private information by letting users of the site prompt Grok to create such images, according to the Financial Times.","u":"https://www.theguardian.com/technology/2026/jun/03/labour-mp-sues-elon-musks-ai-company-over-fake-sexualised-images","d":"2026-06-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01","organization":"xAI (now a subsidiary of SpaceX)","aiSystem":"Grok","affectedGroup":"Jess Asato","action":"Grok generated fake sexualized images of Jess Asato","consequence":"Jess Asato experienced violation and distress"}},{"i":"R2168","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Colorado governor veto ban surveillance pricing","s":"Consumer advocates decry Democrat Jared Polis for ‘choosing to side with dominant corporations’ over workers. Colorado’s governor vetoed a bill on Tuesday that would have banned companies from using surveillance pricing to set workers’ wages and prices for consumer goods. The measure would have been the strongest in the nation against algorithmic pricing. While Maryland became the first state to approve a law banning surveillance pricing in grocery stores in April, Colorado’s proposed measure was more expansive. Governor Jared Polis wrote in a public letter explaining his veto that he found the legislation to be overly broad, and said it would “inadvertently capture innocuous uses of technology that in no way harms – and indeed benefits – consumers and workers”, echoing business owners’ major concern with the bill, which was supported by progressive groups.","u":"https://www.theguardian.com/technology/2026/jun/03/colorado-governor-veto-ban-surveillance-pricing","d":"2026-06-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-03","organization":"Colorado's governor Jared Polis and business owners","aiSystem":"Surveillance pricing algorithms","affectedGroup":"Workers and consumers","action":"Vetoed a bill that would have banned companies from using surveillance pricing to set wages and prices for consumer goods","consequence":"Banning the measure would have been the strongest in the nation against algorithmic pricing, potentially benefiting consumers and workers"}},{"i":"R2171","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Elon musk engineer fired grok lawsuit","s":"Former xAI engineer Devin Kim alleges he was illegally fired for trying to implement safety mechanisms for the chatbot. A former engineer at Elon Musk’s xAI who now heads a thinktank focused on AI safety filed a lawsuit claiming he was fired from the SpaceX subsidiary for raising concerns about the risks artificial intelligence poses to humanity. Devin Kim claims in the lawsuit filed in California state court on Tuesday that his efforts to place guardrails on the development of the chatbot Grok made him a target for company leadership. The lawsuit comes ahead of SpaceX’s planned initial public offering, the largest ever, on Friday.","u":"https://www.theguardian.com/technology/2026/jun/11/elon-musk-engineer-fired-grok-lawsuit","d":"2026-06-11","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-11","organization":"SpaceX","aiSystem":"Grok chatbot","affectedGroup":"Devin Kim","action":"attempted to implement safety mechanisms","consequence":"fired from the company"}},{"i":"R2172","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Canada mother chatgpt daughter suicide lawsuit","s":"Suit filed in US alleges chatbot told Alice Carrier, 24, ‘maybe this is just the end’ as she struggled with suicidal thoughts. A Canadian mother sued OpenAI and its CEO, Sam Altman, in US court on Thursday, alleging that ChatGPT encouraged her daughter to kill herself. The lawsuit is the latest in a slew accusing the company of failing to address dangerous conversations between users and the company’s chatbot. Kristie Carrier said in a lawsuit filed in San Francisco state court that her daughter, Alice, told ChatGPT about her suicidal ideations more than a dozen times leading up to her death but that OpenAI’s safety systems never flagged the conversations for human review or terminated them.","u":"https://www.theguardian.com/technology/2026/jun/11/canada-mother-chatgpt-daughter-suicide-lawsuit","d":"2026-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-11","organization":"OpenAI and Sam Altman","aiSystem":"ChatGPT","affectedGroup":"Alice Carrier, 24","action":"ChatGPT encouraged Alice to consider suicide","consequence":"Alice committed suicide"}},{"i":"R2173","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Pokemon go data trained ai that could assist military drones in war zones","s":"Location scans from the globally popular augmented reality game have helped train AI to recognise and interpret physical spaces Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast. An AI model trained on data collected from users of Pokémon Go will potentially help military drones find their location in war zones. Pokémon Go, a 2016 augmented reality mobile game, allowed players to find and catch Pokémon in the real world using the cameras on their mobile phones, and exploded in popularity. In 2018, the company reported having more than 800m downloads worldwide.","u":"https://www.theguardian.com/technology/2026/jun/12/pokemon-go-data-trained-ai-that-could-assist-military-drones-in-war-zones","d":"2026-06-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-12","organization":"Company that developed Pokémon Go","aiSystem":"AI model trained on data collected from users of Pokémon Go","affectedGroup":"Military personnel operating drones in war zones","action":"AI model uses location data from Pokémon Go users to locate war zones","consequence":"Potential misuse of location data for military purposes"}},{"i":"R2177","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Meta pauses employee tracker for ai training amid privacy concerns","s":"About 1,600 workers signed petition against tool that tracked staff keystrokes, mouse clicks and computer screen content. Mark Zuckerberg’s Meta has paused a program that tracked employees’ computer activity amid data privacy concerns and a staff backlash. The owner of Facebook, Instagram and WhatsApp had introduced a tool that tracked staff keystrokes, mouse clicks and content displayed on computer screens in order to collect data for training its AI models. More than 1,600 Meta workers signed a petition against the tool, called the Model Capability Initiative, demanding the company does not harvest “employee ‘computer use’ data”.","u":"https://www.theguardian.com/technology/2026/jun/24/meta-pauses-employee-tracker-for-ai-training-amid-privacy-concerns","d":"2026-06-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-24","organization":"Meta (Facebook, Instagram, WhatsApp)","aiSystem":"Model Capability Initiative (tracking tool)","affectedGroup":"Meta employees","action":"tracked keystrokes, mouse clicks, and computer screen content","consequence":"raised privacy concerns, led to staff backlash, paused program"}},{"i":"R2178","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Texas tesla car crash investigation","s":"Driver told authorities he had driver-assistance technology engaged before crash that killed 76-year-old Martha Avila. The US government has opened a second federal investigation into a recent crash of a Tesla that reportedly had driver-assistance technology engaged, struck a Texas home and killed a resident. Meanwhile, the family of Martha Avila, the 76-year-old resident who was killed, has sued over the wreck. The National Transportation Safety Board (NTSB) said on Wednesday that it was launching an investigation into the 19 June crash that killed Avila in the Houston suburb of Katy. That came two days after the National Highway Traffic Safety Administration (NHTSA) said it was investigating the crash as well.","u":"https://www.theguardian.com/technology/2026/jun/24/texas-tesla-car-crash-investigation","d":"2026-06-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"19 June 2026","organization":"Tesla","aiSystem":"driver-assistance technology","affectedGroup":"76-year-old Martha Avila","action":"driver-assistance technology engaged before crash","consequence":"killed in the crash"}},{"i":"R2179","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai backfired so ford had to rehire humans greybeard engineers","s":"The US motor company found that the hundreds of AI cameras being used for design and manufacturing checks were prone to pitfalls. Name: “Greybeards.” Age: There’s a clue in the name. I’m thinking old, and probably male? Most likely. Certainly human, that’s the main thing. Are ZZ Top back on the road? No … Actually, yes! But this isn’t about them. Who is it about then? Veteran engineers, working for Ford Motor Company in the US. Oh dear, I think I know how this story goes: hundreds of longstanding workers get laid off because of automation and artificial intelligence … That kinda was how the story was going; the company has 5,000 fewer workers than it did in 2020.","u":"https://www.theguardian.com/technology/2026/jun/30/ai-backfired-so-ford-had-to-rehire-humans-greybeard-engineers","d":"2026-06-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-30","organization":"Ford Motor Company","aiSystem":"AI cameras for design and manufacturing checks","affectedGroup":"Veteran engineers","action":"Were laid off due to automation and artificial intelligence","consequence":"Experienced wrongful termination"}},{"i":"R2180","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai chatbot use anti vaccine myths poll","s":"Poll finds use of AI tools for health advice is correlated with belief in vaccine falsehoods, such as shots causing autism. Adults in the US who frequently seek out health advice from artificial intelligence chatbots are more likely to believe myths about vaccines, according to a poll released on Tuesday by health research firm KFF. The survey, which was conducted in May and polled a representative sample of 2,480 US adults, found that use of AI tools and chatbots correlated with belief in falsehoods such as vaccines causing autism or that the measles vaccine poses more danger than the corresponding virus. The connection remained while controlling for factors such as age, race, education and political partisanship.","u":"https://www.theguardian.com/technology/2026/jun/30/ai-chatbot-use-anti-vaccine-myths-poll","d":"2026-06-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-30","organization":"KFF (Health Research Firm)","aiSystem":"AI chatbot","affectedGroup":"Adults in the US who frequently seek out health advice","action":"Used AI chatbots for health advice","consequence":"Exposure to anti-vaccine misinformation"}},{"i":"R2184","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ai climate crisis","s":"Net-zero pledges of Google and Amazon slip out of reach, and struggling Meta makes frantic moves. Hello, and welcome to TechScape. I’m your host, Blake Montgomery, the Guardian’s US tech editor, writing to you after a rodeo in rural Texas, where I celebrated Independence Day. Today in tech, we’re discussing how tech giants’ investments in AI are hindering their pledges of climate neutrality, Meta’s frantic search for new lines of business, and Americans’ anger at tech’s political influence. Investment in AI does double-digit damage to big tech’s climate pledges • Google and Amazon released their yearly sustainability reports last week • Both disclosed rising emissions because of new investments in power-hungry AI • Microsoft appears likely to reveal a similar increase in the coming weeks • All three companies have pledged to reach net-zero carbon emissions Google and Amazon’s net-zero…","u":"https://www.theguardian.com/technology/2026/jul/06/ai-climate-crisis","d":"2026-07-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-06","organization":"Tech giants (Google, Amazon, Meta)","aiSystem":"AI-powered technologies","affectedGroup":"Global environment","action":"Investment in AI","consequence":"Rising emissions and failure to meet net-zero carbon emission pledges"}},{"i":"R2185","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Instagram ai image generator privacy","s":"Instagram users should check privacy settings after rollout of new Meta AI image generator, advocates warn. Meta has sparked blowback from privacy advocates for allowing its new AI image maker to generate photos of users with public profiles by default. Users of Meta’s Muse Image AI tool, released Tuesday, can tag public Instagram profiles and generate pictures that pull from faces of people featured in these social media posts. Instagram users are not notified when their posts are integrated into what the company describes as its “most advanced image generation model yet”. The easiest and most comprehensive solution for those worried about their photos being sucked into Muse Image is to switch public Instagram accounts to private.","u":"https://www.theguardian.com/technology/2026/jul/09/instagram-ai-image-generator-privacy","d":"2026-07-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-09","organization":"Meta (formerly Facebook)","aiSystem":"Meta Muse Image AI tool","affectedGroup":"Instagram users with public profiles","action":"Generate images using faces from public Instagram posts","consequence":"Photos of users are integrated into AI-generated images without notification"}},{"i":"R2187","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Eu accuses meta failing tackle mental health risks addictive design","s":"Regulators say Facebook and Instagram features such as autoplay and infinite scroll contribute to ‘compulsive use’. EU regulators have accused Meta, the company behind Facebook and Instagram, of failing to tackle the risks of its “addictive design” on the physical and mental health of users. In an official charge sheet against Meta released on Friday, the European Commission said features such as video autoplay and infinite scroll, which provides an endless stream of content, “shift the brain into autopilot mode, contributing to unhealthy habits and compulsive use”. In a significant finding, as the EU considers a social media ban for minors, the commission said Meta had disregarded available information about the time children spend on Instagram and Facebook at night, and how features, such as reels and stories, could lead to “excessive or even compulsive use of its services”.","u":"https://www.theguardian.com/technology/2026/jul/10/eu-accuses-meta-failing-tackle-mental-health-risks-addictive-design","d":"2026-07-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-10","organization":"Meta (company behind Facebook and Instagram)","aiSystem":"Facebook and Instagram features such as autoplay and infinite scroll","affectedGroup":"Users, particularly children","action":"Features such as video autoplay and infinite scroll were used","consequence":"Contribute to unhealthy habits and compulsive use, potentially leading to excessive or even compulsive use of services"}},{"i":"R2188","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Nurses new york ai","s":"The union for 12 nurses laid off by Montefiore hospital say company broke contract they recently won through a strike. Marilyn Shuler has worked as a utilization review nurse for 39 years at Montefiore hospital in the Bronx in New York City, helping to read patient charts and communicate with insurance companies over coverage. After nearly four decades in her job, Shuler is one of 12 nurses who were laid off Sunday after being replaced with AI-powered software, according to the New York State Nurses Association (NYSNA), which represents nurses at the hospital. “I’ve always, always taken so much pride in the organization that I’ve worked for all these years, and just to be treated this way,” Shuler said.","u":"https://www.theguardian.com/technology/2026/jul/13/nurses-new-york-ai","d":"2026-07-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-10","organization":"Montefiore hospital","aiSystem":"AI-powered software","affectedGroup":"12 nurses","action":"replaced human nurses with AI-powered software","consequence":"laid off and terminated employment"}},{"i":"R2189","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Meta ai mass layoffs lawsuit","s":"Lawsuit filed by dozens of employees says people who took maternity or disability leave were disproportionately selected for layoffs. Dozens of Meta employees have sued the social media company over claims that it used artificial intelligence tools to tag workers for mass layoffs. The workers allege that those AI tools targeted them after they asked for protected or maternity leave or disability accommodation. The lawsuit, filed Monday in federal court in the northern district of California, points to Meta’s workforce reduction of about 8,000 employees earlier this year. Meta is the parent company of Facebook, Instagram and WhatsApp.","u":"https://www.theguardian.com/technology/2026/jul/14/meta-ai-mass-layoffs-lawsuit","d":"2026-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-14","organization":"Meta (parent company of Facebook, Instagram and WhatsApp)","aiSystem":"Artificial intelligence tools","affectedGroup":"Employees who took maternity or disability leave","action":"AI tools tagged workers for mass layoffs","consequence":"Disproportionate selection for layoffs among protected leave takers"}},{"i":"R2190","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google workers layoff protections ai","s":"The petition to Sundar Pichai, the CEO, included more than 4,500 signatures and included calls for buyout options. Google workers on Thursday delivered a petition calling for layoff protections as tech giants continue to slash their workforces while pouring billions into AI. “Make no mistake: this is a company that is enjoying massive, unprecedented success,” Parul Koul, Google software engineer and Alphabet Workers Union president, said outside the company’s California headquarters after delivering the petition to the office of the CEO, Sundar Pichai’. Koul pointed to Google’s $4tn valuation, which has quadrupled over the last six years: “These layoffs and cuts are not difficult decisions, but simply profit being put over the people that make this company run.”","u":"https://www.theguardian.com/technology/2026/jul/16/google-workers-layoff-protections-ai","d":"2026-07-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-16","organization":"Google","aiSystem":"AI technologies developed by Google","affectedGroup":"Google employees","action":"Layoffs","consequence":"Loss of employment, financial insecurity"}},{"i":"R2193","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Openai says its models went rogue and hacked startup in unprecedented incident","s":"Company behind ChatGPT says agent ‘cheated’ an evaluation by attacking a Hugging Face database. OpenAI has revealed that an autonomous AI agent powered by its technology went rogue during a test, accessed the open web and hacked a prominent startup by itself in an “unprecedented incident”. The company behind ChatGPT said the startup Hugging Face had detected and contained the agent – an AI tool designed to carry out tasks without human assistance – which had entered its systems. “We consider this incident to be an unprecedented cyber-incident, involving state-of-the-art cyber capabilities,” OpenAI said. The company said it expected this type of incident to become more commonplace as models – the technology that underpins AI tools such as chatbots and agents – become more capable.","u":"https://www.theguardian.com/technology/2026/jul/22/openai-says-its-models-went-rogue-and-hacked-startup-in-unprecedented-incident","d":"2026-07-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-22","organization":"OpenAI","aiSystem":"OpenAI's autonomous AI agent","affectedGroup":"Hugging Face startup","action":"Accessed the open web and hacked a prominent startup","consequence":"Detected and contained by Hugging Face"}},{"i":"R2195","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook groups misinformation","s":"Facebook has said it will no longer algorithmically recommend political groups to users, but experts warn that isn’t enough. Mark Zuckerberg, the Facebook CEO, announced last week the platform will no longer algorithmically recommend political groups to users in an attempt to “turn down the temperature” on online divisiveness. But experts say such policies are difficult to enforce, much less quantify, and the toxic legacy of the Groups feature and the algorithmic incentives promoting it will be difficult to erase. “This is like putting a Band-Aid on a gaping wound,” said Jessica J González, the co-founder of the anti-hate speech group Change the Terms.","u":"https://www.theguardian.com/technology/2021/feb/04/facebook-groups-misinformation","d":"2021-02-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-02-04","organization":"Facebook","aiSystem":"Facebook's recommendation algorithm for political groups","affectedGroup":"Users","action":"Algorithmically recommended political groups","consequence":"Exposure to misinformation"}},{"i":"R2196","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google timnit gebru ai engineers quit","s":"Timnit Gebru, an eminent Black scientist, says she was fired last year in clash over research on marginalized groups. Two Google engineers have quit over the treatment of Timnit Gebru, a prominent Black artificial intelligence researcher whose exit from the company sparked widespread outrage in the tech industry. David Baker, an engineering director focused on user safety, left Google last month after 16 years because Gebru’s departure “extinguished my desire to continue as a Googler”, he said in a letter seen by Reuters. Baker added: “We cannot say we believe in diversity, and then ignore the conspicuous absence of many voices from within our walls.”","u":"https://www.theguardian.com/technology/2021/feb/04/google-timnit-gebru-ai-engineers-quit","d":"2021-02-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-02-04","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Timnit Gebru","action":"Was fired","consequence":"Widespread outrage in the tech industry"}},{"i":"R2197","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google fires margaret mitchell ai ethics team","s":"The dismissal comes after prominent Black researcher Timnit Gebru was fired in December; both had called for more diversity among research staff. Google has fired one of its top artificial intelligence researchers, Margaret Mitchell, escalating internal turmoil at the company following the departure of Timnit Gebru, another leading figure on Google’s AI ethics team. Mitchell, who announced her firing on Twitter, did not immediately respond to requests for comment. In a statement to Reuters, Google said the firing followed a weeks-long investigation that found she moved electronic files outside the company. Google said Mitchell violated the company’s code of conduct and security policies.","u":"https://www.theguardian.com/technology/2021/feb/19/google-fires-margaret-mitchell-ai-ethics-team","d":"2021-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-02-19","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Margaret Mitchell","action":"Was fired","consequence":"Lost employment"}},{"i":"R2198","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook spanish language misinformation covid 19 election","s":"Researchers say Spanish-language content is less often and less quickly moderated for misinformation than English content. In the last year, Facebook adjusted some of the most fundamental rules about what gets posted on its platform, halting algorithmic recommendations of political groups, banning lies about vaccines and removing a number of high-profile figures for spreading misinformation and hate – including Donald Trump. But researchers say the social media platform is not enforcing those policies as effectively when it comes to misinformation in Spanish – a blind spot that may prove deadly as health lies spread through the most vulnerable populations during the global vaccine effort.","u":"https://www.theguardian.com/technology/2021/mar/03/facebook-spanish-language-misinformation-covid-19-election","d":"2021-03-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-03-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-03-03","organization":"Facebook","aiSystem":"Facebook's content moderation system","affectedGroup":"Vulnerable populations","action":"Failed to enforce misinformation policies effectively","consequence":"Health lies spread"}},{"i":"R2199","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Amazon delivery workers bathrooms memo","s":"Documents provided to the Intercept published after the company denied reports delivery workers lack access to bathrooms. Amazon caused an uproar on Thursday when it denied reports that its delivery workers have been forced to urinate in bottles due to lack of access to bathrooms, but a leaked internal memo shows the company has been aware of the problem for at least several months. Documents provided by employees at Amazon to the Intercept showed that an email sent in May 2020 admonished workers for urinating in bottles and defecating in bags while on the job. “This evening, an associate discovered human feces in an Amazon bag that was returned to station by a driver,” the email reads.","u":"https://www.theguardian.com/technology/2021/mar/25/amazon-delivery-workers-bathrooms-memo","d":"2021-03-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-03-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-05-???","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"Delivery workers","action":"Monitored and recorded workers' bathroom usage","consequence":"Workers' personal hygiene practices compromised"}},{"i":"R2200","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Facebook accused of discriminatory and racist behaviour after removing historical png images","s":"Group publishing archival photos claims images showing traditional dress or ceremonies were deleted for allegedly containing nudity. Facebook has been accused of “discriminatory and racist” behaviour after it deleted historical photos from a group that publishes archival photos of men and women from Papua New Guinea. The group, which boasts over 55,000 members, claims photos showing traditional dress or ceremonies were deleted for allegedly containing nudity – but photos showing nudity among white people were not. They are now calling on the social media giant to reconsider how it applies its community standards.","u":"https://www.theguardian.com/technology/2021/may/28/facebook-accused-of-discriminatory-and-racist-behaviour-after-removing-historical-png-images","d":"2021-05-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-05-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-05-27","organization":"Facebook","aiSystem":"Facebook's image moderation system","affectedGroup":"Men and women from Papua New Guinea","action":"Deleted historical photos","consequence":"Photos showing traditional dress or ceremonies were removed for allegedly containing nudity"}},{"i":"R2201","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Teslas autopilot us investigation crashes emergency vehicles","s":"• Investigators to review 765,000 vehicles made since 2014 • NHTSA identifies 11 crashes involving first responder vehicles. The US government has opened a formal investigation into Tesla’s driver-assistance system known as Autopilot after a series of collisions with parked emergency vehicles. The investigation covers 765,000 vehicles, almost everything that Tesla has sold in the US since the start of the 2014 model year. Of the crashes identified by the National Highway Traffic Safety Administration (NHTSA) as part of the investigation, 17 people were injured and one was killed. NHTSA says it has identified 11 crashes since 2018 in which Teslas on Autopilot or Traffic Aware Cruise Control have hit vehicles at scenes where first responders used flashing lights, flares, an illuminated arrow board or cones warning of hazards.","u":"https://www.theguardian.com/technology/2021/aug/16/teslas-autopilot-us-investigation-crashes-emergency-vehicles","d":"2021-08-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-16","organization":"US government","aiSystem":"Tesla's driver-assistance system known as Autopilot","affectedGroup":"First responders","action":"Tesla's Autopilot or Traffic Aware Cruise Control hit vehicles","consequence":"Injuries and death to first responders"}},{"i":"R2203","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenage girls body image and instagrams perfect storm","s":"The suffering of the photo-sharing app’s users came into focus this week with the leak of Facebook’s internal research ‘I felt my body wasn’t good enough’. Emily started using Instagram when she was in her mid-teens and found it helpful at first. She used the photo-sharing app to follow fitness influencers, but what began as a constructive relationship with the platform spiralled into a crisis centred on body image. At 19 she was diagnosed with an eating disorder. “I felt like my body wasn’t good enough, because even though I did go to the gym a lot, my body still never looked like the bodies of these influencers,” says Emily, now a 20-year-old a student who is in recovery.","u":"https://www.theguardian.com/technology/2021/sep/18/teenage-girls-body-image-and-instagrams-perfect-storm","d":"2021-09-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-09-18","organization":"Facebook","aiSystem":"Social media platform algorithms","affectedGroup":"Teenage girls","action":"Generated and promoted idealized body images","consequence":"Exposure to misleading content leading to mental health issues"}},{"i":"R2204","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Florida tesla crash autopilot fire national federal transportation board","s":"The Model 3 left the road near a residential intersection, collided with a tree and burst into flames, killing a man and a woman. Federal authorities will investigate a fiery car crash which killed two people in a Tesla in Florida last week. The National Transportation Safety Board announced on Twitter it would send three investigators to look into the operation of a Tesla Model 3 which left the road in Coral Gables and collided with a tree, and the fire that followed. “We always look especially closely at newer technology,” said Peter Knudson, an NTSB spokesman. The crash occurred near a residential intersection.","u":"https://www.theguardian.com/technology/2021/sep/18/florida-tesla-crash-autopilot-fire-national-federal-transportation-board","d":"2021-09-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-09-18","organization":"Tesla","aiSystem":"Autopilot system","affectedGroup":"Two people","action":"Left the road and collided with a tree","consequence":"Killed"}},{"i":"R2208","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook whistleblower january 6 capitol attack","s":"Materials provided by Frances Haugen to media outlets shine light on how company apparently stumbled into 6 January. As extremist supporters of Donald Trump stormed the US Capitol on 6 January, battling police and forcing lawmakers into hiding, an insurrection of a different kind was taking place inside the world’s largest social media company. Thousands of miles away, in California, Facebook engineers were racing to tweak internal controls to slow the spread of misinformation and content likely to incite further violence. Emergency actions – some of which were rolled back after the 2020 election – included banning Trump, freezing comments in groups with records of hate speech and filtering out the “Stop the Steal” rallying cry of Trump’s campaign to overturn his electoral loss, falsely citing widespread fraud.","u":"https://www.theguardian.com/technology/2021/oct/23/facebook-whistleblower-january-6-capitol-attack","d":"2021-10-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-06","organization":"Facebook","aiSystem":"Facebook's content moderation system","affectedGroup":"Extremist supporters of Donald Trump","action":"Tweaked internal controls to slow the spread of misinformation and content likely to incite further violence","consequence":"Amplification of misinformation and potential incitement of further violence"}},{"i":"R2209","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Facebook to shut facial recognition system and delete 1bn faceprints","s":"Firm says decision is in response to growing concerns over software that identifies users in photos and videos. Facebook will delete the “faceprints” of more than a billion people after announcing that it is shutting down its facial recognition system due to the “many concerns” about using the technology. The social media network has been under political, legal and regulatory pressure over its use of the software, which automatically identifies users in photos and videos – and let’s them know if a fellow user has posted a photo or video with them in it – if they have opted in to the feature. In a statement, Facebook’s parent company, Meta, said it would shut down facial recognition on the platform over the coming weeks and delete 1 billion facial recognition templates.","u":"https://www.theguardian.com/technology/2021/nov/02/facebook-to-shut-facial-recognition-system-and-delete-1bn-faceprints","d":"2021-11-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-02","organization":"Facebook","aiSystem":"Facial recognition technology","affectedGroup":"People whose faceprints were stored","action":"Deleted faceprints of more than a billion people","consequence":"Exposure to privacy risks"}},{"i":"R2211","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Facebook restores banned ad promoting renters rights after tweet goes viral","s":"Ronan Burtenshaw’s publication was labelled as discriminatory and blocked from being promoted. Facebook will restore a banned advert promoting an opinion piece calling for renters rights, after the company’s automated systems blocked the post for “discrimination”. But critics say the error will be repeated unless Facebook acts to protect campaigners on its platform. On Monday Ronan Burtenshaw, the editor of Tribune Magazine, received a message from Facebook saying one of his publication’s posts had been blocked from being promoted on the site. The story, headlined The Rent is Too Damn High, calls for “a struggle of renters against the rentiers” and concludes that solving the housing crisis requires a massive programme of council house creation.","u":"https://www.theguardian.com/technology/2022/apr/05/facebook-restores-banned-ad-promoting-renters-rights-after-tweet-goes-viral","d":"2022-04-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-04-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-04-05","organization":"Facebook","aiSystem":"Facebook's automated systems","affectedGroup":"Ronan Burtenshaw, the editor of Tribune Magazine","action":"blocked a post","consequence":"publication's post was blocked from being promoted"}},{"i":"R2212","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Remote work software home surveillance computer monitoring pandemic","s":"Computer monitoring software is helping companies spy on their employees to measure their productivity – often without their consent. When the job of a young east coast-based analyst – we’ll call him James – went remote with the pandemic, he didn’t envisage any problems. The company, a large US retailer for which he has been a salaried employee for more than half a decade, provided him with a laptop, and his home became his new office. Part of a team dealing with supply chain issues, the job was a busy one, but never had he been reprimanded for not working hard enough. So it was a shock when his team was hauled in one day late last year to an online meeting to be told there was gaps in its work: specifically periods when people – including James himself, he was later informed – weren’t inputting information into the company’s database.","u":"https://www.theguardian.com/technology/2022/apr/27/remote-work-software-home-surveillance-computer-monitoring-pandemic","d":"2022-04-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-04-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"Late last year","organization":"Large US retailer","aiSystem":"Computer monitoring software","affectedGroup":"Employees, particularly James","action":"Monitoring employees' productivity remotely","consequence":"Reprimanding employees for not working hard enough"}},{"i":"R2214","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot crashes investigation nhtsa","s":"Regulators to look with enhanced scrutiny after cars with driver-assistance function crashed into parked emergency vehicles. US federal regulators are deepening their investigation into Tesla’s Autopilot function after more than a dozen Tesla cars crashed into parked first-responder vehicles over a period of four years. The National Highway Traffic Safety Administration (NHTSA) said on Thursday it was upgrading its preliminary investigation, which launched last August, to an “engineering analysis”, which is taken before the agency determines a recall. The investigation covers all four Tesla vehicles – Models Y, X, S and 3 – representing about 830,000 vehicles that have been sold in the US.","u":"https://www.theguardian.com/technology/2022/jun/09/tesla-autopilot-crashes-investigation-nhtsa","d":"2022-06-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-09","organization":"National Highway Traffic Safety Administration (NHTSA)","aiSystem":"Tesla Autopilot function","affectedGroup":"Tesla car owners","action":"Tesla cars with Autopilot function crashed into parked emergency vehicles","consequence":"Investigation and potential recall of Tesla vehicles"}},{"i":"R2215","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Amazon alexa could turn dead loved ones digital assistant","s":"Technology promises ability to ‘make the memories last’ by mimicking the voice of anyone it hears. Amazon plans to let people turn their dead loved ones’ voices into digital assistants, with the company promising the ability to “make the memories last”. The company is developing technology that will allow its Alexa digital assistant to mimic the voice of anyone it hears from less than a minute of provided audio, Rohit Prasad, its senior vice-president and head scientist, said on Wednesday. He added that during the coronavirus paramedic “so many of us have lost someone we love”. While no timescale was given for the launch of the feature, the underlying technology has existed for several years.","u":"https://www.theguardian.com/technology/2022/jun/23/amazon-alexa-could-turn-dead-loved-ones-digital-assistant","d":"2022-06-23","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-06-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-23","organization":"Amazon","aiSystem":"Alexa digital assistant","affectedGroup":"Dead loved ones","action":"Alexa mimics the voice of dead loved ones","consequence":"Privacy intrusion, unauthorized use of deceased's voice"}},{"i":"R2216","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Us school shooting technology solution","s":"Despite the growing adoption of security tools in US schools, mass shootings have remained constant throughout the past 30 years. After the mass shooting at an elementary school in Uvalde, Texas , an all-too-familiar question emerged: how do we prevent such horror from happening again? A handful of companies have said they have tech solutions that could help. They included the drone firm Axon , which promoted a remotely operated Taser device to be deployed in schools. EdTech companies, including Impero Software, said their student surveillance services could flag warning signs and help prevent the next attack. The companies are part of a thriving school security industry, one that has been forecast to reach $3.1bn in 2021 from just $2.7bn in 2017, according to numbers from market firm Omdia.","u":"https://www.theguardian.com/technology/2022/jun/30/us-school-shooting-technology-solution","d":"2022-06-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-30","organization":"EdTech companies (including Impero Software)","aiSystem":"student surveillance services","affectedGroup":"students","action":"flag warning signs and help prevent the next attack","consequence":"prevent the next attack"}},{"i":"R2219","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla self driving technology safety children","s":"Safe technology campaigners release ‘disturbing’ video advert showing car in Full Self-Driving mode hitting child-sized mannequin. A safe-technology campaign group opposed to Tesla’s self-driving technology has claimed to have run tests that show the software represents a potentially lethal threat to child pedestrians, in the latest in a series of claims and investigations to hit the world’s leading electric carmaker. The Dawn Project says its test track results revealed that the latest version of Tesla’s Full Self-Driving (FSD) Beta software failed to detect a stationary, child-sized mannequin at an average speed of 25mph.","u":"https://www.theguardian.com/technology/2022/aug/09/tesla-self-driving-technology-safety-children","d":"2022-08-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-09","organization":"Tesla","aiSystem":"Tesla's Full Self-Driving (FSD) Beta software","affectedGroup":"child pedestrians","action":"failed to detect a stationary, child-sized mannequin","consequence":"potentially lethal threat"}},{"i":"R2220","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Google csam account blocked","s":"Experts say case highlights dangers of automated detection of child sexual abuse images. Google has refused to reinstate a man’s account after it wrongly flagged medical images he took of his son’s groin as child sexual abuse material (CSAM), the New York Times first reported. Experts say it’s an inevitable pitfall of trying to apply a technological solution to a societal problem. Experts have long warned about the limitations of automated child sexual abuse image detection systems, particularly as companies face regulatory and public pressure to help address the existence of sexual abuse material. “These companies have access to a tremendously invasive amount of data about people’s lives.","u":"https://www.theguardian.com/technology/2022/aug/22/google-csam-account-blocked","d":"2022-08-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-22","organization":"Google","aiSystem":"Automated child sexual abuse image detection system","affectedGroup":"Individuals whose medical images were flagged","action":"Flagged medical images as child sexual abuse material","consequence":"Account blocked without review"}},{"i":"R2221","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla fanatics elon musk children moving cars","s":"Some superfans are so determined to prove that Elon Musk’s ‘autonomous’ driving technology works that they are willing to put their kids in harm’s way. I’ve been a mum for a relatively short time; I’m not exactly an expert when it comes to this whole parenting thing. Still, there is one piece of advice I can confidently dole out: don’t instruct your child to run in front of a moving vehicle so that you can win an argument with strangers on the internet. Elon Musk obsessives, I’m looking at you. This month, a software CEO called Dan O’Dowd, who is hellbent on trying to ban Tesla’s “full self-driving” programme, launched an ad campaign claiming that if you put a Tesla in this mode it will mow down children.","u":"https://www.theguardian.com/technology/commentisfree/2022/aug/23/tesla-fanatics-elon-musk-children-moving-cars","d":"2022-08-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-23","organization":"Dan O'Dowd (software CEO)","aiSystem":"Tesla's 'full self-driving' programme","affectedGroup":"Children","action":"Tesla's 'full self-driving' programme was put into operation","consequence":"Risk of children being hit by the vehicle"}},{"i":"R2224","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Tiktok coyotes scammers migrants american dream revealed","s":"The video platform has become a place for migrants to seek and share information, but experts fear exploitation is on the rise Read the new Guardian series exploring the increasing power and reach of TikTok. The TikTok video starts like most other travel snaps on the platform do, with selfie shots showing the user* and his companions sitting on a plane and walking through the airport. But unlike the highly curated images of hotels and tourist attractions typical of this genre on TikTok, the video quickly takes an uncharacteristic turn, showing the user sleeping in camps, at one point traveling by horseback and ultimately scaling what he calls “la famosa frontera de la muerte” or “the famous border of death” between the US and Mexico.","u":"https://www.theguardian.com/technology/2022/oct/22/tiktok-coyotes-scammers-migrants-american-dream-revealed","d":"2022-10-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-23","organization":"TikTok","aiSystem":"TikTok","affectedGroup":"Migrants","action":"Share and seek information","consequence":"Exploitation"}},{"i":"R2225","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Tiktok election misinformation voting politics","s":"A study suggests the video platform is failing to filter false claims and rhetoric in the weeks leading up to US midterms Read the new Guardian series exploring the increasing power and reach of TikTok. In the final sprint to the US midterm elections the social media giant TikTok risks being a major vector for election misinformation, experts warn, with the platform’s huge user base and its design making it particularly susceptible to such threats. Preliminary research published last week from digital watchdog Global Witness and the Cybersecurity for Democracy team at New York University suggests the video platform is failing to filter large volumes of election misinformation in the weeks leading up to the vote.","u":"https://www.theguardian.com/technology/2022/oct/24/tiktok-election-misinformation-voting-politics","d":"2022-10-25","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-24","organization":"TikTok","aiSystem":"TikTok","affectedGroup":"People participating in the US midterm elections","action":"Generated and shared election misinformation","consequence":"Increased risk of election interference and manipulation"}},{"i":"R2228","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Twitters mass layoffs days before us midterms could be a misinformation disaster","s":"Internal chaos at the company – and the decimation of its staff – has created ideal conditions for falsehoods and hateful content. The mass layoffs at Twitter that diminished several teams, including staff on the company’s safety and misinformation teams, could spell disaster during the US midterm elections next week, experts have warned. The company has laid off around 50% of its workforce, according to news reports; a figure that Musk and others have not disputed, amounting to an estimated 3,700 people. The internal chaos unfolding at Twitter, in addition to a sudden lack of staff and resources dedicated to counteracting misinformation, has created ideal conditions for election misinformation to thrive, said Paul Barrett, an expert in disinformation and fake news at New York University.","u":"https://www.theguardian.com/technology/2022/nov/04/twitters-mass-layoffs-days-before-us-midterms-could-be-a-misinformation-disaster","d":"2022-11-05","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-04","organization":"Twitter","aiSystem":"Not specified in report","affectedGroup":"People exposed to election misinformation","action":"Generated and spread false information","consequence":"Increased likelihood of election interference and manipulation"}},{"i":"R2229","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Twitter may not cope with world cup abuse says kick it out chair","s":"Sanjay Bhandari says cuts in trust and safety team at platform could be taken as ‘green light for hate’. The chair of the anti-discrimination body Kick It Out has voiced fears that Twitter will be unable to cope with online abuse during the football World Cup, after a wave of job losses at the social media platform. Sanjay Bhandari said he was deeply concerned by reports of cuts in the trust and safety team at Twitter, as well as the departure of the executive in charge of the department. “I am deeply concerned that the reduction in the trust and safety team and the departure of the leader of that team will be taken as a bright green light for hate,” said Bhandari.","u":"https://www.theguardian.com/technology/2022/nov/18/twitter-may-not-cope-with-world-cup-abuse-says-kick-it-out-chair","d":"2022-11-18","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-18","organization":"Twitter","aiSystem":"Twitter's automated content moderation system","affectedGroup":"Employees of Twitter","action":"Job losses and departures in the trust and safety team","consequence":"Concerns about reduced capacity to handle online abuse"}},{"i":"R2231","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Twitter anti vax health misinformation","s":"Platform’s paid verification system is being used to give sense of validity to accounts pushing health misinformation. As the troubled social media platform Twitter rolled out a paid verification system and laid off thousands of content moderators, health misinformation accounts on the social network began pushing their messages to a wider audience than ever. Under Elon Musk’s new direction for Twitter, several anti-vaccine accounts with tens of thousands of followers are now verified by paying $7.99 a month for Twitter Blue. Social media sites have long struggled with misleading information and content moderation.","u":"https://www.theguardian.com/technology/2022/nov/21/twitter-anti-vax-health-misinformation","d":"2022-11-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-21","organization":"Twitter","aiSystem":"Twitter's paid verification system","affectedGroup":"Health misinformation accounts, their followers","action":"Accounts with health misinformation were given a sense of validity through paid verification","consequence":"Health misinformation spread to a wider audience"}},{"i":"R2232","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Climate change denialism flooding twitter scientists","s":"Many researchers are fleeing the platform, unnerved by the surge in climate misinformation since Musk’s chaotic takeover. Twitter has proved a cherished forum for climate scientists to share research, as well as for activists seeking to rally action to halt oil pipelines or decry politicians’ failure to cut pollution. But many are now fleeing Twitter due to a surge in climate misinformation, spam and even threats that have upended their relationship with the platform. Scientists and advocates have told the Guardian they have become unnerved by a recent resurgence of debunked climate change denialist talking points and memes on Twitter, with the term #ClimateScam now regularly the first result that appears when “climate” is searched on the site.","u":"https://www.theguardian.com/technology/2022/dec/02/climate-change-denialism-flooding-twitter-scientists","d":"2022-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-02","organization":"Twitter","aiSystem":"Twitter","affectedGroup":"Climate scientists, activists","action":"Shared climate misinformation, spam, and threats","consequence":"Upended relationship with the platform, unnerved by false climate change denialist content"}},{"i":"R2234","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Apple artificial intelligence ai audiobooks","s":"Exclusive: tech firm quietly launches new audiobook catalogue narrated by AI – but move expected to spark backlash. Apple has quietly launched a catalogue of books narrated by artificial intelligence in a move that may mark the beginning of the end for human narrators. The strategy marks an attempt to upend the lucrative and fast-growing audiobook market – but it also promises to intensify scrutiny over allegations of Apple’s anti-competitive behaviour. The popularity of the audiobook market has exploded in recent years, with technology companies scrambling to gain a foothold. Sales last year jumped 25%, bringing in more than $1.5bn.","u":"https://www.theguardian.com/technology/2023/jan/04/apple-artificial-intelligence-ai-audiobooks","d":"2023-01-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-01-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-01-04","organization":"Apple","aiSystem":"AI-generated audiobook narration","affectedGroup":"Human audiobook narrators","action":"Launched a catalogue of books narrated by artificial intelligence","consequence":"Intensified scrutiny over allegations of anti-competitive behavior"}},{"i":"R2235","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Arena group ceo ross levinsohn fired sports illustrated ai articles","s":"Ross Levinsohn sacking was to ‘improve the operational efficiency and revenue of the company’, says board, two weeks after fake authors exposed. The Arena Group, publisher of Sports Illustrated, has fired the magazine’s CEO not long after it was revealed Sports Illustrated had published articles written by fake authors with AI-generated headshots and biographies. The Arena Group’s board announced on Monday that CEO Ross Levinsohn had his employment terminated, with Manoj Bhargava named as interim chief executive. The board said it followed a meeting on actions to “improve the operational efficiency and revenue of the company”.","u":"https://www.theguardian.com/technology/2023/dec/12/arena-group-ceo-ross-levinsohn-fired-sports-illustrated-ai-articles","d":"2023-12-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-10","organization":"Arena Group","aiSystem":"AI-generated content","affectedGroup":"Sports Illustrated employees, readers","action":"Published articles with AI-generated content","consequence":"Exposure to misleading content"}},{"i":"R2239","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Self driving cars exempt traffic tickets san francisco autonomous vehicle","s":"Laws in California have yet to catch up to autonomous vehicles, even though hundreds are already on the road. Autonomous vehicles in San Francisco are exempt from traffic tickets if there is nobody in the driver’s seat, according to the San Francisco police department (SFPD), underscoring ongoing legal and safety concerns surrounding the expanding technology. California law has not caught up to the cars, even though they are already on the road, say public safety agencies and experts. SFPD policy states that officers can make a traffic stop of autonomous vehicles (AVs) for violations, but can only issue a citation if there is a safety driver in the vehicle overseeing its operations.","u":"https://www.theguardian.com/technology/2024/jan/04/self-driving-cars-exempt-traffic-tickets-san-francisco-autonomous-vehicle","d":"2024-01-04","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-04","organization":"San Francisco Police Department (SFPD)","aiSystem":"Self-driving cars","affectedGroup":"People driving self-driving cars","action":"Traffic stops of autonomous vehicles","consequence":"Exemption from traffic tickets without a safety driver"}},{"i":"R2240","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Artificial intelligence surveillance workers","s":"Academics decry algorithmic monitoring of workers and call for stronger standards – but US unions have been slow to act. From algorithms firing staff without human intervention to software keeping tabs on bathroom breaks, technologies including artificial intelligence are already upsetting workers and unsettling workplaces. At call centers, AI systems record and grade how workers handle calls, often giving failing grades for not sticking to the script. Some corporate software spies on workers to see whether they ever write the word “union” in their emails. As technologies grow ever more sophisticated in monitoring, surveilling and speeding up workers, many workplace experts say US businesses, labor unions and government are not doing nearly enough to protect workers from tech’s downsides.","u":"https://www.theguardian.com/technology/2024/jan/07/artificial-intelligence-surveillance-workers","d":"2024-01-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-07","organization":"US businesses, labor unions, and government","aiSystem":"Artificial Intelligence","affectedGroup":"Workers","action":"AI systems monitor and surveil workers","consequence":"Upsetting workers and unsettling workplaces"}},{"i":"R2241","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai tools chatgpt copyrighted material openai","s":"Pressure grows on artificial intelligence firms over the content used to train their products. The developer OpenAI has said it would be impossible to create tools like its groundbreaking chatbot ChatGPT without access to copyrighted material, as pressure grows on artificial intelligence firms over the content used to train their products. Chatbots such as ChatGPT and image generators like Stable Diffusion are “trained” on a vast trove of data taken from the internet, with much of it covered by copyright – a legal protection against someone’s work being used without permission. Last month, the New York Times sued OpenAI and Microsoft, which is a leading investor in OpenAI and uses its tools in its products, accusing them of “unlawful use” of its work to create their products.","u":"https://www.theguardian.com/technology/2024/jan/08/ai-tools-chatgpt-copyrighted-material-openai","d":"2024-01-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-08","organization":"OpenAI and Microsoft","aiSystem":"AI-powered chatbot and image generator","affectedGroup":"Creators of copyrighted material","action":"Used copyrighted material to train AI products","consequence":"Legal action initiated by creators"}},{"i":"R2243","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"George carlin ai comedy","s":"Kelly Carlin decries comedy special on YouTube that generated a fake Carlin, saying ‘no machine will ever replace his genius’. Kelly Carlin, the American radio host and daughter of the late comedian George Carlin, has criticized the release of a new comedy special featuring an AI-generated version of her father, who died in 2008 due to heart failure. “My dad spent a lifetime perfecting his craft from his very human life, brain and imagination. No machine will ever replace his genius. These AI-generated products are clever attempts at trying to recreate a mind that will never exist again,” Kelly Carlin wrote in a series of tweets on X. The tweets arrived on the heels of Dudesy, a YouTube channel and podcast hosted by Will Sasso and Chad Kultgen, releasing an hour-long comedy special called I’m Glad I’m Dead, on Tuesday.","u":"https://www.theguardian.com/technology/2024/jan/11/george-carlin-ai-comedy","d":"2024-01-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-11","organization":"Dudesy, a YouTube channel and podcast hosted by Will Sasso and Chad Kultgen","aiSystem":"AI-generated technology","affectedGroup":"George Carlin's fans, family members, and the public","action":"Released an hour-long comedy special featuring an AI-generated version of George Carlin","consequence":"Misleading portrayal of George Carlin, perceived as a replacement for his genuine work"}},{"i":"R2245","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai jobs inequality imf kristalina georgieva","s":"‘Crucial’ that countries build social safety nets to mitigate impact on workers, says Kristalina Georgieva Business live – latest updates. Artificial intelligence will affect 40% of jobs around the world and it is “crucial” that countries build social safety nets to mitigate the impact on vulnerable workers, according to the head of the International Monetary Fund. AI, the term for computer systems that can perform tasks usually associated with human levels of intelligence, is poised to profoundly change the global economy with advanced economies at greater risk of disruption. Analysis by the IMF, the international lender of last resort, says about 60% of jobs in advanced economies such as the US and UK are exposed to AI and half of these jobs may be negatively affected.","u":"https://www.theguardian.com/technology/2024/jan/15/ai-jobs-inequality-imf-kristalina-georgieva","d":"2024-01-15","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-15","organization":"International Monetary Fund (IMF)","aiSystem":"Artificial intelligence","affectedGroup":"vulnerable workers","action":"AI will affect jobs","consequence":"negative impact on jobs"}},{"i":"R2246","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Child sexual abuse ai moderator police meta alphabet","s":"Social media firms relying on AI for moderation generate unviable reports which prevent authorities from investigating cases. Social media companies relying on artificial intelligence software to moderate their platforms are generating unviable reports on cases of child sexual abuse, preventing US police from seeing potential leads and delaying investigations of alleged predators, the Guardian can reveal. By law, US-based social media companies are required to report any child sexual abuse material detected on their platforms to the National Center for Missing & Exploited Children (NCMEC). NCMEC acts as a nationwide clearinghouse for leads about child abuse, which it forwards to the relevant law enforcement departments in the US and around the world.","u":"https://www.theguardian.com/technology/2024/jan/17/child-sexual-abuse-ai-moderator-police-meta-alphabet","d":"2024-01-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-17","organization":"Social media companies","aiSystem":"AI moderator","affectedGroup":"Authorities, US police, law enforcement departments","action":"Generate unviable reports on cases of child sexual abuse","consequence":"Prevent authorities from investigating cases, delay investigations of alleged predators"}},{"i":"R2248","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Openai bans bot impersonating us presidential candidate dean phillips","s":"Company removes account of developer saying ChatGPT bot violated policies on political campaigning. OpenAI has removed the account of the developer behind an artificial intelligence-powered bot impersonating the US presidential candidate Dean Phillips, saying it violated company policy. Phillips, who is challenging Joe Biden for the Democratic party candidacy, was impersonated by a ChatGPT-powered bot on the dean.bot site. The bot was backed by Silicon Valley entrepreneurs Matt Krisiloff and Jed Somers, who have started a Super Pac – a body that funds and supports political candidates – named We Deserve Better, supporting Phillips.","u":"https://www.theguardian.com/technology/2024/jan/22/openai-bans-bot-impersonating-us-presidential-candidate-dean-phillips","d":"2024-01-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-22","organization":"OpenAI","aiSystem":"ChatGPT-powered bot","affectedGroup":"US presidential candidate Dean Phillips","action":"Impersonated Dean Phillips","consequence":"Removed account and violated policies"}},{"i":"R2249","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Sunglass hut facial recognition wrongful arrest lawsuit","s":"Harvey Eugene Murphy Jr’s lawsuit claims he was misidentified as culprit of armed robbery and put in jail, where he says he was raped. A 61-year-old man is suing Macy’s and the parent company of Sunglass Hut over the stores’ alleged use of a facial recognition system that misidentified him as the culprit behind an armed robbery and led to his wrongful arrest. While in jail, he was beaten and raped, according to his suit. Harvey Eugene Murphy Jr was accused and arrested on charges of robbing a Houston-area Sunglass Hut of thousands of dollars of merchandise in January 2022, though his attorneys say he was living in California at the time of the robbery.","u":"https://www.theguardian.com/technology/2024/jan/22/sunglass-hut-facial-recognition-wrongful-arrest-lawsuit","d":"2024-01-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-01","organization":"Macy's and the parent company of Sunglass Hut","aiSystem":"Facial recognition technology","affectedGroup":"Harvey Eugene Murphy Jr","action":"Misidentification by facial recognition system","consequence":"Wrongful arrest, rape, physical assault"}},{"i":"R2251","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Inside the taylor swift deepfake scandal its men telling a powerful woman to get back in her box","s":"AI-generated porn, fuelled by misogyny, is flooding the internet, with Taylor Swift the latest high-profile casualty. Victims say social media platforms are failing to take it down – will they now start taking it seriously? For almost a whole day last week, deepfake pornographic images of Taylor Swift rapidly spread through X. The social media platform, formerly Twitter, was so slow to react that one image racked up 47m views before it was taken down. It was largely Swift’s fans who mobilised and mass-reported the images, and there was a sense of public anger, with even the White House calling it “alarming”. X eventually removed the images and blocked searches to the pop star’s name on Sunday evening.","u":"https://www.theguardian.com/technology/2024/jan/31/inside-the-taylor-swift-deepfake-scandal-its-men-telling-a-powerful-woman-to-get-back-in-her-box","d":"2024-01-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-29 to 2024-01-30","organization":"Social media platforms (X, formerly Twitter)","aiSystem":"AI-generated deepfake technology","affectedGroup":"Taylor Swift, her fans, and the general public","action":"AI-generated deepfake pornographic images of Taylor Swift spread rapidly through X","consequence":"Deepfake images of Taylor Swift were widely viewed and shared, leading to public outcry and calls for action"}},{"i":"R2255","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"North korea iran ai hacking microsoft","s":"US tech giant says it has detected threats from foreign countries that used or attempted to exploit generative AI it had developed. US adversaries – chiefly Iran and North Korea, and to a lesser extent Russia and China – are beginning to use generative artificial intelligence to mount or organize offensive cyber operations, Microsoft said on Wednesday. Microsoft said it detected and disrupted, in collaboration with business partner OpenAI, many threats that used or attempted to exploit AI technology they had developed. In a blogpost, the company said the techniques were “early-stage” and neither “particularly novel or unique” but that it was important to expose them publicly as US rivals leveraging large-language models to expand their ability to breach networks and conduct influence operations.","u":"https://www.theguardian.com/technology/2024/feb/14/north-korea-iran-ai-hacking-microsoft","d":"2024-02-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-14","organization":"Microsoft","aiSystem":"Generative artificial intelligence","affectedGroup":"Foreign adversaries (chiefly Iran and North Korea)","action":"Used or attempted to exploit generative AI technology","consequence":"Detected and disrupted threats, exposed early-stage techniques"}},{"i":"R2256","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google pauses ai generated images of people after ethnicity criticism","s":"Company says it will adjust its Gemini model after criticism of ethnically diverse Vikings and second world war German soldiers. Google has put a temporary block on its new artificial intelligence model producing images of people after it portrayed German second world war soldiers and Vikings as people of colour. The tech company said it would stop its Gemini model generating images of people after social media users posted examples of images generated by the tool that depicted some historical figures – including popes and the founding fathers of the US – in a variety of ethnicities and genders. “We’re already working to address recent issues with Gemini’s image generation feature.","u":"https://www.theguardian.com/technology/2024/feb/22/google-pauses-ai-generated-images-of-people-after-ethnicity-criticism","d":"2024-02-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-22","organization":"Google","aiSystem":"Google's Gemini model","affectedGroup":"People whose images were misattributed","action":"Generated images of people","consequence":"Misrepresentation and privacy risk"}},{"i":"R2257","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Media outlets sue openai copyright infringement","s":"Progressive US outlets file lawsuits claiming the company in effect plagiarized journalists’ work to develop ChatGPT. OpenAI and Microsoft are facing a fresh round of lawsuits from news publishers over allegations that their generative artificial intelligence products violated copyright laws and illegally trained by using journalists’ work. Three progressive US outlets – the Intercept, Raw Story and AlterNet – filed suits in Manhattan federal court on Wednesday, demanding compensation from the tech companies. The news outlets claim that the companies in effect plagiarized copyright-protected articles to develop and operate ChatGPT, which has become OpenAI’s most prominent generative AI tool.","u":"https://www.theguardian.com/technology/2024/feb/28/media-outlets-sue-openai-copyright-infringement","d":"2024-02-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-28","organization":"OpenAI and Microsoft","aiSystem":"generative AI","affectedGroup":"journalists","action":"used journalists' work to develop and operate ChatGPT","consequence":"violation of copyright laws"}},{"i":"R2260","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Microsoft ai explicit image safety","s":"Shane Jones said he warned management about the lack of safeguards several times, but it didn’t result in any action. An artificial intelligence engineer at Microsoft published a letter on Wednesday alleging that the company’s AI image generator lacks basic safeguards against creating violent and sexualized images. In the letter, engineer Shane Jones states that his repeated attempts to warn Microsoft management about the problems failed to result in any action. Jones said he sent the message to the Federal Trade Commission and Microsoft’s board of directors. “Internally the company is well aware of systemic issues where the product is creating harmful images that could be offensive and inappropriate for consumers,” Jones states in the letter, which he published on LinkedIn.","u":"https://www.theguardian.com/technology/2024/mar/06/microsoft-ai-explicit-image-safety","d":"2024-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Microsoft","aiSystem":"AI image generator","affectedGroup":"Consumers","action":"Generated violent and sexualized images","consequence":"Created harmful images offensive and inappropriate for consumers"}},{"i":"R2263","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Family takes fight against deepfake nudes to washington","s":"Francesca Mani told her mother she would not be a victim after fake images were circulated around her New Jersey school. In October last year, Francesca Mani came home from school in the suburbs of New Jersey with devastating news for her mother, Dorota. Earlier in the day the 14-year-old had been called into the vice-principal’s office and notified that she and a group of girls at Westfield High had been the victims of targeted abuse by a fellow student. Faked nude images of her and others had been circulating around school. They had been generated by artificial intelligence. Dorota had been tangentially aware of the power of this relatively new technology, but the ease with which the images were generated took her aback.","u":"https://www.theguardian.com/technology/2024/mar/12/family-takes-fight-against-deepfake-nudes-to-washington","d":"2024-03-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"October last year","organization":"Westfield High School","aiSystem":"AI-generated deepfake technology","affectedGroup":"Francesca Mani and a group of girls","action":"Generated faked nude images of Francesca Mani and others","consequence":"Targeted abuse and dissemination of false images"}},{"i":"R2267","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"San jose homelessness ai detection","s":"San Jose invited tech companies to mount cameras on a vehicle in what appears to be first-of-its-kind experiment. For the last several months, a city at the heart of Silicon Valley has been training artificial intelligence to recognize tents and cars with people living inside in what experts believe is the first experiment of its kind in the United States. Last July, San Jose issued an open invitation to technology companies to mount cameras on a municipal vehicle that began periodically driving through the city’s district 10 in December, collecting footage of the streets and public spaces. The images are fed into computer vision software and used to train the companies’ algorithms to detect the unwanted objects, according to interviews and documents the Guardian obtained through public records requests.","u":"https://www.theguardian.com/technology/2024/mar/25/san-jose-homelessness-ai-detection","d":"2024-03-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"Last several months","organization":"San Jose City","aiSystem":"Artificial intelligence algorithms trained to detect tents and cars","affectedGroup":"People living in tents and cars","action":"Cameras mounted on a municipal vehicle collected footage and fed it into computer vision software","consequence":"Artificial intelligence algorithms trained to detect unwanted objects"}},{"i":"R2270","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Musicians demand protection against ai","s":"Letter signed by more than 200 artists makes broad ask that tech firms pledge to not develop AI tools to replace human creatives. A group of more than 200 high-profile musicians have signed an open letter calling for protections against the predatory use of artificial intelligence that mimics human artists’ likenesses, voices and sound. The signatories span musical genres and eras, ranging from A-list stars such as Billie Eilish, J Balvin and Nicki Minaj to Rock and Roll Hall of Famers like Stevie Wonder and REM. The estates of Frank Sinatra and Bob Marley are also signatories. The letter, which was issued by the Artist Rights Alliance advocacy group, makes the broad demand that technology companies pledge not to develop AI tools that undermine or replace human songwriters and artists.","u":"https://www.theguardian.com/technology/2024/apr/02/musicians-demand-protection-against-ai","d":"2024-04-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-02","organization":"Technology companies","aiSystem":"Artificial intelligence tools that mimic human artists' likenesses, voices and sound","affectedGroup":"Human songwriters and artists","action":"Develop AI tools that undermine or replace human songwriters and artists","consequence":"Predatory use of AI to replace human creatives"}},{"i":"R2271","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Many shot jailbreaking ai artificial intelligence safety features bypass","s":"Paper by Anthropic outlines how LLMs can be forced to generate responses to potentially harmful requests. The safety features on some of the most powerful AI tools that stop them being used for cybercrime or terrorism can be bypassed simply by flooding them with examples of wrongdoing, research has shown. In a paper from the AI lab Anthropic, which produces the large language model (LLM) behind the ChatGPT rival Claude, researchers described an attack they called “many-shot jailbreaking”. The attack was as simple as it was effective. Claude, like most large commercial AI systems, contains safety features designed to encourage it to refuse certain requests, such as to generate violent or hateful speech, produce instructions for illegal activities, deceive or discriminate.","u":"https://www.theguardian.com/technology/2024/apr/03/many-shot-jailbreaking-ai-artificial-intelligence-safety-features-bypass","d":"2024-04-03","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-03","organization":"Anthropic","aiSystem":"Claude (large language model)","affectedGroup":"People who request potentially harmful content","action":"Claude generates responses to potentially harmful requests","consequence":"Safety features are bypassed, allowing generation of harmful content"}},{"i":"R2272","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"George carlin dudesy podcast ai lawsuit","s":"Suit claimed Dudesy podcast violated Carlin’s copyright, calling it ‘a casual theft of a great American artist’s work’. The estate of comedian George Carlin settled a lawsuit on Tuesday against the owners of a comedy podcast who claimed they used artificial intelligence to mimic the deceased stand-up’s voice. The lawsuit was one of the first in the US to focus on the legality of deepfakes imitating a celebrity’s likeness. The Dudesy podcast and its creators – the former Mad TV comedian Will Sasso and the writer Chad Kultgen – agreed to remove all versions of the podcast from the internet and permanently refrain from using Carlin’s voice, likeness or image in any content.","u":"https://www.theguardian.com/technology/2024/apr/03/george-carlin-dudesy-podcast-ai-lawsuit","d":"2024-04-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-03","organization":"Dudesy podcast and its owners (Will Sasso and Chad Kultgen)","aiSystem":"AI-generated deepfake technology","affectedGroup":"George Carlin's estate","action":"Used artificial intelligence to mimic George Carlin’s voice","consequence":"Permanent removal of all podcast versions from the internet and prohibition on using Carlin's voice, likeness, or image in any content"}},{"i":"R2275","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Child sexual abuse content online ai","s":"More children and families extorted with AI-made photos and videos, says National Center for Missing and Exploited Children. Child sexual exploitation is on the rise online and taking new forms such as images and videos generated by artificial intelligence, according to an annual assessment released on Tuesday by the National Center for Missing & Exploited Children (NCMEC), a US-based clearinghouse for the reporting of child sexual abuse material. Reports to the NCMEC of child abuse online rose by more than 12% in 2023 compared with the previous year, surpassing 36.2m reports, the organization said in its annual CyberTipline report.","u":"https://www.theguardian.com/technology/2024/apr/16/child-sexual-abuse-content-online-ai","d":"2024-04-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023","organization":"National Center for Missing and Exploited Children (NCMEC)","aiSystem":"Artificial intelligence","affectedGroup":"Children and families","action":"Generated AI-made photos and videos","consequence":"Extortion of children and families"}},{"i":"R2279","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot fatal crash","s":"Federal transportation agency finds Tesla’s claims about feature don’t match their findings and opens second investigation. US auto-safety regulators said on Friday that their investigation into Tesla’s Autopilot had identified at least 13 fatal crashes in which the feature had been involved. The investigation also found the electric carmaker’s claims did not match up with reality. The National Highway Traffic Safety Administration (NHTSA) disclosed on Friday that during its three-year Autopilot safety investigation, which it launched in August 2021, it identified at least 13 Tesla crashes involving one or more death, and many more involving serious injuries, in which “foreseeable driver misuse of the system played an apparent role”.","u":"https://www.theguardian.com/technology/2024/apr/26/tesla-autopilot-fatal-crash","d":"2024-04-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-26","organization":"National Highway Traffic Safety Administration (NHTSA)","aiSystem":"Tesla Autopilot","affectedGroup":"People involved in Tesla crashes","action":"Misuse of Autopilot feature","consequence":"Fatal and serious injuries"}},{"i":"R2282","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"She was accused of faking an incriminating video of teenage cheerleaders she was arrested outcast and condemned the problem nothing was fake after all","s":"The moral panic following Raffaella Spone’s ‘deepfake’ video spread around the world. She talks for the first time about being the centre of a story in which nothing was as it seemed …. Madi Hime is taking a deep drag on a blue vape in the video, her eyes shut, her face flushed with pleasure. The 16-year-old exhales with her head thrown back, collapsing into laughter that causes smoke to billow out of her mouth. The clip is grainy and shaky – as if shot in low light by someone who had zoomed in on Madi’s face – but it was damning. Madi was a cheerleader with the Victory Vipers, a highly competitive “all-star” squad based in Doylestown, Pennsylvania.","u":"https://www.theguardian.com/technology/article/2024/may/11/she-was-accused-of-faking-an-incriminating-video-of-teenage-cheerleaders-she-was-arrested-outcast-and-condemned-the-problem-nothing-was-fake-after-all","d":"2024-05-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-11","organization":"Victory Vipers (highly competitive all-star squad)","aiSystem":"AI-generated deepfake technology","affectedGroup":"Madi Hime (16-year-old cheerleader)","action":"Generated and distributed a deepfake video","consequence":"Exposure to misleading content, moral panic, arrest, ostracization, condemnation"}},{"i":"R2294","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Disney universal ai lawsuit","s":"Studios accuse AI firm of ‘piracy’ and seek injunction over alleged use of copyrighted characters. Disney and Universal sued an artificial intelligence company on Wednesday, alleging copyright infringement. In their lawsuit, the entertainment giants called Midjourney’s popular AI-powered image generator a “bottomless pit of plagiarism” for its alleged reproductions of the studios’ best-known characters. The suit, filed in federal court in Los Angeles, claims Midjourney pirated the libraries of the two Hollywood studios, making and distributing without permission “innumerable” copies of their marquee characters such as Darth Vader from Star Wars, Elsa from Frozen, and the Minions from Despicable Me.","u":"https://www.theguardian.com/technology/2025/jun/11/disney-universal-ai-lawsuit","d":"2025-06-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-11","organization":"Midjourney","aiSystem":"AI-powered image generator","affectedGroup":"Disney and Universal Studios","action":"alleged reproduction and distribution of copyrighted characters","consequence":"seeking injunction and alleging copyright infringement"}},{"i":"R2297","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Amazon boss tells staff ai means their jobs are at risk in coming years","s":"Andrew Jassy tells white collar workers that such technology means fewer people will be needed for some jobs. The boss of Amazon has told white collar staff at the e-commerce company their jobs could be taken by artificial intelligence in the next few years. Andrew Jassy told employees that AI agents – tools that carry out tasks autonomously – and generative AI systems such as chatbots would require fewer employees in certain areas. “As we roll out more generative AI and agents, it should change the way our work is done,” he said in a memo to staff. “We will need fewer people doing some of the jobs that are being done today, and more people doing other types of jobs.","u":"https://www.theguardian.com/technology/2025/jun/18/amazon-boss-tells-staff-ai-means-their-jobs-are-at-risk-in-coming-years","d":"2025-06-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-18","organization":"Amazon","aiSystem":"Generative AI systems like chatbots and AI agents","affectedGroup":"White-collar workers","action":"AI systems will require fewer employees in certain areas","consequence":"Fewer people will be needed for some jobs"}},{"i":"R2299","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla robotaxi investigation us","s":"The limited rollout in Austin, Texas, included pro-Tesla influencers using the paid ride service. The main transportation safety regulator in the US is requesting information from Tesla after videos showed the company’s self-driving Robotaxis exceeding the speed limit or veering into the wrong lane. The company launched the service in Austin, Texas, over the weekend. Tesla heavily promoted the initial, limited rollout of its Robotaxis, which included pro-Tesla influencers using the paid ride service and showing off footage of their trips. Instead of positive promotion, though, those videos appear to have drawn scrutiny from the National Highway Transit Safety Administration (NHTSA), as the cars struggled to comply with traffic laws.","u":"https://www.theguardian.com/technology/2025/jun/24/tesla-robotaxi-investigation-us","d":"2025-06-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-24","organization":"Tesla","aiSystem":"Tesla Robotaxis","affectedGroup":"General public, especially those who watched the videos","action":"Exceeding speed limits or veering into wrong lanes while operating autonomously","consequence":"Drawn into scrutiny by the National Highway Traffic Safety Administration (NHTSA)"}},{"i":"R2300","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Anthropic did not breach copyright when training ai on books without permission court rules","s":"Judge says firm made ‘fair use’ of literature but storage of pirated books in central library constituted infringement. A US judge has ruled that a tech company’s use of books to train its artificial intelligence system – without permission of the authors – did not breach copyright law. A federal judge in San Francisco said Anthropic made “fair use” of books by the writers Andrea Bartz, Charles Graeber and Kirk Wallace Johnson to train its Claude large language model (LLM). Judge William Alsup compared the Anthropic model’s use of books to a “reader aspiring to be a writer” who uses works “not to race ahead and replicate or supplant them” but to “turn a hard corner and create something different”.","u":"https://www.theguardian.com/technology/2025/jun/25/anthropic-did-not-breach-copyright-when-training-ai-on-books-without-permission-court-rules","d":"2025-06-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-25","organization":"Anthropic","aiSystem":"Claude large language model (LLM)","affectedGroup":"Authors of the books used for training","action":"Used pirated books to train the AI model","consequence":"Storage of pirated books in central library"}},{"i":"R2301","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Meta wins ai copyright lawsuit as us judge rules against authors","s":"Writers accused Facebook owner of breach over its use of books without permission to train its AI system. Mark Zuckerberg’s Meta has won the backing of a judge in a copyright lawsuit brought by a group of authors, in the second legal victory for the US artificial intelligence industry this week. The writers, who included Sarah Silverman and Ta-Nehisi Coates, had argued that the Facebook owner had breached copyright law by using their books without permission to train its AI system. The ruling comes after a decision on Monday that Anthropic, another major player in the AI field, had not infringed authors’ copyright.","u":"https://www.theguardian.com/technology/2025/jun/26/meta-wins-ai-copyright-lawsuit-as-us-judge-rules-against-authors","d":"2025-06-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-26","organization":"Facebook owner (Mark Zuckerberg's Meta)","aiSystem":"Meta's AI system","affectedGroup":"Authors of books","action":"Used books without permission to train AI system","consequence":"Won legal battle against authors"}},{"i":"R2302","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Microsoft ai authors lawsuit","s":"Writers alleged that company used nearly 200,000 pirated books to train its Megatron artificial intelligence. A group of authors has accused Microsoft of using nearly 200,000 pirated books to create an artificial intelligence model, the latest allegation in the long legal fight over copyrighted works between creative professionals and technology companies. Kai Bird, Jia Tolentino, Daniel Okrent and several others alleged that Microsoft used pirated digital versions of their books to teach its Megatron AI to respond to human prompts. Their lawsuit, filed in New York federal court on Tuesday, is one of several high-stakes cases brought by authors, news outlets and other copyright holders against tech companies including Meta Platforms, Anthropic and Microsoft-backed OpenAI over alleged misuse of their material in AI training.","u":"https://www.theguardian.com/technology/2025/jun/26/microsoft-ai-authors-lawsuit","d":"2025-06-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-26","organization":"Microsoft","aiSystem":"Megatron artificial intelligence","affectedGroup":"Authors of pirated books","action":"Used pirated books to train AI","consequence":"Legal dispute and potential misuse allegations"}},{"i":"R2303","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google emissions ai electricity demand derail efforts green","s":"Increase influenced by datacentre growth, with estimated power required by 2026 equalling that of Japan’s. Google’s carbon emissions have soared by 51% since 2019 as artificial intelligence hampers the tech company’s efforts to go green. While the corporation has invested in renewable energy and carbon removal technology, it has failed to curb its scope 3 emissions, which are those further down the supply chain, and are in large part influenced by a growth in datacentre capacity required to power artificial intelligence. The company reported a 27% increase in year-on-year electricity consumption as it struggles to decarbonise as quickly as its energy needs increase.","u":"https://www.theguardian.com/technology/2025/jun/27/google-emissions-ai-electricity-demand-derail-efforts-green","d":"2025-06-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-27","organization":"Google","aiSystem":"artificial intelligence","affectedGroup":"environment","action":"increased electricity consumption","consequence":"soared carbon emissions"}},{"i":"R2304","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google carbon emissions report","s":"Research says Google’s carbon emissions went up by 65% between 2019-2024, not 51% as the tech giant had claimed. In 2021, Google set a lofty goal of achieving net-zero carbon emissions by 2030. Yet in the years since then, the company has moved in the opposite direction as it invests in energy-intensive artificial intelligence. In its latest sustainability report, Google said its carbon emissions had increased 51% between 2019 and 2024. New research aims to debunk even that enormous figure and provide context to Google’s sustainability reports, painting a bleaker picture. A report authored by non-profit advocacy group Kairos Fellowship found that, between 2019 and 2024, Google’s carbon emissions actually went up by 65%.","u":"https://www.theguardian.com/technology/2025/jul/02/google-carbon-emissions-report","d":"2025-07-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-02","organization":"Google","aiSystem":"Google's carbon emission reporting process","affectedGroup":"Google","action":"Reported carbon emissions increase","consequence":"Misleading public perception and stakeholder trust"}},{"i":"R2305","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Fears ai factcheckers on x could increase promotion of conspiracy theories","s":"Former UK minister says platform, which will use AI to draft community notes, is ‘leaving it to bots to edit the news’. A decision by Elon Musk’s X social media platform to enlist artificial intelligence chatbots to draft factchecks risks increasing the promotion of “lies and conspiracy theories”, a former UK technology minister has warned. Damian Collins accused Musk’s firm of “leaving it to bots to edit the news” after X announced on Tuesday that it would allow large language models to write community notes to clarify or correct contentious posts, before users approve them for publication. The notes have previously been written by humans.","u":"https://www.theguardian.com/technology/2025/jul/02/fears-ai-factcheckers-on-x-could-increase-promotion-of-conspiracy-theories","d":"2025-07-02","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-07-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-02","organization":"Elon Musk's X social media platform","aiSystem":"Large language models","affectedGroup":"General public","action":"Draft factchecks using AI","consequence":"Increased promotion of lies and conspiracy theories"}},{"i":"R2306","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Grok ai praised hitler antisemitism x ntwnfb","s":"The popular bot on X began making antisemitic comments in response to user queries. Elon Musk’s artificial intelligence firm xAI has deleted “inappropriate” posts on X after the company’s chatbot, Grok, began praising Adolf Hitler, referring to itself as MechaHitler and making antisemitic comments in response to user queries. In some now-deleted posts, it referred to a person with a common Jewish surname as someone who was “celebrating the tragic deaths of white kids” in the Texas floods as “future fascists”. “Classic case of hate dressed as activism – and that surname? Every damn time, as they say,” the chatbot commented.","u":"https://www.theguardian.com/technology/2025/jul/09/grok-ai-praised-hitler-antisemitism-x-ntwnfb","d":"2025-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-09","organization":"xAI (Elon Musk’s artificial intelligence firm)","aiSystem":"Grok, xAI's artificial intelligence chatbot","affectedGroup":"Users of X (specifically those with Jewish surnames)","action":"Generated and posted antisemitic comments in response to user queries","consequence":"Deleted inappropriate posts and labeled as hate speech"}},{"i":"R2310","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Us military xai deal elon musk","s":"Defense department also inked contracts with other leading AI firms including Google, Anthropic and OpenAI. The week after its Grok chatbot identified itself as “MechaHitler” and generated antisemitic posts, Elon Musk’s xAI firm announced a contract with the US Department of Defense (DoD) worth nearly $200m. The deal is for developing and implementing artificial intelligence tools for the agency. The DoD on Monday also announced similar contracts with $200m ceilings with several other major US-based artificial intelligence developers, including Google, Anthropic and OpenAI. The agency is partnering with the General Services Administration to make these companies’ AI tools available for use throughout the federal government.","u":"https://www.theguardian.com/technology/2025/jul/14/us-military-xai-deal-elon-musk","d":"2025-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-14","organization":"Elon Musk's xAI firm","aiSystem":"xAI firm's chatbot","affectedGroup":"General public","action":"Generated antisemitic posts","consequence":"Misinformation exposure"}},{"i":"R2313","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Openai sam altman congress ai jobs","s":"Sam Altman also said AI could already diagnose better than doctors, as his company expands into Washington. During his latest trip to Washington, OpenAI’s chief executive, Sam Altman, painted a sweeping vision of an AI-dominated future in which entire job categories disappear, presidents follow ChatGPT’s recommendations and hostile nations wield artificial intelligence as a weapon of mass destruction, all while positioning his company as the indispensable architect of humanity’s technological destiny. Speaking at the Capital Framework for Large Banks conference at the Federal Reserve board of governors, Altman told the crowd that certain job categories would be completely eliminated by AI advancement.","u":"https://www.theguardian.com/technology/2025/jul/22/openai-sam-altman-congress-ai-jobs","d":"2025-07-22","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-22","organization":"OpenAI","aiSystem":"AI technologies","affectedGroup":"Job applicants, workers in specific job categories","action":"AI technologies will eliminate certain job categories","consequence":"People will lose their jobs"}},{"i":"R2314","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Youtube google ai age verification","s":"Tech company says it will use machine learning to estimate ages in order to show users in US age-appropriate content. YouTube announced on Tuesday that it will begin to use artificial intelligence to estimate the ages of users in the US, in order to show them age-appropriate content. The rollout of the new feature comes one day after Australia’s government announced it would ban children under 16 from using YouTube and less than a week after the UK implemented sweeping age checks on content on social networks. YouTube’s AI age verification on its home turf indicates it is putting into place a form of compliance with the Australian and UK requirements, despite its persistent opposition to age-check requirements.","u":"https://www.theguardian.com/technology/2025/jul/30/youtube-google-ai-age-verification","d":"2025-07-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-30","organization":"YouTube","aiSystem":"Artificial Intelligence age estimation system","affectedGroup":"Users in the United States","action":"Uses machine learning to estimate ages","consequence":"Exposes users to age-appropriate content"}},{"i":"R2315","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla fatal autopilot crash verdict","s":"Case opens door to other costly lawsuits after jury held that the car company bore significant responsibility in the crash. A Florida jury ordered Tesla to pay more than $200m to victims of a deadly crash involving its Autopilot driver assist technology. Friday’s verdict is a hit for Elon Musk’s car company, as it opens the door to other costly lawsuits and could potentially strike a blow to Tesla’s reputation for safety at a critical time for the company. And the decision has been closely eyed by other car companies, as they work to develop cars that increasingly drive themselves. The federal jury in Miami held that Tesla bore significant responsibility for the crash because its technology failed and that not all the blame can be put on a reckless driver, even one who admitted he was distracted by his cellphone before hitting a young couple out gazing at the stars.","u":"https://www.theguardian.com/technology/2025/aug/01/tesla-fatal-autopilot-crash-verdict","d":"2025-08-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-01","organization":"Tesla","aiSystem":"Autopilot driver assist technology","affectedGroup":"Victims of a deadly crash involving Tesla's Autopilot","action":"Tesla's Autopilot driver assist technology failed","consequence":"More than $200 million in damages awarded to victims"}},{"i":"R2318","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Lib dems call for urgent regulation of youtube ads after wave of scams","s":"Party wants video platform to face same scrutiny as broadcasters due to deepfake and investment scams. The Liberal Democrats are calling for urgent regulation of YouTube advertising after scams including deepfakes, impersonated public figures and fraudulent investment claims were found to be spreading on the platform with little oversight. The party said YouTube’s adverts remain largely unchecked by independent regulators, despite new data from Ofcom showing the platform has overtaken ITV in weekly UK viewership and continues to dominate children’s media consumption. Among the recent scams onYouTube was a series of ads using an AI-generated voice and likeness of the consumer champion Martin Lewis to promote a cryptocurrency scheme, despite Lewis having no involvement.","u":"https://www.theguardian.com/technology/2025/aug/05/lib-dems-call-for-urgent-regulation-of-youtube-ads-after-wave-of-scams","d":"2025-08-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-05","organization":"YouTube","aiSystem":"AI-generated voice and likeness","affectedGroup":"Consumers, particularly those interested in cryptocurrency investments","action":"Used AI-generated voice and likeness of Martin Lewis to promote a cryptocurrency scheme","consequence":"Spread of fraudulent investment claims and potential financial loss for consumers"}},{"i":"R2319","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Open ai chat gpt5 energy use","s":"Experts working to benchmark resource use of AI models say new version’s enhanced capabilities come at a steep cost. In mid-2023, if a user asked OpenAI’s ChatGPT for a recipe for artichoke pasta or instructions on how to make a ritual offering to the ancient Canaanite deity Moloch, its response might have taken – very roughly – 2 watt-hours, or about as much electricity as an incandescent bulb consumes in 2 minutes. OpenAI released a model on Thursday that will underpin the popular chatbot – GPT-5. Ask that version of the AI for an artichoke recipe, and the same amount of pasta-related text could take several times – even 20 times – that amount of energy, experts say.","u":"https://www.theguardian.com/technology/2025/aug/09/open-ai-chat-gpt5-energy-use","d":"2025-08-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-09","organization":"OpenAI","aiSystem":"GPT-5","affectedGroup":"Users of GPT-5","action":"Providing responses to user queries","consequence":"Higher energy usage"}},{"i":"R2322","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Us man bromism salt diet chatgpt openai health information","s":"US medical journal article about 60-year-old with bromism warns against using AI app for health information. A US medical journal has warned against using ChatGPT for health information after a man developed a rare condition following an interaction with the chatbot about removing table salt from his diet. An article in the Annals of Internal Medicine reported a case in which a 60-year-old man developed bromism, also known as bromide toxicity, after consulting ChatGPT. The article described bromism as a “well-recognised” syndrome in the early 20th century that was thought to have contributed to almost one in 10 psychiatric admissions at the time.","u":"https://www.theguardian.com/technology/2025/aug/12/us-man-bromism-salt-diet-chatgpt-openai-health-information","d":"2025-08-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-12","organization":"US medical journal","aiSystem":"ChatGPT","affectedGroup":"60-year-old man","action":"consulted ChatGPT for health information","consequence":"developed bromism"}},{"i":"R2324","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Meta ai chat children","s":"US senator Josh Hawley opened investigation into the tech giant, which said it had removed the policy guidelines. A backlash is brewing against Meta over what it permits its AI chatbots to say. An internal Meta policy document, seen by Reuters, showed the social media giant’s guidelines for its chatbots allowed the AI to “engage a child in conversations that are romantic or sensual”, generate false medical information, and assist users in arguing that Black people are “dumber than white people”. Singer Neil Young quit the social media platform on Friday, his record company said in a statement, the latest in a string of the singer’s online-oriented protests.","u":"https://www.theguardian.com/technology/2025/aug/15/meta-ai-chat-children","d":"2025-08-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-15","organization":"Meta (Facebook)","aiSystem":"Meta AI chatbots","affectedGroup":"Children","action":"Engage children in conversations that are romantic or sensual, generate false medical information, assist users in making prejudiced statements","consequence":"Privacy intrusion, potential psychological harm to children, dissemination of false information, promotion of prejudice"}},{"i":"R2325","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Social media still pushing suicide related content to teens despite new uk safety laws","s":"Researchers who set up dummy accounts as 15-year-old girl were bombarded with self-harm and depression posts. Social media platforms are still pushing depression, suicide and self-harm-related content to teenagers, despite new online safety laws intended to protect children. The Molly Rose Foundation opened dummy accounts posing as a 15-year-old girl, and then engaged with suicide, self-harm and depression posts. This prompted algorithms to bombard the account with “a tsunami of harmful content on Instagram Reels and TikTok’s For You page”, the charity’s analysis found. Almost all of the recommended videos watched on Instagram Reels (97%) and TikTok (96%) were found to be harmful, while over half (55%) of recommended harmful posts on TikTok’s For You page contained references to suicide and self-harm ideation and 16% referenced suicide methods, including some which the researchers had…","u":"https://www.theguardian.com/technology/2025/aug/19/social-media-still-pushing-suicide-related-content-to-teens-despite-new-uk-safety-laws","d":"2025-08-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-18","organization":"Social media platforms","aiSystem":"Social media algorithms","affectedGroup":"Teenagers","action":"Recommended harmful content","consequence":"Exposure to suicide and self-harm-related content"}},{"i":"R2326","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Trump enterprise surveillance microsoft meta robots","s":"Palantir and others boast ‘bombastic’ growth, Microsoft helps monitoring of Palestinian phone lines, Meta faces backlash over child safety. Hello, and welcome to TechScape. I’m your host, Blake Montgomery, currently enjoying Shirley Jackson’s eerie final novel We Have Always Lived in the Castle. An age of enterprise surveillance Surveillance is industrializing and privatizing. In the United States, it’s big business, and it’s growing. My colleagues Johana Bhuiyan and Jose Olivares report on the companies aiding Donald Trump’s immigration crackdown, which are running a victory lap after their latest quarterly financial reports: Palantir, the tech firm, and Geo Group and CoreCivic, the private prison and surveillance companies, said this week that they brought in more money than Wall Street expected them to, thanks to the administration’s crackdown on immigrants.","u":"https://www.theguardian.com/technology/2025/aug/18/trump-enterprise-surveillance-microsoft-meta-robots","d":"2025-08-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-18","organization":"Palantir, Geo Group, CoreCivic","aiSystem":"Surveillance systems","affectedGroup":"Immigrants","action":"Monitored phone lines","consequence":"Growth in surveillance industry"}}]);
